COPLAS_PIEZA(10, [["preciso_coleccion-p0109-01",18,"Nada mi amor con riesgo\nsobre una tabla,\nporque el amor sin riesgo\nno vale nada:\nque quando hay riesgo\nse ve quien es el que ama\ncon mas afecto.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,109,109,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0109-02",18,"A conquistar tu plaza\nme dirigia,\nquando ví que otro puso\nla batería:\nJugué de diestro,\ny puse en otra parte\nmi campamento.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,109,109,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0109-03",18,"Por dar alas los hombres\ná las mugeres,\ncomo esclavos á todos\ntratar nos quieren:\nmas no hacen esto\ncon los hombres que tienen\ngobierno y seso.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,109,109,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0110-01",18,"Aguarda, caminante,\ndeten el paso,\ny enjuga de mis ojos\nel triste llanto:\nporque aquí yace\nla fúnebre esperanza\nde un triste amante.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,110,110,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0110-02",18,"Al corazon le engañan\ntal vez los ojos,\nluego los desengaños\nle son odiosos;\nporque en el amor\nla informacion primera\nsiempre es la mejor.",222,0,-1,223,"",4,7,"o",72,0,-1,0,110,110,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0110-03",18,"Sin voluntad me tienes\nni entendimiento,\nllévate la memoria\nque es mi tormento;\npues si me dexas,\n¿de qué sirve acordarme\nde tus finezas?",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,110,110,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0111-01",18,"Parece tu cariño\nflor del almendro:\nnace pronto y fallece\nal primer viento:\nno es así el mio,\npues no le acaba el ayre\nde tus desvíos.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,111,111,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0111-02",18,"Vivo con la esperanza\nde un desengaño,\npero el tiempo se pasa\ny áun no le hallo:\ny si esto dura\naun peor que la herida\nserá la cura.",222,0,-1,223,"",4,7,"ua",17,0,-1,0,111,111,"","",76,"palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0111-03",18,"Es amor un veneno\nde tal calidad,\nque sana con lo mismo\nque suele enfermar:\nle buscan todos\ny si quieren dexarle\nno hallan el modo.",222,0,-1,223,"",4,7,"oo",-1,0,-1,0,111,111,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0112-01",18,"Te fuiste y me dexaste\ndesconsolado,\nmi amor no merecia\nde tí tal pago;\npero ya advierto\nque en muger la constancia\nla llevó el viento.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,112,112,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0112-02",18,"Por conseguir un gusto\nbueno es suspirar,\npero es malo el suspiro\ndespues de lograr:\nporque el suspiro\nsi antes era deseo\nluego es fastidio.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,112,112,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0112-03",18,"Es el vago suspiro\nde amor misterio,\nporque suelen las dichas\ncoger al vuelo,\nno ames con miedo\nque de los perezosos\nse hacen los necios.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,112,112,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0113-01",18,"Los amores mas tivios\ny mas ingratos,\nsuelen ser comunmente\nmejor pagados;\nque el amor niño\ndesprecia las finezas\npor un capricho.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,113,113,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0113-02",18,"El corazon amante\nnada repara,\nsolo de lo que quiere\nbusca la paga:\ny si la encuentra,\nno hay imposible alguno\nque no se venza.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,113,113,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0113-03",18,"No hay rincon en tu casa\nque á mi memoria\nno le esté recordando\naquí fue Troya;\ny este recuerdo\nme aflige, y en mi alma\naviva el fuego.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,113,113,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0114-01",18,"De tus hermosos ojos\ntengo en mi pecho\ntu imágen retratada\ncon sus reflexos;\nporque sus rayos\nson de mi amante pecho\ndulces ensayos.",222,0,-1,223,"",4,7,"ao",671,0,-1,0,114,114,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0114-02",18,"Quantas y quantas veces\nconsigue un sueño,\nlo que no han alcanzado\nmuchos desvelos:\ny en estas glorias\nlos que rien dormidos\ndespiertos lloran.",222,0,-1,223,"",4,7,"oa",-1,0,-1,0,114,114,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0114-03",18,"Hoy que ya sin cadenas\nlibre respiro,\nla libertad disfruto\nde mi alvedrío;\ny estoy contento\nde verme tan distante\ndel cautiverio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,114,114,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0115-01",18,"Una ofensa que te he hecho\nte voy á decir,\nun momento tan solo\nme olvidé de tí;\nno digas nada,\nque con la culpa quedo\nbien castigada.",222,0,-1,223,"",4,7,"aa",49,0,-1,0,115,115,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0115-02",18,"A tu amor he rendido\nlas tres potencias,\npero yo no lo siento\nque están bien puestas:\nsolo deseo\nque alguna de las tuyas\nme dés en premio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,115,115,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0115-03",18,"Dicen se muda el hombrè\nluego en logrando,\ny yo quanto mas logro\nmas idolatro;\nsolo me pesa\nel instante que pasa\nsin ver mi prenda.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,115,115,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0116-01",18,"Para imprimir tu afecto\nfuí yo de bronce,\npero estando ya impreso\nno hay quien le borre;\nporque yo tardo,\npero si á querer llego,\nnunca me aparto.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,116,116,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0116-02",18,"Mil delicias amantes\nlogré algun tiempo,\ny ahora solo pesares\nson los que tengo:\namor tirano,\nhazme otra vez presente\ntiempos pasados.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,116,116,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0116-03",18,"Es verdad que te quise,\nmas fué creyendo\nque en tí hallaban amparo\nmis desconsuelos;\npero no fué así,\nque buscando favores\nmi desprecio ví.",222,0,-1,223,"",4,7,"i",23,0,-1,0,116,116,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0117-01",18,"Creí que me querias\ny ahora contemplo,\nque solo me querias\nde cumplimiento:\nbien claro se vé,\npues á mi amor desprecias\nsin saber por qué.",222,0,-1,223,"",4,7,"e",77,0,-1,0,117,117,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0117-02",18,"Las mugeres me enfadan\ny fino gimo\nel dia que no veo\ná la que estimo;\npues con mi pasion\ntengo á todas por sombra\nde aquella que es sol.",222,0,-1,223,"",4,7,"o",-1,0,-1,0,117,117,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0117-03",18,"Quando ví tu hermosura\nte dí el corazon:\nte fuiste sin volverlo,\n¿cómo estaré yo?\nven á traerle,\nque sin corazon vive\nquien por tí muere.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,117,117,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0118-01",18,"Pretendió á tu hermosura\nsubir mi vuelo,\ny aunque mas quiso alzarse\nquedó en el suelo;\ncreo sin duda\nque no podrá alcanzarte\nsi no le ayudas.",222,0,-1,223,"",4,7,"ua",-1,0,-1,0,118,118,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0118-02",18,"El amor siempre empieza\npor algun chiste,\ncon sujeciones media,\ny acaba triste:\nno quiero tomar\ncosa que en sus extremos\nes tan desigual.",222,0,-1,223,"",4,7,"a",-1,0,-1,0,118,118,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0118-03",18,"Que quiera el que disfruta\nno es cosa nueva:\nquerer sin lograr nada\nsí que es fineza;\npues hoy se usa,\nque el que no logra pronto,\nluego se muda.",222,0,-1,223,"",4,7,"ua",-1,0,-1,0,118,118,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0119-01",18,"Qual te quise te quiero,\npero ya vivo\nsin esperar ser nunca\ncorrespondido;\npues si no agradé\nno podrá ser ahora\nlo que antes no fué.",222,0,-1,223,"",4,7,"e",77,0,-1,0,119,119,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0119-03",18,"De tus finezas hice\nlos eslabones\npara subir al trono\nde mis amores;\npoco he dudado,\nque en la lid de los zelos\nme han destronado.",222,0,-1,223,"",4,7,"ao",14,0,-1,0,119,119,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0120-01",18,"Con los ojos me explicas\ntu amante llama,\nrepara bien los mios\nverás la paga;\ny en los extremos\nserán los ojos lenguas\npara entendernos,",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,120,120,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0120-02",18,"Como por tí estoy ciego\nquieres burlarte;\nmira que si te veo\nha de pesarte:\nporque no dudo\ntus engaños; si cuerdo\nlos disimulo.",222,0,-1,223,"",4,7,"uo",-1,0,-1,0,120,120,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0120-03",18,"De tus yerros te formas\nlos eslabones,\nque texen la cadeña\nde tus traiciones;\ny así afligido\nserás un vil esclavo\nde mis olvidos.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,120,120,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0121-01",18,"¿Cómo podrá un amante\nlograr su dicha,\nsi está ausente quien puede\ndarle la vida?\ncruel tormento,\nhallarse separados\ndos finos pechos.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,121,121,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0121-02",18,"No me rindo á los ruegos\nde tu cariño,\npor no olvidar lo propio\ncon que te obligo;\nporque los ruegos\ncesan en el instante\ndel vencimiento.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,121,121,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0121-03",18,"No mires tanto al suelo,\nhermosa deidad,\nque me causa vergüenza\ntanta honestidad:\ná tí te digo\nla que baxas los ojos\nquando te miro.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,121,121,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0122-01",18,"Si te miran los sordos,\ndirán: ¡qué necia!\ny si te oyen los ciegos,\ndirán: ¡qué fea!\nambos se engañan,\nporque tú eres á un tiempo\nhermosa y sábia.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,122,122,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0122-02",18,"Dueña de mis pasiones\ny mi alvedrío,\ná nadie me sujeto\nni aun por capricho;\npero Cupido\njura que ha de vengarse,\ny yo me rio.",222,0,-1,223,"",4,7,"o",-1,0,-1,0,122,122,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0122-03",18,"Muger que manifiesta\ná un hombre su amor,\nse expone á mil desprecios\ny á perder su honor;\ny así aconsejo\nque su amor lo sepulte\nen el silencio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,122,122,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0123-01",18,"Una cosa te pido,\nme la has de otorgar,\nque en estando en tus glorias\nno me has de olvidar;\nsi me olvidares\nlo que te pido y ruego\nque no te alabes.",222,0,-1,224,"",4,7,"ae",-1,0,-1,0,123,123,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0123-02",18,"Si no hubiera yo sido\ntan firme en amar,\nno tuvieran mis ojos\ntanto que llorar;\nmal haya el alma\nque no cumple su gusto\ny á nadie aguarda.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,123,123,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0124-01",18,"De los cien imposibles\nque el amor tiene,\ntengo yo ya vencidos\nnoventa y nueve:\ntengo esperanza\nde que venceré pronto\nel que me falta.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,124,124,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0124-02",18,"Me enamoré de noche\ny así me salió,\nque carita que puse\nquando amaneció:\nporque los gatos,\ncomo dicen, de noche\ntodos son pardos.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,124,124,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0124-03",18,"Con fingimiento trato\nsiempre á las damas,\npues esta es la moneda\nque entre ellas anda:\nyo las engaño,\ny si ellas lo pretenden\ngano de mano.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,124,124,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0125-01",18,"El Lunes me enamoro,\nMártes lo digo,\nMiércoles me declaro,\nJuéves consigo:\nViérnes doy zelos,\ny Sábado y Domingo\nbusco amor nuevo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,125,125,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0125-02",18,"El carácter del hombre\nsi bien se advierte,\nno es el que manifiesta\nquando pretende:\nque en tales casos,\nel soberbio es humilde\ny el necio sabio.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,125,125,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0125-03",18,"Yo no sé lo que tiene\nel tio Pedro,\nque me mira, se rie,\nse chupa el dedo:\npero yo juzgo\nque por mas que lo chupe\nno saque jugo.",222,0,-1,224,"",4,7,"uo",-1,0,-1,0,125,125,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0126-01",18,"Es amor un embuste\ntan bien dispuesto,\nque le hacen las mugeres\ntener por cierto:\ny con engaños\ntienen á muchos hombres\nembolismados.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,126,126,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0126-02",18,"Sé que finezas haces\ná otro sugeto;\nbien puedes, pues hé sido\nyo tu maestro:\nno te equivoques,\ny por costumbre en ellas\ná mí me nombres.",222,0,-1,224,"",4,7,"oe",-1,0,-1,0,126,126,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0126-03",18,"El que quisiere amando\nvivir sin pena,\nha de tomar el tiempo\nconforme venga:\nquiera querido,\ny quando le desprecien\nhaga lo mismo.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,126,126,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0127-01",18,"Soy Filis, que á Cupido\nnunca dí entrada\nen los firmes palacios\nde mi morada:\nporque estoy cierta\nque donde entra este vicho\ntodo lo enreda.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,127,127,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0127-02",18,"El que se ausenta y dexa\ná su querida,\nluego no forme queja\nsi es que le olvida:\npues será fixo,\nque se verá obsequiada\nde sus amigos.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,127,127,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0127-03",18,"Porque tú á mí me dexes\nno tengo queja,\nporque en dexar no ha sido\ntú la primera:\nmas por si acaso,\npor no perder de postre\ngano de mano.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,127,127,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0128-01",18,"No fies en amante\nque estando á solas\nte cuente los favores\nque tuvo en otra:\nporque es muy fixo,\nque si los tuyos logra\nhará lo mismo.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,128,128,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0128-02",18,"Las mugeres del dia\npor lo que vemos,\ntienen propios y arbitrios\ncomo los pueblos:\npero es preciso\nenagenar los propios\npor los arbitrios.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,128,128,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0128-03",18,"La que sigue los triunfo\nde la veleidad,\npasea, rie y goza\nla primera edad:\nmas luego pára,\nporque su cara bella\nle sale cara.",222,0,-1,224,"",4,7,"aa",57,0,-1,0,128,128,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0129-01",18,"Es el amor del pobre\nsermon en Argel,\nque nadie que le oye\nhace caso de él;\npor lo que vemos\nque si un pobre enamora\nsufre desprecios.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,129,129,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0129-02",18,"La dama por esquiva\nno hay que dexarla,\nque en el hierro mas duro\nmas se machaca;\ny golpe á golpe\naun la piedra mas dura\nblanda se pone.",222,0,-1,224,"",4,7,"oe",-1,0,-1,0,129,129,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0129-03",18,"No alabes buenos mozos\nnunca á tu dama,\nque la darás deseos\nde una mudanza:\n¡qué mas martirio\nsi tú llevas la leña\ná el sacrificio!",222,0,-1,224,"",4,7,"io",-1,0,-1,0,129,129,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0130-01",18,"No fies en colores\nde ciertas caras,\nque hay muchas que parecen\ná las manzanas;\nque las paredes\nquando están revocadas\nnuevas parecen.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,130,130,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0130-02",18,"La embriaguez en los ricos\nsolo es xaqueca,\ny el vahido en los pobres\nes borrachera:\nque en estos tiempos\ngraduan las acciones\npor los sugetos.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,130,130,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0130-03",18,"Si no cumple mi majo\nlo que ha tratado,\nlo dexaré sin alma\nde un rejonazo;\nal arma, guerra,\ny que pague el indino\nlo que me deba.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,130,130,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0131-01",18,"En muger y en caballo\nno fies, Roque,\nque al mejor tiempo pegan\nun par de coces;\ny es un ganado\nque al que mejor le trata\nle da peor pago.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,131,131,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0131-02",18,"Por Dios que disimules\nlo que me quieres,\nque tú no logras nada\ny á mí me pierdes;\nporque estas cosas\nen ser comunes pierden\nel ser preciosas.",222,0,-1,224,"",4,7,"oa",61,0,-1,0,131,131,"","",76,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0131-03",18,"A ninguna he querido\ntanto como á tí:\ntú has sido mi principio,\ntú has de ser mi fin;\npero con desden,\nsabiendo que te quiero,\ntiras del cordel.",222,0,-1,224,"",4,7,"e",-1,0,-1,0,131,131,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0132-01",18,"Ya no te quiero, mueble,\nporque no caben\ndos pilotos á un tiempo\nen una nave;\ny yo he sabido\nque te traigo la paja,\ny otro hace el nido.",222,0,-1,224,"",4,7,"io",101,0,-1,0,132,132,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0132-02",18,"El demonio me lleva\nquando me acuerdo\nde que nada consigo\nde quanto intento;\ny mas me lleva\nal ver que otros consiguen\nquanto desean.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,132,132,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0132-03",18,"Al pasar por la fragua\ndixe á un herrero\nque me hiciera un amante\nde fino acero:\ny él me responde,\n¿cómo puede ser fino,\nsi ha de ser hombre?",222,0,-1,224,"",4,7,"oe",-1,0,-1,0,132,132,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0133-01",18,"Todo el hombre que quiera\ncomo yo quiero,\nen su vida eche plantas\nni juramentos:\npues yo aburrido\nhe jurado mil cosas,\ny no he cumplido.",222,0,-1,224,"",4,7,"io",101,0,-1,0,133,133,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0133-02",18,"Dile, niña, á tu novio\nque se desista\nde aquellas tonterías\nque solicita:\nque luego cuestan\nno pocas pesadumbres\nlas ligerezas.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,133,133,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0133-03",18,"Amor es como el agua,\nsegun se toma,\nque á muchos los refresca\ny á otros sofoca:\nbeber con tiento,\nque hay mil enfermedades\npor el exceso.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,133,133,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0134-01",18,"Si fueres á visita\nponte á lo obscuro,\nque si está allí Don Pedro\nno es muy seguro:\npero es el caso,\nque tan bueno es Don Pedro\ncomo Don Pablo.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,134,134,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0134-02",18,"No quiero yo mugeres,\nporque mi afecto,\nsolo le tengo en una,\nque es la que quiero:\ny en ella encuentro\nque reune mas gracias\nque el mundo entero.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,134,134,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0134-03",18,"Eres tonto de noche,\ntonto de dia,\ntonto por la mañana\ny al mediodia:\nno me acordaba\nque tambien eres tonto\nde madrugada.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,134,134,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0135-01",18,"Para los que comercian\ná lo escondido\nno faltan en la Corte\ncasas de giro:\ny aquí las letras\nse pagan á la vista,\nsin mas espera.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,135,135,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0135-02",18,"Diga usted á mi madre\nque no me riña,\nque ella tambien jugaba\nquando era niña:\nporque yo pienso\nque aquestas diversiones\nvan con el tiempo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,135,135,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0135-03",18,"Jugando á la pelota\nestaba un tuerto,\ny de un golpe le quitan\nel ojo bueno:\ny él muy conforme,\ntengan ustedes, dice,\nmuy buenas noches.",222,0,-1,224,"",4,7,"oe",-1,0,-1,0,135,135,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0136-01",18,"Si á otro, quando me quieres,\nla mano le das,\nquando ya no me quieras,\ndí ¿qué le darás?\nmas no lo digas,\nque yo estaba creyendo\nque eras mas fina.",222,0,-1,224,"",4,7,"ia",-1,0,-1,0,136,136,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0136-02",18,"Por el punto se guardan\nmuchas doncellas,\npero en perdiendo el punto,\nvan de carrera:\nquando así se ven,\ndicen: quien hace un cesto,\nya me entiende vmd.",222,0,-1,224,"",4,7,"",-1,0,-1,0,136,136,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0136-03",18,"Dicen que tiene gracia\nla muger fea,\nmas no quiero yo gracia\nque no se vea:\npues si está oculta\nantes de ver qual sea\nel dueño asusta.",222,0,-1,224,"",4,7,"ua",-1,0,-1,0,136,136,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0137-01",18,"Como experimentado\ndixo un grande autor,\nlos cuernos á los dientes\nparecidos son:\nduelen al nacer,\npero despues con ellos\nse suele comer.",222,0,-1,224,"",4,7,"e",20,0,-1,0,137,137,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0137-02",18,"Yo voy hácia la Iglesia,\ntú vas por detras,\nsi no mudas camino\nno me encontrarás:\nsi el bien anhelas,\nbúscame en calles anchas,\nno en callejuelas.",222,0,-1,224,"",4,7,"ea",605,0,-1,0,137,137,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0137-03",18,"Aunque á muchas gallinas\ndivierta un gallo,\nsiempre la mas querida\nduerme á su lado:\ny el hombre á veces\nsuele tener al lado\nla que aborrece.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,137,137,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0138-01",18,"El animal mas fiero\nes el marido;\npero algunas le temen\nmenos que á un niño:\nque los hay tales,\nque de ser hombres pierden\nlos memoriales.",222,0,-1,224,"",4,7,"ae",26,0,-1,0,138,138,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0138-02",18,"Contigo mi cariño\nes tan constante,\nque no me olvido nunca\nque estas delante;\nporque te advierto\nque por nada en el mundo\nyo me sujeto.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,138,138,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0138-03",18,"Quien ama muger fea\ntiene disculpa,\nque pasa el purgatorio,\ny paga la culpa;\npues yo no creo\nque haya mayor castigo\nque un mueble feo.",222,0,-1,224,"",4,7,"eo",66,0,-1,0,138,138,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0139-01",18,"Aunque usted finja, niña,\nser de alta esfera,\ntambien para las torres\nhay escalera;\ny no hay mozuelo\nque en las fiestas no suba\ny toque á vuelo.",222,0,-1,224,"",4,7,"eo",10,0,-1,0,139,139,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0139-02",18,"Por entrarme en la huerta\nde otro labrador,\notro se entró en la mia,\ntomó posesion:\npor atrevido,\nde una me arrojó el dueño,\nla otra he perdido.",222,0,-1,224,"",4,7,"io",101,0,-1,0,139,139,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0139-03",18,"Con falsedad no trates\ná quien te ama,\nque puedes ir por pelo,\nvolver sin lana;\nporque sucede,\ndonde menos se piensa\nsaltar la liebre.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,139,139,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0140-01",18,"Una moza le dixo\ná un jorobado,\nme pareces ovillo\nmal devanado:\ndixo él, mozuela,\npues tú por el ovillo\nsacas la hebra.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,140,140,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0140-02",18,"Lleva sin ser barbero\nel hombre pobre\ndos vacías de plata\nen los calzones:\nque aunque no quiera\nde todo van vacías\nlas faltriqueras.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,140,140,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0140-03",18,"No enamore quien tenga\npoco dinero,\nque aunque sea buen mozo\nquedará feo:\npues las mugeres\nhuyen como del diablo\nde tales gentes.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,140,140,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0141-01",18,"Que bien dixo el que dixo\nque al perro ageno,\nen darle pan se pierde\nel pan y el perro:\ny en este refran\nvenimos á ser ambos\ntú el perro, yo el pan.",222,0,-1,224,"",4,7,"a",147,0,-1,0,141,141,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0141-02",18,"Es el cortejo un duende\nno conocido,\npero por sus idéas\nbien recibido:\ny esto depende\nde que adula rendido\ndespues que ofende.",222,0,-1,224,"",4,7,"ee",233,0,-1,0,141,141,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0141-03",18,"Juguetes amorosos\nson las querellas,\n¿y qué resulta de ellos?\nel perderse ellas:\nellos barajan,\njuegan y salen libres\nde polvo y paja.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,141,141,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0142-01",18,"De los calvos no quieras\nenamorarte,\nque si riñes no tienes\ná qué agarrarte:\ny es gran tristeza\nestar siempre mirando\nsu calavera.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,142,142,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0142-02",18,"Los que de amor padecen\nson cazadores,\nsiempre están aguardando\nlas ocasiones:\ny si la encuentran,\naunque haya inconvenientes\nlos atropellan.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,142,142,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0142-03",18,"¿De qué sirve á un amante\npasear la calle,\nsi no logra sus gustos\nel miserable?\nbien insensato\nes el que se contenta\ncon el olfato.",222,0,-1,224,"",4,7,"ao",19,0,-1,0,142,142,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0143-01",18,"En tu casa, en mi casa,\ny aun en el prado,\nfacilité tu intento,\nlo has malogrado:\n¿y por qué quieres\necharme á mí la culpa,\nsi tú la tienes?",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,143,143,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0143-02",18,"Muchos páxaros andan\nrevoloteando\npor entrar en la ermita\nde quando en quando:\ny la ermitaña\ná todos los despluma\ncon mucha maña.",222,0,-1,224,"",4,7,"aa",213,0,-1,0,143,143,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0143-03",18,"Se parecen los hombres\ná las abejas,\npues siempre andan buscando\nflores diversas:\ny aunque de paso\ntodas las flores llevan\nsu picotazo.",222,0,-1,224,"",4,7,"ao",43,0,-1,0,143,143,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0144-01",18,"El que juega á las damas\nal punto coma,\nporque si no el contrario\nllega y la sopla:\nme he descuidado,\ny una que yo tenia\nme la han soplado.",222,0,-1,224,"",4,7,"ao",14,0,-1,0,144,144,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0144-02",18,"Se parece á los olmos\nel amor tuyo,\nque todo es ojarasca,\npero sin fruto:\ny yo no quiero\nsin provecho ninguno\ngastar el tiempo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,144,144,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0144-03",18,"Estoy como los perros\nbaxo la mesa,\nesperando las sobras\nque el amo dexa:\ny así es preciso\nel mantenerse un hombre\nde desperdicios.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,144,144,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0145-01",18,"Mas quiero yo en tu casa\nroer un hueso,\nque comer fuera de ella\nmanjares tiernos:\npero es mi pena,\nque para consolarme\nni ahullar me dexan.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,145,145,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0145-02",18,"Si quieres que te caiga\nla Lotería,\ncorteja una Andaluza\npobre y bonita:\nverás qué terno\nte sale de desdichas,\ntrampas y enredos.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,145,145,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0145-03",18,"La que en sus mocedades\nfué cariñosa,\nquando ya no la quieran\nes fastidiosa:\n¡ah que de males\nnos causa el amor propio\ná los mortales!",222,0,-1,224,"",4,7,"ae",26,0,-1,0,145,145,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0146-01",18,"Un necio y un discreto\nhacen apuesta\ná quien sube mas pronto\ncierta escalera:\npero el discreto\nadvierte que los tontos\nsuben mas presto.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,146,146,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0146-02",18,"Ya pasaste el creciente\ncomo la luna,\nahora estás en el lleno\nde la fortuna:\nvete con tiento,\ncuidado que al menguante\nno mude el tiempo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,146,146,"","",76,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0146-03",18,"Las finezas que hacias\nantes conmigo,\nlas empleas ahora\ncon mi enemigo:\ntente, villana,\nno te pierdas como otras\npor su inconstancia.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,146,146,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0147-01",18,"De puerta en puerta un pobre\ncoge mas quartos\nque quedándose en una\nsiempre parado:\npor esa cuenta\nando yo en mis amores\nde puerta en puerta.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,147,147,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0147-02",18,"Tengo yo un cofrecito\ndonde ir echando\ntodas las pesadumbres\nque me vas dando:\npero algun dia\nse abrirá el cofrecito\ny será la mia.",222,0,-1,224,"",4,7,"a",0,0,-1,0,147,147,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0147-03",18,"Mi madre me ha mandado\nque no te quiera,\ny yo le digo, madre,\n¡si usted la viera!\nQuedó tamaña,\ny mordiéndose el labio,\ndixo: ¡caramba!",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,147,147,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0148-01",18,"Lo mismo que la sombra\nson las mugeres,\nhuyen del que las sigue,\nal que huye quieren:\ny de aquí nace\nque quedan muchas veces\nsin colocarse.",222,0,-1,224,"",4,7,"ae",-1,0,-1,0,148,148,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0148-02",18,"Si me quieren soy firme,\nsi nó mudable,\nporque al son que me tocan\nsigo yo el bayle:\nvivo contento,\ny hallo en qualquier parte\ndivertimiento.",222,0,-1,224,"",4,7,"eo",94,0,-1,0,148,148,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0148-03",18,"Le decia á un majo\ncierta mozuela:\neres bravo espantajo\npara una higuera:\nmala persona,\nque de nada me sirve\nmas que de sombra.",222,0,-1,224,"",4,7,"oa",-1,0,-1,0,148,148,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0149-01",18,"Dormia un jardinero\ná pierna suelta,\nsin mirar que dexaba\nla puerta abierta:\nllegó un usía,\ny le quitó la rosa\nque él mas queria.",222,0,-1,224,"",4,7,"ea",0,0,-1,0,149,149,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0149-02",18,"Voces desde una viña\nme daba un guarda,\ndespues que la tenia\nyo vendimiada:\ndixe, compadre,\nlas voces al principio,\nque ahora ya es tarde.",222,0,-1,224,"",4,7,"ae",-1,0,-1,0,149,149,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0149-03",18,"Nadie tenga su viña\njunto al camino,\nporque todo el que pasa\ncorta un racimo:\ny entre unos y otros\nse la van vendimiando\nsin saber como.",222,0,-1,224,"",4,7,"oo",-1,0,-1,0,149,149,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0150-01",18,"Las suelen llamar flacas\ná las mugeres:\nmas flacos son los hombres,\nque ellas los vencen:\nque á vencer una\nno bastan muchos hombres,\nsi ella no gusta.",222,0,-1,224,"",4,7,"ua",-1,0,-1,0,150,150,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0150-02",18,"Si por irte con otro\nme has olvidado,\néchate en el bolsillo\nlo que has ganado:\nandar andillo,\nsi tu padre te pega,\nhuye, chiquillo.",222,0,-1,224,"",4,7,"io",228,0,-1,0,150,150,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0150-03",18,"Esquelas de convite\nlos amantes son,\nen todas partes dicen\nla misma expresion:\ny en donde pega\ndura veinte y quatro horas\nla pasion ciega.",222,0,-1,224,"",4,7,"ea",257,0,-1,0,150,150,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0151-01",18,"Yo no sé que tendria\ná noche mi Juan,\nque le puse la cena\ny no quiso cenar:\nmas yo he pensado\nque no le gusta mucho\ncierto guisado.",222,0,-1,224,"",4,7,"ao",14,0,-1,0,151,151,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0151-02",18,"Los efectos que nacen\nde amor perfecto,\nno distiguen de clases\nni de sugetos:\nporque el corazon\ndirige sus pasiones\nsin adulacion.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,151,151,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0151-03",18,"El andar tras las mozas\nno sé por qué es,\nnada de ellas se saca,\nantes al reves:\ny siempre veo\nque andan hombres tras ellas,\ncon mucho anhelo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,151,151,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0152-01",18,"Todos de las mugeres\ndicen mucho mal,\npero veo que todos\nlas van á buscar:\ny en sus enredos\nmuchas veces la culpa\nla tienen ellos.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,152,152,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0152-02",18,"Hay viejas en el mundo\ntan aplicadas,\nque se alquilan por madres\nde muchas maulas:\npor eso hay moza\nque tiene aquí una madre\ny en Cádiz otra.",222,0,-1,224,"",4,7,"oa",-1,0,-1,0,152,152,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0152-03",18,"Aunque todos reniegan\nde la inconstancia,\nyo tengo quien me quiere\ncon esta gracia:\npues soy tan rara,\nque he dado en divertirme\ncon ver que rabian.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,152,152,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0153-01",18,"Con falsedad yo trato\nsiempre á las damas,\nporque esta es la moneda\nque entre ellas anda:\ny las engaño\npor si acaso lo intentan,\nganar de mano.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,153,153,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0153-02",18,"La que mas fina viva\nsi es que se ausenta,\nal instante se muda\ncomo veleta:\ny estos son males\nmuy comunes, pues ellas\ntodas son tales.",222,0,-1,224,"",4,7,"ae",26,0,-1,0,153,153,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0153-03",18,"Tus malas intenciones\nbien las conozco,\ndesnudastes á un santo\npor vestir á otro:\npero te digo\nque el que tú desnudaste\nya está vestido.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,153,153,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0154-01",18,"Como sé que te mudas\ná todos áyres,\nno suspiro, mi vida,\npor no mudarte:\nque aunque no abulta,\nel ayre de un suspiro\ná mí me asusta.",222,0,-1,224,"",4,7,"ua",-1,0,-1,0,154,154,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0154-02",18,"¿Qué importa que una dama\ndueño me llame,\nsi no sé si ella es mia,\nni ella lo sabe?\nsi no poseo,\njamas de hacienda agena\nme llamo dueño.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,154,154,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0154-03",18,"Desnuda te quisiera\npor mas hermosa,\ndesnuda de pasiones,\nno de otra cosa:\ny de esta suerte\nfuera yo quien vistiera\ntus desnudeces.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,154,154,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0155-01",18,"Entre bobo y discreto\nanda el que espera;\nmas que me llamen tonto\nsi el lance llega:\nponer los medios,\ny dexar la esperanza\nque venga luego.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,155,155,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0155-02",18,"Es el mundo guitarra\nde cuerdas dobles\ndonde entona Cupido\nfalsas canciones:\ny con quimeras\ntemplan siempre las primas\ncon las terceras.",222,0,-1,224,"",4,7,"ea",103,0,-1,0,155,155,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0155-03",18,"En tocando que toquen\ná la aleluya,\nveremos si es constante\nla pasion tuya:\npero recelo\nque todas son lisonjas\nlas que voy viendo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,155,155,"","",76,"rm_t3","","",2,0,0,[],"",""],["preciso_coleccion-p0156-01",18,"Cazador cauteloso\nciego cupido,\nque con ojos vendados\nno yerras tiro:\nsuspende el arco,\nque ocasionan tus iras\nmuchos disparos.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,156,156,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0156-02",18,"En tratar es preciso\nser precavidas,\nque no conviene siempre\nser conocidas:\nirse con tiento,\ny tener disimulo,\nque es del intento.",222,0,-1,224,"",4,7,"eo",94,0,-1,0,156,156,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0156-03",18,"Con el abaniquito,\nque te haces ayre,\nestás haciendo señas\ná quien tú sabes:\ncon ese tema\nlo que á tí te dá fresco\ná mí me quema:",222,0,-1,224,"",4,7,"ea",216,0,-1,0,156,156,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0157-01",18,"Tienes, niña, en tus labios\ndos clavelitos,\néchales agua fresca\nque están marchitos:\npero si quieres\nme darás la licencia\nque te los riegue.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,157,157,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0157-02",18,"Que se volvió paloma\nsoñó una dama,\ncon el palomo al lado\nque la arrullaba:\ndispertó sola,\ny entonces ya sentía\nno ser paloma.",222,0,-1,224,"",4,7,"oa",-1,0,-1,0,157,157,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0157-03",18,"No se encuentra en mugeres\nquien fina sea,\ntodas sus expresiones\nson con idea:\ny por costumbre,\ny así nada las sierve\nde pesadumbre.",222,0,-1,224,"",4,7,"ue",181,0,-1,0,157,157,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0158-01",18,"Muchos baxan al prado\ná refrescarse,\ny encuentran casos raros\npara abrasarse:\ny muchos de ellos\nsuelen estar sudando\nmeses enteros.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,158,158,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0158-02",18,"No fies en colores\nde ciertas caras,\nque hay muchas que parecen\ná las manzanas:\nque aun las paredes\nsi están bien revocadas\nnuevas parecen.",222,0,-1,224,"",4,7,"ee",-1,0,-1,0,158,158,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0158-03",18,"Me citas y me debes,\nchusca del alma,\n¿en quantas veces, dime,\nquieres la paga?\ncuentas iguales,\ny verás, prenda mia,\nqué bien que sales.",222,0,-1,224,"",4,7,"ae",26,0,-1,0,158,158,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0159-01",18,"¡Ay hombres infelices!\nlastima os tengo,\npues siempre os engañamos\ncomo queremos:\nun breve gozo\nos damos, pero hacemos\nnuestro negocio.",222,0,-1,224,"",4,7,"oo",-1,0,-1,0,159,159,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0159-02",18,"Se divierte una dama\npuesta en un balcon,\ncon las aves que pasan\nforma diversion:\ny está pensando\nsi el páxaro que vuela\nvendrá á la mano.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,159,159,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0159-03",18,"Te criaron sin rienda\ny hoy cuidan de tí,\nquien yerra los principios\ntarde acierta el fin:\ndí á quien te zela,\nque harto haces imitando\nlo que te enseña.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,159,159,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0160-01",18,"A la puerta del gusto\ntengo el reparo,\ny así no entrará nadie\nsin registrarlo:\nque la advertencia\nsuele quitar lo malo\npor la apariencia.",222,0,-1,224,"",4,7,"ea",46,0,-1,0,160,160,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0160-02",18,"No siento que me dexe\nla que me quiera,\npues señal que me tuvo\nquando me dexa:\nmas me consuelo\nque no irán á desquite\nde las que dexo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,160,160,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0160-03",18,"Preguntas si te quiero,\ny es bobería,\ntómate la respuesta\nque tú darías:\npues á qualquiera\nle dices que le quieres,\nsea ó no sea.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,160,160,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0161-01",18,"Las rentas de Cupido\ntienen mil guardas,\ny ministros que cobran\nlas alcabalas:\ny sin embargo,\nviven muchos en ellas\nde contrabando.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,161,161,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0161-02",18,"Con palabras á solas\ntu amor me explicas,\ny veo que las obras\ná otros dedicas.\nEsto no sirve,\nporque siempre es dichoso\nel que recibe.",222,0,-1,224,"",4,7,"ie",-1,0,-1,0,161,161,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0161-03",18,"Dios nos libre de chismes\ny horas menguadas,\npero principalmente\ndel agua mansa;\ncuyos estragos\nson mas irremediables\nquantos mas tardos.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,161,161,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0162-01",18,"Nadie trata á los tunos\ncomo las majas,\nque tan pronto los quieren\ncomo los plantan:\ny ellos á ellas,\nque tan pronto las toman\ncomo las dexan.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,162,162,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0162-02",18,"Mercader que en sus tratos\nvario camina,\nno halla correspondencia\nmientras no gira:\n¡qué viles tratos\npara cariños firmes\nlos cortesanos!",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,162,162,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0162-03",18,"Te has hecho, vida mia,\ntan miserable,\nque niegas que te quiero\npor no pagarme:\npero esta deuda\nte perdono gustoso\ncomo me quieras.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,162,162,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0163-01",18,"Amor antiguamente\nfué trato honesto,\ny ahora de tanto trato\nse ha hecho comercio:\ny como en feria,\nquien da mas por la alhaja\naquel la lleva.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,163,163,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0163-02",18,"No pretendas ser sola,\nmira que es chanza,\nporque esa es una cosa\nque nadie alcanza:\nama de veras,\ny déxate de todas\nesas quimeras.",222,0,-1,224,"",4,7,"ea",103,0,-1,0,163,163,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0163-03",18,"Tú vives en la calle\nde la garduña,\nyo junto á puño en rostro\nque hay menos bulla:\nson dos extremos\ncon que si no te mudas\nno nos hablemos.",222,0,-1,224,"",4,7,"eo",127,0,-1,0,163,163,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0164-01",18,"Aunque de azul me visto\nno soy zeloso,\nbien puedes, vida mia,\nhablar con otro:\npero te advierto\nque algunas expresiones\nno las consiento.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,164,164,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0164-02",18,"Yo no quiero esperanzas\nnunca en el amor,\nque me canso si presto\nno hallo posesion:\npues el que espera\nencuentra en bodas largas\nbarajas nuevas.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,164,164,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0164-03",18,"Para la despedida\nde mis cantares,\ndel corazon y el alma\nte doy las llaves:\nmira, pichona,\nsi por tí queda pobre\nesta persona.",222,0,-1,224,"",4,7,"oa",7,0,-1,0,164,164,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0165-01",18,"Confiado en tus tratos\nte alquilé el alma,\nme convine en que fuese\ná media paga:\nse cumplió el plazo,\nte requerí mil veces,\nsalté del quarto.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,165,165,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0165-02",18,"Si juego á naypes solo\nlas sotas hallo,\ny si enamoro á mozas\nme dan caballos:\nyo bien quisiera\nenamorar jugando\nsi no perdiera.",222,0,-1,224,"",4,7,"ea",44,0,-1,0,165,165,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0165-03",18,"Codornices los hombres\nvenimos á ser,\nque nos rinde el reclamo\nde qualquier muger:\nal mejor tiempo\nquando volar se quiere,\npresos nos veimos.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,165,165,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0166-01",18,"A precio muy barato\ncompra el que es necio,\nyo como generoso\nlo caro aprecio:\naunque no es regla,\npero esta opinion sigo\nsea ó no sea.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,166,166,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0166-02",18,"Yo pensé que era solo\nquien te queria,\npero veo que tienes\nmucha familia:\npues voy ya viendo\nrecibes cada dia\ncriados nuevos.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,166,166,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0166-03",18,"En mi casa hay un loro\nque dice, quiero,\ny es la causa que á solas\nme lo está oyendo:\nanimalito,\nlo que yo digo â solas\npublíca á gritos.",222,0,-1,224,"",4,7,"io",-1,0,-1,0,166,166,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0167-01",18,"Muy discreto es tu ingenio,\npero he notado\nque á veces por lucirlo\nte haces pesado:\nque en ocasiones\ndonde hay razon que explica\nsobran razones.",222,0,-1,224,"",4,7,"oe",34,0,-1,0,167,167,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0167-02",18,"Mundo, demonio y carne,\ntres enemigos,\nen la muger cifrados\ntodos los miro:\nporque á mi vista\nmundo, demonio tientan,\ncarne ella misma.",222,0,-1,224,"",4,7,"ia",-1,0,-1,0,167,167,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0167-03",18,"En cuenta de mis ansias\ny mis extremos\npondrás muchas partidas\nque estás debiendo:\nen ellas entra\naquel atraso grande\nque erró mi cuenta.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,167,167,"","",76,"rm_t3","","",2,0,0,[],"",""],["preciso_coleccion-p0168-01",18,"Un fondo vitalicio\nson las pasiones,\nque aseguran las rentas\nde lo que ponen:\nmas si se aumentan,\nen vez de enriquecerse\npierden su renta.",222,0,-1,224,"",4,7,"ea",-1,0,-1,0,168,168,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0168-02",18,"Amor es un enredo\ndicen los sábios,\npero yo veo á muchos\nmuy enredados:\nde lo que infiero\nque son muy dulces lazos\nlos de este enredo.",222,0,-1,224,"",4,7,"eo",-1,0,-1,0,168,168,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0168-03",18,"Hay gatos que callando\ncomen pichones,\ny otros hay que mayando\nno ven ratones:\ny de esto saco\nque aquel que menos maya\nes mejor gato.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,168,168,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0169-01",18,"Si por otro que es ménos\nme quieres dexar,\nyo he pensado en dexarte\npor otra que es mas:\nme has hecho favor,\npues ya tenia ganas\nde mudar de amor.",222,0,-1,224,"",4,7,"o",72,0,-1,0,169,169,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0169-02",18,"Si estás triste, estoy triste,\nsi alegre, alegre,\nporque yo tomo el tiempo\nconforme viene:\ny no hago caso\nviendo son tus mudanzas\ná cada paso.",222,0,-1,224,"",4,7,"ao",145,0,-1,0,169,169,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0169-03",18,"Camina recatado\nen tus intentos,\nmira que se descubren\ntus pensamientos:\ny aunque logrados,\naun de tí si pudieres\nhas de ocultarlos.",222,0,-1,224,"",4,7,"ao",-1,0,-1,0,169,169,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0170-01",18,"Es la chocolatera\nde amor remedo,\ncrece mucho y se sale\nestando al fuego:\ny si se aparta\nse enfria, y lo que es mucho\nmengua y es nada.",222,0,-1,224,"",4,7,"aa",-1,0,-1,0,170,170,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0171-01",18,"Nace amor como planta\nen el corazon,\nlos halagos la riegan,\nla seca el rigor.",222,0,-1,225,"",6,4,"o",-1,0,-1,0,171,171,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0171-02",18,"¿Cómo quieres que tenga\ngusto sin verte,\nsi eres la que mas quiero\ny estás ausente?",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,171,171,"","",76,"rm_t3, palau_cantares","","",14,0,0,[],"",""],["preciso_coleccion-p0171-03",18,"Corazon que en la pena\ntu alivio encuentras,\nsi en la pena descansas\n¿de qué te quejas?",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,171,171,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0172-01",18,"¿Qué haré yo con contarte\ntodas mis penas,\nsi aunque me las escuches\nno las remedias?",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,172,172,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0172-02",18,"Tus suspiros que vienen\nlos mios que van,\nsi se encuentran al paso\n¿qué extremos no harán?",222,0,-1,225,"",6,4,"a",147,0,-1,0,172,172,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0172-03",18,"Siento mucho el dexarte\nque eres bonita,\naunque estoy enfadado,\npasion no quita:::",222,0,-1,225,"",6,4,"ia",50,0,-1,0,172,172,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0172-04",18,"Discurriendo en tus aras\nhallar piedades,\nsolo hallo sinsabores\ny falsedades.",222,0,-1,225,"",6,4,"ae",373,0,-1,0,172,172,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0172-05",18,"Mi corazon padece\npenas crueles\npor no saber de cierto\nsi tú me quieres.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,172,172,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0173-01",18,"El templo de la fama\nhe registrado,\ny sobre una columna\nví tu retrato.",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,173,173,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0173-02",18,"Supuesto que me has muerto\nmanda me entierren,\nen el panteon triste\nde tus desdenes.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,173,173,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0173-03",18,"Pondrás por epitafio\nen mi sepulcro,\naquí murió, aquí yace\nquien amar supo.",222,0,-1,225,"",3,4,"uo",-1,0,-1,0,173,173,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0173-05",18,"Si hacer pruebas pretendes\nde mi fino amor,\nsolo has de hallar constancias\ncontra tu rigor.",222,0,-1,225,"",0,4,"o",72,0,-1,0,173,173,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0174-01",18,"En láminas de bronce\ntengo de imprimir\nun fúnebre epitafio\nque diga ¡ay de mí!",222,0,-1,225,"",0,4,"i",-1,0,-1,0,174,174,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0174-02",18,"Muchos hay que no logran\nlo que desean:\npor ser cortos de genio\ncortos se quedan.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,174,174,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0174-03",18,"Un corazon que vive\ndesconfiado\nde ser correspondido,\nvive penando.",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,174,174,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0174-04",18,"De unos ojos hermosos\npreso y cautivo,\nhumilde el yugo sufro\nde su capricho.",222,0,-1,225,"",6,4,"io",-1,0,-1,0,174,174,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0174-05",18,"Con zelosos discursos\ndivierto el tiempo,\ndesde que amor sus flecha\ntiró á mi pecho.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,174,174,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0175-01",18,"En la funesta guerra\nde mi memoria,\nsolo podrá el olvido\nlograr victoria.",222,0,-1,225,"",6,4,"oa",126,0,-1,0,175,175,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0175-02",18,"En el lóbrego abismo\nde mi tormento,\nsolo las penas mias\nhallan consuelo.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,175,175,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0175-03",18,"Que te tuve en mis brazos\nanoche soñé,\nlo que reí dormido,\ndispierto lloré.",222,0,-1,225,"",0,4,"e",77,0,-1,0,175,175,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0175-04",18,"A mí mismo me quiero\npor quererte á tí,\ny si tú no me quieres\nyo tampoco á mí.",222,0,-1,225,"",0,4,"i",23,0,-1,0,175,175,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0175-05",18,"No es gloria de famosos\nconquistadores\nusar con quien se rinde\ntantos rigores.",222,0,-1,225,"",6,4,"oe",5,0,-1,0,175,175,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0176-01",18,"Al rayo ardiente y ciego\ndel dios vendado\nmuestra amor ser mas firme\nque el fuego airado.",222,0,-1,225,"",6,4,"ao",14,0,-1,0,176,176,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0176-02",18,"Confuso está mi pecho\ndesde que te ví:\nde mí ya no me acuerdo,\nsolo pienso en tí.",222,0,-1,225,"",0,4,"i",23,0,-1,0,176,176,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0176-03",18,"Ya está el carro cargado\nde tus desprecios,\nmira no falte el exe\ndel sufrimiento.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,176,176,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0176-04",18,"Ay! qué tristes cadenas!\nqué dura cárcel!\ná esto se han reducido\nmis libertades.",222,0,-1,225,"",6,4,"ae",-1,0,-1,0,176,176,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0176-05",18,"Cárcel es mi esperanza,\njuez mi voluntad,\ntus ojos son los reos,\nla causa es amar.",222,0,-1,225,"",0,4,"a",-1,0,-1,0,176,176,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0177-01",18,"En la bóveda obscura\nde tu falsedad\nresonaban los ecos\nde mi lealtad.",222,0,-1,225,"",0,4,"a",16,0,-1,0,177,177,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0177-02",18,"¡Qué funesto es el tiempo\nque sin tí paso!\n¡quántas fatigas sufro,\nquántos quebrantos!",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,177,177,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0177-03",18,"Retrocede á tu centro,\nsuspiro mio,\nque en el alma te dexas\ná quien te envío.",222,0,-1,225,"",6,4,"io",3,0,-1,0,177,177,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0177-04",18,"La pasion oprimida\nes como el rayo,\nquanto mas resistencia\nmayor estrago.",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,177,177,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0177-05",18,"Mas allá de la vida\nhe de quererte,\nque amor está en el alma\ny esa no muere.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,177,177,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0178-01",18,"Al impulso violento\nde una mudanza\nse desquician los exes\nde una esperanza.",222,0,-1,225,"",6,4,"aa",163,0,-1,0,178,178,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0178-02",18,"De una chispa tan sola,\nque no hice caso,\nse originó el incendio\nen que me abraso.",222,0,-1,225,"",6,4,"ao",145,0,-1,0,178,178,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0178-04",18,"¿Quál de los dos amantes\ntendrá mas pena,\nel que se ausenta libre,\nó el que se queda?",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,178,178,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0178-05",18,"Soy peñasco, soy risco,\nsoy dura piedra,\npara todos soy bronce,\npara tí cera.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,178,178,"","",76,"rm_t2, palau_cantares, frenk_t1","","",4,0,0,[],"",""],["preciso_coleccion-p0179-01",18,"Memoria que en el tiempo\nde los desvíos\nse acuerda de la dicha,\ndobla el martirio.",222,0,-1,225,"",6,4,"io",-1,0,-1,0,179,179,"","",76,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0179-02",18,"En amantes dolencias\nsuelen los zelos\nser á veces sangrías\nhechas á tiempo.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,179,179,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0179-03",18,"Esperanza consuela,\nposesion cansa,\napetecer desvela,\nno lograr mata.",222,0,-1,225,"",6,4,"aa",-1,0,-1,0,179,179,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0179-04",18,"Por mas que nos separe\nla tiranía,\nhe de ser siempre tuyo,\ntú siempre mía",222,0,-1,225,"",6,4,"ia",0,0,-1,0,179,179,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0179-05",18,"Te hablaré por los ojos,\nque es mas segura\nlengua, que por los ojos\nse explica muda.",222,0,-1,225,"",6,4,"ua",-1,0,-1,0,179,179,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0180-01",18,"Es el amor un fuego\ncuya materia,\nquanto mas se consume\nmas se fomenta.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,180,180,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0180-02",18,"¡Ay de aquel infelice\nque hacer no puede!\n¡y ay de aquel que pudiendo\nhacer no quiere!",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,180,180,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0180-03",18,"Fin en mi fino pecho\ntu amor no tendrá,\ny esta fineza el tiempo\nla acreditará.",222,0,-1,225,"",0,4,"a",9,0,-1,0,180,180,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0180-04",18,"Mi corazon del pecho\nsalir pretende:\nyo no sé lo que busca,\ntú ya lo entiendes.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,180,180,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0180-05",18,"Con lo que me consuelo\nquando estoy triste,\nes con ver el camino\npor donde fuiste.",222,0,-1,225,"",6,4,"ie",153,0,-1,0,180,180,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0181-01",18,"La tortolilla triste\nde ver se admira\ncómo mi pecho tierno\nsu canto imita.",222,0,-1,225,"",6,4,"ia",-1,0,-1,0,181,181,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0181-02",18,"¡Ay cómo te remontas,\nmemoria ufana!\nmira que no es lo mismo\nhoy que mañana.",222,0,-1,225,"",6,4,"aa",4,0,-1,0,181,181,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0181-03",18,"Ya se acabó aquel tiempo,\ntodo se acaba,\nque solo con mirarte\nme alimentaba.",222,0,-1,225,"",6,4,"aa",28,0,-1,0,181,181,"","",76,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0181-04",18,"Dime, dueño del alma,\ndime si quedó\nceniza de aquel fuego\nque algun tiempo ardió.",222,0,-1,225,"",0,4,"o",2,0,-1,0,181,181,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0181-05",18,"Toda la noche velo\nconsiderando\nquando serás tú mia,\nyo tuyo quándo.",222,0,-1,225,"",6,4,"ao",33,0,-1,0,181,181,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0182-01",18,"Porfian en quererte\nlas ansias mias,\npero tú en despreciarlas\ntambien porfias.",222,0,-1,225,"",6,4,"oa",-1,0,-1,0,182,182,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0182-02",18,"El que ama no siendo\ncorrespondido,\nese sí que merece\nnombrarse fino",222,0,-1,225,"",6,4,"io",-1,0,-1,0,182,182,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0182-03",18,"Tuve cierto cariño,\ny aun no me pesa,\naunque fué muy ingrata\nla recompensa.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,182,182,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0182-04",18,"A Dios, y mis cuidados\nno te los dexo,\npor ser la única alhaja\nque de tí llevo,",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,182,182,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0182-05",18,"Arrojé una mirada,\nsembré un deseo,\nfloreció una esperanza,\ncogí un desprecio.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,182,182,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0183-01",18,"Ingrata, que me engañas\nbien lo conozco,\npasas conmigo el tiempo,\ncon otro el gozo.",222,0,-1,225,"",6,4,"oo",-1,0,-1,0,183,183,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0183-02",18,"Si despues de un desprecio\ndura el afecto,\npasion es incurable\ny amor perfecto.",222,0,-1,225,"",6,4,"eo",256,0,-1,0,183,183,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0183-03",18,"Mi querer será eterno,\nmi amor sin tasa,\nmi voluntad de bronce;\nmi fé de malla.",222,0,-1,225,"",6,4,"aa",-1,0,-1,0,183,183,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0183-04",18,"Quien suspira en ausencia\nno tiene alivio,\nántes sí le da al alma\nmayor martirio.",222,0,-1,225,"",6,4,"io",-1,0,-1,0,183,183,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0183-05",18,"Si aborreciste á otro\npara quererme,\ntambien te será facil\naborrecerme.",222,0,-1,225,"",6,4,"ee",245,0,-1,0,183,183,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0184-01",18,"No por antecedentes\namor infieras,\nque suelen salir falsas\nlas consecuencias.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,184,184,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0184-02",18,"Segun veo las obras\nyo ya contemplo\nque tus adoraciones\nvan á otro templo.",222,0,-1,225,"",6,4,"eo",376,0,-1,0,184,184,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0184-03",18,"Ya estás, Fabio, en el solio,\npero contempla\nquan grande es la subida,\nla caida es cierta.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,184,184,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0184-04",18,"O finges ó no finges,\ntirano dueño:\nsi finges, acabóse,\nsi no, acabemos.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,184,184,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0184-05",18,"Al infierno parecen\nmis pensamientos\nen el atormentarme\ny en ser eternos.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,184,184,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0185-01",18,"El que muchos te quieran\nno me hace eco,\nel que tú correspondas\nes lo que siento.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,185,185,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0185-02",18,"Acuérdate, tirana,\nquando solias\nprevenir los acasos\npara las dichas,",222,0,-1,225,"",6,4,"ia",-1,0,-1,0,185,185,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0185-03",18,"¿Quál es la mayor prueba\nde una fineza?\nadorar no esperando\ncorrespondencia.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,185,185,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0185-04",18,"Suspiros exálados\ndel pecho mio,\n¿quién fuera con vosotros\ndonde os envio?",222,0,-1,225,"",6,4,"eo",3,0,-1,0,185,185,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0185-05",18,"He de ser firme muro\nque á los combates\nde zelos y desdenes\njamas desmaye.",222,0,-1,225,"",6,4,"ae",-1,0,-1,0,185,185,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0186-01",18,"Se conforma mi afecto\ncon lo que tiene,\nde paciencia se viste\nquien mas no puede.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,186,186,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0186-02",18,"Amor que tiene juicio\npoco amor tiene,\nque el amor á el mas cuerdo\nloco le vuelve.",222,0,-1,225,"",6,4,"ee",-1,0,-1,0,186,186,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0186-03",18,"Amores al principio\nson agradables,\npero en la subsistencia\nson muy mudables.",222,0,-1,225,"",6,4,"ae",694,0,-1,0,186,186,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0186-04",18,"Amor es una senda\ntan sin camino,\nque el que mas bien la sabe\nva mas perdido.",222,0,-1,225,"",6,4,"io",-1,0,-1,0,186,186,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0186-05",18,"Tengo yo mis potencias\ntan bien halladas\nen tus contemplaciones,\nque no se cansan.",222,0,-1,225,"",6,4,"aa",-1,0,-1,0,186,186,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0187-01",18,"Forzado de la estrella\nque me domina,\namante te idolatro,\nVenus divina.",222,0,-1,225,"",6,4,"ia",11,0,-1,0,187,187,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0187-03",18,"Quando estoy á mis solas\nen tí pensando,\ntan perdido me encuentro\nque no me hallo.",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,187,187,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0187-04",18,"Tanta vanidad tienes\nde mis tormentos,\nque solo te alimentas\nde rendimientos.",222,0,-1,225,"",6,4,"eo",234,0,-1,0,187,187,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0187-05",18,"Qué pronto se acabáron\ntodas mis glorias,\nsueño fuéron mis dichas,\ntormento ahora.",222,0,-1,225,"",6,4,"oa",-1,0,-1,0,187,187,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0188-01",18,"Ya has logrado, fortuna,\ntodo tu anelo,\nabatiendo mis dichas\ndel cielo al suelo.",222,0,-1,225,"",6,4,"eo",10,0,-1,0,188,188,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0188-02",18,"El amor que es logrado\npronto se olvida,\nque hermosura gozada\nluego fastidia.",222,0,-1,225,"",6,4,"ia",-1,0,-1,0,188,188,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0188-03",18,"Quisiera me dixeras,\naleve ingrato,\nqué gloria te se sigue\nde tu mal trato.",222,0,-1,225,"",6,4,"ao",19,0,-1,0,188,188,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0188-04",18,"Qué gustòsa va un alma\nquando la llevan\ndesde las falsedades\ná las finezas.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,188,188,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0188-05",18,"Amor que ha de ser firme,\nhá de ser ciego,\nqueriendo solamente\npor solo quiero.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,188,188,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0189-01",18,"Dicen que sueño es muertè\nmas yo lo niego,\npues quando duermo vivo,\nquando no, muero.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,189,189,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0189-02",18,"Si no tengo á la vista\nsiempre á mi dueño,\npor mas que me confie\nvivo muriendo.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,189,189,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0189-03",18,"Mi pensamiento al humo\nse le parece,\nporque al paso que sube\nse desvanece.",222,0,-1,225,"",6,4,"ee",64,0,-1,0,189,189,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0189-04",18,"Desde que la confianza\nvive segura\nse rien los amantes\nde la fortuna.",222,0,-1,225,"",6,4,"ua",-1,0,-1,0,189,189,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0189-05",18,"Corsario que á dos naves\nsigue diversas,\nlogrará desengaños,\npero no presas.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,189,189,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0190-01",18,"Para que mi cariño\nse mortifique\nle vas dando finezas\npor alambique.",222,0,-1,225,"",6,4,"ie",311,0,-1,0,190,190,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0190-02",18,"Deidad eres sin duda,\npues no es posible\nque humana me rindieras\ncomo me rindes.",222,0,-1,225,"",6,4,"ie",-1,0,-1,0,190,190,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0190-03",18,"En méritos no fundo\nmis esperanzas,\nque el querer no es justicia,\nsí solo es gracia.",222,0,-1,225,"",6,4,"aa",-1,0,-1,0,190,190,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0190-04",18,"Qué importa que el deseo\nlo facilite,\nsi un motivo que media\nno lo permite.",222,0,-1,225,"",6,4,"ie",315,0,-1,0,190,190,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0190-05",18,"Es la comun disculpa\nde los amantes\nllamar á las traiciones\ncasualidades.",222,0,-1,225,"",6,4,"ae",-1,0,-1,0,190,190,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0191-01",18,"Una tirana ausencia\nme quiere matar,\ny si lo intenta, creo\nque lo ha de lograr.",222,0,-1,225,"",0,4,"a",21,0,-1,0,191,191,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0191-02",18,"Libertad blasonaba\nmi pecho altivo,\nmas al mirarte vime\nde amor rendido.",222,0,-1,225,"",6,4,"io",-1,0,-1,0,191,191,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0191-03",18,"Me mandas que te olvide,\nno sé si sabré,\nmas tratando contigo\nde tí aprenderé.",222,0,-1,225,"",0,4,"e",77,0,-1,0,191,191,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0191-04",18,"Dias ha que lo verde\nme dá inquietudes,\nporque mis esperanzas\nse han vuelto azules.",222,0,-1,225,"",6,4,"ue",-1,0,-1,0,191,191,"","",76,"rm_t2, rm_t3, palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0191-05",18,"Eres tú quien decias\nque amabas con fé,\nlo contrario acredita\ntu corresponder.",222,0,-1,225,"",0,4,"e",-1,0,-1,0,191,191,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0192-01",18,"A Dios y ten presente\nque á mi fineza\nno siendo causa tuya\nnada hace fuerza.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,192,192,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0192-02",18,"Si mi querer te enfada\nyo te prometo\nque no hallarás finezas\nen mí tan presto.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,192,192,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0192-03",18,"El quererte y no verte\nse puede llevar,\npero verte y no hablarte\n¿qué mayor penar?",222,0,-1,225,"",0,4,"a",21,0,-1,0,192,192,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0192-04",18,"Si te miro me admira\ntu gallardía,\ny en ansias amorosas\nse me va el dia.",222,0,-1,225,"",6,4,"a",0,0,-1,0,192,192,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0192-05",18,"Vámonos, dueño mio,\npor esos montes,\ndonde lo que te quiero\npublique á voces.",222,0,-1,225,"",6,4,"oe",-1,0,-1,0,192,192,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0193-01",18,"Como fácil olvidas\npiensa tu halago\nque tengo yo el olvido\ntan en mi mano.",222,0,-1,225,"",6,4,"ao",-1,0,-1,0,193,193,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0193-02",18,"Si en hacer que yo pene\ntienes consuelo,\nmuéstrate mas ingrata\nque penar quiero.",222,0,-1,225,"",6,4,"eo",-1,0,-1,0,193,193,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0193-03",18,"Por Dios si no me quieres\nque no me mires,\nya que no me rescates,\nno me cautives.",222,0,-1,225,"",6,4,"ie",-1,0,-1,0,193,193,"","",76,"huambachano, palau_cantares","","",7,0,0,[],"",""],["preciso_coleccion-p0193-04",18,"Memoria, solo sirves\nde recordarme\nespecies que aun fingidas\npueden matarme.",222,0,-1,225,"",6,4,"ae",35,0,-1,0,193,193,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0193-05",18,"Ingrata, porqúe sepas\nlo que amor cuesta,\npermita Dios que ames\ny te aborrezcan.",222,0,-1,225,"",6,4,"ea",-1,0,-1,0,193,193,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0194-01",18,"El corazon me dice\nque me has de olvidar,\n¡qué pago á mis finezas\nsi sale verdad!",222,0,-1,225,"",0,4,"a",-1,0,-1,0,194,194,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0194-02",18,"No es bastante el deseo\npara conseguir,\nque es menester fortuna\ny saber pedir.",222,0,-1,225,"",0,4,"i",157,0,-1,0,194,194,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0195-01",18,"Muchos hay que se quejan\nde tiranías,\n¡ay! si yo me quejára\nquántas tenia!",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,195,195,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0195-02",18,"Ya que por vergonzoso\nmi amor no digo,\nbastante me declaro\nquando te miro.",222,0,-1,226,"",6,4,"io",-1,0,-1,0,195,195,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0195-03",18,"Dígale usté á aquel majo\nde la montera,\nque si busca camorra\nsalga allá fuera.",222,0,-1,226,"",6,4,"ea",44,0,-1,0,195,195,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0196-01",18,"Con todas te diviertes\ny gastas chanzas,\nhe de ser yo solita,\nsi no naranjas.",222,0,-1,226,"",6,4,"aa",-1,0,-1,0,196,196,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0196-02",18,"Tú me tienes que apenas\nyo me conozco,\nque á veces me pregunto\nyo por mí propio.",222,0,-1,226,"",6,4,"oo",-1,0,-1,0,196,196,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0196-03",18,"Ponte un alfilerito\nen el pañuelo,\nque te se ven los naypes,\ný haces mal juego.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,196,196,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0196-04",18,"Ama, espera y confia,\nporque no puede\nquien vence sin contrario\ndecir que vence.",222,0,-1,226,"",6,4,"ee",-1,0,-1,0,196,196,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0196-05",18,"Si me das uvas verdes\nde tus higueras,\nen teniendo yo parra\nte daré brevas.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,196,196,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0197-01",18,"Muchos con la esperanza\nviven alegres,\nmuchos son los borricos\nque comen verde.",222,0,-1,226,"",6,4,"ee",-1,0,-1,0,197,197,"","",76,"rm_t4, palau_cantares, barcenas_marinera, huambachano, maguina_vida","","",7,0,0,[],"",""],["preciso_coleccion-p0197-02",18,"No te fies del tiempo,\nmira que engaña,\nlogra las ocasiones\nquando te salgan.",222,0,-1,226,"",6,4,"aa",-1,0,-1,0,197,197,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0197-03",18,"Penas y sobresaltos,\nansias y zelos,\nsi de amor no son señas\nserán torreznos.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,197,197,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0197-04",18,"Como es propio de ciegos,\nel ir tentando,\nmientras mas tiento pongo\nmas pronto caygo.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,197,197,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0197-05",18,"Ya no quiero mirarte,\nque si te miro,\nse me van las potencias\npor esos trigos.",222,0,-1,226,"",6,4,"io",-1,0,-1,0,197,197,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0198-01",18,"A noche en tu ventana\nenfermé de amor,\nllamé á tu puerta y dixe:\n¿vive aquí el doctor?",222,0,-1,226,"",0,4,"o",72,0,-1,0,198,198,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0198-02",18,"Yo no sé que demonios\nlos dos tenemos,\nmientras mas regañamos\nmas nos queremos.",222,0,-1,226,"",6,4,"eo",127,0,-1,0,198,198,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0198-03",18,"Cupido quando niño\nhizo diabluras,\ny ahora estamos pagando\nsus travesuras.",222,0,-1,226,"",3,4,"ua",238,0,-1,0,198,198,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0198-04",18,"Dame, niña, la mano\nque jugaremos,\nporque amor sin licencia\ntodo es respeto.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,198,198,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0198-05",18,"Carga de contrabando\nes la hermosura,\nquanto mas se resguarda\nmenos segura.",222,0,-1,226,"",6,4,"ua",17,0,-1,0,198,198,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0199-01",18,"Tus ojitos me matan,\ny yo los quiero,\n¿quién dirá que yo vivo\npor lo que muero?",222,0,-1,226,"",6,4,"eo",38,0,-1,0,199,199,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0199-02",18,"En mi casa hay un libro,\ndice la letra:\nen cuidados agenos\nnadie se meta.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,199,199,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0199-03",18,"Válgame Dios, mi vida,\nqué ingrata que eres,\nmil finezas me has hecho\ny una no quieres.",222,0,-1,226,"",6,4,"ee",55,0,-1,0,199,199,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0199-04",18,"Yo bien fuera constante,\npero me temo\nque me tengan por monstruo\nlas de mi sexô.",222,0,-1,226,"",6,4,"e",-1,0,-1,0,199,199,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0199-05",18,"Páxaro que á deshora\ndexas tu nido,\nsi le hallas ocupado,\nbien merecido.",222,0,-1,226,"",6,4,"io",101,0,-1,0,199,199,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0200-01",18,"No me mires, ingrata,\ncon tanto dengue,\nque si no tengo penas\nme haces que pene.",222,0,-1,226,"",6,4,"ee",-1,0,-1,0,200,200,"","",76,"rm_t2","","",2,0,0,[],"",""],["preciso_coleccion-p0200-02",18,"Propiedades de luna\ntiene mi amante,\npara un punto de aumento\nmuchos menguantes.",222,0,-1,226,"",6,4,"ae",-1,0,-1,0,200,200,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0200-03",18,"Al telar de Cupido\nmuchos acuden,\nunos traman la tela,\ny otros la urden.",222,0,-1,226,"",6,4,"ue",-1,0,-1,0,200,200,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0200-04",18,"Ya no voy á tu casa\ncon mis amores,\nporque allí pagan justos\npor pecadores.",222,0,-1,226,"",6,4,"oe",5,0,-1,0,200,200,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0200-05",18,"La dama que á uno quiere\ny á dos engaña,\ncastigarla, y que pierda\nla mala maña.",222,0,-1,226,"",6,4,"aa",213,0,-1,0,200,200,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0201-01",18,"Siempre rabio por verte,\ny si te veo,\nnunca puedo decirte\nlo que te quiero.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,201,201,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0201-02",18,"De tu vista me apartan\ncon poca razon,\nporque piensan ladrones\nque todos lo son.",222,0,-1,226,"",6,4,"o",31,0,-1,0,201,201,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0201-03",18,"A Dios, dueño del alma,\nque me retiro,\ndonde gastas la cera\ngasta el pavilo.",222,0,-1,226,"",6,4,"io",-1,0,-1,0,201,201,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0201-04",18,"¡O mal haya, mal haya\nmi cobardía,\nque por ser yo cobarde\ntú no eres mia!",222,0,-1,226,"",6,4,"a",0,0,-1,0,201,201,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0201-05",18,"Dime, dueño, si vivo\ndentro del alma,\nque no quiero gastemos\npólvora en salva.",222,0,-1,226,"",6,4,"aa",-1,0,-1,0,201,201,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0202-01",18,"El relox de tus gustos\nfuí yo, madama,\ny al fin me despediste\nporque no daba.",222,0,-1,226,"",6,4,"aa",-1,0,-1,0,202,202,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0202-02",18,"Amores escondidos\npor tiempo largo,\nsi en tragedia no acaban\nserá milagro.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,202,202,"","",76,"rm_t4, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0202-03",18,"Supuesto quieres, Fabio,\nquerer á Celia,\nno la quieras si quieres\nque ella te quiera.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,202,202,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0202-04",18,"Si el sueño á mí me rinde,\nsueño á mi dueño,\ny en mí se verifica\nla vida es sueño.",222,0,-1,226,"",6,4,"eo",138,0,-1,0,202,202,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0202-05",18,"A nadie te convides,\nque es grande daño,\nguárdate recatada,\nque el que es buen paño...",222,0,-1,226,"",6,4,"ao",40,0,-1,0,202,202,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0203-01",18,"De muchachos te fias\nen tus cariños,\nsin mirar que se dice\nque quien con niños...",222,0,-1,226,"",6,4,"io",625,0,-1,0,203,203,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0203-02",18,"Me dixiste burlando\nque era yo tu amor,\ny le dixe á mi sayo:\ná otro perro con...",222,0,-1,226,"",0,4,"o",-1,0,-1,0,203,203,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0203-03",18,"Siempre aguardo mi dicha\nmas nunca viene,\nya me aparto á buscarla,\nque quien va y tiene...",222,0,-1,226,"",6,4,"ee",70,0,-1,0,203,203,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0203-04",18,"Que no pare un instante\nmi amor me manda,\nbuscando mi fortuna,\npues quien no anda...",222,0,-1,226,"",6,4,"aa",502,0,-1,0,203,203,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0203-05",18,"Aunque mas dichas logres\nnunca las digas,\nporque nunca se logran\nlas dichas dichas.",222,0,-1,226,"",6,4,"ia",-1,0,-1,0,203,203,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0204-01",18,"Vil es quien de tus ojos\nteme el incendio,\npues su esplendor convida\ncon vida á un muerto.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,204,204,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0204-02",18,"No quiero pedir zelos\ná mi morena,\nporque sintiera mucho\nque me los diera.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,204,204,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0204-03",18,"Dame, niña, tus ojos\npor una noche,\nporque quiero con ellos\nmatar á un hombre.",222,0,-1,226,"",6,4,"oe",-1,0,-1,0,204,204,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0204-04",18,"Al principio de amarse\ndos corazones,\nnunca falta un demonio\nque los estorbe.",222,0,-1,226,"",6,4,"oe",-1,0,-1,0,204,204,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0204-05",18,"Son los enamorados\ncomo las bestias,\nque solo se mantienen\nde lo que piensan.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,204,204,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0205-01",18,"La calle está regada,\ndicen que ha sido\nlágrimas de un amante\nque han despedido.",222,0,-1,226,"",6,4,"io",101,0,-1,0,205,205,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0205-02",18,"Tengo un tiesto de rosas,\npara guardarlo\nno bastan las espinas\nni mi cuidado.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,205,205,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0205-03",18,"El ayre me las vuelve,\ny yo zeloso,\nporque no se deshojen\nyo me desojo.",222,0,-1,226,"",6,4,"oo",-1,0,-1,0,205,205,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0205-04",18,"Que mando en tu persona\nme dices, quando\ncon tus propias razones\nme estás quemando.",222,0,-1,226,"",6,4,"ao",33,0,-1,0,205,205,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0205-05",18,"Ausente te idolatro,\npenas se doblan,\nverdes son las cortinas\nde mi memoria.",222,0,-1,226,"",6,4,"oa",-1,0,-1,0,205,205,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0206-01",18,"Varios juicios se forman\nde nuestro trato,\npero hasta ahora ninguno\nha dado al blanco.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,206,206,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0206-02",18,"Siempre que juego pierdo,\ny así he pensado\nel hacer una trampa\npor ver si gano.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,206,206,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0206-03",18,"El alma me has robado,\ndame la tuya,\nque el ladron es preciso\nque restituya.",222,0,-1,226,"",6,4,"ua",111,0,-1,0,206,206,"","",76,"palau_cantares","","",5,0,0,[],"",""],["preciso_coleccion-p0206-04",18,"Yo no digo que juegues\ncon dos barajas,\nlo que sé es que á dos manos\nrepartes cartas.",222,0,-1,226,"",6,4,"aa",-1,0,-1,0,206,206,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0206-05",18,"Cinco cuerdas componen\nuna vihuela,\n¿y á quántos descompone\nsolo una cuerda?",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,206,206,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0207-01",18,"Quítate de delante\ncara de luna,\nque me dan tentaciones\nde atar la burra.",222,0,-1,226,"",6,4,"ua",-1,0,-1,0,207,207,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0207-02",18,"Trátame como quieras,\nno he de quejarme,\nque es preciso me quieras\ncomo me trates.",222,0,-1,226,"",6,4,"ae",-1,0,-1,0,207,207,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0207-03",18,"Si el preguntar es yerro\nquiero preguntar,\nbaxo de una esperanza\nsi habrá caridad.",222,0,-1,226,"",0,4,"a",-1,0,-1,0,207,207,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0207-04",18,"No hay cosa mas salada\nque las mugeres,\nni cosa mas ingrata\nque sus mercedes.",222,0,-1,226,"",6,4,"ee",-1,0,-1,0,207,207,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0207-05",18,"En ausencia se muestra\nlo que es cariño,\npues aunque siglos pasen\nreyna en el mio.",222,0,-1,226,"",6,4,"o",-1,0,-1,0,207,207,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0208-01",18,"La perdicion del hombre\nes una muger,\ny á veces el remedio\ntambien suele ser.",222,0,-1,226,"",0,4,"e",20,0,-1,0,208,208,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0208-02",18,"Quito las ocasiones,\nporque conozco\nque admitir las finezas\nes durar poco.",222,0,-1,226,"",6,4,"oo",-1,0,-1,0,208,208,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0208-03",18,"Un pastor me pretende\ny un hortelano,\nmas quiero vender leche\nque arrancar nabos.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,208,208,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0208-04",18,"Dicen que hay damas firmes,\nno sé qual sea,\npues la que no ha caido\nse bambolea.",222,0,-1,226,"",6,4,"ea",54,0,-1,0,208,208,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0208-05",18,"El amor y el cuchillo\nson dos extremos,\nmucho azero á la punta,\ny al cabo un cuerno.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,208,208,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0209-01",18,"Quatro cortejos tengo,\ny aun no hay bastantes\npara el tiempo que corre\ntan inconstante.",222,0,-1,226,"",6,4,"ae",-1,0,-1,0,209,209,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0209-02",18,"Si me quitan el verte,\nque es mi alimento,\nsuban al campanario,\ntoquen á muerto.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,209,209,"","",76,"rm_t2, rm_t3","","",3,0,0,[],"",""],["preciso_coleccion-p0209-03",18,"¿Para qué vas y vienes\ny vienes y vas?\notros con rondar menos\nalcanzarán mas.",222,0,-1,226,"",0,4,"a",51,0,-1,0,209,209,"","",76,"","","",7,0,0,[],"",""],["preciso_coleccion-p0209-04",18,"Acuérdate, bien mio,\nde aquella ocasion,\nque si tú bien estabas\nyo estuve mejor.",222,0,-1,226,"",6,4,"o",-1,0,-1,0,209,209,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0209-05",18,"La dama que á dos majos\nexpresa su amor,\nmerece que la saquen\nviva el corazon.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,209,209,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0210-01",18,"No es de majos discretos\ndos majas tener,\nque no se puede á un tiempo\nsoplar y sorber.",222,0,-1,226,"",0,4,"e",20,0,-1,0,210,210,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0210-02",18,"Te pido, dueño mio,\nque aunque esté ausente\nlibres á mi cabeza\nde algo que aumente.",222,0,-1,226,"",6,4,"ee",15,0,-1,0,210,210,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0210-03",18,"Contigo me dan vaya,\ndueño querido,\ncontigo me dan vaya,\nvaya contigo.",222,0,-1,226,"",6,4,"io",-1,0,-1,0,210,210,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0210-04",18,"Perro de muchas bodas\nme estas diciendo,\nquando tú eres la boda\nde tantos perros.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,210,210,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0210-05",18,"Que tienes muchos majos\ndicen que dices,\nmira quando reclames\nno halles perdices.",222,0,-1,226,"",6,4,"ie",113,0,-1,0,210,210,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0211-01",18,"Si mi madre quisiera\nlo que yo quiero,\ndias hace tuviera\nen casa un yerno.",222,0,-1,226,"",6,4,"eo",-1,0,-1,0,211,211,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0211-02",18,"Quarenta novias tengo,\nno amo á ninguna,\ny tendré si me quieres\nquarenta y una.",222,0,-1,226,"",6,4,"ua",56,0,-1,0,211,211,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0211-03",18,"Te quiero porque veas\nmi desinteres,\nque te quiero á tí sola,\ny tú á quantos ves.",222,0,-1,226,"",6,4,"e",-1,0,-1,0,211,211,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0211-04",18,"Como tú me llevaras\nadonde fueras,\nen yendo yo contigo\nmas que no vuelvas.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,211,211,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0211-05",18,"Haces por no mirarme\nla vista gorda:\n¿si quieres olvidarme\nquién te lo estorba?",222,0,-1,226,"",6,4,"oa",-1,0,-1,0,211,211,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0212-01",18,"Muchos hay que perdiendo\nsalen ganando,\npues quando pierden ganan\nun desengaño.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,212,212,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0212-02",18,"Mi voluntad es libre\npara qualquiera,\ny en viendo falsedades\ná fuera, á fuera.",222,0,-1,226,"",6,4,"ea",44,0,-1,0,212,212,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0212-03",18,"Aun del agua que bebes\ntengo yo envidia,\nmira si tendré zelos\nde quien te mira.",222,0,-1,226,"",6,4,"ia",-1,0,-1,0,212,212,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0212-04",18,"La pena de no verte\nme martiriza;\ny quando llego á verte\nDios nos asista.",222,0,-1,226,"",6,4,"ia",-1,0,-1,0,212,212,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0212-05",18,"Con quien pide ofreciendo\nno andes garbosa,\nque paga adelantada\npaga es viciosa.",222,0,-1,226,"",6,4,"oa",63,0,-1,0,212,212,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0213-01",18,"Unos cogen los mimbres,\notros los pelan,\notros hacen las cestas,\notros las llevan.",222,0,-1,226,"",6,4,"ea",-1,0,-1,0,213,213,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0213-02",18,"Hablando de mugeres\nme dixo un zote,\nsi se inclina á cortejos\nande el garrote.",222,0,-1,226,"",6,4,"oe",292,0,-1,0,213,213,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0213-03",18,"Unta, Juanillo, el exe,\nque chilla el carro,\nque hasta un leño insensible\ngusta de halagos.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,213,213,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0213-04",18,"Es la muger hoy dia\nbella y amable,\ntodas las gracias tiene,\nmenos constante.",222,0,-1,226,"",6,4,"ae",-1,0,-1,0,213,213,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0213-05",18,"Llora, gime, suspira,\nsiente, y al cabo\nlo que logra un amante\nes desengaños.",222,0,-1,226,"",6,4,"ao",-1,0,-1,0,213,213,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0214-01",18,"Ya no voy á tu casa,\njardin de flores,\nporque allí pagan justos\npor pecadores.",222,0,-1,226,"",6,4,"oe",5,0,-1,0,214,214,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0214-02",18,"Si en tus brazos me viera\nno mas que un poco,\nvieras de un loco cuerdo\nun cuerdo loco.",222,0,-1,226,"",6,4,"oo",152,0,-1,0,214,214,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0214-03",18,"Dando fin á mis ansias\nte quiero decir,\nno me olvides, bien mio,\nque yo hasta morir.",222,0,-1,226,"",0,4,"i",157,0,-1,0,214,214,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0215-01",18,"Ausentarme es preciso,\npero me queda\nel consuelo, bien mio,\nque quando vuelvas...",222,0,-1,227,"",6,4,"ea",-1,0,-1,0,215,215,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0215-02",18,"Aunque mas expresiones\nhagan contigo,\nno te fies, mi vida,\nque el mas amigo...",222,0,-1,227,"",6,4,"io",106,0,-1,0,215,215,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0215-03",18,"Por otro de tu gusto,\nniña, me dexas,\ny así se verifica\nque cada oveja...",222,0,-1,227,"",6,4,"ea",-1,0,-1,0,215,215,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0216-01",18,"A todos los pretendes\ncon rostro afable,\ny así se verifica\nque á buena hambre...",222,0,-1,227,"",6,4,"ae",-1,0,-1,0,216,216,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0216-02",18,"Mi amor no se complace\nsolo con verte,\nporque el adagio dice\nque quien mas tiene...",222,0,-1,227,"",6,4,"ee",-1,0,-1,0,216,216,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0216-03",18,"Aunque mas me acaricies\nno me convengo,\nque hay adagio que dice\nque al perro viejo...",222,0,-1,227,"",6,4,"eo",-1,0,-1,0,216,216,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0216-04",18,"Quien con pícaros anda,\npícaro será,\nporque un lobo á otro lobo\n¿qué le enseñará?",222,0,-1,227,"",0,4,"a",9,0,-1,0,216,216,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0216-05",18,"Entibióse un cariño\nconstante y noble,\nentibióse algun dia,\npero enti-vióse.",222,0,-1,227,"",6,4,"oe",-1,0,-1,0,216,216,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0217-01",18,"Casamiento con Filis\ntengo dispuesto,\nen casa no lo digo,\nque en casa-miento.",222,0,-1,227,"",6,4,"eo",-1,0,-1,0,217,217,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0217-02",18,"No está Amarilis mala\nde comer tierra,\nde lo que está amarilla\nes de amar ella.",222,0,-1,227,"",6,4,"ea",-1,0,-1,0,217,217,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0217-03",18,"Hay una dama puesta\nen la ventana,\npasa un galan y dice:\nay-una dama.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,217,217,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0217-04",18,"Dos amantes rendidos\nsurcan el agua,\nel uno veloz vuela,\ny el otro nada.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,217,217,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0217-05",18,"A la secansa juega\ncierta madama,\ny á medio juego dice\nque ya se-cansa.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,217,217,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0218-01",18,"Beata es la que adoro,\npero no santa,\nbeata porque á todos\nquantos vé-ata.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,218,218,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0218-02",18,"Apaga tus deseos,\nbella madama,\nno des como dan otras\ntu amor á paga.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,218,218,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0218-03",18,"Si utilidad no sacas\nde nuestra amistad,\nanda, ve con el otro,\nque es sutil y-da.",222,0,-1,227,"",0,4,"a",-1,0,-1,0,218,218,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0218-04",18,"Empeñada una dama\nen hallarme está,\nme llama con halagos,\npero en-peña-dá.",222,0,-1,227,"",0,4,"a",9,0,-1,0,218,218,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0218-05",18,"Serenada y con gusto\nbebes el agua,\nmira que si me olvidas,\nyo seré-nada.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,218,218,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0219-01",18,"Apagado me tienes,\nniña, á tu lado,\npues ninguno se arrima\nsi no ha-pagado.",222,0,-1,227,"",6,4,"ao",14,0,-1,0,219,219,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0219-02",18,"Bebí con sed el agua\nque me diste á mí,\ny despues de beberla\nlo que otro vé-ví.",222,0,-1,227,"",0,4,"i",23,0,-1,0,219,219,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0219-03",18,"Confianzas no quiero\ncon tus palabras,\nque de tí no me fio\nni aun con-fianzas.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,219,219,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0219-04",18,"Que de desdichas lleno\nme ví algun dia,\nya es tiempo, amor, ya es tiempo\nde que dés-dichas.",222,0,-1,227,"",6,4,"ia",-1,0,-1,0,219,219,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0219-05",18,"Es mi corazon fuego\nde vivas llamas,\nquanto mas agua le echan\nmas llamas-llama.",222,0,-1,227,"",6,4,"aa",-1,0,-1,0,219,219,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0220-01",18,"Tú vieras que te amaba\ncomo tuvieras,\nmas no comprendas que amo\nsino con-prendas.",222,0,-1,227,"",6,4,"ea",-1,0,-1,0,220,220,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0220-02",18,"Tédio dices te causa\nquien antes te amó,\neso acaso sería\nporque no te-dió.",222,0,-1,227,"",0,4,"o",2,0,-1,0,220,220,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0220-03",18,"Con tenerte en el alma\nansio por verte,\nno puedo contenerme,\nni aun con-tenerte.",222,0,-1,227,"",6,4,"ee",-1,0,-1,0,220,220,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0220-04",18,"Al campo salió Filis,\npisó un esparto,\nla dió un dolor y dixo:\nJesus ¡qué es-parto!",222,0,-1,227,"",6,4,"ao",697,0,-1,0,220,220,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0220-05",18,"Ayuno todo el año,\ny me consumo\nde ver que entro en tu casa,\ny siempre ay-uno.",222,0,-1,227,"",6,4,"uo",-1,0,-1,0,220,220,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0221-01",18,"No siento que en tu casa\nentre ó no entre,\nque se siente á tu lado\nsí que se-siente.",222,0,-1,227,"",6,4,"ee",-1,0,-1,0,221,221,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0221-02",18,"Apique fué mi nave\nporque te quise,\ny de haberte querido\nyo estuve á-pique.",222,0,-1,227,"",6,4,"ie",-1,0,-1,0,221,221,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0221-03",18,"Si piensas que á otro dueño\nsigue mi aficion;\nsuspende la malicia,\npues piensa el ladron...",222,0,-1,227,"",6,4,"ao",31,0,-1,0,221,221,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0221-04",18,"No blasones afectos\nde un amor tierno,\npues sabes que los niños\ncon qualquier juego...",222,0,-1,227,"",6,4,"eo",-1,0,-1,0,221,221,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0221-05",18,"Fementida fortuna,\ntu rueda esquiva\nmuchas veces ha hecho\nmi fé-mentida.",222,0,-1,227,"",6,4,"ia",-1,0,-1,0,221,221,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0222-01",18,"Fino fué mi cariño,\nfalso fué tu amor,\nbien dicen que la soga\nsiempre quiebra por...",222,0,-1,227,"",0,4,"o",72,0,-1,0,222,222,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0222-02",18,"No podrán tus desvíos\nborrar mi aficion,\ntú alevosa, yo fino,\ncada loco con..",222,0,-1,227,"",6,4,"o",31,0,-1,0,222,222,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0222-03",18,"Despues de tanta angústia\nsolo me queda\nsaber que la fortuna\nsu rueda rueda.",222,0,-1,227,"",6,4,"ea",266,0,-1,0,222,222,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0223-01",18,"Si de tu ausencia no muero,\ny con ella he de morir,\ndigan que soy en el mundo\nla muger mas infeliz.",222,0,-1,228,"",0,4,"i",-1,0,-1,0,223,223,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0223-02",18,"En el jardin de tu pecho\nsoy jardinero de amor,\ny quando mas le cultivo.\ntodo el fruto queda en flor.",222,0,-1,228,"",0,4,"o",72,0,-1,0,223,223,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0223-03",18,"Sin vida estoy de vivir\nla vida que estoy viviendo,\npues vivo, y no sé si vivo,\nporque no es vida, pues muero,",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,223,223,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0224-01",18,"- Yo cultivo tus favores,\naunque poco los disfruto:\n¿de qué sirve mi cuidado,\nsi sé que otro coge el fruto?",222,0,-1,228,"",0,4,"uo",327,0,-1,0,224,224,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0224-02",18,"Mas quisiera que al principio\nme hubieras aborrecido,\nque no hallarme apasionado\nde un bien que lloro perdido.",222,0,-1,228,"",0,4,"io",101,0,-1,0,224,224,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0224-03",18,"Algun dia bien te quise,\ny de quererte enfermé,\nvolví á tus ojos, y luego\nte mudaste, me mudé.",222,0,-1,228,"",0,4,"e",77,0,-1,0,224,224,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0224-04",18,"Una palabra me diste,\nla que no me cumplirás,\nmas yo cumpliré la mia\nde no olvidarte jamas.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,224,224,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0224-05",18,"Constante no te adoré?\ny fino no te serví?\nno hice quanto fué tu gusto?\npues por qué me olvidas? dí.",222,0,-1,228,"",0,4,"i",23,0,-1,0,224,224,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0225-01",18,"Opilada de desdenes\nme manda el Doctor tomar\naceros de desengaños,\nque obran bien y saben mal.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,225,225,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0225-02",18,"Tener miedo al escarmiento\nno es propio de quien bien ama,\nque el que bien á amar acierta,\nno pierde en perderse nada.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,225,225,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0225-03",18,"Tirana que de amor muere,\nno llame muerte al morir,\nque es morir por quien se adora\nel mas dichoso vivir.",222,0,-1,228,"",0,4,"i",157,0,-1,0,225,225,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0225-04",18,"Tal vez halla compasion,\nquien publica su dolencia:\nes raro el que ha conseguido\nsin pedir lo que desea.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,225,225,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0225-05",18,"En tu adoracion, bien mio,\nes víctima el rendimiento,\nholocausto la esperanza,\nsin que lo sepa el deseo.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,225,225,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0226-01",18,"He sabido ya quien eres,\ncon que cesan mis pesares,\nde mi devocion no esperes\nmas incienso en tus altares.",222,0,-1,228,"",1,4,"ae",164,0,-1,0,226,226,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0226-02",18,"Son tan breves los instantes\nque se disfrutan las dichas,\ncomo dilatado el tiempo\nque se tarda en conseguirlas.",222,0,-1,228,"",0,4,"ia",-1,0,-1,0,226,226,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0226-03",18,"Pues los cariños te ofenden,\nle pido á Dios de los Cielos,\nque de aquel á quien estimas\ntengas que sufrir desprecios.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,226,226,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0226-04",18,"Ya no vivo yo con gusto,\nya mi suerte se trocó,\nquien perdió lo que bien quiso,\nquanto hay que perder perdió.",222,0,-1,228,"",0,4,"o",2,0,-1,0,226,226,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0226-05",18,"Que segun sin mí te hallas,\npuedo llamar mis contentos\ncensos que son al quitar,\nque me los quitan tan presto.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,226,226,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0227-01",18,"De dos penas que ha querido\ndar amor á un desdichado,\nes el ser aborrecido\nmenor que ser olvidado.",222,0,-1,228,"",1,4,"ao",14,0,-1,0,227,227,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0227-02",18,"Con alas volaba amor\npor gozar del sol mas cerca,\ny el calor las derritió\ncomo si fueran de cera.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,227,227,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0227-03",18,"Perdida la tortolilla\nllora afligida en el monte,\nporque no espera cobrar\ná su perdido consorte.",222,0,-1,228,"",0,4,"oe",-1,0,-1,0,227,227,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0227-04",18,"Toda mi vida fué sustos,\ntoda penas, toda llantos;\ny siendo pocos los gustos,\nfueron los pesares tantos.",222,0,-1,228,"",1,4,"ao",618,0,-1,0,227,227,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0227-05",18,"No quiero mas amistades,\nquiero seguir mi opinion,\nque de pasion con extremos\nresulta una perdicion.",222,0,-1,228,"",0,4,"io",31,0,-1,0,227,227,"","",76,"lafuente_madrid, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0228-01",18,"Divino imposible mio,\n¿cómo es posible que viva\nquien como imposible te ama,\ny entre imposibles te mira?",222,0,-1,228,"",0,4,"ia",-1,0,-1,0,228,228,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0228-02",18,"Jamas pensé, vida mia,\nquererte como te quiero,\nquando me voy á acostar\nno puedo quajar el sueño.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,228,228,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0228-03",18,"De las potencias del alma\nla memoria es la cruel,\npues me causa el mayor mal,\nsi me acuerda el mayor bien.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,228,228,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0228-04",18,"Entre todos sus vasallos\nno ha conocido el amor\nmuger mas falsa que tú,\nni hombre mas fino que yo.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,228,228,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0228-05",18,"Entra el amor por los ojos,\ndeposítase en el pecho,\nle alimentan los oidos,\nmas le matan los desprecios.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,228,228,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0229-01",18,"Quiero vivir con quien quiero\npobre, humilde y abatido,\ny tus riquezas no quiero,\nsoberbio y engrandecido.",222,0,-1,228,"",1,4,"io",101,0,-1,0,229,229,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0229-02",18,"La que quiere ser amada,\nsin tener correspondencia,\nquiere conservar el fuego,\nsin la pension de hacer leña.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,229,229,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0229-03",18,"Lo que mas idolatraba\nde mi vista se ausentó:\nya no he de querer á nadie,\npues que todo me faltó.",222,0,-1,228,"",0,4,"o",2,0,-1,0,229,229,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0229-04",18,"Corazon, aunque te abrases,\nno mandes tocar á fuego,\nque el remedio suele ser\nel mas peligroso incendio.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,229,229,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0229-05",18,"Que bien dixo aquel que dixo,\nquejándose de los zelos,\nno hay cosa para el olvido\nque otro amor ó tierra en medio.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,229,229,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0230-01",18,"Quien diga que los amantes\nestán divertidos siempre,\nno debió de tener zelos,\nni estuvo jamas ausente.",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,230,230,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0230-02",18,"La fundacion del querer\ná mí me pueden llamar,\nporque he sido en tus amores\nla piedra fundamental.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,230,230,"","",76,"palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["preciso_coleccion-p0230-03",18,"Es un fuego de alquitran\neste en que me estoy ardiendo,\nque mas se aviva la llama,\nmientras mas lágrimas vierto.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,230,230,"","",76,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0230-04",18,"En la torre de mis gustos\nen lo mas alto me ví,\nlos cimientos fueron falsos,\notro subió, yo caí.",222,0,-1,228,"",0,4,"i",23,0,-1,0,230,230,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0230-05",18,"Ya no soy quien he sido,\nni quien yo solia ser,\nsoy un quadro de tristeza\narrimado á una pared.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,230,230,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0231-01",18,"Una soledad deseo\npara aliviar mis fatigas\nque allí regarán mis ojos\nplantas y flores marchitas.",222,0,-1,228,"",0,4,"ia",-1,0,-1,0,231,231,"","",76,"lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0231-02",18,"Acuérdate, aleve, quando\nmi mano á la tuya asida,\nme dixiste suspirando,\nquien bien quiere, tarde olvida.",222,0,-1,228,"",1,4,"ia",37,0,-1,0,231,231,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0231-03",18,"Una dama que yo adoro,\nsiempre me dice-esperanza,\nmas de qué me sirve el nombre,\nsi mi amor corre borrasca.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,231,231,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0231-04",18,"Desde que te ví te amé,\nporque amar y ver tu cielo\nbien pudieron ser dos cosas,\npero ninguna primero.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,231,231,"","",76,"lafuente_madrid","","",17,0,0,[],"",""],["preciso_coleccion-p0231-05",18,"Corazon, por qué estas triste,\npor qué enternecido sientes,\nsi quieres vivir, no quieras,\nsi quieres querer, ¿que quieres?",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,231,231,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0232-01",18,"Vé, pregonero, y dá voces,\npublicando mi dolor,\ná ver si encuentras alivio\ná tan terrible pasion.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,232,232,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0232-02",18,"Estoy tan bien con mi mal\ndesde que perdí mi bien,\nque el bien me parece mal,\ny el mal me parece bien.",222,0,-1,228,"",1,4,"e",-1,0,-1,0,232,232,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0232-03",18,"Triste el corazon se queja,\ny yo le pregunto triste:\ncorazon, ¿por qué te has muerto,\ny él responde: porque quise.",222,0,-1,228,"",0,4,"ie",-1,0,-1,0,232,232,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0232-04",18,"¿A quién le contaré yo\nlo que á mí me está pasando?\nse lo contaré á la tierra\nquando me estén enterrando.",222,0,-1,228,"",0,4,"ao",33,0,-1,0,232,232,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0232-05",18,"Corazon osado mio,\nyo no sé qué hacer con vos,\nque vos queréis que yo quiera,\ny no quiero querer yo.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,232,232,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0233-01",18,"Entre callar yo mi pena,\nó publicar mi dolor,\nsi la callo, no hay remedio,\nsi la digo, no hay pasion.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,233,233,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0233-02",18,"Todo el mundo me lo dice,\ndigo que tienen razon,\nque hombre que trata con muchas\ná ninguna tiene amor.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,233,233,"","",76,"rm_t3","","",14,0,0,[],"",""],["preciso_coleccion-p0233-03",18,"¿De qué sirve que yo quiera\ndisimular mi dolor,\nsi en los ojos y el semblante\nllevo escrita mi pasion?",222,0,-1,228,"",0,4,"o",-1,0,-1,0,233,233,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0233-04",18,"Empecemos, corazon,\ná padecer y penar,\npues adoro un imposible\nque no he de poder lograr.",222,0,-1,228,"",0,4,"a",21,0,-1,0,233,233,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0233-05",18,"Aunque padezca fatigas\ny sienta mi corazon,\nmas quiero en tí la esperanza\nque en otra la posesion.",222,0,-1,228,"",0,4,"o",31,0,-1,0,233,233,"","",76,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0234-01",18,"A un peñasco dí mis quejas\npor ver si me consolaba,\nque el que zeloso se mira,\nhasta con las peñas habla.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,234,234,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0234-02",18,"En los brazos de la noche,\npor vivir, quise morirme,\npues quien vive como yo,\nsolo quando duerme vive.",222,0,-1,228,"",0,4,"ie",-1,0,-1,0,234,234,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0234-03",18,"Con el dolor que yo vivo\nes imposible vivir,\nsi el mundo no da otra vuelta,\ndará de mi vida fin.",222,0,-1,228,"",0,4,"i",-1,0,-1,0,234,234,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["preciso_coleccion-p0234-04",18,"El amor mas imposible\nsuele ser el mas constante,\nque amor permanece poco\ndonde halla facilidades.",222,0,-1,228,"",0,4,"ae",-1,0,-1,0,234,234,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0234-05",18,"Para el dolor de un ausente\nno hay alivio ni consuelo,\nporque tiene cerca el daño\ny distantes los remedios.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,234,234,"","",76,"rm_t4, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0235-01",18,"A qué precio tan costoso\ndispones de mi amistad,\nsi una hora me das de gusto,\nme das ciento de pensar.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,235,235,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0235-02",18,"Favor, cielos, que me abraso\nen el volcan del amor,\ny el fuego de un imposible\nhace mi llama mayor.",222,0,-1,228,"",0,4,"o",72,0,-1,0,235,235,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0235-03",18,"Si piensas que porque callo\ntus sinrazones no entiendo,\nadvierte que aquel que calla\nhablará en llegando el tiempo.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,235,235,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0235-04",18,"Satisfacciones me pides,\nyo no te las quiero dar,\nque darte satisfacciones\nes volver á la amistad.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,235,235,"","",76,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0235-05",18,"Quien tiene muger hermosa,\ny viña en camino real,\nsi ha de coger solo el fruto.\nbien necesita velar.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,235,235,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0236-01",18,"Muger, llora y vencerás\nsi tu amante te desdeña,\nque hay un adagio que dice:\nlágrimas ablandan peñas.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,236,236,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0236-02",18,"Olvídame, pero advierte\nque soy piedra y puede ser\nque algun dia en mí tropieces,\ny en mí vuelvas á caer.",222,0,-1,228,"",0,4,"e",20,0,-1,0,236,236,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0236-03",18,"No te quejes, corazon,\nsufre la llama en que ardes:\nsupuesto que el mal quisiste,\nes preciso que lo pases.",222,0,-1,228,"",0,4,"ae",-1,0,-1,0,236,236,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0236-04",18,"Válgame Dios de los cielos,\n¿á donde me fuera yo\nque pudiera desechar\nesta enemiga pasion?",222,0,-1,228,"",0,4,"o",-1,0,-1,0,236,236,"","",76,"","","",33,0,0,[],"",""],["preciso_coleccion-p0236-05",18,"Las fatigas de un enfermo,\nquando está para morir,\nson las que paso, bien mio,\nquando me acuerdo de tí.",222,0,-1,228,"",0,4,"i",-1,0,-1,0,236,236,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0237-01",18,"¡O dulce suspiro mio,\nno quisiera mas de tí\nque hallarme donde te envio\nquando te apartas de mí!",222,0,-1,228,"",1,4,"i",23,0,-1,0,237,237,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0237-02",18,"Soñé que en brazos de amor\nestaba qual otro dueño,\ny al despertar sin la dicha\nhallé que la vida es sueño.",222,0,-1,228,"",0,4,"eo",138,0,-1,0,237,237,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0237-03",18,"Se remonta mi pasion,\npero temo la caida,\nque suele quien alto sube\nacabar con una ruina.",222,0,-1,228,"",0,4,"ia",-1,0,-1,0,237,237,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0237-04",18,"La naturaleza humana,\nsegun en sus hijos veo,\nparió gigante al deseo\ny á la posesion enana.",222,0,-1,228,"",11,4,"aa",4,0,-1,0,237,237,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0237-05",18,"No estaré jamas sin tí,\nque solo podrá el rigor\nsepararte de mis ojos,\nmas no de mi corazon.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,237,237,"","",76,"palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["preciso_coleccion-p0238-01",18,"Qué me importa que florezca\nel árbol de mi esperanza,\nsi se marchitan las flores,\ny jamas el fruto cuaja.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,238,238,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0238-02",18,"El feliz y el desdichado\nsuspiran con diferencia:\nunos publican sus gustos;\ny otros publican sus penas.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,238,238,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0238-03",18,"Dicen que el amor es gloria,\ny yo digo que es infierno,\npues siempre están los amantes\nen un continuo tormento.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,238,238,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0238-04",18,"Quien diga que ha enamorado\nsin sentir ni padecer,\nó ha sido siempre muy necio,\nó nunca ha querido bien.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,238,238,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0238-05",18,"Grande pena es el morir,\npero yo no la sintiera,\npues quien vive como yo\nde alegría le sirviera.",222,0,-1,228,"",0,4,"ea",44,0,-1,0,238,238,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0239-01",18,"¿Qué importa que tú me quieras\ny que yo te quiera á tí,\nsi lo que yo solicito\nno lo puedo conseguir?",222,0,-1,228,"",0,4,"i",-1,0,-1,0,239,239,"","",76,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0239-02",18,"Está tan acostumbrado\nmi corazon al veneno,\nque lo mismo que á otros mata,\nme sirve á mí de consuelo.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,239,239,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0239-03",18,"Triste el corazon me anuncia\nque hay en mi dueño traicion,\nque suele ser de un agravio\nastrólogo el corazon.",222,0,-1,228,"",0,4,"ao",-1,0,-1,0,239,239,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0239-04",18,"Todos mis cinco sentidos\nen tí los quise poner,\ncayóme tierra en los ojos,\npor mi mano me cegué.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,239,239,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0239-05",18,"Ya se acabó mi esperanza:\n¡triste desesperacion,\nque bueno es un desengaño\nquando llega la ocasion!",222,0,-1,228,"",0,4,"ao",-1,0,-1,0,239,239,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0240-01",18,"Mi corazon siente penas,\ny me las viene á contar,\ny yo digo que las calle\nque él tiene la culpa ya.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,240,240,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0240-02",18,"Querer por solo querer\nsin esperanza de premio;\nes amor bien desdichado,\npero es amor verdadero.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,240,240,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0240-03",18,"Quien ama correspondido\nno dexe de recelarse,\nque son los dias de gusto\nvísperas de los pesares.",222,0,-1,228,"",0,4,"ae",-1,0,-1,0,240,240,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0240-04",18,"Eché un candado á mi pecho\ndesde que ví tu belleza,\nporque ninguna entre en él\nsin que tú le des licencia.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,240,240,"","",76,"lafuente_madrid","","",2,0,0,[],"",""],["preciso_coleccion-p0240-05",18,"Mis penas me han consumido,\nme han sacado de mi ser,\nme veo tan abatido\nque no me basta el saber.",222,0,-1,228,"",1,4,"e",20,0,-1,0,240,240,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0241-01",18,"¿Huyes sin oir mis quejas?\nplegue á Dios que donde vas\ncomo me tratas te traten,\nsin que te quieran jamas.",222,0,-1,228,"",0,4,"a",51,0,-1,0,241,241,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0241-02",18,"A estos ojos que os adoran\nno los cerceneis por Dios\nel bien que en veros reciben,\nque es darles mortal dolor.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,241,241,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0241-03",18,"¿Quién verá, Venus divina,\ntu hermosura y gentileza,\nque no te dé por tributo\nmil vidas si las tuviera?",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,241,241,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0241-04",18,"Mis penas me han de matar,\nporque ya mi sufrimiento\nestá tan falto de fuerzas\nque casi á vivir no acierto.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,241,241,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0241-05",18,"En el fuego que me abraso,\ncomo la fragua es amor,\ncon agua nunca se apaga,\nantes crece con su ardor.",222,0,-1,228,"",0,4,"o",72,0,-1,0,241,241,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0242-01",18,"¿Como quieres que navegue\nun navío que está en calma?\n¿como es posible que viva\nun cuerpo que está sin alma?",222,0,-1,228,"",0,4,"aa",125,0,-1,0,242,242,"","",76,"","","",6,0,0,[],"",""],["preciso_coleccion-p0242-02",18,"Tan hecho á vivir penando\nestá mi fiel corazon,\nque creo si le faltara\nmoriria de dolor.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,242,242,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0242-03",18,"Ya no me asomo á la reja\nque me solia asomar,\nque me asomo á la ventana\nque cae á la soledad.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,242,242,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0242-04",18,"Permita Dios que te vea\nen un calabozo oscuro,\ny que pase por mi mano\ntodo el alimento tuyo.",222,0,-1,228,"",0,4,"uo",-1,0,-1,0,242,242,"","",76,"lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0242-05",18,"La maldicion que te echo\ndesde hoy en adelante\nes que los bienes te sobren,\npero que el gusto te falte.",222,0,-1,228,"",0,4,"ae",-1,0,-1,0,242,242,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0243-01",18,"Yo soy como aquel torillo\nque está en medio de una plaza,\nque despues que se halla herido\nva buscando su venganza.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,243,243,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0243-02",18,"Pensando en tí me dormí,\nhermosura de los cielos,\ny dispertando me hallé\nsin mí, sin tí y sin consuelo.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,243,243,"","",76,"","","",9,0,0,[],"",""],["preciso_coleccion-p0243-03",18,"Alma y vida te rendí,\ny todo por adorarte:\n¿qué quieres pedirme á mí\nsi ya no tengo que darte?",222,0,-1,228,"",1,4,"ae",8,0,-1,0,243,243,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0243-04",18,"Considera por tí propia\nsi en otros brazos me vieras,\ny tú me quisieras bien:\nen este lance ¿qué hicieras?",222,0,-1,228,"",0,4,"ea",103,0,-1,0,243,243,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0243-05",18,"Quando yo estaba en prisiones\nen lo que me entretenia\nera en escribir tu nombre\nen los ladrillos que habia.",222,0,-1,228,"",0,4,"ia",0,0,-1,0,243,243,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0244-01",18,"A la puerta de la cárcel\nno me vengas á llorar,\nya que no me quites penas,\nno me las vengas á dar.",222,0,-1,228,"",0,4,"a",21,0,-1,0,244,244,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0244-02",18,"Tú dexaste mi amistad\npor querer seguir tu rumbo,\nanda que presto verás\nel pago que te da el mundo.",222,0,-1,228,"",0,4,"uo",-1,0,-1,0,244,244,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0244-03",18,"Tengo oro, tengo plata\ny navíos en la mar,\ntengo el querer á mi gusto,\nno puedo desear mas.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,244,244,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0244-04",18,"Ahí tienes mi corazon,\nházmele dos mil pedazos,\nha de ser con condicion\nque he de morir en tus brazos.",222,0,-1,228,"",1,4,"ao",132,0,-1,0,244,244,"","",76,"","","",7,0,0,[],"",""],["preciso_coleccion-p0244-05",18,"Ingrata desconocida,\n¿cómo es que no reconoces\nla sangre que tienes mia,\nque te está llamando á voces?",222,0,-1,228,"",0,4,"oe",205,0,-1,0,244,244,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0245-01",18,"Si porque te quiero quieres\nque yo la muerte reciba,\nhágase tu voluntad,\nmuera yo porque otro viva.",222,0,-1,228,"",0,4,"ia",53,0,-1,0,245,245,"","",76,"isaacs_colombia","","",11,0,0,[],"",""],["preciso_coleccion-p0245-02",18,"Me aconsejan que te olvide,\nyo no te puedo olvidar,\ncomo no saben querer\nme vienen á aconsejar.",222,0,-1,228,"",0,4,"a",21,0,-1,0,245,245,"","",76,"","","",7,0,0,[],"",""],["preciso_coleccion-p0245-03",18,"El intentar imposibles\nes la fineza mayor,\nporque aquel que ama no teme,\nni supo amar quien temió.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,245,245,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0245-04",18,"Ven, muerte, tan escondida\nque no te sienta venir,\nporque el placer del morir\nno me vuelva á dar la vida.",222,0,-1,228,"",11,4,"ia",37,0,-1,0,245,245,"","",76,"carrizo_salta","","",7,0,0,[],"",""],["preciso_coleccion-p0245-05",18,"Solo el silencio testigo\npuede ser de mi tormento,\ny aun no cabe lo que siento\nen todo lo que no digo.",222,0,-1,228,"",11,4,"io",106,0,-1,0,245,245,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0246-01",18,"No digas nada á mi amante,\npues si acaso bien me quieres,\nel amor le dirá mas\nque lo que decirle puedes.",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,246,246,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0246-02",18,"Ausente del bien que adoro\nsin esperanza de verle,\nno puede haber para mí\nmas consuelo que la muerte.",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,246,246,"","",76,"palau_cantares, lafuente_madrid","","",10,0,0,[],"",""],["preciso_coleccion-p0246-03",18,"Mis amigos me desprecian\nporque me ven abatido:\ntodo el mundo corta leña\ndel árbol que está caido.",222,0,-1,228,"",0,4,"io",101,0,-1,0,246,246,"","",76,"rm_t4, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["preciso_coleccion-p0246-04",18,"En lo oscuro de un engaño\nviví aun estando muerto,\ny ahora me encuentro despierto\ná la luz de un desengaño.",222,0,-1,228,"",3,4,"ao",40,0,-1,0,246,246,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0246-05",18,"Una pena quita pena,\nun dolor quita dolor,\nun clavo saca otro clavo,\npero amor no quita amor.",222,0,-1,228,"",0,4,"o",72,0,-1,0,246,246,"","",76,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0247-01",18,"Permita Dios de los cielos\nque como me matas mueras,\ny que te vean mis ojos\nquerer sin que á tí te quieran:",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,247,247,"","",76,"palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["preciso_coleccion-p0247-02",18,"No puede haber mayor gloria\npara dos amantes pechos\ncomo el reunir sus cariños\nsin que intervengan los zelos.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,247,247,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0247-03",18,"No hay quien se ponga á razones\ncon los zelos; y á mi ver\ngente que razon no escucha,\nmuy necia debe de ser.",222,0,-1,228,"",0,4,"e",20,0,-1,0,247,247,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0247-04",18,"El amor todo lo puede\ndice un refran, y es así;\ntú me dices que no puedes,\nluego no hay amor en tí.",222,0,-1,228,"",0,4,"i",23,0,-1,0,247,247,"","",76,"rm_t3, lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0247-05",18,"Corazon mio, no llores,\nno llores ni tengas penas,\nque si tú pasas trabajos,\notros arrastran cadenas.",222,0,-1,228,"",0,4,"ea",62,0,-1,0,247,247,"","",76,"rm_t3","","",3,0,0,[],"",""],["preciso_coleccion-p0248-01",18,"Yo quiero bien, y no puedo\ndecir á quien quiero bien:\ntan solo diré que quiero\nsolo por solo querer.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,248,248,"","",76,"rm_t2, lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0248-02",18,"Quando te veo en la calle,\ny no me dices á Dios,\nen tormentos infernales\nse abrasa mi corazon.",222,0,-1,228,"",0,4,"o",-1,0,-1,0,248,248,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0248-03",18,"Te enojas quando te miro,\nsi no te miro te ofendes,\nde parte de amor te pido\nque me digas lo que quieres.",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,248,248,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0248-04",18,"¿Como ha de ser la memoria\nel correo en las ausencias,\nsi jamas da los recados\nni vuelve con las respuestas?",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,248,248,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0248-05",18,"Navegaba viento en popa\nla nave de mi esperanza,\npero en trocándose el ayre\ncon el desayre naufraga.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,248,248,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0249-01",18,"El pago mal merecido\nque tú me habias de dar\ndias ha que lo sabia,\nno me causa novedad.",222,0,-1,228,"",0,4,"a",-1,0,-1,0,249,249,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0249-02",18,"Ven acá, falso tirano,\npues que tan infiel me vendes,\n¿qué has ha llado mas que en mí\nen la dama que pretendes?",222,0,-1,228,"",0,4,"ee",552,0,-1,0,249,249,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0249-03",18,"El demonio de la corte\nen todo es particular,\npues allí hasta los maridos\nno son como en mi lugar.",222,0,-1,228,"",0,4,"a",21,0,-1,0,249,249,"","",76,"lafuente_madrid","","",2,0,0,[],"",""],["preciso_coleccion-p0249-04",18,"El querer que tú me tienes\nes piedra que cae de lo alto,\nque en una parte da el golpe,\ny á mí viene de rechazo.",222,0,-1,228,"",0,4,"ao",-1,0,-1,0,249,249,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0249-05",18,"Aunque te vea con otra\nno se me alborota el pecho,\nque se han de tomar las cosas\nconforme son los sugetos.",222,0,-1,228,"",0,4,"eo",-1,0,-1,0,249,249,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0250-01",18,"Tan ofendida me tienen\ntus obras y tus palabras,\nque aunque difunto te viera\nni agua bendita te echára.",222,0,-1,228,"",0,4,"aa",-1,0,-1,0,250,250,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0250-02",18,"Me ha engañado la confianza\nde que me querias bien,\ny en la mejor ocasion\nme diste pago cruel.",222,0,-1,228,"",0,4,"e",-1,0,-1,0,250,250,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0250-03",18,"Es verdad que te queria,\ny que remedio no tiene,\naunque lo padezca el alma\nvenga pues lo que viniere.",222,0,-1,228,"",0,4,"ee",-1,0,-1,0,250,250,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0250-04",18,"Yo te tengo de querer,\naunque le pese á mi estrella,\naunque contra mí se opongan\nayre, fuego, mar y tierra.",222,0,-1,228,"",0,4,"ea",-1,0,-1,0,250,250,"","",76,"","","",6,0,0,[],"",""],["preciso_coleccion-p0251-01",18,"Cinco sentidos tenemos,\ntodos los necesitamos,\ntodos cinco los perdemos\nquando nos enamoramos.",222,0,-1,229,"",1,4,"ao",116,0,-1,0,251,251,"","",76,"","","",8,0,0,[],"",""],["preciso_coleccion-p0251-02",18,"Muchos ofrecen partidas\nhasta lograr sus intentos,\ny en logrando luego dicen\nsi te he visto no me acuerdo.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,251,251,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0251-03",18,"La que permita cortejos\nno viva sin sobresalto,\nporque suele algun descuido\nengendrar nuevos cuidados.",222,0,-1,229,"",0,4,"ao",-1,0,-1,0,251,251,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0252-01",18,"A los árboles frutales\nse parecen los cortejos,\nque en cayéndose la hoja\nson espantajos del huerto.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,252,252,"","",76,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0252-02",18,"El que fuere pobre y solo\nno se meta á enamorar,\nporque la misma pobreza\nle hará oir, ver y callar.",222,0,-1,229,"",0,4,"a",21,0,-1,0,252,252,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0252-03",18,"Guárdate de mis suspiros\nsi los sientes caminar,\nporque llevan mucho fuego,\ny te pueden abrasar.",222,0,-1,229,"",0,4,"a",21,0,-1,0,252,252,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0252-04",18,"Porque te miro á la cara\nno por eso te he de amar,\nque muchos van á la feria\npor ver y no por comprar.",222,0,-1,229,"",0,4,"a",21,0,-1,0,252,252,"","",76,"rm_t3","","",2,0,0,[],"",""],["preciso_coleccion-p0252-05",18,"Contra veneno triaca,\nagua fria quando hay sed,\npara las sardinas vino,\npara el hombre la muger.",222,0,-1,229,"",0,4,"e",-1,0,-1,0,252,252,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0253-01",18,"Por el nombre que yo tengo\nque te digo la verdad,\nque el amor puesto en dos partes\nno tiene seguridad.",222,0,-1,229,"",0,4,"a",16,0,-1,0,253,253,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0253-02",18,"El que quiera vivir mucho\nha de huir lo mas que pueda\nde médicos y botica,\npepinos, melones y hembras.",222,0,-1,229,"",0,4,"ea",-1,0,-1,0,253,253,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0253-03",18,"El hombre que se enamora,\ny tiene poca prudencia,\nle vienen luego á dexar\ná la luna de Valencia.",222,0,-1,229,"",0,4,"ea",46,0,-1,0,253,253,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0253-04",18,"Siempre que miro al cangrejo\nme pongo á considerar,\nque se parece á mis dichas\nque caminan hácia tras.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,253,253,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0253-05",18,"Quando uno quiere á una,\ny esa una no le quiere,\nes lo mismo que encontrarse\nun calvo en la calle un peyne.",222,0,-1,229,"",0,4,"ee",-1,0,-1,0,253,253,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0254-01",18,"Si me quieren, sé querer,\nsi me olvidan, olvidar.\nsi me desprecian, desprecio,\nque aqueste es mi natural.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,254,254,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0254-02",18,"Si por beber de una fuente\nhas dexado secar otra,\nolvidar para querer\nesa es fantasía loca.",222,0,-1,229,"",0,4,"oa",-1,0,-1,0,254,254,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0254-03",18,"Yo conozco quien tenia\nun paxarillo en la mano,\ny por querer coger otro\nse le escapáron entrambos.",222,0,-1,229,"",0,4,"ao",-1,0,-1,0,254,254,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0254-04",18,"El médico me receta,\nviendo mi mal que es de amor,\nonza y media de escarmiento\ny de desengaños dos.",222,0,-1,229,"",0,4,"o",-1,0,-1,0,254,254,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0254-05",18,"Yo cómo de lo que cómo,\ny bebo lo que me dan,\npero masco algunas cosas\nque no las puedo tragar.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,254,254,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0255-01",18,"Ese corazon de perro\nte le quisiera arrancar\ny comérmele á pedazos,\nporque me has pagado mal.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,255,255,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0255-02",18,"Ven acá, falsa y refalsa,\nfalsa te vuelvo á decir,\nel dia que me vendiste\n¿quánto te dieron por mí?",222,0,-1,229,"",0,4,"i",-1,0,-1,0,255,255,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0255-03",18,"Es la muger en rigor\ncomo manjar con veneno,\nque lo dulce está por fuera,\ny lo amargo por adentro.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,255,255,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0255-04",18,"Algun dia querrá Dios\nque yo te encuentre en la calle,\najustarémos las cuentas,\ny el que debiere que pague.",222,0,-1,229,"",0,4,"ae",-1,0,-1,0,255,255,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0255-05",18,"Algun dia querrá Dios\nque tú caygas ó tropieces,\ny que yo sea la piedra\ndonde los sesos te dexes.",222,0,-1,229,"",0,4,"ee",-1,0,-1,0,255,255,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0256-01",18,"Si movido de tu amor\nhiciese algun desatino,\nno tienes que decir luego\nsi fué, si tornó, si vino.",222,0,-1,229,"",0,4,"io",199,0,-1,0,256,256,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0256-02",18,"En teniendo un peso duro\ny un buen querer á mi lado,\nno quiero ya mas gachares,\nya está mi cuerpo amparado.",222,0,-1,229,"",0,4,"ao",14,0,-1,0,256,256,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0256-03",18,"Mas quiero un jaleo pobre\ny unos pimientos asados,\nque no tener una usía\ndesaborida á mi lado.",222,0,-1,229,"",0,4,"ao",-1,0,-1,0,256,256,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0256-04",18,"El amor de mi mozuela\nyo no le puedo entender,\nque unas veces no me quiere,\ny otras no me puede ver.",222,0,-1,229,"",0,4,"e",20,0,-1,0,256,256,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0256-05",18,"En todas partes te pones\ná publicar tu querer,\ny si me vieras en la horca\nme tiraras de los pies.",222,0,-1,229,"",0,4,"e",-1,0,-1,0,256,256,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0257-01",18,"Quien se fie de las hembras,\ny en sus halagos creyere,\nsi no se ahorcase á sí mismo\nserá porque ellas lo hicieren.",222,0,-1,229,"",0,4,"ee",-1,0,-1,0,257,257,"","",76,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["preciso_coleccion-p0257-02",18,"Esclavo soy, pero cuyo\neso no lo diré yo,\npues cuyo soy me mandó\nno dixese que era suyo.",222,0,-1,229,"",11,4,"uo",78,0,-1,0,257,257,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0257-03",18,"Desde que usted se pasea\npor las calles del lugar\nestá perdida la venta\nde las cañas de pescar.",222,0,-1,229,"",0,4,"a",21,0,-1,0,257,257,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0257-04",18,"Esto es amor en los hombres\nser su lisura doblez,\nsus inocencias delitos,\n¡mal haya el amor, amen!",222,0,-1,229,"",0,4,"e",-1,0,-1,0,257,257,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0257-05",18,"El que fuere majo y pobre\nno busque maja bonita,\nporque en medio de sus gustos\nviene el rico y se la quita.",222,0,-1,229,"",0,4,"ia",50,0,-1,0,257,257,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0258-01",18,"La muger que encuentre un hombre\nfino, constante y leal,\nllévele por cosa rara\ná la historia natural.",222,0,-1,229,"",0,4,"a",1,0,-1,0,258,258,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0258-02",18,"Una vieja en la comedia\ntiró un soplo tan atroz,\nque apagó las candelillas\ny mató al apuntador.",222,0,-1,229,"",0,4,"o",-1,0,-1,0,258,258,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0258-03",18,"Para despedir á un hombre\nno es menester mala cara,\nse le dice con buen modo\nque se vaya noramala.",222,0,-1,229,"",0,4,"aa",-1,0,-1,0,258,258,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0258-04",18,"Los años y las mudanzas\ndexan á muchos sugetos,\ná unos calvos de cabeza,\ná otros calvos de dinero.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,258,258,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0258-05",18,"El que á título de rico\ncortéja mozas, y es viejo,\necha en el fondo perdido\nsu persona y el dinero.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,258,258,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0259-01",18,"Las mugeres se parecen\nen el amor á los gatos,\nque halagan con la cabeza,\ny destruyen con las manos.",222,0,-1,229,"",0,4,"ao",-1,0,-1,0,259,259,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0259-02",18,"Se parecen á la araña\nmuchas mugeres y mozas,\npues es su mayor cuidado\nandar buscando la mosca.",222,0,-1,229,"",0,4,"oa",-1,0,-1,0,259,259,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0259-03",18,"El que quiera en este mundo\nestar de arañazos libre,\nno haga fiestas á los gatos,\nni á las mugeres se arrime.",222,0,-1,229,"",0,4,"ie",-1,0,-1,0,259,259,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0259-04",18,"Amantes que siempre riñen,\ny que jamas escarmientan,\nen llegando á conformarse\n¡Dios te la depare buena!",222,0,-1,229,"",0,4,"ea",-1,0,-1,0,259,259,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0259-05",18,"Un vestido que he comprado\nme ha costado un dineral,\ny ahora que lo he estrenado\nno vale ni la mitad.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,259,259,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0260-01",18,"El que quiera en este mundo\ntener paz con su muger,\naunque vea muchas cosas\nha de hacer que no las ve.",222,0,-1,229,"",0,4,"e",-1,0,-1,0,260,260,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0260-02",18,"A las niñas de mis ojos\nlas tengo de castigar,\npara que sepan mis ojos\nde quien se han de enamorar.",222,0,-1,229,"",1,4,"a",21,0,-1,0,260,260,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0260-05",18,"De los trabajos del mundo\nyo no sé qual es mayor,\nsi el casarse ó el morirse,\nó el ser pobre; ¿que sé yo?",222,0,-1,229,"",0,4,"o",-1,0,-1,0,260,260,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0261-01",18,"Me quisiste, me olvidaste,\ny me volviste á querer,\nzapato que yo deshecho\nno me lo vuelvo á poner.",222,0,-1,229,"",0,4,"e",20,0,-1,0,261,261,"","",76,"","","",8,0,0,[],"",""],["preciso_coleccion-p0261-02",18,"De una voluntad tan sola\ntengo pendiente mi vida,\nmiren en qué breve instante\nla puedo tener perdida.",222,0,-1,229,"",0,4,"ia",37,0,-1,0,261,261,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0261-03",18,"De chiquita yo lloraba,\ny de grande tambien lloro;\nquando chiquita por teta,\ny ahora por el bien que adoro.",222,0,-1,229,"",3,4,"oo",85,0,-1,0,261,261,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0261-04",18,"Siempre pasear la calle,\nmirar y guiñar el ojo,\nentra y sale la criada,\nmuy malo anda este negocio.",222,0,-1,229,"",0,4,"oo",-1,0,-1,0,261,261,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0261-05",18,"Zapato que yo deshecho\ny le arrojo al muladar,\nque se lo ponga quien quiera\ná mí poco se me da.",222,0,-1,229,"",0,4,"a",-1,0,-1,0,261,261,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0262-01",18,"Me quisiste, me olvidaste,\nno me da pena maldita,\nque la mancha de una mora\ncon otra verde se quita.",222,0,-1,229,"",0,4,"ia",50,0,-1,0,262,262,"","",76,"","","",8,0,0,[],"",""],["preciso_coleccion-p0262-02",18,"El que corteja por pobre\nno tiene que pedir zelos,\nharto favor se le hace\nen quererle pelo á pelo.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,262,262,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0262-03",18,"Tengo de echar un cortejo\ncomo si fuera una gala,\ny en estando algo traido\nropa vieja á la criada.",222,0,-1,229,"",0,4,"aa",-1,0,-1,0,262,262,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0262-04",18,"Estando en gracia de Dios\nmaté á mi muger de un palo;\nsi esto es en gracia de Dios,\n¿que será en gracia del diablo?",222,0,-1,229,"",0,4,"ao",-1,0,-1,0,262,262,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0262-05",18,"A nadie habrá sucedido\nlo que á mí me sucedió,\nla primer noche de novio\nla cama se me quebró.",222,0,-1,229,"",0,4,"o",2,0,-1,0,262,262,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0263-01",18,"Las mocitas de esta corte\nson como las aceytunas,\nque aquella que está mas verde\nsuele ser la mas madura.",222,0,-1,229,"",0,4,"ua",-1,0,-1,0,263,263,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0263-02",18,"El amor de las mugeres\nle comparo con el perro,\nque aunque le sacudan palos\nnunca desampara el dueño.",222,0,-1,229,"",0,4,"eo",-1,0,-1,0,263,263,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0263-03",18,"Ayer me dixiste que hoy,\nhoy me dices que mañana,\ny mañana me dirás\nque me vaya enhoramala.",222,0,-1,229,"",0,4,"aa",-1,0,-1,0,263,263,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0264-01",18,"Pena que no se consiente,\nsiente dolor porque calla,\nhalla en el desasosiego\nsosiego si se declara.",222,0,-1,230,"",0,4,"aa",-1,0,-1,0,264,264,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0264-02",18,"De tu desden desespero;\nespero, y tú te retiras;\ntiras al corazon flechas\nhechas de violentas iras.",222,0,-1,230,"",0,4,"ia",295,0,-1,0,264,264,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0264-03",18,"Quando de tí se despide,\npide el corazon al pecho\nhecho pedazos aparte\nparte de sus sentimientos.",222,0,-1,230,"",0,4,"eo",-1,0,-1,0,264,264,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0265-01",18,"Engañado el pensamiento,\nmiento por ver si consigo:\nsigo aplicando remedios,\nmedios no los facilito.",222,0,-1,230,"",0,4,"io",-1,0,-1,0,265,265,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0265-02",18,"Del amor en las batallas\nhallas triunfante lo fino,\ny no vence nunca Marte\narte que enseñó Cupido.",222,0,-1,230,"",0,4,"io",-1,0,-1,0,265,265,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0265-03",18,"Se trataban los amantes\nántes con menos recelos:\nzelos vivos indisponen,\nponen á vista el tormento.",222,0,-1,230,"",0,4,"eo",-1,0,-1,0,265,265,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0265-04",18,"Dime si tal desconsuelo\nconsuelo tendrá en amar:\nmar ha sido mi fortuna,\nuna suerte y un azar.",222,0,-1,230,"",0,4,"a",21,0,-1,0,265,265,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0265-05",18,"Que á mi fé no correspondes\nrespondes con voz altiva,\ny va faltando en tal calma\nalma para el que suspira.",222,0,-1,230,"",0,4,"ia",-1,0,-1,0,265,265,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0266-01",18,"Si logró mi sentimiento\nsolo quitarme el sentido,\n¿qué consigo con sentir\nni con haber consentido",222,0,-1,230,"",0,4,"io",101,0,-1,0,266,266,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0266-02",18,"Llorando noches y dias\ndoy á mis ojos enojos,\ncomo si fueran mis ojos\ncausa de las penas mias.",222,0,-1,230,"",11,4,"a",214,0,-1,0,266,266,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0266-03",18,"Yo sé los pasos que traes:\ntu boca á mí me desmiente:\nándate en este camino:\ncántaro que va á la fuente...",222,0,-1,230,"",0,4,"ee",15,0,-1,0,266,266,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0266-04",18,"Bien sé que vas á funciones:\nte aseguro que lo siento,\nporque suelen decir muchos\nque siempre á rio revuelto...",222,0,-1,230,"",0,4,"eo",-1,0,-1,0,266,266,"","",76,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["preciso_coleccion-p0266-05",18,"Por querer á otro consorte\nte olvidaste de mi amor;\nno es urbanidad sublime\ndesnudar á un santo por...",222,0,-1,230,"",0,4,"o",72,0,-1,0,266,266,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0267-01",18,"Algun dia querrá Dios\nque alguno de sí te arroje,\ny te digas á tí misma\nquien bien tiene y mal escoge...",222,0,-1,230,"",0,4,"oe",503,0,-1,0,267,267,"","",76,"palau_cantares","","",5,0,0,[],"",""],["preciso_coleccion-p0267-02",18,"Porque te quiero mi gente\nestá con notable pena,\ny con sobrada razon\nme dicen que cada oveja...",222,0,-1,230,"",0,4,"ea",-1,0,-1,0,267,267,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0267-03",18,"Por todas tus propiedades\npeligras si no la dexas,\nporque todas las mugeres\ndicen que quanto mas viejas...",222,0,-1,230,"",0,4,"ea",-1,0,-1,0,267,267,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0267-04",18,"Bien sé que otro amante tienes\nmas propio á tu natural,\npero tiene un no sé que;\nmas en fin tal para qual.",222,0,-1,230,"",0,4,"a",1,0,-1,0,267,267,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0267-05",18,"De ser firme y muy constante\nme hicistes un juramento;\npero en tí no me fio,\nque dicen, quien hizo un cesto...",222,0,-1,230,"",0,4,"eo",-1,0,-1,0,267,267,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0268-01",18,"Sin que puedas agraviarte\nme he de olvidar de tu amor,\npara que pueda decir\nla gala del nadador...",222,0,-1,230,"",0,4,"o",72,0,-1,0,268,268,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0268-02",18,"Bien sé con quien vas á misa,\ny quien tu persona manda;\nsin llegar á conocer\nque quien entre lobos anda...",222,0,-1,230,"",0,4,"aa",502,0,-1,0,268,268,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0268-03",18,"Señora, mis tristes quejas\nhoy á tu ingratitud llaman:\nóyelas con atencion,\nque quando los mudos hablan...",222,0,-1,230,"",0,4,"aa",-1,0,-1,0,268,268,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0268-04",18,"Si entiendes que son ganancias\nel tener á muchos ley,\nmira que son ignorancias,\npues díme ¿donde irá el buey?...",222,0,-1,230,"",1,4,"e",133,0,-1,0,268,268,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0268-05",18,"Tú quieres que yo te quiera;\nyo no quiero, que he mirado\naquel adagio que dice:\nniña, que el gato escaldado...",222,0,-1,230,"",0,4,"ao",14,0,-1,0,268,268,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0269-01",18,"De todas mis pretensiones\nnada sacaré yo al fin,\ny si con nada pagases,\ndiré al fin, que á gente ruin...",222,0,-1,230,"",0,4,"i",211,0,-1,0,269,269,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0269-02",18,"De que tengo de olvidarte\nes lo que á tí te desvela:\nno vives muy engañada,\nque siempre aquel que recela...",222,0,-1,230,"",0,4,"ea",167,0,-1,0,269,269,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0269-03",18,"Yo me retiro, señora,\nde este tu esquivo desden:\nanda por donde quisieres,\nque á bien que ojos que no ven...",222,0,-1,230,"",0,4,"e",242,0,-1,0,269,269,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0269-04",18,"Ahora que fino te adoro,\nprocuras que yo me corra:\nyo te juro por quien soy\nque no hace tanto la zorra...",222,0,-1,230,"",0,4,"oa",461,0,-1,0,269,269,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0269-05",18,"Por Dios te digo, señora,\nque mitigues ese ardor,\ny cúmplase aquel adagio\nque dice: amor con amor...",222,0,-1,230,"",0,4,"o",72,0,-1,0,269,269,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0270-01",18,"Ni tú comes, ni yo cómo,\ntodo el dia estás rabiando\ny así es que haces el oficio\ndel perro del hortelano...",222,0,-1,230,"",0,4,"ao",-1,0,-1,0,270,270,"","",76,"","","",2,0,0,[],"",""],["fernan_caballero-p0208-01",19,"Mira que te mira Dios,\nmira que te está mirando,\nmira que te has de morir,\nmira que no sabes cuándo.",223,0,35,231,"",0,4,"ao",33,0,-1,0,208,208,"","",0,"rm_t4, lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0208-02",19,"Sufre, si quieres gozar;\nbaja, si quieres subir;\npierde, si quieres ganar;\nmuere, si quieres vivir.",223,0,35,231,"",1,4,"i",157,0,-1,0,208,208,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0208-03",19,"Nacer sin querer nacer,\nsin quererlo padecer;\nvivir sin querer vivir,\nmorir sin querer morir.",223,0,35,231,"",5,4,"i",157,0,-1,0,208,208,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0208-04",19,"Todos sujetos estamos,\nporque Aquel que nos crió,\ntan sólo para salvarnos,\nel libre albedrío nos dió.",223,0,35,231,"",0,4,"o",2,0,-1,0,208,208,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0208-05",19,"Yo no le temo á la muerte,\nque la muerte es natural;\nsólo le temo á la cuenta\nque á Dios le tengo que dar.",223,0,35,231,"",0,4,"a",-1,0,-1,0,208,208,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0209-01",19,"Acuérdate, pecador,\nque tu vida es una luz,\ny que tú puedes morir\nantes que digas: ¡Jesús!",223,0,35,231,"",0,4,"u",270,0,-1,0,209,209,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0209-02",19,"Desde el día que nacemos\ná la muerte caminamos:\nno hay cosa que más se olvide\ny que más cierta tengamos.",223,0,35,231,"",0,4,"ao",116,0,-1,0,209,209,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0209-03",19,"Aquel que tiene tres viñas\ny el tiempo le quita dos,\nconténtese con la una,\ny dele gracias á Dios.",223,0,35,231,"",0,4,"o",87,0,-1,0,209,209,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0209-04",19,"Sufre con ánimo igual,\nalma, lo que más lastima;\nque la más áspera lima\nlimpia mejor el metal.",223,0,35,231,"",11,4,"a",1,0,-1,0,209,209,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0209-05",19,"La pena más excesiva\nque los condenados sienten,\nes aquella voz que grita:\n¡para siempre, para siempre!",223,0,35,231,"",0,4,"ee",-1,0,-1,0,209,209,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0209-06",19,"Yo no le temo á la muerte,\naunque la encuentre en la calle;\nque sin licencia de Dios,\nla muerte no mata á nadie.",223,0,35,231,"",0,4,"ae",-1,0,-1,0,209,209,"","",0,"lafuente_madrid","","",12,0,0,[],"",""],["fernan_caballero-p0209-07",19,"A San Antonio le pido\nque me dé conformidad,\nque los bienes de este mundo\nDios los quita y Dios los da.",223,0,35,231,"",0,4,"a",-1,0,-1,0,209,209,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0210-01",19,"No ama mucho quien lo dice,\nsino quien mucho padece,\nporque amor sin penas y obras,\nde amor sólo el nombre tiene.",223,0,35,231,"",0,4,"ee",-1,0,-1,0,210,210,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0210-02",19,"Hazte guerra y tendrás paz:\nciega y hallarás la luz.\n¿Quieres gloria? Ansía por Cruz.\nSé simple, y serás la paz.",223,0,35,231,"",11,4,"a",-1,0,-1,0,210,210,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0210-03",19,"Si al Sumo Bien te has de unir,\nsu voz interior atiende,\npues lo que tu Dios pretende\nes que le quieras oir.",223,0,35,231,"",11,4,"o",157,0,-1,0,210,210,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0210-04",19,"Por divino adoro á Dios\ny lo admiro por perfecto;\npor bondadoso lo amo,\npor justiciero le temo.",223,0,35,231,"",0,4,"eo",-1,0,-1,0,210,210,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0210-05",19,"Borda el Oriente de luz\ncuando asoma linda estrella\ná adorar ante la cruz\nal que fué clavado en ella.",223,0,35,231,"",1,4,"ea",6,0,-1,0,210,210,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0210-06",19,"Los moros de Berbería\ndicen que no puede ser\nparir y quedar doncella\nla esposa de San José.",223,0,35,231,"",0,4,"e",-1,0,-1,0,210,210,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0210-07",19,"Si supieran la doctrina\nque enseña el Santo Evangelio,\nsupieran cómo María\nfué madre y Virgen á un tiempo.",223,0,35,231,"",0,4,"eo",-1,0,-1,0,210,210,"","",0,"lafuente_madrid","","",2,0,0,[],"",""],["fernan_caballero-p0211-01",19,"En Abril llueve bastante;\nlas aguas no son dañinas,\nque las manda el Criador\npara que salga la espiga.",223,0,35,231,"",0,4,"ia",-1,0,-1,0,211,211,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0211-02",19,"El primer día de Mayo,\nen punto de medio día,\ná visitar los sembrados\nsalen Jesús y María.",223,0,35,231,"",0,4,"ia",0,0,-1,0,211,211,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0211-03",19,"Se paran de trecho en trecho,\nles echan su bendición,\nmandan que corran los vientos\npara dar la granazón.",223,0,35,231,"",0,4,"o",31,0,-1,0,211,211,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0211-04",19,"En llegando el mes de Junio,\nme da mi Dios la licencia\npara que pueda segar\nde los campos la cosecha.",223,0,35,231,"",0,4,"ea",-1,0,-1,0,211,211,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0211-05",19,"Por la voluntad divina,\nla que á todos nos mantiene,\ny la ayuda de los hombres,\nson recogidas las mieses.",223,0,35,231,"",0,4,"ee",-1,0,-1,0,211,211,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0211-06",19,"No hay nombre como Manuel,\nni mujer como María;\namor como amor de madre,\nni luz como la del día.",223,0,35,231,"",0,4,"ia",0,0,-1,0,211,211,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0211-07",19,"Todos los días del año\nse dice una misa en Roma,\nque la dice el Padre Santo\ny la ayuda una paloma (1).",223,0,35,231,"",0,4,"oa",86,0,-1,0,211,211,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0212-01",19,"Dicen que la golondrina\ntiene la pechuga blanca,\ny yo digo que María\nfué concebida sin mancha.",223,0,35,231,"",0,4,"aa",-1,0,-1,0,212,212,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",12,0,0,[],"",""],["fernan_caballero-p0212-02",19,"¡Ay! Madre de los remedios,\nmadre de los afligidos,\nlos trigos se van secando,\nmanda tu santo rocío.",223,0,35,231,"",0,4,"io",-1,0,-1,0,212,212,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0212-03",19,"Vengan, vengan en mi ayuda\nlos inocentes corderos\nque degolló el fiero Herodes\ncon un cuchillo de acero.",223,0,35,231,"",0,4,"eo",-1,0,-1,0,212,212,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0212-04",19,"Los profetas y patriarcas\ny los mártires queremos,\nque son nuestros protectores\ny de Dios los mensajeros.",223,0,35,231,"",0,4,"eo",-1,0,-1,0,212,212,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0212-05",19,"A las ánimas benditas\nnadie les cierre la puerta;\ncon decirles que perdonen\nvan las ánimas contentas (1).",223,0,35,231,"",0,4,"ea",-1,0,-1,0,212,212,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0212-06",19,"En el cielo no hay faroles,\nque todas son estrellitas.\n¡Qué bien parece, señores,\nla honestidad en las mocitas\ny la razón en los hombres!",223,0,35,231,"",7,5,"oe",-1,0,-1,0,212,212,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0213-01",19,"Como del cielo el rocío,\ncaiga en mí tu bendición,\ny nacerán las virtudes\ncomo en el campo la flor.",223,0,35,231,"",0,4,"o",-1,0,-1,0,213,213,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0213-02",19,"Un árbol hay en la iglesia\ncon espinas y sin flor (1);\nen cada ramita un ángel,\nen medio, Nuestro Señor.",223,0,35,231,"",0,4,"o",72,0,-1,0,213,213,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0213-03",19,"La piedad de Dios nos dé\nlo que pedimos con fe:\nla paz, el pan, la paciencia,\ny muerte con penitencia.",223,0,35,231,"",5,4,"ea",46,0,-1,0,213,213,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0213-04",19,"El sagrario está abierto\nvamos llegando,\nque la mesa está puesta,\nDios convidando.",223,0,35,231,"",6,4,"ao",33,0,-1,0,213,213,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0213-05",19,"En lo alto del cielo\nsuenan clarines,\ncoronando á María\nlos serafines.",223,0,35,231,"",6,4,"ie",272,0,-1,0,213,213,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0213-06",19,"Un loquito del hospicio\nme dijo en una ocasión:\nni son todos los que están,\nni están todos los que son.",223,0,35,231,"",0,4,"o",31,0,-1,0,213,213,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0214-01",19,"Veinticinco pesetas\nson cien reales;\nen faltando un ochavo,\nno están cabales.",223,0,35,231,"",6,4,"ae",26,0,-1,0,214,214,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0214-02",19,"El que siembre alcachofas,\nespinas coge;\nel que cría colmenas,\nla miel se come.",223,0,35,231,"",6,4,"oe",-1,0,-1,0,214,214,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0214-03",19,"La mujer que no come\ncon su marido,\nlo mejor de la olla\nse lo ha comido.",223,0,35,231,"",6,4,"io",101,0,-1,0,214,214,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0214-04",19,"Compañerita del alma,\ndiga usted lo que yo digo:\nque el que no sabe leer,\n¿para qué quiere los libros?",223,0,35,231,"",0,4,"io",-1,0,-1,0,214,214,"","",0,"","","",20,0,0,[],"",""],["fernan_caballero-p0214-05",19,"Desciendes de mala rama,\nno lo puedes remediar;\nlas mujeres y caballos\npor casta se han de buscar.",223,0,35,231,"",0,4,"a",21,0,-1,0,214,214,"","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0214-06",19,"No te cases con viejo\npor la moneda;\nla moneda se gasta,\ny el viejo queda.",223,0,35,231,"",6,4,"ea",266,0,-1,0,214,214,"","",0,"palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0214-07",19,"—¿Qué son celos?—pregunta\nun hombre sabio;\ny un rústico responde:\n—Ama y sabráslo.",223,0,35,231,"",6,4,"ao",-1,0,-1,0,214,214,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0215-01",19,"Le pueden quitar á un rey\nsu corona y sus estados;\nmas no le pueden quitar\nla gloria de haber reinado.",223,0,35,231,"",0,4,"ao",-1,0,-1,0,215,215,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0215-02",19,"Semejan esperanzas\ná los laureles;\nsin darle fruto á nadie,\nsiempre están verdes.",223,0,35,231,"",6,4,"ee",-1,0,-1,0,215,215,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0215-03",19,"No quieras casa caída,\nni paredes derrumbadas,\nni casamiento á disgusto;\ndonde no hay gusto no hay nada.",223,0,35,231,"",0,4,"aa",-1,0,-1,0,215,215,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0215-04",19,"En una alforja al hombro\nllevo los vicios;\ndelante los ajenos,\ndetrás los míos.",223,0,35,231,"",6,4,"io",-1,0,-1,0,215,215,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0215-05",19,"¿Te quieres poner conmigo?\nle dijo el tiempo al querer;\nesa soberbia que tienes\nyo te la castigaré.",223,0,35,231,"",0,4,"e",-1,0,-1,0,215,215,"","",0,"rm_t4","","",4,0,0,[],"",""],["fernan_caballero-p0215-06",19,"Cuando la perdiz canta\nnublado viene;\nno hay más señal de agua\nque cuando llueve.",223,0,35,231,"",6,4,"ee",-1,0,-1,0,215,215,"","",0,"rm_t4","","",4,0,0,[],"",""],["fernan_caballero-p0215-07",19,"¿Quieres vivir sin afanes?\ndeja la bola rodar;\nque lo que fuere de Dios\ná las manos se vendrá.",223,0,35,231,"",0,4,"a",-1,0,-1,0,215,215,"","",0,"rm_t4","","",3,0,0,[],"",""],["fernan_caballero-p0216-01",19,"Esperar y no venir,\nquerer y que no lo quieran,\nacostarse y no dormir,\n¿cuál será la mayor pena?",223,0,35,231,"",0,4,"ea",-1,0,-1,0,216,216,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0216-02",19,"Ninguno cante victoria\naunque en el estribo esté,\nque muchos en el estribo\nse suelen quedar á pie.",223,0,35,231,"",0,4,"e",77,0,-1,0,216,216,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",7,0,0,[],"",""],["fernan_caballero-p0216-03",19,"Las nubes las destruye\nun viento recio;\nasí á una tertulia\nla acaba un necio.",223,0,35,231,"",6,4,"eo",276,0,-1,0,216,216,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0216-04",19,"El secreto de tu pecho\nno se lo des á tu amigo,\nque si la amistad quebrare,\nte ha de servir de testigo.",223,0,35,231,"",0,4,"io",106,0,-1,0,216,216,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0216-05",19,"Ser rico y ser avariento\nuna misma cosa es,\nporque nunca se separa\nla codicia del tener.",223,0,35,231,"",0,4,"e",-1,0,-1,0,216,216,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0216-06",19,"Amiga, la más amiga,\namiga del corazón,\nla más amiga la pega\nen llegando la ocasión.",223,0,35,231,"",0,4,"o",31,0,-1,0,216,216,"","",0,"rm_t4","","",5,0,0,[],"",""],["fernan_caballero-p0216-07",19,"En la isla de León\nse pesca con hilo y caña;\npor la boca muere el pez:\ncuenta con lo que se habla.",223,0,35,231,"",0,4,"aa",-1,0,-1,0,216,216,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0217-01",19,"Nunca compres mula coja\npensando que sanará,\npues si las sanas cojean,\nlas cojas, ¿qué es lo que harán?",223,0,35,231,"",0,4,"a",-1,0,-1,0,217,217,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0217-02",19,"Alerta, alerta, mozuelas,\nque el hombre no sufre daño;\nen sacudiendo la capa,\ncáese el polvo y queda el paño.",223,0,35,231,"",3,4,"ao",40,0,-1,0,217,217,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0217-03",19,"El que presume de honra\nes porque carece de ella;\naquel que no tiene capa,\nse acuerda de Grazalema (1).",223,0,35,231,"",0,4,"ea",-1,0,-1,0,217,217,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0217-04",19,"La mujer que se enamora\nde la ropa, y no del hombre,\nno tiene vergüenza en cara,\nporque la ropa se rompe.",223,0,35,231,"",0,4,"oe",-1,0,-1,0,217,217,"","",0,"rm_t4, lafuente_madrid, palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0217-05",19,"En ningún hombre casado\npongas nunca tu querer,\nque al fin y á la por partida\nse los lleva su mujer.",223,0,35,231,"",0,4,"e",20,0,-1,0,217,217,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0217-06",19,"Nadie ponga su viña\njunto al camino,\nporque todo el que pasa\ncoge un racimo.",223,0,35,231,"",6,4,"io",-1,0,-1,0,217,217,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0217-07",19,"Cuando yo tenía dinero\nme llamaban don Tomás,\ny ahora que no lo tengo\nme llaman Tomás no más.",223,0,35,231,"",0,4,"a",51,0,-1,0,217,217,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0218-01",19,"No adelantes el discurso\nsino para pensar bien,\nque á veces nos discurrimos\nlo que no ha sido ni es.",223,0,35,232,"",0,4,"e",-1,0,-1,0,218,218,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0218-02",19,"Hasta la leña del campo\ntiene su separación:\nuna sirve para santos\ny otra para hacer carbón.",223,0,35,232,"",0,4,"o",31,0,-1,0,218,218,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0218-03",19,"Aquel que empieza una obra\nrazón será que la acabe,\npara que nunca se diga\nque la dejó por cobarde.",223,0,35,232,"",0,4,"ae",-1,0,-1,0,218,218,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0218-04",19,"Entre mi oficial y yo\nhicimos este retablo;\nsi está bueno, lo hice yo,\ny mi oficial si está malo.",223,0,35,232,"",0,4,"ao",-1,0,-1,0,218,218,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0218-05",19,"Cásate con un pastor,\ny te llamarán pastora;\ncásate con un señor,\ny te llamarán señora.",223,0,35,232,"",1,4,"oa",107,0,-1,0,218,218,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0219-01",19,"Ni fíes ni desconfíes,\nni hijos ajenos críes,\nni pongas viñas, ni domes potro,\nni tu mujer enseñes á otro.",223,0,35,232,"",3,4,"oo",275,0,-1,0,219,219,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0219-02",19,"Nadie diga bien estoy,\nporque yo he solido estar\nen casa de balconaje,\ny ahora vivo en un solar.",223,0,35,232,"",3,4,"a",21,0,-1,0,219,219,"","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0219-03",19,"Más quisiera en una plaza\ná un toro bravo esperar,\nque no á una mujer que diga:\n¡Qué cuidado se me da!",223,0,35,232,"",0,4,"a",-1,0,-1,0,219,219,"","",0,"rm_t4, lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0219-04",19,"Unta el eje, Juanillo,\nque chilla el carro;\nque hasta lo inanimado\ngusta de halagos.",223,0,35,232,"",6,4,"ao",-1,0,-1,0,219,219,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0219-05",19,"Nadie diga en este mundo:\nDe este agua no beberé;\npor muy turbia que la vea,\nle puede apretar la sed.",223,0,35,232,"",0,4,"e",-1,0,-1,0,219,219,"","",0,"lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0219-06",19,"Aquel que más alto sube\nmás grande porrazo da;\nmira la puente de Arcos\nen lo que vino á parar.",223,0,35,232,"",0,4,"a",-1,0,-1,0,219,219,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0219-07",19,"Si fueres á buscar novia,\nque no sea en romería,\nsino en casa de su padre,\ncon ropita de aquel día.",223,0,35,232,"",0,4,"ia",0,0,-1,0,219,219,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0220-01",19,"¡Ay! ¡Desgraciado de aquel\nque pone su cara en tierra;\nque el que queda por acá,\ntarde ó temprano se alegra!",223,0,35,232,"",0,4,"ea",-1,0,-1,0,220,220,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0220-02",19,"Todo lo puede el amor,\ntodo el dinero lo vence,\ntodo lo consume el tiempo,\ntodo lo acaba la muerte.",223,0,35,232,"",0,4,"ee",-1,0,-1,0,220,220,"","",0,"lafuente_madrid, rm_t4","","",3,0,0,[],"",""],["fernan_caballero-p0220-03",19,"En tu vida, de nadie\ndádivas tomes,\ny con eso te excusas\nde obligaciones.",223,0,35,232,"",6,4,"oe",-1,0,-1,0,220,220,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0220-04",19,"La mujer que se compone\ncon demasiado artificio,\nno será por agradar\nsolamente á su marido.",223,0,35,232,"",0,4,"io",-1,0,-1,0,220,220,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0220-05",19,"En este mundo redondo\nquien mal anda mal acaba;\nen casa del jabonero,\naquel que no cae, resbala.",223,0,35,232,"",0,4,"aa",-1,0,-1,0,220,220,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0220-06",19,"Vale más saber que haber,\ndice la común sentencia;\nque el pobre puede ser rico,\ny el rico no compra ciencia.",223,0,35,232,"",0,4,"ea",46,0,-1,0,220,220,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0220-07",19,"Males que acarrea el tiempo,\n¡quién pudiera penetrarlos,\npara ponerles remedio\nantes que viniera el daño!",223,0,35,232,"",0,4,"ao",-1,0,-1,0,220,220,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0221-01",19,"No quiero que me dé nadie\nválida de un alfiler,\nporque todo en este mundo\nse da. por el interés.",223,0,35,232,"",0,4,"e",-1,0,-1,0,221,221,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0221-02",19,"Considera, considera,\ny siempre considerando,\nlos mayores imposibles\nse suelen vencer callando.",223,0,35,232,"",0,4,"ao",33,0,-1,0,221,221,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0221-03",19,"Ninguno por cantar bien\nhable mal de aquel que canta;\nunos cantan lo que saben,\ny otros saben lo que cantan.",223,0,35,232,"",0,4,"aa",-1,0,-1,0,221,221,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0221-04",19,"Como á la puente de Arcos\nte tiene de suceder:\nque trajeron cal y canto\ny se quedó por hacer.",223,0,35,232,"",0,4,"e",20,0,-1,0,221,221,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0221-05",19,"Si con hambre castigas\ná quien te ama,\nadvierte que el desmayo\nquita la gana.",223,0,35,232,"",6,4,"aa",-1,0,-1,0,221,221,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0221-06",19,"Un rosal cría una rosa,\ny una maceta un clavel;\ny un padre cría una hija,\nsin saber para quién es.",223,0,35,232,"",0,4,"e",-1,0,-1,0,221,221,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0221-07",19,"No te fíes de consejos,\naunque te los quieran dar,\nsino de lo que te salga\nde tu propia voluntad.",223,0,35,232,"",0,4,"a",-1,0,-1,0,221,221,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0222-01",19,"Amigos, no hay amigos;\nel más amigo la pega;\nno hay más amigo que Dios\ny un duro en la faltriquera.",223,0,35,232,"",0,4,"ea",-1,0,-1,0,222,222,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0222-02",19,"Casadita y con hijos\nte quiero yo ver,\nque mocita y curiosa\ncualquiera lo es.",223,0,35,232,"",6,4,"e",-1,0,-1,0,222,222,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0222-03",19,"Si quieres que el dinero\nnunca te falte,\nel primero que tengas\nnunca lo gastes.",223,0,35,232,"",6,4,"ae",-1,0,-1,0,222,222,"","",0,"rm_t4","","",3,0,0,[],"",""],["fernan_caballero-p0222-04",19,"Aunque lo mires ajado,\nno desprecies al laurel,\nque algún día fué buen árbol,\ny puede reverdecer.",223,0,35,232,"",0,4,"e",-1,0,-1,0,222,222,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0222-05",19,"Procura reflexionar\nlo que puede suceder,\nporque es mejor precaver\nque tener que remediar.",223,0,35,232,"",11,4,"a",21,0,-1,0,222,222,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0222-06",19,"En materia de gusto\nnadie dispute,\nque para ser de gusto\nbasta que guste.",223,0,35,232,"",6,4,"ue",-1,0,-1,0,222,222,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0222-07",19,"El avariento, amigo,\nes como el puerco,\nque á ninguno aprovecha\nhasta que es muerto.",223,0,35,232,"",6,4,"eo",-1,0,-1,0,222,222,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0223-01",19,"El tiempo con el querer\nhicieron una contrata,\ny lo que el querer dispone\nel tiempo lo desbarata.",223,0,35,232,"",0,4,"aa",74,0,-1,0,223,223,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0223-02",19,"Mis cuñadas y mi suegra\ndicen no me quieren bien;\n¿para qué enturbiar el agua\nque se tiene de beber?",223,0,35,232,"",0,4,"e",-1,0,-1,0,223,223,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0223-03",19,"Si quieres que te aplaudan\ny te desprecien,\nen tu vida reparte\nlo que tuvieres.",223,0,35,232,"",6,4,"ee",-1,0,-1,0,223,223,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0223-04",19,"Una camisa sin mangas,\nsin cuello ni delantera,\nsin género en las espaldas,\nno ha menester lavandera.",223,0,35,232,"",0,4,"ea",44,0,-1,0,223,223,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0223-05",19,"Si fueres á comprar paño\nmira primero la muestra,\nporque en el paño hay engaño,\ncomo en la dama compuesta.",223,0,35,232,"",0,4,"ea",-1,0,-1,0,223,223,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0223-06",19,"Del carro de los locos\ntodos tiramos;\nunos con tiros cortos,\notros con largos.",223,0,35,232,"",6,4,"ao",-1,0,-1,0,223,223,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0223-07",19,"Anda, pregúntale á un sabio\ncuál de los dos sufrió más:\nel que comió de sus carnes,\nó el que publicó su mal.",223,0,35,232,"",0,4,"a",-1,0,-1,0,223,223,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0224-01",19,"Anduvistes escogiendo\ncomo peces en banasta,\ny al fin viniste á dar\ncon uno de mala casta.",223,0,35,232,"",0,4,"aa",488,0,-1,0,224,224,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0224-02",19,"Al alma del negocio\nva todo el mundo,\ny al negocio del alma\nno va ninguno.",223,0,35,232,"",6,4,"uo",-1,0,-1,0,224,224,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0225-01",19,"Yo quisiera morirme\ny oir mi doble,\npor ver quién me decía:\nDios te perdone.",223,0,35,233,"",6,4,"oe",-1,0,-1,0,225,225,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0225-02",19,"Dicen de que no cuesta\nla despedida;\ndile al que te lo ha dicho\nque se despida.",223,0,35,233,"",6,4,"ia",37,0,-1,0,225,225,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0225-03",19,"De tu ventana á la mía\nme tiraste un limón;\nel limón cayó en la calle,\nel zumo en mi corazón.",223,0,35,233,"",0,4,"o",31,0,-1,0,225,225,"","",0,"","","",10,0,0,[],"",""],["fernan_caballero-p0225-04",19,"Mi amante con la luna\nme envía cartas,\ny yo con el lucero\npenas á mantas.",223,0,35,233,"",6,4,"aa",-1,0,-1,0,225,225,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0225-05",19,"Como Sevilla tiene\nfuertes murallas,\nno pueden mis suspiros\natravesallas.",223,0,35,233,"",6,4,"aa",188,0,-1,0,225,225,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0226-01",19,"Son tan grandes mis fatigas\nque me tienden á ahogar;\nse siguen unas ó otras\ncomo las olas del mar.",223,0,35,233,"",0,4,"a",21,0,-1,0,226,226,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0226-02",19,"¡Qué largas las horas son\nen el reloj del afán.\ny qué poco á poco dan\nalivio á mi corazón!",223,0,35,233,"",11,4,"o",31,0,-1,0,226,226,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0226-03",19,"Más quiero yo aguardarte\nquinientos años,\nque no beber las hieles\ndel desengaño.",223,0,35,233,"",6,4,"ao",-1,0,-1,0,226,226,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0226-04",19,"¿A quién le contaré yo\nlo que á mí me está pasando?\nSe lo contaré á la tierra\ncuando me estén enterrando.",223,0,35,233,"",0,4,"ao",33,0,-1,0,226,226,"","",0,"rm_t3","","",3,0,0,[],"",""],["fernan_caballero-p0226-05",19,"El amor y la naranja\nse parecen infinito,\nque por muy dulces que sean,\nde agrio tienen su poquito.",223,0,35,233,"",0,4,"io",119,0,-1,0,226,226,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0226-06",19,"Sin vida estoy por vivir\nla vida que estoy viviendo,\npues vivo y no sé si vivo,\nporque más que vivo, muero.",223,0,35,233,"",0,4,"eo",-1,0,-1,0,226,226,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0226-07",19,"Cuando te veo con pena,\nen mí no reina alegría,\npues como te quiero tanto,\nsiento tu pena y la mía.",223,0,35,233,"",0,4,"ia",0,0,-1,0,226,226,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0227-01",19,"Sufro, siento y padezco,\nsuspiro y lloro;\ncon decir que te quiero\nlo digo todo.",223,0,35,233,"",6,4,"oo",-1,0,-1,0,227,227,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0227-02",19,"A la mar fueron mis ojos\npor agua para llorar,\ny se volvieron sin ella,\nporque estaba seco el mar.",223,0,35,233,"",0,4,"a",21,0,-1,0,227,227,"","",0,"rm_t3","","",3,0,0,[],"",""],["fernan_caballero-p0227-03",19,"Se me oprime el corazón\nal ver tu vestido negro,\nque la sombra de tu pena\ná mí me da sentimiento.",223,0,35,233,"",0,4,"eo",-1,0,-1,0,227,227,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0227-04",19,"Es el engaño leal\ny el desengaño traidor;\nel uno, mal sin dolor,\ny el otro, dolor sin mal.",223,0,35,233,"",11,4,"a",1,0,-1,0,227,227,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0227-05",19,"Rosa me puso mi madre\npara ser más desgraciada,\npues no hay rosa en este mundo\nque no muera deshojada.",223,0,35,233,"",0,4,"aa",49,0,-1,0,227,227,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0227-06",19,"La esperanza de verte\nme tiene viva;\nque si no, ya tuviera\nla tierra encima.",223,0,35,233,"",6,4,"ia",-1,0,-1,0,227,227,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0227-07",19,"¡Triste está mi corazón\ny no sabe lo que tiene!...\nQue está muy lejos de aquí\nel que consolarlo puede.",223,0,35,233,"",0,4,"ee",-1,0,-1,0,227,227,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0228-01",19,"La pena y la que no es pena\ntodo es pena para mí;\nayer penaba por verte,\ny hoy peno porque te vi.",223,0,35,233,"",0,4,"i",23,0,-1,0,228,228,"","",0,"rm_t3, andina_t1","","",9,0,0,[],"",""],["fernan_caballero-p0228-02",19,"Los suspiros de un cautivo\nno pueden llegar á España,\nque está la mar de por medio\ny se han de hundir en el agua.",223,0,35,233,"",0,4,"aa",-1,0,-1,0,228,228,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0228-03",19,"A las rejas de la cárcel\nno me vengas á llorar;\nya que no me quites penas,\nno me las vengas á dar.",223,0,35,233,"",0,4,"a",21,0,-1,0,228,228,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0228-04",19,"Los ojos de mi morena\nse parecen á mis males:\ngrandes como mis fatigas,\nnegros como mis pesares.",223,0,35,233,"",0,4,"ae",-1,0,-1,0,228,228,"","",0,"rm_t2","","",23,0,0,[],"",""],["fernan_caballero-p0228-05",19,"Las aves de la Arabia\nviven eternas;\nviven porque no saben\nlo que son penas.",223,0,35,233,"",6,4,"ea",-1,0,-1,0,228,228,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0228-06",19,"Entre la hostia y el cáliz\ná mi Dios se lo pedí:\nque no te maten las penas\nque me están matando á mí.",223,0,35,233,"",0,4,"i",23,0,-1,0,228,228,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0228-07",19,"Si supiera la pena\nque era no verte,\nme hubiera resignado\ná no quererte.",223,0,35,233,"",6,4,"ee",134,0,-1,0,228,228,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0229-01",19,"Desde que te vi, te amé;\ndesde que te amé, me muero;\ny si me muero por ti,\ndichoso me considero.",223,0,35,233,"",0,4,"eo",38,0,-1,0,229,229,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",17,0,0,[],"",""],["fernan_caballero-p0229-02",19,"Compañera de mi alma,\nya no me conocerás,\nque acaba más una pena\nque una larga enfermedad.",223,0,35,233,"",0,4,"a",-1,0,-1,0,229,229,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0229-03",19,"En la soledad del campo\nme puse á llorar mis penas;\ny fueron tantos mis llantos,\nque florecieron las hierbas.",223,0,35,233,"",0,4,"ea",-1,0,-1,0,229,229,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0229-04",19,"Suspiros que de mí salgan\n¡y otros que de ti vendrán,\nsi en el camino se encuentran,\nqué de cosas se dirán!",223,0,35,233,"",0,4,"a",147,0,-1,0,229,229,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0229-05",19,"Por agravios que me hagas,\nde ti no me vengaré,\nporque te vale el sagrado\nde haberte querido bien.",223,0,35,233,"",0,4,"e",-1,0,-1,0,229,229,"","",0,"rm_t2, rm_t3, lafuente_madrid, palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0229-06",19,"Todo el día estoy alegre,\ny en llegando la oración,\nuna piedra de molino\nparece mi corazón.",223,0,35,233,"",0,4,"o",31,0,-1,0,229,229,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0229-07",19,"¿Cómo quieres que yo vaya\nal jardín de la alegría,\nsi se marchitan las flores\nal ver estas penas mías?",223,0,35,233,"",0,4,"ia",-1,0,-1,0,229,229,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0230-01",19,"Ni contigo ni sin ti\npuedo yo tener consuelo;\ncontigo, porque me matas,\ny sin ti, porque me muero.",223,0,35,233,"",0,4,"eo",-1,0,-1,0,230,230,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0230-02",19,"Voy á la fuente y bebo;\nno la aminoro,\nque aumenta su corriente\ncon lo que lloro.",223,0,35,233,"",6,4,"oo",85,0,-1,0,230,230,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0230-03",19,"Cansada estoy de llorar\ny hasta de dar suspiros;\ncon las aguas y las brisas\ndicen que se ajan los lirios.",223,0,35,233,"",0,4,"io",-1,0,-1,0,230,230,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0230-04",19,"Yo soy como la verbena\nque pusieron en maceta;\ncomo se ve en tierra ajena,\naunque la cuiden, se seca.",223,0,35,233,"",0,4,"ea",-1,0,-1,0,230,230,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0230-05",19,"Como la campana tiene\nfundidos siete metales,\nasí tengo tu cariño\nen la masa de la sangre.",223,0,35,233,"",0,4,"ae",-1,0,-1,0,230,230,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0230-06",19,"De dolor y sentimiento\ndicen que no muere nadie;\nyo me tengo de morir\npor ver si se muere alguien.",223,0,35,233,"",0,4,"ae",-1,0,-1,0,230,230,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0230-07",19,"En el jardín del amor,\nten por sabido,\nla flor que más abunda\nes el suspiro.",223,0,35,233,"",6,4,"io",-1,0,-1,0,230,230,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0231-01",19,"Dícese que nos queremos,\nyo no sé si desearlo;\nla risa de amor es dulce,\npero su llanto es amargo.",223,0,35,233,"",0,4,"ao",-1,0,-1,0,231,231,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0231-02",19,"Yendo y viniendo\nfuíme enamorado;\nempecé riendo,\ny acabé llorando.",223,0,35,233,"",3,4,"ao",-1,0,-1,0,231,231,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0231-03",19,"Corazón que en las penas\ntu alivio encuentras,\nsi las penas descansan,\n¿de qué te quejas?",223,0,35,233,"",6,4,"ea",-1,0,-1,0,231,231,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0231-04",19,"Las fatigas de la muerte\ngrandes fatiguillas son,\npero con las del querer\nno tienen comparación.",223,0,35,233,"",0,4,"o",31,0,-1,0,231,231,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0231-05",19,"Seguidillas son guindas,\nguindas son flores,\npalillos de retama\nson mis amores.",223,0,35,233,"",6,4,"oe",5,0,-1,0,231,231,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0231-06",19,"Si supiera que en otro\ntu amor ponías,\nle echara un velo negro\nal alma mía.",223,0,35,233,"",6,4,"ia",-1,0,-1,0,231,231,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0231-07",19,"Tres años después de muerto\nla tierra me preguntó\nque si le había olvidado,\ny yo le dije que no.",223,0,35,233,"",0,4,"o",2,0,-1,0,231,231,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0232-01",19,"A una piedra de la calle\nle contaba mi dolor;\nmira lo que le diría,\nque la piedra se partió.",223,0,35,233,"",0,4,"o",-1,0,-1,0,232,232,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0232-02",19,"Yo me confié á un amigo\npor ver si me consolaba,\ny el amigo estaba enfermo\ndel mismo mal que yo estaba.",223,0,35,233,"",0,4,"aa",28,0,-1,0,232,232,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0232-03",19,"Dentro de mi pecho tengo\nun entierro bien formado;\nmi corazón es el muerto,\ntu querer me lo ha matado.",223,0,35,233,"",0,4,"ao",14,0,-1,0,232,232,"","",0,"rm_t3, lafuente_madrid","","",32,0,0,[],"",""],["fernan_caballero-p0232-04",19,"Un corazón de madera\ntengo de mandar hacer,\nque ni sienta ni padezca,\nni sepa lo que es querer.",223,0,35,233,"",0,4,"e",20,0,-1,0,232,232,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0232-05",19,"Corazón, no suspires;\nalma, no sientas;\nmemoria, no te acuerdes\nde quien te acuerdas.",223,0,35,233,"",6,4,"ea",-1,0,-1,0,232,232,"","",0,"palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0232-06",19,"Ausente de tu vista,\nmucho más vivo,\nporque cada momento\nse me hace un siglo.",223,0,35,233,"",6,4,"io",-1,0,-1,0,232,232,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0232-07",19,"A los santos les pido\nque en esta ausencia,\ná ti te den constancia\ny á mí paciencia.",223,0,35,233,"",6,4,"ea",46,0,-1,0,232,232,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0233-01",19,"De la retama la rama,\ndel saúco la corteza,\nno son cosas más amargas\nque amor donde no hay firmeza.",223,0,35,233,"",0,4,"ea",108,0,-1,0,233,233,"","",0,"lafuente_madrid, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0233-02",19,"Estoy tan hecha á penar,\nque en no penando,\nparece que me falta\nlo necesario.",223,0,35,233,"",6,4,"ao",-1,0,-1,0,233,233,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0233-03",19,"Una palabra me diste\nque jamás me cumplirás;\nyo sí cumpliré la mía\nde no olvidarte jamás.",223,0,35,233,"",0,4,"a",51,0,-1,0,233,233,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0233-04",19,"Estrellas del alto cielo,\nbajad y firmad por mí;\nque cumpliré la palabra\nque al que está ausente le di.",223,0,35,233,"",0,4,"i",23,0,-1,0,233,233,"","",0,"palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0233-05",19,"Toma allá mi corazón,\néchalo en esa candela;\nmas no agarres las cenizas,\nque te has de quemar con ellas.",223,0,35,233,"",0,4,"ea",-1,0,-1,0,233,233,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",7,0,0,[],"",""],["fernan_caballero-p0233-06",19,"Hasta la cama en que duermo\nse queja de mi dolor;\nsiendo de madera, siente,\n¿qué será mi corazón?",223,0,35,233,"",0,4,"o",-1,0,-1,0,233,233,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0233-07",19,"Todo aquel que dice ¡ay!\nes señal que le ha dolido;\ncuando tantos ayes da,\nved si mi pecho ha sufrido.",223,0,35,233,"",0,4,"io",101,0,-1,0,233,233,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0234-01",19,"Me dicen que soy hermosa;\nmas me retiro del mundo,\nque tengo mi corazón\ndentro del pecho difunto.",223,0,35,233,"",0,4,"uo",-1,0,-1,0,234,234,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0234-02",19,"Todo el tiempo de mi vida\namándote pasaré;\ny si me olvidas por otro,\nen ti y en Dios pensaré.",223,0,35,233,"",0,4,"e",77,0,-1,0,234,234,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0234-03",19,"De tus ingratitudes\ntengo yo hecho,\ncomo la Magdalena,\nllaga en el pecho.",223,0,35,233,"",6,4,"eo",60,0,-1,0,234,234,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0234-04",19,"Aunque me ves que canto,\ncanta la boca,\nporque mi pecho tiene\npena y no poca.",223,0,35,233,"",6,4,"oa",178,0,-1,0,234,234,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0234-05",19,"Como canjilón de noria\nson mis fatigas y penas;\nunas suben aguas malas\ny otras suben aguas buenas.",223,0,35,233,"",0,4,"ea",62,0,-1,0,234,234,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0234-06",19,"En un macetón sembré\nun amor que me brindaron;\ncon lágrimas lo regué,\npor eso se arraigó tanto.",223,0,35,233,"",0,4,"ao",-1,0,-1,0,234,234,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0234-07",19,"La soledad me acompaña,\nla alegría me entristece,\npues aborrezco la vida,\npues apetezco la muerte.",223,0,35,233,"",0,4,"ee",-1,0,-1,0,234,234,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0235-01",19,"Dentro de la sepultura,\ny de gusanos roído,\nse han de encontrar en mi pecho\nseñas de haberte querido.",223,0,35,233,"",0,4,"io",101,0,-1,0,235,235,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0236-01",19,"María me dió una rosa,\ny su madre la miró;\nmás colorada se puso\nque la rosa que me dió.",223,0,35,234,"",0,4,"o",2,0,-1,0,236,236,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0236-02",19,"La nieve por tu cara\npasó diciendo:\ndonde no hago yo falta\nno me detengo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,236,236,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0236-03",19,"Si quieres qu formemos\nlos dos un cordón,\ntu pondrás la constancia,\nyo pondré el amor.",223,0,35,234,"",0,4,"o",-1,0,-1,0,236,236,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0236-04",19,"Los dientes de tu boca\nme tienen preso;\n¡quién ha visto cadena\nhecha de hueso!",223,0,35,234,"",6,4,"eo",48,0,-1,0,236,236,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0236-05",19,"Los dientes de tu boca\nme tienen así;\n¡quién ha visto grilletes\nhechos de marfil!",223,0,35,234,"",0,4,"i",-1,0,-1,0,236,236,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0237-01",19,"Amantito, Amantito,\namante, amante,\nlas pestañas me estorban\npara mirarte.",223,0,35,234,"",6,4,"ae",-1,0,-1,0,237,237,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0237-02",19,"Las estrellitas del cielo\ncada cual tiene su nombre;\nla mía se llama Rita,\n¡la llamo y no me responde!",223,0,35,234,"",0,4,"oe",-1,0,-1,0,237,237,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",25,0,0,[],"",""],["fernan_caballero-p0237-03",19,"Dime, niña, tú que vives\narrimadita á la Audiencia,\nsi habrás oído leer\nel papel de la sentencia.",223,0,35,234,"",0,4,"ea",46,0,-1,0,237,237,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0237-04",19,"Tú eres el juez de la causa,\ny yo soy el delincuente;\nacaba de sentenciar\nsi soy de vida ó de muerte.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,237,237,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0237-05",19,"¿Para qué vienes á verme\nsi tienes quien te lo estorbe?\nDale gusto á esa persona,\ny ten partidas de hombre.",223,0,35,234,"",0,4,"oe",-1,0,-1,0,237,237,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0237-06",19,"Cuando te encuentro en la calle\ny no me dices adiós,\nni las ánimas benditas\npasan lo que paso yo.",223,0,35,234,"",0,4,"o",-1,0,-1,0,237,237,"","",0,"","","",13,0,0,[],"",""],["fernan_caballero-p0237-07",19,"Enfrente del sol saliente\ntiene mi niña el balcón;\nsale el sol, sale mi niña,\nsalen mi niña y el sol.",223,0,35,234,"",0,4,"o",-1,0,-1,0,237,237,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0238-01",19,"De la mar en la orilla\nte bautizaron,\ny vinieron los peces,\nla sal te echaron.",223,0,35,234,"",6,4,"ao",41,0,-1,0,238,238,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0238-02",19,"Mi padre me tiene dicho\nque me tiene que sacar\nlos ojos con qué te miro,\ny yo que te he de mirar.",223,0,35,234,"",0,4,"a",21,0,-1,0,238,238,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0238-03",19,"Cuando voy á la iglesia\ny no te veo,\nquisiera que la misa\ndurara un credo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,238,238,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0238-04",19,"Cuando voy á la iglesia\ny allí te hallo,\nquisiera que la misa\ndurara un año.",223,0,35,234,"",6,4,"ao",-1,0,-1,0,238,238,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0238-05",19,"Tengo vergüenza y me callo,\ntengo amor y no lo digo;\nno sé cómo te dijera:\n¿Te quieres casar conmigo?",223,0,35,234,"",0,4,"io",106,0,-1,0,238,238,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0238-06",19,"Quisiera ser por un rato\nperla de tu gargantilla,\nde tus zarcillos arete,\nde tus zapatos hebilla.",223,0,35,234,"",0,4,"ia",162,0,-1,0,238,238,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0238-07",19,"No hay ojos más hermosos\nque los azules,\ny si no, mira al cielo\ncuando no hay nubes.",223,0,35,234,"",6,4,"ue",-1,0,-1,0,238,238,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0239-01",19,"Amor mío, no pierdas\nlas esperanzas,\nque en el pozo más hondo\nla soga alcanza.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,239,239,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0239-02",19,"Morena, tú me matas\ncon tus rigores,\nquieres que paguen justos\npor pecadores.",223,0,35,234,"",6,4,"oe",5,0,-1,0,239,239,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0239-03",19,"Las estrellas del cielo\nno están cabales,\nporque están en tu cara\nlos principales.",223,0,35,234,"",6,4,"ae",26,0,-1,0,239,239,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0239-04",19,"Vale más lo moreno\nde mi morena,\nque toda la blancura\nde la azucena.",223,0,35,234,"",6,4,"ea",59,0,-1,0,239,239,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0239-05",19,"Tengo un clavel encarnado\ná la sombra y bajo llave,\npara que el sol no lo vea\ny con mirarlo lo aje.",223,0,35,234,"",0,4,"ae",-1,0,-1,0,239,239,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0239-06",19,"Quisiera verte y no verte,\nquisiera hablarte y no hablarte,\nquisiera encontrarte á solas,\ny quisiera no encontrarte.",223,0,35,234,"",0,4,"ae",8,0,-1,0,239,239,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0239-07",19,"Una porción de civiles\nhan salido de Morón\nen busca de unos ladrones;\nmi niña, tus ojos son.",223,0,35,234,"",0,4,"o",31,0,-1,0,239,239,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0240-01",19,"Todo el mundo en contra mía,\nserrana, porque te quiero;\ntodo el mundo en contra mía,\ny yo contra el mundo entero.",223,0,35,234,"",1,4,"eo",38,0,-1,0,240,240,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0240-02",19,"El amor y el interés\nsalieron al campo un día,\ny el interés pudo más\nque el amor que me tenías.",223,0,35,234,"",0,4,"ia",-1,0,-1,0,240,240,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0240-03",19,"Cuando quise, no quisiste,\ny ahora que quieres, no quiero;\ngozarás del amor triste\ncomo yo gocé primero.",223,0,35,234,"",3,4,"eo",38,0,-1,0,240,240,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0240-04",19,"No te enamores, mi niña,\nde mocito forastero,\nque en volviendo las espaldas,\nsi te vide, no me acuerdo.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,240,240,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0240-05",19,"Si San Rafael me diera\nlas alas de su volar,\ndonde tengo el pensamiento\nfuera de un vuelo á parar.",223,0,35,234,"",0,4,"a",21,0,-1,0,240,240,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0240-06",19,"Yo te quise no pensando\nque me habías de olvidar;\ntú juegas con dos barajas,\ny yo con una no más.",223,0,35,234,"",0,4,"a",-1,0,-1,0,240,240,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0240-07",19,"Dame la manita, iremos\nal sitio donde lloraste,\ny, entre los dos cogeremos\nlas perlas que derramaste.",223,0,35,234,"",1,4,"ae",212,0,-1,0,240,240,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0241-01",19,"Te quiero y sé que nunca\nseré tu dueño;\nesto sí que es firmeza\nde amor sin premio.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,241,241,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0241-02",19,"Ya que no te puedo hablar,\nponte donde yo te vea;\ndaré placer á la vista,\nya que otra cosa no sea.",223,0,35,234,"",0,4,"ea",54,0,-1,0,241,241,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0241-03",19,"No me mandes papeles,\nque no sé leer;\nmándame tu persona,\nque la quiero ver.",223,0,35,234,"",0,4,"e",20,0,-1,0,241,241,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0241-04",19,"Tus ojos son ladrones\nque roban y hurtan;\ntus pestañas el monte\ndonde se ocultan.",223,0,35,234,"",6,4,"ua",-1,0,-1,0,241,241,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0241-05",19,"Los ojos de mi morena\ntienen un mirar extraño;\nque matan en una hora\nmás que la muerte en un año.",223,0,35,234,"",0,4,"ao",40,0,-1,0,241,241,"","",0,"rm_t2, palau_cantares","","",23,0,0,[],"",""],["fernan_caballero-p0241-06",19,"El hombre que á mí me quiera,\nme ha de venir á buscar,\ncomo el agua busca el río,\ny el río busca á la mar.",223,0,35,234,"",0,4,"a",21,0,-1,0,241,241,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0241-07",19,"Esos dedos que tú tienes,\ndedos quieren parecer;\npero en tanto que yo viva,\nnunca \"de dos\" han de ser.",223,0,35,234,"",0,4,"e",20,0,-1,0,241,241,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0242-01",19,"Tienes unos ojitos\nadormilados,\nque es preciso quererlos\ná ojos cerrados.",223,0,35,234,"",6,4,"ao",18,0,-1,0,242,242,"","",0,"rm_t2, palau_cantares","","",20,0,0,[],"",""],["fernan_caballero-p0242-02",19,"Tus colchones son jazmines\ny tus sábanas mosquetas,\nazucenas tu almohada,\ny tú, rosa que te acuestas.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,242,242,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0242-03",19,"Los cipreses de tu casa\nestán vestidos de luto,\ny es porque no tienen flores\nque ofrecerte por tributo.",223,0,35,234,"",0,4,"uo",327,0,-1,0,242,242,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0242-04",19,"El naranjo de tu patio,\ncuando te acercas á él,\nse desprende de sus flores\ny te las echa á los pies.",223,0,35,234,"",0,4,"e",-1,0,-1,0,242,242,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0242-05",19,"Dueño mío, no vayas\ná misa mayor,\nque ni rezas, ni rezo,\nni pongo atención.",223,0,35,234,"",0,4,"o",-1,0,-1,0,242,242,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0242-06",19,"Atame con un cabello\ná la reja de tu casa,\nque aunque se rompa el cabello\nseguro está que me vaya.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,242,242,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0242-07",19,"Valientemente, muchacha,\nDios te dió sabiduría;\nuna palabra que hablas\nvale por doscientas mías.",223,0,35,234,"",0,4,"ia",-1,0,-1,0,242,242,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0243-01",19,"Te quiero más que al dinero,\nmás que á mi padre y mi madre,\ny si no fuese pecado,\nmás que á la Virgen del Carmen.",223,0,35,234,"",0,4,"ae",-1,0,-1,0,243,243,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0243-02",19,"Mucho quiero á San Francisco,\nmás á San Judas Tadeo;\npero más quiero á aquel santo\nque señala con el dedo.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,243,243,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0243-03",19,"El médico me receta,\nviendo que es mi mal de amor,\nonza y media de escarmiento,\ny de desengaño dos.",223,0,35,234,"",0,4,"o",-1,0,-1,0,243,243,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0243-04",19,"¿Quieres ajustar la cuenta\ndel tiempo que te he querido?\nDame la carta de pago,\ny yo te daré el recibo.",223,0,35,234,"",0,4,"io",-1,0,-1,0,243,243,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0243-05",19,"El ave fría en el campo\nclaramente dice nieve,\ny eso lo dice por ti,\nsabiendo que á nadie quieres.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,243,243,"","",0,"lafuente_madrid","","",2,0,0,[],"",""],["fernan_caballero-p0243-06",19,"El león con ser león,\ndicen que lo rindió el sueño;\nyo, que soy criatura humana,\nde pensar en ti no duermo.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,243,243,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0243-07",19,"Si pasaras por mi calle\ny me quisieras hablar,\nrepara bien en mi sombra,\nella te responderá.",223,0,35,234,"",0,4,"a",-1,0,-1,0,243,243,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0244-01",19,"Me llaman el celoso,\ná mí, ¡qué pena!\nSoy labrador, y quiero\nguardar mi hacienda.",223,0,35,234,"",6,4,"ea",-1,0,-1,0,244,244,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0244-02",19,"Anoche soñaba yo\nque dos negros me mataban,\ny eran tus hermosos ojos\nque enojados me miraban.",223,0,35,234,"",0,4,"aa",39,0,-1,0,244,244,"","",0,"rm_t2, palau_cantares, frenk_t2, lafuente_madrid","","",9,0,0,[],"",""],["fernan_caballero-p0244-03",19,"Tienes unos ojitos\nde picaporte:\ncada vez que los cierras,\n¡siento yo un golpe!",223,0,35,234,"",6,4,"oe",-1,0,-1,0,244,244,"","",0,"","","",20,0,0,[],"",""],["fernan_caballero-p0244-04",19,"Por una Pepita muero,\npepita y no de melón,\nque es Pepita que yo tengo\ndentro de mi corazón.",223,0,35,234,"",0,4,"o",31,0,-1,0,244,244,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0244-05",19,"Ya yo no vivo en la calle\ndonde usted me conoció;\nahora vivo en la plazuela\ndel desengaño mayor.",223,0,35,234,"",0,4,"o",-1,0,-1,0,244,244,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0244-06",19,"San Antonio lleva el niño,\nSanto Domingo la estrella,\ny San Juan lleva la palma:\nentiéndame quien me entienda.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,244,244,"","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0244-07",19,"Aunque tú no me quieras,\ntengo el consuelo\nde saber que tú sabes\nque yo te quiero.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,244,244,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",7,0,0,[],"",""],["fernan_caballero-p0245-01",19,"Tan imposible lo hallo\nencontrar en ti cariño,\ncomo llegar á quitarle\ná San Antonio su niño.",223,0,35,234,"",0,4,"io",176,0,-1,0,245,245,"","",0,"","","",13,0,0,[],"",""],["fernan_caballero-p0245-02",19,"De San Juan quiero la palma,\nde San Francisco el cordón,\nde Santa Rita la espina,\nde mi amante el corazón.",223,0,35,234,"",0,4,"o",31,0,-1,0,245,245,"","",0,"murciano_antiguo","","",4,0,0,[],"",""],["fernan_caballero-p0245-03",19,"Un pino alto lo troncho,\nun álamo lo blandeo,\nun toro bravo lo amanso,\ny á ti, muchacha, no puedo.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,245,245,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0245-04",19,"A tu amor lo he comparado\ná los días del invierno:\nya se aclara, ya se nubla,\nya diluvia, ya hace bueno.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,245,245,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0245-05",19,"Ya yo he caído en desgracia,\n¡paciencia!, ¡cómo ha de ser!\nAunque yo santos pintara,\ndiablos te han de parecer.",223,0,35,234,"",0,4,"e",20,0,-1,0,245,245,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0245-06",19,"Una gotera continua\nablanda un duro peñón,\ny mis suspiros no pueden\nablandar tu corazón.",223,0,35,234,"",0,4,"o",31,0,-1,0,245,245,"","",0,"rm_t2, carrizo_salta, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0245-07",19,"Estrellas del alto cielo,\nbajad y firmad por mí,\nque cumpliré la palabra\nque á mi morena le di.",223,0,35,234,"",0,4,"i",23,0,-1,0,245,245,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0246-01",19,"De los juncos sale el agua,\nde los álamos el viento,\ny de ti, pulida dama,\nmemoria y entendimiento.",223,0,35,234,"",0,4,"eo",94,0,-1,0,246,246,"","",0,"rm_t2","","",4,0,0,[],"",""],["fernan_caballero-p0246-02",19,"Como estás esta noche\ntan celosita,\npareces una rosa\ncon espinitas.",223,0,35,234,"",6,4,"ia",-1,0,-1,0,246,246,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0246-03",19,"Más te quiero enojada\nque placentera,\nque haces una enojada\nmuy sandunguera.",223,0,35,234,"",6,4,"ea",44,0,-1,0,246,246,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0246-04",19,"Tengo una puñaladita\nque me la dió una mozuela;\nno he visto puñaladita\nmás chiquita y que más duela.",223,0,35,234,"",1,4,"ea",167,0,-1,0,246,246,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0246-05",19,"—Tienes, niña, una mañita\nque te la vengo á reñir;\nque te quitas de la puerta\nen cuanto me ves venir.",223,0,35,234,"",0,4,"i",157,0,-1,0,246,246,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0246-06",19,"—Si has notado que me quito,\nyo no me quito por ti,\nsino por tus amiguitos,\nque no tengan qué decir.",223,0,35,234,"",0,4,"i",-1,0,-1,0,246,246,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0246-07",19,"—Ya mis amigos lo saben\nque yo adoro tu persona,\nque tú te estés en la puerta,\nes para mí una corona.",223,0,35,234,"",0,4,"oa",7,0,-1,0,246,246,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0247-01",19,"Como abrí sin precaución\ntu carta, dueño querido,\nse cayó tu corazón;\nmas en mi pecho ha caído.",223,0,35,234,"",1,4,"io",101,0,-1,0,247,247,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0247-02",19,"En él yo le he dado abrigo,\npero no cabiendo dos,\nel mío te mando yo\ny el tuyo queda conmigo.",223,0,35,234,"",5,4,"io",106,0,-1,0,247,247,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0247-03",19,"Las estrellas y luceros\ntodas se rinden al día,\ny yo me rindo á tus plantas,\nMaría del alma mía.",223,0,35,234,"",0,4,"ia",0,0,-1,0,247,247,"","",0,"","","",10,0,0,[],"",""],["fernan_caballero-p0247-04",19,"No quiero salgas de casa\nni que á la puerta te asomes,\nni tomes agua bendita\ndonde la toman los hombres.",223,0,35,234,"",0,4,"oe",-1,0,-1,0,247,247,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0247-05",19,"Si mi corazón llegase\ná pedirte una limosna,\ny no tuvieses qué darle,\ndile con amor: perdona.",223,0,35,234,"",0,4,"oa",-1,0,-1,0,247,247,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0247-06",19,"De aquí tengo que ausentarme,\nmi querer está en peligro,\nraíces va ya criando\ncomo en el suelo el olivo.",223,0,35,234,"",0,4,"io",-1,0,-1,0,247,247,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0247-07",19,"Son tus labios dos cortinas\nde color de carmesí,\ny entre cortina y cortina\nestoy esperando el sí.",223,0,35,234,"",3,4,"i",23,0,-1,0,247,247,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0248-01",19,"Me han dicho que estás malita\ny que te sangran mañana;\ná ti te sangran del pie,\ny á mí me sangran del alma.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,248,248,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0248-02",19,"Todo el mundo me lo dice,\nyo acredito esa verdad:\nen estando un hombre ausente,\notro ocupa su lugar.",223,0,35,234,"",0,4,"a",-1,0,-1,0,248,248,"","",0,"","","",14,0,0,[],"",""],["fernan_caballero-p0248-03",19,"No suspiro por verte,\nque bien te veo;\nsuspiro por hablarte,\nquiero y no puedo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,248,248,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0248-04",19,"Yo no sé qué me haga\ncon unos celos,\nque ya estoy para darlos\npor no tenerlos.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,248,248,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0248-05",19,"La cadena del amor\ntiene fuertes eslabones,\ny aquel que en ella se mete,\ntarde sale de prisiones.",223,0,35,234,"",0,4,"oe",34,0,-1,0,248,248,"","",0,"lafuente_madrid, palau_cantares","","",8,0,0,[],"",""],["fernan_caballero-p0248-06",19,"Los árboles de Aranjuez,\nunidos de siete en siete,\nno tienen tan firmeza\ncomo yo para quererte.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,248,248,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0248-07",19,"Esa madeja de pelo\nte cuelga por las espaldas,\nde día por hermosura,\nde noche por almohada.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,248,248,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0249-01",19,"Un imposible adoro,\nque es de discretos;\nlas posibilidades\nlas ama un necio.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,249,249,"","",0,"rm_t2","","",4,0,0,[],"",""],["fernan_caballero-p0249-02",19,"María, si bien me quieres,\nno se lo digas al cura;\nque los secretos de amor\nson para la sepultura.",223,0,35,234,"",0,4,"ua",17,0,-1,0,249,249,"","",0,"rm_t2, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0249-03",19,"El que enferma de amores\nsin calentura,\nváyase á la parroquia\nque el cura cura.",223,0,35,234,"",6,4,"ua",17,0,-1,0,249,249,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0249-04",19,"Médico quise hacerme\npor curarte á ti,\ny el mal que tú tenías\nse me pegó á mí.",223,0,35,234,"",0,4,"i",23,0,-1,0,249,249,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0249-05",19,"Quise bien, y aborrecí,\nque no es delito en quien ama,\nque cuando yo aborrecí,\nmás que aborrecido estaba.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,249,249,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0249-06",19,"Niña, cuando vas á misa,\nla iglesia se resplandece,\nla hierba seca que pisas\ncon verte se reverdece.",223,0,35,234,"",0,4,"ee",64,0,-1,0,249,249,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0249-07",19,"¿Por qué me diste vista,\nSanta Lucía,\nsi no veo lo que quiero\ntodos los días?",223,0,35,234,"",6,4,"ia",-1,0,-1,0,249,249,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0250-01",19,"Esos rizos que te adornan\nesa peregrina cara,\nson flechas con que me has hecho\nherida que nunca sana.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,250,250,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0250-02",19,"Mucho quiero á San Francisco,\nporque tiene cinco llagas;\npero más te quiero á ti,\nporque Francisca te llamas.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,250,250,"","",0,"lafuente_madrid, palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0250-03",19,"Creo que no tienes alma,\nni has nacido en este reino,\nsino que en la Morería\ntuviste tu nacimiento.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,250,250,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0250-04",19,"A lo lejos que te vea\nse me alegra el corazón;\ndonde candela se hizo,\nsiempre ceniza quedó.",223,0,35,234,"",0,4,"o",-1,0,-1,0,250,250,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0250-05",19,"Manojitos de alfileres\nme parecen tus pestañas;\ncada vez que las meneas\nse me clavan en el alma.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,250,250,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0250-06",19,"Fuentecita cristalina,\narroyuelo caudaloso,\npara dos que bien se quieren,\nlargos caminos son cortos.",223,0,35,234,"",0,4,"oo",-1,0,-1,0,250,250,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0250-07",19,"Anoche fuí al correo,\nno tuve carta.\nSe vistieron de luto\nmis esperanzas.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,250,250,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0251-01",19,"Tienes unos ojos, niña,\nque si los pones á premio,\nno faltará quién te dé\nun veinticinco por ciento.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,251,251,"","",0,"","","",13,0,0,[],"",""],["fernan_caballero-p0251-02",19,"En una teja en su casa\ncrió mi niña un clavel,\ny cuando á su vera pasa\nle da un besito en la sién.",223,0,35,234,"",0,4,"e",-1,0,-1,0,251,251,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0251-03",19,"A la mar te pareces\nen enojarte,\nporque la mar se enoja\nsólo del aire.",223,0,35,234,"",6,4,"ae",-1,0,-1,0,251,251,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0251-04",19,"Si quieres que te quiera,\nme lo has de pagar,\nque también mi cariño\ncobra su jornal.",223,0,35,234,"",0,4,"a",-1,0,-1,0,251,251,"","",0,"","","",17,0,0,[],"",""],["fernan_caballero-p0251-05",19,"Es tu querer como el toro,\ndonde lo llaman se va;\nel mío es como la piedra,\ndonde se pone se está.",223,0,35,234,"",0,4,"a",9,0,-1,0,251,251,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0251-06",19,"A mí no me gustan plantas,\nmozo bueno, escuche usted;\nlo que me gustan son obras,\ny esas no las tiene usted.",223,0,35,234,"",0,4,"e",-1,0,-1,0,251,251,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0251-07",19,"Cuando te encuentro en la calle,\nse me alegra el corazón,\nque donde hubo candela,\nsiempre rescoldo quedó.",223,0,35,234,"",0,4,"o",-1,0,-1,0,251,251,"","",0,"","","",13,0,0,[],"",""],["fernan_caballero-p0252-01",19,"A Santa Rita de Casia\nno le tengo de rezar,\npues le pedí un imposible,\ny no lo quiso otorgar.",223,0,35,234,"",0,4,"a",21,0,-1,0,252,252,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0252-02",19,"Moreno pintan á Cristo,\nmorena á la Magdalena,\nmoreno es el bien que adoro.\n¡Viva la gente morena!",223,0,35,234,"",0,4,"ea",59,0,-1,0,252,252,"","",0,"palau_cantares, frenk_t1, machado_venezuela, andina_t1, lafuente_madrid, huambachano","","",10,0,0,[],"",""],["fernan_caballero-p0252-03",19,"Como mi amante es moreno,\npor eso lo quiero tanto,\nporque la tierra morena\nse señorea en el campo.",223,0,35,234,"",0,4,"ao",-1,0,-1,0,252,252,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0252-04",19,"Los ojos de mi niña\nson de pan tierno,\ny los míos de hambre\nse están muriendo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,252,252,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0252-05",19,"Una morena se vende.\nDicen los apreciadores,\nque la sal de una morena\nno es pagada con doblones.",223,0,35,234,"",0,4,"oe",-1,0,-1,0,252,252,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0252-06",19,"Toma allá mi corazón,\nmétetelo en el corpiño\ny arrúllalo como un niño,\nque llora y tiene razón.",223,0,35,234,"",11,4,"o",31,0,-1,0,252,252,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0252-07",19,"Aunque pongan á tu puerta\nla artillería real,\ny á tu padre de artillero,\ncontigo me he de casar.",223,0,35,234,"",0,4,"a",-1,0,-1,0,252,252,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0253-01",19,"El día que tu naciste\nnacieron todas las flores,\ny en la pila del bautismo\ncantaron los ruiseñores.",223,0,35,234,"",0,4,"oe",5,0,-1,0,253,253,"","",0,"","","",16,0,0,[],"",""],["fernan_caballero-p0253-02",19,"Tus ojos y los míos\nse han enredado,\ncomo las zarzamoras\npor los vallados.",223,0,35,234,"",6,4,"ao",-1,0,-1,0,253,253,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["fernan_caballero-p0253-03",19,"Si supiera que con flores\nte había de divertir,\nyo te trajera más flores\nque crían Mayo y Abril.",223,0,35,234,"",0,4,"i",-1,0,-1,0,253,253,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0253-04",19,"Aunque me ves encogida\ny que tengo pocos años,\nen tocando á la firmeza,\nni la cruz de San Fernando.",223,0,35,234,"",0,4,"ao",-1,0,-1,0,253,253,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0253-05",19,"Con la luna de Enero\nte he comparado,\nque es la luna más clara\nque tiene el año.",223,0,35,234,"",6,4,"ao",-1,0,-1,0,253,253,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0253-06",19,"Las estrellas del cielo\nson mil y siete;\ncon las dos de tu cara\nson mil y nueve.",223,0,35,234,"",6,4,"ee",-1,0,-1,0,253,253,"","",0,"rm_t2, palau_cantares","","",9,0,0,[],"",""],["fernan_caballero-p0253-07",19,"Con la luz te comparo,\n¡mira qué dicha!\nSin la luz no se puede\ncelebrar misa.",223,0,35,234,"",6,4,"ia",-1,0,-1,0,253,253,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0254-01",19,"Mis amores son del campo\ny no vienen al lugar;\nmis suspiros son correos,\nque unos vienen, otros van.",223,0,35,234,"",0,4,"a",-1,0,-1,0,254,254,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0254-02",19,"Llévame en la trasera\ndel carro, Pedro,\npara así estar más cerca\ndel bien que dejo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,254,254,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0254-03",19,"Firma tú y firmaré yo,\ny se juntarán dos firmas;\nveremos cuál de los dos\ncon más firmeza camina.",223,0,35,234,"",0,4,"ia",-1,0,-1,0,254,254,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0254-04",19,"Puse mi amor en un peso,\ny se quebró la balanza;\nquien bien ama, tarde olvida,\nquien porfía, mucho alcanza.",223,0,35,234,"",0,4,"aa",163,0,-1,0,254,254,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0254-05",19,"Escribistes en la arena\ny firmastes en el mar,\nel viento fué tu correo;\n¡vaya una seguridad!",223,0,35,234,"",0,4,"a",-1,0,-1,0,254,254,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0254-06",19,"Un imposible me mata,\npor un imposible muero,\nimposible es alcanzar\nel imposible que quiero.",223,0,35,234,"",0,4,"eo",38,0,-1,0,254,254,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0254-07",19,"Dicen que te vas, te vas,\ny muy pronto, dueño mío;\nmira no bebas el agua\nde la fuente del olvido.",223,0,35,234,"",0,4,"io",-1,0,-1,0,254,254,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0255-01",19,"El cielo de Andalucía\nestá vestido de azul;\npor eso la sal abunda\nen todo el suelo andaluz.",223,0,35,234,"",0,4,"u",-1,0,-1,0,255,255,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0255-02",19,"Sale la Cruz de la iglesia\nvestida de luto negro;\nharta Cruz tiene quien quiere\nprenda que estima á otro dueño.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,255,255,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0255-03",19,"Desde que te vi, rubita,\nese rostro tan severo,\nlas alas del corazón\ná los pies se me cayeron.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,255,255,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0255-04",19,"No me mires con ojos\natravesados,\nmírame con los ojos\nque Dios te ha dado.",223,0,35,234,"",6,4,"ao",-1,0,-1,0,255,255,"","",0,"rm_t2, barcenas_marinera","","",3,0,0,[],"",""],["fernan_caballero-p0255-05",19,"Quisiera ser de los cielos\ny mantenerte en el aire,\ny ya que yo no te llevo,\nque no te llevara nadie.",223,0,35,234,"",0,4,"ae",-1,0,-1,0,255,255,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0255-06",19,"Si piensas que porque canto\ntengo el corazón alegre,\nyo soy como el pajarito,\nque canta cuando se muere.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,255,255,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0255-07",19,"Si coronado vinieras\ncomo el santo rey David,\ny que á mis pies te pusieras,\nno habías de lograr el sí.",223,0,35,234,"",0,4,"i",-1,0,-1,0,255,255,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0256-01",19,"El corazón te daré,\nlas entrañas y la vida;\nel alma no te la doy,\npor que esta prenda no es mía.",223,0,35,234,"",0,4,"ia",-1,0,-1,0,256,256,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0256-02",19,"Desde tu puerta á la iglesia\nhe de poner una parra,\npara que vengas á misa\nsin darte el sol en la cara.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,256,256,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0256-03",19,"Aunque te vea en el suelo\ncon cuatro velas ardiendo,\nlos clérigos en la puerta,\nte tengo de estar queriendo.",223,0,35,234,"",0,4,"eo",52,0,-1,0,256,256,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0256-04",19,"Echame, niña bonita,\nlágrimas en un pañuelo,\ny las llevaré á Granada\nque las engarce un platero.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,256,256,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0256-05",19,"Sentenciado estoy á muerte\nsi me ven hablar contigo;\nya pueden los matadores\naprevenir los cuchillos.",223,0,35,234,"",0,4,"io",-1,0,-1,0,256,256,"","",0,"lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0256-06",19,"Aquel que tiene la culpa\nde que yo fatigas pase,\nse vea en Argel cautivo\nsin tener ningún rescate.",223,0,35,234,"",0,4,"ae",-1,0,-1,0,256,256,"","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0256-07",19,"Una vela se consume\ná fuerza de mucho arder;\nasí se consume un hombre\nal lado de una mujer.",223,0,35,234,"",0,4,"e",20,0,-1,0,256,256,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",7,0,0,[],"",""],["fernan_caballero-p0257-01",19,"Corazones partidos\nyo no los quiero,\nque cuando doy el mío\nle doy entero.",223,0,35,234,"",6,4,"eo",38,0,-1,0,257,257,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0257-02",19,"Son como los mosquitos\ntus amores, Juan,\nque pican, hacen ronchas,\ncantan y se van.",223,0,35,234,"",0,4,"a",147,0,-1,0,257,257,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0257-03",19,"Tienes ojos azules,\nojos de gloria,\ny los míos les piden\nmisericordia.",223,0,35,234,"",6,4,"oa",-1,0,-1,0,257,257,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0257-04",19,"Me han dicho que estás mala,\nDios te dé salud;\nno puedo ir á verte,\nbien lo sabes tú.",223,0,35,234,"",0,4,"u",-1,0,-1,0,257,257,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0257-05",19,"No me hagas más penar,\nmira que no soy de bronce,\ny aun las piedras se quebrantan\ná fuerza de muchos golpes.",223,0,35,234,"",0,4,"oe",-1,0,-1,0,257,257,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0257-06",19,"Cuando yo estaba en prisiones,\nmorena, me entretenía\nen contar los eslabones\nque mi cadena tenía.",223,0,35,234,"",1,4,"ia",0,0,-1,0,257,257,"","",0,"","","",10,0,0,[],"",""],["fernan_caballero-p0257-07",19,"Tu cuerpo parece un junco,\ntu cabeza una naranja,\ntu pecho un jardín de flores\ndonde descansa mi alma.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,257,257,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0258-01",19,"Son tus ojos dos fuentes\nde agua manantial,\ny mi pecho el aljibe\ndonde va á parar.",223,0,35,234,"",0,4,"a",-1,0,-1,0,258,258,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0258-02",19,"Tus amores me han puesto\nfuera de tino,\ny aunque estoy de esta suerte\nsin ti no vivo.",223,0,35,234,"",6,4,"io",-1,0,-1,0,258,258,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0258-03",19,"Si tuviera figura\nmi pensamiento,\nsiempre te lo encontraras\nen tu aposento.",223,0,35,234,"",6,4,"eo",94,0,-1,0,258,258,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0258-04",19,"De tus hermosos ojos\nno tengo queja,\nporque quieren mirarme\ny tú no los dejas.",223,0,35,234,"",6,4,"ea",-1,0,-1,0,258,258,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0258-05",19,"Eres el arco iris\nde mis pesares,\ncon el que se remedian\ntodos mis males.",223,0,35,234,"",6,4,"ae",-1,0,-1,0,258,258,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0258-06",19,"En Enero no hay claveles,\nporque los marchita el hielo;\nen tu cara los hay siempre,\nporque lo permite el cielo.",223,0,35,234,"",0,4,"eo",10,0,-1,0,258,258,"","",0,"rm_t2, carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0258-07",19,"Tengo yo una cuñada\nque se parece\nal lucero del alba\ncuando amanece.",223,0,35,234,"",6,4,"ee",64,0,-1,0,258,258,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0259-01",19,"Por San Juan hizo un año\nque te quería;\nmás firme estoy ahora\nque el primer día.",223,0,35,234,"",6,4,"ia",0,0,-1,0,259,259,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0259-02",19,"Tienes el amor puesto\ncon alfileres,\ny tan pronto me olvidas\ncomo me quieres.",223,0,35,234,"",6,4,"ee",55,0,-1,0,259,259,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0259-03",19,"Amarillo es el oro,\nblanca la plata,\ny pardos son los ojos\nque á mí me matan.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,259,259,"","",0,"palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0259-04",19,"Yo sembré una esperanza,\nnació un cariño,\nfloreció un desengaño,\ncausó un olvido.",223,0,35,234,"",6,4,"io",-1,0,-1,0,259,259,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0259-05",19,"Se murió una esperanza,\nfuí á su entierro,\ny vi que el desengaño\niba de duelo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,259,259,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0259-06",19,"Lo moreno lo hizo Dios,\nlo blanco lo hizo un platero,\nquien quiera tome lo blanco,\nyo lo moreno me quiero.",223,0,35,234,"",0,4,"eo",38,0,-1,0,259,259,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0259-07",19,"Por una que peinaba\nrubios cabellos,\nolvidé á una morena\nde pelo negro.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,259,259,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0260-01",19,"Mientras más ausénte estamos,\nmás firme estoy en amar;\nla luz del cielo me falte\nsi yo te llego á olvidar.",223,0,35,234,"",0,4,"a",21,0,-1,0,260,260,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0260-02",19,"¿Dónde vas con ese muerto\ncon la noche tan obscura?\nEl mismo me mandó que\nle diera la sepultura.",223,0,35,234,"",0,4,"ua",17,0,-1,0,260,260,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0260-03",19,"Tienes unos ojitos,\ny unas pestañas,\ny una linda boquita\ncon que me engañas.",223,0,35,234,"",6,4,"aa",42,0,-1,0,260,260,"","",0,"","","",20,0,0,[],"",""],["fernan_caballero-p0260-04",19,"El día que no veo\ná mi rubita,\nel dolor de cabeza\nno se me quita.",223,0,35,234,"",6,4,"ia",50,0,-1,0,260,260,"","",0,"rm_t2","","",4,0,0,[],"",""],["fernan_caballero-p0260-05",19,"Dame la mano, prima;\nno quiero, primo,\nque está muy lejos Roma\ny no sé el camino.",223,0,35,234,"",6,4,"io",-1,0,-1,0,260,260,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0260-06",19,"¿Cómo quieres que tenga\nfinos colores,\nsi me lo están quitando\ntus sinrazones?",223,0,35,234,"",6,4,"oe",-1,0,-1,0,260,260,"","",0,"","","",14,0,0,[],"",""],["fernan_caballero-p0260-07",19,"No quiero que me quieras\nni yo quererte,\nni que tú me aborrezcas\nni aborrecerte.",223,0,35,234,"",6,4,"ee",134,0,-1,0,260,260,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0261-01",19,"Una silla en mi casa\nno te la niego,\npero te desengaño,\nque no te quiero.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,261,261,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0261-02",19,"Entré en la iglesia moza,\nsalí casada;\nno hay quien desate el nudo\nde esta lazada.",223,0,35,234,"",6,4,"aa",49,0,-1,0,261,261,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0261-03",19,"Por el sí que dió la niña\nen la puerta de la iglesia,\npor el sí que dió la niña\nentró libre y salió presa.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,261,261,"","",0,"rm_t4, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0261-04",19,"De San Antonio vengo,\nAntonia mía;\nsólo de ver tu santo\ntraigo alegría.",223,0,35,234,"",6,4,"ia",0,0,-1,0,261,261,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0261-05",19,"De los altos cielecitos\ncayeron nueve azucenas:\ntres Antonias, tres Franciscas\ny tres divinas Manuelas.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,261,261,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0261-06",19,"Me enamoré jugando\nde una María;\ncuando quise olvidarla\nya no podía.",223,0,35,234,"",6,4,"ia",0,0,-1,0,261,261,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0261-07",19,"Virgen del Carmen, valedme;\nSan Antonio, que me muero;\ntengo una puñaladita\nen este costado izquierdo.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,261,261,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0262-01",19,"Si las estrellas del cielo\ntodas se volvieran lanzas\npunta abajo para el suelo,\nno pierdo las esperanzas.",223,0,35,234,"",1,4,"aa",110,0,-1,0,262,262,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0262-02",19,"Eres valle en lo bonita,\ny en lo garbosa Dolores,\ny en lo lozana y alegre\neres un ramo de flores.",223,0,35,234,"",3,4,"oe",5,0,-1,0,262,262,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0262-03",19,"El sentido se me pierde\ncuando con ella platico,\nen ver que tengo una novia\ncantadora y con buen pico.",223,0,35,234,"",0,4,"io",141,0,-1,0,262,262,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0262-04",19,"Si yo pudiese, mi niña,\nte pusiera por corona\ndos águilas imperiales\ny al Padre Santo de Roma.",223,0,35,234,"",0,4,"oa",-1,0,-1,0,262,262,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0262-05",19,"Si supiera ó entendiera\nque el sol que sale te ofende,\ncon el sol me peleara,\naunque el sol me diera muerte.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,262,262,"","",0,"palau_cantares, lafuente_madrid","","",11,0,0,[],"",""],["fernan_caballero-p0262-06",19,"Yo te quisiera estar viendo\ntreinta días cada mes,\nsiete días en semana,\ncada minuto una vez.",223,0,35,234,"",0,4,"e",150,0,-1,0,262,262,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0262-07",19,"Ausente estoy de tu vista,\npero no del pensamiento;\ncon los ojitos del alma\nte veo á cada momento.",223,0,35,234,"",0,4,"eo",94,0,-1,0,262,262,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0263-01",19,"Mi corazón dió un suspiro\ny el alma le preguntó:\n—¿Corazón, por qué suspiras?\n—Alma, porque tengo amor.",223,0,35,234,"",0,4,"o",-1,0,-1,0,263,263,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0263-02",19,"Bendito sea Dios, madre,\nque ya pareció el perdido;\nque no se puede perder\npájaro que tiene nido.",223,0,35,234,"",0,4,"io",101,0,-1,0,263,263,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0263-03",19,"Cada vez que paso y miro\nlos umbrales de tu puerta,\nme arrodillo y me prosterno\ncomo si fuese la iglesia.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,263,263,"","",0,"","","",25,0,0,[],"",""],["fernan_caballero-p0263-04",19,"El corazón se me parte\nde dolor y sentimiento,\nal ver que estás en el mundo\ny ya para mí te has muerto.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,263,263,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0263-05",19,"Si me quieres escribir\nyo te diré dónde vivo;\nen casa del desengaño,\ndonde tú nunca has vivido.",223,0,35,234,"",0,4,"io",-1,0,-1,0,263,263,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0263-06",19,"Echale pan al perro\nsi vas á verme,\nporque tiene mi madre\nsueño de liebre.",223,0,35,234,"",6,4,"ee",-1,0,-1,0,263,263,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0263-07",19,"Penita sobre penita,\nsobre penitas más penas;\nvengan, vengan sobre mí,\nque yo soy la madre de ellas.",223,0,35,234,"",0,4,"ea",-1,0,-1,0,263,263,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0264-01",19,"Envidia tengo á la tierra,\ny también á los gusanos,\nque te tienen de comer\nese cuerpo tan gitano.",223,0,35,234,"",0,4,"ao",-1,0,-1,0,264,264,"","",0,"lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0264-02",19,"Morena tiene que ser\nla tierra para claveles,\ny la mujer para el hombre\nmorenita y con desdenes.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,264,264,"","",0,"rm_t2, lafuente_madrid","","",9,0,0,[],"",""],["fernan_caballero-p0264-03",19,"Hermanitos terceros\nson los claveles;\nun clavel fué la causa\nde yo quererte.",223,0,35,234,"",6,4,"ee",-1,0,-1,0,264,264,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0264-04",19,"Tengo perdido el sueño\ny no sé dónde buscarlo;\nlo buscaré en el olvido,\ny el olvido, ¿dónde hallarlo?",223,0,35,234,"",0,4,"ao",236,0,-1,0,264,264,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0264-05",19,"A la luz del cigarro\nte vi la cara;\nno he visto clavellina\nmás encarnada.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,264,264,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0264-06",19,"Debajo de tu ventana,\npor pintarte á ti, pinté\nuna rosa catalana\ny un clavel aragonés.",223,0,35,234,"",0,4,"e",-1,0,-1,0,264,264,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",29,0,0,[],"",""],["fernan_caballero-p0264-07",19,"La mañana de San Juan\ncuaja la almendra y la nuez;\nasí cuajan los amores\ncuando dos se quieren bien.",223,0,35,234,"",0,4,"e",-1,0,-1,0,264,264,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0265-01",19,"Tan sólo en el mundo hay una\ncon que poder compararte,\ny la encontré por fortuna\npintada en un estandarte.",223,0,35,234,"",1,4,"ae",8,0,-1,0,265,265,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0265-02",19,"Entre los árboles todos\nse señorea el laurel;\nentre las mujeres Ana,\nentre flores el clavel.",223,0,35,234,"",0,4,"e",32,0,-1,0,265,265,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0265-03",19,"A mi padre y á mi madre\nlos quiero como es debido;\npero en llegando á mi amante,\npierdo los cinco sentidos.",223,0,35,234,"",0,4,"io",-1,0,-1,0,265,265,"","",0,"lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0265-04",19,"Tienes una cinturita\ntan delgada, que pareces\nel clavel en la maceta\nque con el aire se mece.",223,0,35,234,"",0,4,"ee",-1,0,-1,0,265,265,"","",0,"","","",14,0,0,[],"",""],["fernan_caballero-p0265-05",19,"Sin duda que tu padre\nfué confitero,\ny te hizo los labios\nde caramelo.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,265,265,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0265-06",19,"Mi corazón tú lo tienes,\ndámelo si no te sirve,\nse lo daré á otra paloma\nque con su calor lo abrigue.",223,0,35,234,"",0,4,"ie",-1,0,-1,0,265,265,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0266-01",19,"El encarnado clavel\nviene publicando agravios,\nporque no lo han hecho á él\nhermoso como tus labios.",223,0,35,234,"",1,4,"ao",45,0,-1,0,266,266,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0266-02",19,"Clavellina te diré,\npero no rosa de olor,\nque la rosa se deshoja\ny la clavellina no.",223,0,35,234,"",0,4,"o",-1,0,-1,0,266,266,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0266-03",19,"Vivo en el cautiverio\nde una morena,\ny, con un «sí» tan solo,\nsalgo de penas.",223,0,35,234,"",6,4,"ea",-1,0,-1,0,266,266,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0266-04",19,"Es tu cara la luna,\nla redondita,\ny tus ojos luceros\nque la visitan.",223,0,35,234,"",6,4,"ia",-1,0,-1,0,266,266,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0266-05",19,"Ya no se llaman dedos\nlos de tus manos,\nque se llaman claveles\nde cinco en ramo.",223,0,35,234,"",6,4,"ao",-1,0,-1,0,266,266,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0266-06",19,"El querer que te tengo\nlo he confesado,\ny el confesor me ha dicho\nque no es pecado.",223,0,35,234,"",6,4,"ao",14,0,-1,0,266,266,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0266-07",19,"Eres chiquita y bonita,\neres como yo te quiero,\npareces campanillita\nhecha á manos de un platero.",223,0,35,234,"",1,4,"eo",38,0,-1,0,266,266,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0267-01",19,"Yo tenía una maceta\nde claveles encarnados;\nde la noche á la mañana\nse han vuelto marisalados.",223,0,35,234,"",0,4,"ao",18,0,-1,0,267,267,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0267-02",19,"Antes de conocerte\nya te quería,\nporque me lo anunciaba\nla estrella mía.",223,0,35,234,"",6,4,"ia",0,0,-1,0,267,267,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0267-03",19,"La primera clavellina\nque eche mi clavellinero,\nse la tengo de poner\ná mi amante en el sombrero.",223,0,35,234,"",0,4,"eo",38,0,-1,0,267,267,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0267-04",19,"Manuel se llama Cristo,\n¡qué dulce nombre!\nDichoso el que naciendo\nManuel le ponen.",223,0,35,234,"",6,4,"oe",-1,0,-1,0,267,267,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0267-05",19,"La rosa en tus mejillas\nperdió su color,\ny el clavel en sus labios\nse disciplinó.",223,0,35,234,"",0,4,"o",-1,0,-1,0,267,267,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0267-06",19,"A tomillo y romero\nme hueles, niña.\n—Como vengo del campo,\nno es maravilla.",223,0,35,234,"",6,4,"ia",-1,0,-1,0,267,267,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0267-07",19,"María me dió una rosa,\nun clavel me dió Isabel;\ntoma tu rosa, María,\nque yo más quiero al clavel.",223,0,35,234,"",0,4,"e",32,0,-1,0,267,267,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0268-01",19,"Si mi corazón tuviera\nventanitas de cristal,\nte asomarías y vieras\nlo dolorido que está.",223,0,35,234,"",0,4,"a",-1,0,-1,0,268,268,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0268-02",19,"Compadécete de mí,\nque tienes el corazón\nmás duro que las columnas\ndel templo de Salomón.",223,0,35,234,"",0,4,"o",31,0,-1,0,268,268,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0268-03",19,"Yo tomé un cortijo á renta\ncon intención de labrarlo;\notro me pujó la puesta,\nme fué preciso dejarlo.",223,0,35,234,"",0,4,"ao",236,0,-1,0,268,268,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0268-04",19,"Por una prima tuya\nte quiero tanto;\nsiempre por la peana\nse besa al santo.",223,0,35,234,"",6,4,"ao",30,0,-1,0,268,268,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0268-05",19,"Si quieres que te quiera\ndame fianza;\npues de ti no me fío,\nque eres muy falsa.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,268,268,"","",0,"rm_t3, palau_cantares","","",17,0,0,[],"",""],["fernan_caballero-p0268-06",19,"Al mirarme tus ojos\nbajo los míos,\nque tus ojos abrasan\nmás que el estío.",223,0,35,234,"",6,4,"io",-1,0,-1,0,268,268,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0268-07",19,"Los claveles y las rosas\nformaron una batalla,\ny los claveles ganaron,\nporque estaban en tu casa.",223,0,35,234,"",0,4,"aa",-1,0,-1,0,268,268,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0269-01",19,"Cuatro eses componen\namor perfecto;\nser solícito y sabio,\nsolo y secreto.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,269,269,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0269-02",19,"Cada vez que te veo,\npara mí digo:\ná mi prójimo amo\ncomo á mí mismo.",223,0,35,234,"",6,4,"io",-1,0,-1,0,269,269,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["fernan_caballero-p0269-03",19,"Ya viene Marzo con flores,\ny con sus rosas Abril,\ny Mayo con sus claveles\npara coronarte á ti.",223,0,35,234,"",0,4,"i",-1,0,-1,0,269,269,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0269-04",19,"Mira cómo corre el agua\npor la hoja del clavel;\nasí corre la hermosura\npor la cara de mi bien",223,0,35,234,"",0,4,"e",-1,0,-1,0,269,269,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0269-05",19,"Es tanto lo que te quiero,\ny lo que te quiero es tanto,\nque el día que no te veo\nno le rezo á ningún santo.",223,0,35,234,"",0,4,"ao",30,0,-1,0,269,269,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",26,0,0,[],"",""],["fernan_caballero-p0269-06",19,"Yo te quiero y te requiero\ny te tengo de querer,\nhasta soltar el pellejo\ncomo San Bartolomé.",223,0,35,234,"",0,4,"e",-1,0,-1,0,269,269,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0269-07",19,"Mal haya la ropa negra\ny el sastre que la cortó,\nque mi niña está de luto\nsin haberme muerto yo.",223,0,35,234,"",0,4,"o",2,0,-1,0,269,269,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0270-01",19,"Hábito de Dolores\ntiene mi dama;\ncon los siete cuchillos\nme parte el alma.",223,0,35,234,"",6,4,"aa",-1,0,-1,0,270,270,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0270-02",19,"Quiéreme poco á poco,\nno te apresures,\nque lo que á mí me gusta\nquiero que dure.",223,0,35,234,"",6,4,"ue",-1,0,-1,0,270,270,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0270-03",19,"El clavel que tú me diste\nel día de la Ascensión,\nno fué clavel, sino clavo\nque clavó en mi corazón.",223,0,35,234,"",0,4,"o",31,0,-1,0,270,270,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0270-04",19,"Yo sembré una mirada,\nnació un deseo,\nfloreció una esperanza,\ncogí un desprecio.",223,0,35,234,"",6,4,"eo",-1,0,-1,0,270,270,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0270-05",19,"Esos ojitos azules\nse los robastes al cielo,\ny al cielo le darás cuenta\ndel mal que hiciste con ellos.",223,0,35,234,"",0,4,"eo",-1,0,-1,0,270,270,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0270-06",19,"Yo te quiero y no quiero,\nque son dos cosas;\nyo te quiero, y no quiero\nque lo conozcas.",223,0,35,234,"",6,4,"oa",-1,0,-1,0,270,270,"","",0,"rm_t2, suspiros_amor","","",5,0,0,[],"",""],["fernan_caballero-p0270-07",19,"Las calles de Sevilla\nse están arando;\nde rosas y claveles\nse están sembrando.",223,0,35,234,"",6,4,"ao",33,0,-1,0,270,270,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0271-01",19,"Los celos y las olas\ndel mar son unas,\nque producen montañas\ny son espuma.",223,0,35,234,"",6,4,"ua",-1,0,-1,0,271,271,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0271-02",19,"A la flor de la adelfa\nte he comparado,\nque es hermosa y no come\nde ella el ganado.",223,0,35,234,"",6,4,"ao",14,0,-1,0,271,271,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0271-03",19,"No me seas retrechera,\nporque te he de comparar\ncon el reloj de Pamplona,\nque apunta, pero no da.",223,0,35,234,"",0,4,"a",-1,0,-1,0,271,271,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0271-04",19,"La calle en que vives,\nsi fuera mía,\nde brillantes y perlas\nla empedraría.",223,0,35,234,"",6,4,"ia",0,0,-1,0,271,271,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0271-05",19,"A mi corazón prendieron,\ná la cárcel lo llevaron,\ny sin delito ninguno,\ná muerte lo sentenciaron.",223,0,35,234,"",0,4,"ao",41,0,-1,0,271,271,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0271-06",19,"¿Para qué vas y vienes,\ndoctor, confuso,\nsi el mal que á mí me aqueja\nno sale al pulso?",223,0,35,234,"",6,4,"uo",-1,0,-1,0,271,271,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["fernan_caballero-p0271-07",19,"Dos estrellas se han perdido\ny en el cielo no parecen;\nen tu casa se han metido\ny en tu cara resplandecen.",223,0,35,234,"",1,4,"ee",359,0,-1,0,271,271,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0272-01",19,"No sé qué tenía el agua\nque me distes á beber,\nque á todo el mundo aborrezco\ny á ti no ha podido ser.",223,0,35,234,"",0,4,"e",20,0,-1,0,272,272,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0272-02",19,"Tienes en la cara pecas,\ny en tu garganta lunares,\ny en tu pecho más virtudes\nque arena tienen los mares.",223,0,35,234,"",0,4,"ae",164,0,-1,0,272,272,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0272-03",19,"Tengo que hacer un castillo\nencima de un alfiler,\ny ha de tener más firmeza\nque ha tenido tu querer.",223,0,35,234,"",0,4,"e",20,0,-1,0,272,272,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0273-01",19,"La constancia y el Fénix\nson dos prodigios\nde quienes todos hablan\ny nadie ha visto.\nPor mí confieso\nque no penaré nunca\npor conocerlos.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,273,273,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0273-03",19,"Cuando el amor ardiendo\nestá en el alma,\nlos reflejos del fuego\ndan en la cara.\nTambién el humo\nsale haciendo burla\ndel disimulo.",223,0,35,235,"",4,7,"uo",-1,0,-1,0,273,273,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0273-05",19,"Por Dios, si no me quieres\nque no me mires;\nya que no me rescates,\nno me cautives.\nNo me mires más;\nno me pongas cadenas\nque no has de quitar.",223,0,35,235,"",4,7,"a",-1,0,-1,0,273,273,"","",0,"rm_t2","","",7,0,0,[],"",""],["fernan_caballero-p0274-01",19,"Descuidados mis ojos\nvieron tu cara;\ncara les ha costado\nesa mirada.\nPues dijo el alma:\n¡qué cara tan divina!\npero ¡qué cara!",223,0,35,235,"",4,7,"aa",-1,0,-1,0,274,274,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0274-03",19,"Diga usted, señor platero:\n¿cuánta plata es menester\npara engarzar unos celos\nque me ha dado mi mujer?\nSi fuera mía,\nyo engarzara los celos\nen mala vida.",223,0,35,235,"",4,7,"ia",-1,0,-1,0,274,274,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0274-05",19,"Vivo con la esperanza\nde ser tu dueño,\ny por eso me visto\nde verde y negro.\nVerde esperanza,\ny lo negro es el luto\nde la tardanza.",223,0,35,235,"",4,7,"aa",163,0,-1,0,274,274,"","",0,"rm_t2","","",4,0,0,[],"",""],["fernan_caballero-p0274-07",19,"Soñé que me querías\nla otra mañana,\ny soñé al mismo tiempo\nque lo soñaba.\nQue á un infelice,\naun las dichas soñadas\nson imposibles.",223,0,35,235,"",4,7,"ie",-1,0,-1,0,274,274,"","",0,"preciso_coleccion","","",4,0,0,[],"",""],["fernan_caballero-p0275-01",19,"Pasando por tu calle\nvi pelearse\ndos piedras, pretendiendo\nque las pisases.\nYo dije entonces:\nsi esto hacen las piedras\n¿qué harán los hombres?",223,0,35,235,"",4,7,"oe",-1,0,-1,0,275,275,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0275-03",19,"Un oficial muy fino\nme dijo un día,\nque si yo no lo amaba\nse moriría.\nPero es lo cierto\nque yo no le he amado,\ny él no se ha muerto.",223,0,35,235,"",4,7,"eo",88,0,-1,0,275,275,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0275-05",19,"San Antonio bendito,\ntres cosas pido:\nsalvación y dinero\ny un buen marido.\nYa te lo he dado,\njugador de las cartas\ny enamorado.",223,0,35,235,"",4,7,"ao",14,0,-1,0,275,275,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0275-07",19,"En el alma te tengo\ntan á lo vivo,\nque despierto soñando\nsiempre contigo.\nY en despertando,\nme digo yo á mí mismo:\nvamos soñando.",223,0,35,235,"",4,7,"ao",33,0,-1,0,275,275,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0276-01",19,"Yo me arrimé á una fragua,\ndije al herrero\nque me hiciese un amante\nde fino acero.\nEl me responde:\nno puede ser muy fino\nsi ha de ser hombre.",223,0,35,235,"",4,7,"oe",-1,0,-1,0,276,276,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0276-03",19,"Son tu mejillas rosas,\nquiero cogerlas;\npero tienen espinas\nque las defiendan.\nY que esas rosas\nlas espinas que tienen\nson enconosas.",223,0,35,235,"",4,7,"oa",61,0,-1,0,276,276,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0276-05",19,"Herodes y Pilatos\nson enemigos;\npara perder al Justo\nse hacen amigos.\nDios nos ampare,\nsi Herodes y Pilatos\nse hacen compadres.",223,0,35,235,"",4,7,"ae",-1,0,-1,0,276,276,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0276-07",19,"Me miras y te miro,\ncallas y callo,\nasí nos estaremos\ndoscientos años.\nMas te prevengo,\nque si tú no te explicas,\nyo no te entiendo.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,276,276,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0277-01",19,"Son tantos los que tienes\nen el corazón,\nque del lado de afuera\nme he quedado yo.\nY muy contento,\npor no estar confundido\ncon los de dentro.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,277,277,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0277-03",19,"Algún día sentía\ntus esquiveces,\ny hoy me son tus halagos\nindiferentes.\nDe esta mudanza,\npregúntate á ti misma\nquién es la causa.",223,0,35,235,"",4,7,"aa",-1,0,-1,0,277,277,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0277-05",19,"Primero que te olvide,\ndijiste, Aurora,\nse ha de volver cristiana\nla reina mora.\nMe has olvidado,\npero la reina mora\nmora ha quedado.",223,0,35,235,"",4,7,"ao",14,0,-1,0,277,277,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0277-07",19,"No compres en la tienda\ndel dios Cupido,\nque por cualquier cosa\nlleva un sentido.\nVe con cautela,\nno cambies los sentidos\npor bagatelas.",223,0,35,235,"",4,7,"ea",-1,0,-1,0,277,277,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0278-01",19,"Calla, no me repliques,\nque el cargo es justo;\ndeja que te convenza\nde que te sufro.\nNo satisfaces,\ny me quitas el gusto\nde perdonarte.",223,0,35,235,"",4,7,"ae",-1,0,-1,0,278,278,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0278-03",19,"Si mil almas tuviera,\nte diera juntas;\ntoma, pues no las tengo,\nmil veces una.\nQue si lo adviertes,\nes más que miles juntas\nuna mil veces.",223,0,35,235,"",4,7,"ee",-1,0,-1,0,278,278,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0278-05",19,"En tu abanico, Elvira,\nquiero pintarte,\npara que tu retrato\nte dé algún aire.\nPues no hay pintor\nque dibuje con aire,\ngracia y primor.",223,0,35,235,"",4,7,"o",72,0,-1,0,278,278,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0278-07",19,"Es mi amor, dueño mío,\ncomo la sombra;\nmientras más apartado,\nmás cuerpo toma.\nQue ausencia es aire\nque apaga el fuego chico\ny enciende el grande.",223,0,35,235,"",4,7,"ae",-1,0,-1,0,278,278,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0279-01",19,"El sol, al ver tus ojos,\ncorrido huye;\nque le des luces pide,\nque le desluces.\nPues hay más fuego\nen tus ojos, María,\nque en todo el cielo.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,279,279,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0279-03",19,"Una noche lloviendo\nquise olvidarte,\nporque estaba yo viendo\nsegundo amante.\nY yo no quiero\nque haya segundo amante\ny más yo viendo.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,279,279,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0279-05",19,"Me preguntó un amigo\nlo que eran celos;\nno sabe el bien que tiene\ncon no saberlo.\nDe buena gana\ntrocara yo mi ciencia\npor su ignorancia.",223,0,35,235,"",4,7,"aa",-1,0,-1,0,279,279,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0279-07",19,"Permíteme te diga,\nsi no te ofendo,\nque mientras más te trato\nmenos te entiendo.\nPues prontamente\nretrocedes de amante\ná indiferente.",223,0,35,235,"",4,7,"ee",15,0,-1,0,279,279,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0280-01",19,"Ausente de tu vista\nmucho más vivo,\nporque cada momento\nse me hace un siglo.\nPero mi dueño,\nmás que vivir ausente,\nmorirme quiero.",223,0,35,235,"",4,7,"eo",-1,0,-1,0,280,280,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0280-03",19,"Mi corazón de cera,\ntus ojos soles;\ncontempla si me miras\ncómo me pones.\nY si reparas,\nverás que me derrito\nde una mirada.",223,0,35,235,"",4,7,"aa",-1,0,-1,0,280,280,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0280-05",19,"Dame de tu cabeza\nsiquiera un pelo,\npara atarme una herida\nque amor me ha hecho.\nPero es una locura,\npues más ha de inflamarse\ncon la atadura.",223,0,35,235,"",4,7,"ua",17,0,-1,0,280,280,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0280-07",19,"Mi corazón volando\nse fué á tu pecho,\nle cortaste las alas\ny quedó dentro.\nPor atrevido,\nse quedará por siempre\nen él metido.",223,0,35,235,"",4,7,"io",101,0,-1,0,280,280,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0281-01",19,"Tengo yo un cofrecito\ndonde ir echando\npenas y pesadumbres\nque me vas dando.\nPero algún día\nse abrirá el cofrecito;\nserá la mía.",223,0,35,235,"",4,7,"ia",0,0,-1,0,281,281,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0281-03",19,"Cuando voy á la casa\nde mi María,\nse me hace cuesta abajo\nla cuesta arriba.\nY cuando salgo,\nse me hace cuesta arriba\nla cuesta abajo.",223,0,35,235,"",4,7,"ao",-1,0,-1,0,281,281,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0281-05",19,"Me dijiste veleta\npor lo mudable;\nsi yo soy la veleta,\ntú eres el aire.\nQue la veleta,\nsi el aire no la mueve,\nsiempre está quieta.",223,0,35,235,"",4,7,"ea",200,0,-1,0,281,281,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0281-07",19,"Para pescar á un hombre,\nse necesita\nuna caña muy larga\ncon una guita.\nY para echarlo,\nponerlo en el poyete\ny arrempujarlo.",223,0,35,235,"",4,7,"ao",236,0,-1,0,281,281,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0282-01",19,"He pensado olvidarte\nquinientas veces,\ny en viéndote, no hay forma\nde que me acuerde.\nQue un pecho fino\nsólo olvida las causas\nde los olvidos.",223,0,35,235,"",4,7,"io",-1,0,-1,0,282,282,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0282-03",19,"Si te preguntan, niña,\ná quién adoras,\nprimero morir mártir\nque confesora.\nQue el que confiesa,\ntiene siempre segura\nla penitencia.",223,0,35,235,"",4,7,"ea",-1,0,-1,0,282,282,"","",0,"rm_t2, suspiros_amor","","",3,0,0,[],"",""],["fernan_caballero-p0282-05",19,"Me quisistes amante;\nmás de ahí á poco,\ndesnudastes á un santo\npor vestir á otro.\nPero te digo\nque el santo desnudado\nya está vestido.",223,0,35,235,"",4,7,"io",-1,0,-1,0,282,282,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0282-07",19,"Al sol es parecido\nquien celos tiene,\nque levanta vapores\nque lo obscurecen.\nY las tormentas\nse forman de las nubes\nde las sospechas.",223,0,35,235,"",4,7,"ea",-1,0,-1,0,282,282,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0283-01",19,"A la sala del crimen\nllevé tus ojos,\nporque son dos ladrones\nfacinerosos.\nY cuando entraron\nse ha quejado el regente\nque le robaron.",223,0,35,235,"",4,7,"ao",41,0,-1,0,283,283,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0283-03",19,"Delicada es la rosa;\nmas si la ofenden,\ntiene en el tronco espinas\nque la defienden.\nPara cogerla\nes necesario tiento\ny no ofenderla.",223,0,35,235,"",4,7,"ea",428,0,-1,0,283,283,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0283-05",19,"Capuchinos tus ojos\nme han parecido,\ny con ojos de santo\nme han seducido.\n¡Quién lo pensara,\nque con ojos de santo\ntú me engañaras!",223,0,35,235,"",4,7,"aa",-1,0,-1,0,283,283,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0284-01",19,"Empiezo la primera\nen nombre de Dios;\nperderé la vergüenza\ny alzaré la voz.",223,0,35,236,"",0,4,"o",280,0,-1,0,284,284,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0284-02",19,"En el nombre sea de Dios\ny del Espíritu Santo;\nesta es la primera copla\nque á tu puerta, niña, canto.",223,0,35,236,"",0,4,"ao",30,0,-1,0,284,284,"","",0,"rm_t2, lafuente_madrid","","",7,0,0,[],"",""],["fernan_caballero-p0284-03",19,"A tu puerta estamos cuatro,\ntodos cuatro te queremos;\nescoge tú al que tú quieras,\nque los demás buscaremos.",223,0,35,236,"",0,4,"eo",127,0,-1,0,284,284,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0284-04",19,"Del polvo de la tierra\nsaco yo coplas;\nno bien se acaba una,\nya tengo otra.",223,0,35,236,"",6,4,"oa",-1,0,-1,0,284,284,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0284-05",19,"Si esta noche no sales\ná la ventana,\ncuéntame entre los muertos\ndesde mañana.",223,0,35,236,"",6,4,"aa",4,0,-1,0,284,284,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0285-01",19,"La guitarra sin prima\nsuena quejosa,\ncomo estoy yo contigo\npor cierta cosa.",223,0,35,236,"",6,4,"oa",63,0,-1,0,285,285,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0285-02",19,"A esta puerta hemos llegado,\ntodo el mundo cante bien,\nque es hija de un padre honrado\ny de una mujer de bien.",223,0,35,236,"",1,4,"e",-1,0,-1,0,285,285,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0285-03",19,"A tu puerta hemos llegado\ncuatrocientos en cuadrilla;\nsi quieres que te cantemos,\nsaca cuatrocientas sillas.",223,0,35,236,"",0,4,"ia",-1,0,-1,0,285,285,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0285-04",19,"Por la calle abajo viene\nuna guitarra de plata,\ny la prima va diciendo:\nuna morena me mata.",223,0,35,236,"",0,4,"aa",74,0,-1,0,285,285,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0285-05",19,"Si supiera que cantando\nte había de divertir,\ntoda la noche cantara,\naunque perdiera el dormir.",223,0,35,236,"",0,4,"i",157,0,-1,0,285,285,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",10,0,0,[],"",""],["fernan_caballero-p0285-06",19,"¿Cómo quieres que tenga\ngusto en el cante,\nsi la prenda que adoro\nno está delante?",223,0,35,236,"",6,4,"ae",47,0,-1,0,285,285,"","",0,"rm_t3, palau_cantares","","",14,0,0,[],"",""],["fernan_caballero-p0285-07",19,"Madre mía del Carmen,\ndadme salero,\nque el cantar quiere gracia\ny no la tengo.",223,0,35,236,"",6,4,"eo",-1,0,-1,0,285,285,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0286-01",19,"Coplitas y más coplitas,\ncoplitas he de cantar,\nporque tengo un arca llena\ny un costal por desatar.",223,0,35,236,"",0,4,"a",21,0,-1,0,286,286,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0286-02",19,"Bien pudiera la luna\nser campechana,\ny alumbrar con sus rayos\ná tu ventana.",223,0,35,236,"",6,4,"aa",4,0,-1,0,286,286,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0286-03",19,"Cante usted, compañerito;\ncante usted, vamos cantando,\nque si usted no sabe coplas,\nyo se las iré apuntando.",223,0,35,236,"",0,4,"ao",33,0,-1,0,286,286,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0286-04",19,"Debajo de tu ventana\nme dió el sueño y me dormí,\ny me despertó tu gallo\ncantando quiquiriquí.",223,0,35,236,"",0,4,"i",23,0,-1,0,286,286,"","",0,"","","",29,0,0,[],"",""],["fernan_caballero-p0286-05",19,"La paloma está en la cama\narropadita y caliente,\ny el palomo está en la esquina\ndándose diente con diente.",223,0,35,236,"",0,4,"ee",15,0,-1,0,286,286,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0286-06",19,"Si mis suspiros llegan\ná tu almohada,\ncomo caritativa,\ndales posada.",223,0,35,236,"",6,4,"aa",49,0,-1,0,286,286,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0286-07",19,"Tengo este cuerpo de coplas\nque parece un avispero,\nbatallando una con otra\ná ver cuál sale primero.",223,0,35,236,"",0,4,"eo",38,0,-1,0,286,286,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0287-01",19,"Asómate á esa ventana,\ncara de luna brillante;\naunque yo no te conozco,\nconmigo viene tu amante.",223,0,35,236,"",0,4,"ae",47,0,-1,0,287,287,"","",0,"","","",50,0,0,[],"",""],["fernan_caballero-p0287-02",19,"Voy á cantar las coplas\nque me han mandado,\nque no quiero que digan,\nmalo y rogado.",223,0,35,236,"",6,4,"ao",14,0,-1,0,287,287,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0287-03",19,"Asómate á esa ventana,\ncara de piñón de oro;\nquiero encender un cigarro\nen la niña de tus ojos.",223,0,35,236,"",0,4,"oo",-1,0,-1,0,287,287,"","",0,"","","",50,0,0,[],"",""],["fernan_caballero-p0287-04",19,"La luna para salir\nal cielo pide licencia,\ny para cantar yo aquí\nla pido con reverencia.",223,0,35,236,"",0,4,"ea",46,0,-1,0,287,287,"","",0,"","","",14,0,0,[],"",""],["fernan_caballero-p0287-05",19,"Por esta calle á lo largo\nanda un gavilán perdido,\nque dice que ha de sacar\nla paloma de su nido.",223,0,35,236,"",0,4,"io",101,0,-1,0,287,287,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0287-07",19,"Por esta calle á lo largo\ndicen que no hay Catalinas;\nsi las supiesen buscar,\nlas hay como clavellinas.",223,0,35,236,"",0,4,"ia",243,0,-1,0,287,287,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0288-01",19,"A mí me tocó la suerte,\ncomo mejor director,\nde venir á despertar\ndel barrio la mejor flor.",223,0,35,236,"",0,4,"o",72,0,-1,0,288,288,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0288-02",19,"La otra noche en tu ventana\ncinco claveles te di,\ny eran los cinco sentidos\nque puestos tenía en ti.",223,0,35,236,"",0,4,"i",23,0,-1,0,288,288,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0288-03",19,"De todas las despedidas\nes la mía la más alta:\nadiós, clavel; adiós, rosa;\nadiós, matita de albahaca.",223,0,35,236,"",0,4,"aa",-1,0,-1,0,288,288,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0288-04",19,"Echemos la despedida\ncon muchísimo dolor;\nen los clavos de tu puerta\nse queda mi corazón.",223,0,35,236,"",0,4,"o",-1,0,-1,0,288,288,"","",0,"","","",18,0,0,[],"",""],["fernan_caballero-p0288-05",19,"Despidámosla, señores,\ndespidámosla corteses,\nque es hija de buenos padres\ny que ella se lo merece.",223,0,35,236,"",0,4,"ee",-1,0,-1,0,288,288,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0288-06",19,"Cuando cierras la ventana,\nal crujir de la madera\nse me pone el corazón\ncomo el panal de la cera.",223,0,35,236,"",0,4,"ea",44,0,-1,0,288,288,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0288-07",19,"Mis amiguitos me dicen\nque no me sé despedir;\nadiós, clavel; adiós, rosa;\nadiós, precioso jazmín.",223,0,35,236,"",0,4,"i",-1,0,-1,0,288,288,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0289-01",19,"Echemos la despedida,\nla que Cristo echó en el río;\nlos pájaros piden agua\ny las muchachas marido.",223,0,35,236,"",0,4,"io",-1,0,-1,0,289,289,"","",0,"lafuente_madrid","","",18,0,0,[],"",""],["fernan_caballero-p0289-02",19,"Allá va la despedida\nal uso de Barcelona;\nla madre que te parió\nmerecía una corona.",223,0,35,236,"",0,4,"oa",7,0,-1,0,289,289,"","",0,"","","",25,0,0,[],"",""],["fernan_caballero-p0289-03",19,"Con esta copla, señores,\nde mi niña me despido,\nque mi madre ya dirá:\n¿Dónde estará ese perdido?",223,0,35,236,"",0,4,"io",101,0,-1,0,289,289,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0289-04",19,"Allá va la despedida,\nque ya me voy á dormir,\nporque mi madre no tiene\naceite para el candil.",223,0,35,236,"",0,4,"i",-1,0,-1,0,289,289,"","",0,"","","",25,0,0,[],"",""],["fernan_caballero-p0290-01",19,"A la que está bailando\necharle rosas,\nporque se lo merece\npor buena moza.",223,0,35,237,"",6,4,"oa",-1,0,-1,0,290,290,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0290-02",19,"La niña que está bailando\nparece un pimpollo de oro;\npregúntale, compañero,\nsi es casada ó tiene novio.",223,0,35,237,"",0,4,"oo",-1,0,-1,0,290,290,"","",0,"palau_cantares, lafuente_madrid","","",19,0,0,[],"",""],["fernan_caballero-p0290-03",19,"La niña que está bailando\nes mi novia, y no me pesa;\nme la quisiera poner\npor corona en la cabeza.",223,0,35,237,"",0,4,"ea",108,0,-1,0,290,290,"","",0,"","","",19,0,0,[],"",""],["fernan_caballero-p0290-04",19,"La niña que está bailando\nparece una Santa Rita,\ny puede cortarle un sayo\ná las ánimas benditas.",223,0,35,237,"",0,4,"ia",-1,0,-1,0,290,290,"","",0,"","","",19,0,0,[],"",""],["fernan_caballero-p0290-05",19,"El mocito que baila\nlas seguidillas\nse ha dejado en su casa\nlas pantorrillas.",223,0,35,237,"",6,4,"ia",294,0,-1,0,290,290,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0291-01",19,"Señor bailadorcito,\nno me la canses,\nque va á ser mi madrina\ncuando me case.",223,0,35,237,"",6,4,"ae",-1,0,-1,0,291,291,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0291-02",19,"Esos dos que están bailando,\n¡qué parejitos que son!\nSi yo fuese padre cura,\nles daba la bendición.",223,0,35,237,"",0,4,"o",31,0,-1,0,291,291,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0291-03",19,"Ya está puesta en el baile\nla que no quiere\nque le digan la reina\nde las mujeres.",223,0,35,237,"",6,4,"ee",-1,0,-1,0,291,291,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0292-01",19,"¡Con qué pena vivirá\nla mujer del marinero,\nque al pie del palo mayor\ntiene pagado el entierro!",223,0,35,238,"",0,4,"eo",-1,0,-1,0,292,292,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0292-02",19,"A los vientos pregunto\nsi han visto á mi amor;\ncomo son mis contrarios,\nme dicen que no.",223,0,35,238,"",0,4,"o",-1,0,-1,0,292,292,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0292-03",19,"Todas las mañana voy\ná la orillita del mar,\ná preguntar á las olas\nsi han visto á mi amor pasar.",223,0,35,238,"",0,4,"a",21,0,-1,0,292,292,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0292-04",19,"En el mar hay un pescado\nque le llaman la corbina,\ny en la tierra una serpiente\nque se llama Catalina.",223,0,35,238,"",0,4,"ia",11,0,-1,0,292,292,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0292-05",19,"Toma, niña, esta tumbaga,\nque te la da un marinero;\n¡ojalá que te se vuelva\nuna barquita con remos!",223,0,35,238,"",0,4,"eo",-1,0,-1,0,292,292,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0293-01",19,"Yo soy como aquel barquito\nque lo están encarenando;\nmientras más golpes le dan,\nmás firme lo van dejando.",223,0,35,238,"",0,4,"ao",33,0,-1,0,293,293,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0293-02",19,"Tengo yo una navecita,\ndonde navego de día,\nque en soltándole los remos\ntodas las mares son mías.",223,0,35,238,"",0,4,"ia",-1,0,-1,0,293,293,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0293-03",19,"Marinero soy, señora;\nen el hombro traigo el ancla,\ny cuando llego á bahía\ndoy fondo con la esperanza.",223,0,35,238,"",0,4,"aa",-1,0,-1,0,293,293,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0293-04",19,"En el cielo está mi Dios,\nen la mar está mi dicha,\nen el aire mi esperanza\ny en tierra quedó mi vida.",223,0,35,238,"",0,4,"ia",-1,0,-1,0,293,293,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0293-05",19,"Al marinero en el mar\nnunca le falta una pena;\nya se le rompe el timón,\nya se le \"rifa la vela\".",223,0,35,238,"",0,4,"ea",-1,0,-1,0,293,293,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0293-06",19,"Toda mi vida en el mar\nno me han cautivado moros,\ny una vez que entré en tu casa\nme cautivaron tus ojos.",223,0,35,238,"",0,4,"oo",-1,0,-1,0,293,293,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0293-07",19,"Un marinerito, madre,\nme tiene robada el alma;\nsi no me caso con él\nmuero moza y llevo palma.",223,0,35,238,"",0,4,"aa",125,0,-1,0,293,293,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0294-01",19,"Mi madre me pega palos\nporque quiero á un marinero,\ny al son de los palos digo:\nvivan las anclas y remos.",223,0,35,238,"",0,4,"eo",-1,0,-1,0,294,294,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0294-02",19,"Un carpintero me quiere,\ny un sastre me solicita,\ny un marinero ha de ser\ndueño de mi personita.",223,0,35,238,"",0,4,"ia",50,0,-1,0,294,294,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0294-03",19,"Marinero es mi amante\nde agua salada,\nporque los de agua dulce\nno valen nada.",223,0,35,238,"",6,4,"aa",49,0,-1,0,294,294,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["fernan_caballero-p0294-04",19,"Marinero es mi amante,\nmucho lo siento;\nque andan por esos mares\nmis pensamientos.",223,0,35,238,"",6,4,"eo",-1,0,-1,0,294,294,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["fernan_caballero-p0294-05",19,"A las doce de la noche\neché mi barquita al mar,\npensando que era Levante,\ny se volvió vendaval.",223,0,35,238,"",0,4,"a",-1,0,-1,0,294,294,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0294-06",19,"Tengo pasadas por ti\nmás penas y más fatigas\nque pasan los marineros\nen el Callao de Lima.",223,0,35,238,"",0,4,"ia",-1,0,-1,0,294,294,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0295-01",19,"A la puerta de un sastre\ntodas son tiras,\ny á la de un zapatero\ntodas mentiras.",223,0,35,239,"",6,4,"ia",295,0,-1,0,295,295,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0295-02",19,"Tienen los zapateros\nen el cogote\nun letrero que dice:\nviva el cerote.",223,0,35,239,"",6,4,"oe",292,0,-1,0,295,295,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0295-03",19,"Yo soy un pobre barbero\ny no tengo qué comer;\nno sé si cierre la puerta\ny abra la de mi mujer.",223,0,35,239,"",0,4,"e",20,0,-1,0,295,295,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0295-04",19,"No lo quiero zapatero,\nque se le secan los muslos,\nsino lo quiero arriero\nque vaya y venga en el mulo.",223,0,35,239,"",0,4,"uo",-1,0,-1,0,295,295,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0295-05",19,"Un remendero fué á misa\ny no sabía rezar,\ny andaba por los altares:\n—¿Zapatos que remendar?",223,0,35,239,"",0,4,"a",21,0,-1,0,295,295,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0296-01",19,"Un zapatero y un sastre\ny un oficial de barbero,\nson tres personas distintas\ny ninguno verdadero.",223,0,35,239,"",0,4,"eo",38,0,-1,0,296,296,"","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",9,0,0,[],"",""],["fernan_caballero-p0296-02",19,"No te enamores, mi niña,\nde maestro de barbero,\nque se acuestan sin cenar\ny amanecen sin dinero.",223,0,35,239,"",0,4,"eo",38,0,-1,0,296,296,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0296-03",19,"—Lo quiero carpintero,\nque saque astillas.\n—Sí, hija, y que las saque\nde tus costillas.",223,0,35,239,"",6,4,"ia",294,0,-1,0,296,296,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0296-04",19,"Si me quieres, te advierto\nque soy albañil;\nuna peseta gano,\ny esa es para mí.",223,0,35,239,"",0,4,"i",-1,0,-1,0,296,296,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0296-05",19,"Anda vete, anda vete,\nbarbero loco,\nque mi madre no quiere\nni yo tampoco.",223,0,35,239,"",6,4,"oo",152,0,-1,0,296,296,"","",0,"rm_t3","","",6,0,0,[],"",""],["fernan_caballero-p0296-06",19,"Tengo un amante hechicero\nque vale más que un Perú,\ny su oficio es de torero,\ntorerito y andaluz.",223,0,35,239,"",0,4,"u",-1,0,-1,0,296,296,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0296-07",19,"Tienen las cigarreras\nen el zapato\nun letrero que dice:\nviva el tabaco.",223,0,35,239,"",6,4,"ao",-1,0,-1,0,296,296,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0297-01",19,"Si en mi libro hubiese damas\ncomo las que estoy mirando,\ntoda la noche de Dios\nme la llevara estudiando.",223,0,35,240,"",0,4,"ao",33,0,-1,0,297,297,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0297-02",19,"Cuando un estudiante llega\ná la esquina de una plaza,\ndicen las revendedoras:\nfuera ese perro de caza.",223,0,35,240,"",0,4,"aa",307,0,-1,0,297,297,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0297-03",19,"Un estudiante tunante\nse puso á pintar la luna,\ny de hambre que tenía,\npintó un plato de aceitunas.",223,0,35,240,"",0,4,"ua",-1,0,-1,0,297,297,"","",0,"rm_t4, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0297-05",19,"De una cuchara de palo\nque llevaba un estudiante,\nse fabricaron las puertas\ndel castillo de Alicante.",223,0,35,240,"",0,4,"ae",47,0,-1,0,297,297,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0298-01",19,"Mi padre piensa que estoy\nestudiando en Salamanca;\ny me he venido á este pueblo\ná conquistar las muchachas.",223,0,35,240,"",0,4,"aa",-1,0,-1,0,298,298,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0298-02",19,"El otro día en paseo\nse ha perdido un estudiante,\ny ha venido á parecer\ndebajo de un miriñaque.",223,0,35,240,"",0,4,"ae",-1,0,-1,0,298,298,"","",0,"rm_t4, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0298-03",19,"Que viva la tuna,\nque viva el jaleo,\nla sotana vieja\ny el roto manteo.",223,0,35,240,"",0,4,"eo",66,0,-1,0,298,298,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0298-04",19,"La capa del estudiante\nparece un jardín de flores,\ntoda llena de remiendos\nde diferentes colores.",223,0,35,240,"",0,4,"oe",5,0,-1,0,298,298,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0298-05",19,"Caballero generoso,\ndenos usté una peseta,\nque traemos la barriga\ncomo cañón de escopeta.",223,0,35,240,"",0,4,"ea",200,0,-1,0,298,298,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0298-06",19,"A los estudiantes, niña,\ncompara con las sardinas:\nsaladitas, con escamas,\npoca carne y mucha espina.",223,0,35,240,"",0,4,"ia",-1,0,-1,0,298,298,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0298-07",19,"Si queréis saber, señora,\nla vida del estudiante,\ncomer poco y andar mucho,\nla miseria por delante.",223,0,35,240,"",0,4,"ae",47,0,-1,0,298,298,"","",0,"lafuente_madrid","","",2,0,0,[],"",""],["fernan_caballero-p0299-01",19,"Cuando un estudiante sale\nal mercado en día cubierto,\nlos jamones y embuchados\nse ponen en movimiento.",223,0,35,240,"",0,4,"eo",-1,0,-1,0,299,299,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0299-02",19,"A estos pobres estudiantes\nde cuchara y aceituna,\nécheles usted una peseta,\nque van corriendo la tuna.",223,0,35,240,"",3,4,"ua",56,0,-1,0,299,299,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0300-01",19,"Pensamientos tuve, niña,\nde servir al rey Fernando;\ndesde que vi tu hermosura\ndije: que lo sirva el diablo.",223,0,35,241,"",0,4,"ao",-1,0,-1,0,300,300,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0300-02",19,"En Málaga senté plaza\ny en Sevilla me acordé\ndel garbo de tu persona,\ny al punto me deserté.",223,0,35,241,"",0,4,"e",77,0,-1,0,300,300,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0300-03",19,"¡Qué bonito está un soldado\nen la puerta del cuartel,\ncon corbatín estirado\ny sin tener qué comer!",223,0,35,241,"",0,4,"e",-1,0,-1,0,300,300,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0300-04",19,"Cuatro cuartos me da el rey\ny con esos como y bebo,\nle pago á la lavandera\ny siempre tengo dinero.",223,0,35,241,"",0,4,"eo",-1,0,-1,0,300,300,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0300-05",19,"—Soldadito, soldadito,\n¿qué llevas en la mochila?\n—Llevo las armas del rey\ny el corazón de una niña.",223,0,35,241,"",0,4,"ia",-1,0,-1,0,300,300,"","",0,"rm_t4","","",4,0,0,[],"",""],["fernan_caballero-p0301-01",19,"Soldado soy de á caballo,\ncuanto quieras te daré;\npero en tocando á casaca,\nno quiere mi coronel.",223,0,35,241,"",0,4,"e",-1,0,-1,0,301,301,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0301-02",19,"Si te quiere un soldado,\nquiérelo, niña;\nque no ha de ser soldado\ntoda su vida.",223,0,35,241,"",6,4,"ia",-1,0,-1,0,301,301,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0301-03",19,"¡Qué lástima de carita\nque fuese para un paisano,\npudiéndosela llevar\nun soldado veterano!",223,0,35,241,"",0,4,"ao",81,0,-1,0,301,301,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0301-04",19,"Si Dios me saca con bien\ndel servicio militar,\nharé cuenta que me he muerto\ny he vuelto á resucitar.",223,0,35,241,"",0,4,"a",21,0,-1,0,301,301,"","",0,"rm_t4, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0301-05",19,"Soldado soy, ¡qué remedio!,\nsi lo dispuso la suerte,\ny no me pesa el fusil,\npero sí dejar de verte.",223,0,35,241,"",0,4,"ee",134,0,-1,0,301,301,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0301-06",19,"La vida de los soldados\nes andar por los lugares,\ndormir en cama prestada,\nmorir en los hospitales.",223,0,35,241,"",0,4,"ae",-1,0,-1,0,301,301,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0301-07",19,"Por un pan de munición\nque el rey de España me da,\nme tiene toda la noche:\n—¡Centinela!—¡Alerta está!",223,0,35,241,"",0,4,"a",9,0,-1,0,301,301,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0302-01",19,"Bayonetas caladas\npide el gobernador,\nque se lleva los mozos;\n¡qué pena y qué dolor!",223,0,35,241,"",0,4,"o",72,0,-1,0,302,302,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0302-02",19,"Que se los lleve,\nó no se los lleve,\nla guerra no se ha hecho\npara mujeres.",223,0,35,241,"",6,4,"ee",-1,0,-1,0,302,302,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0302-03",19,"¡Qué bonito va un soldado\ncuando á la revista va;\nlleva su cara lavá,\nsu pelito bien peinado,\nel corbatín apretado,\nla mochila, el morrión,\nasí va á la formación!\nMas si por su mal le pegan,\ndesde aquel día reniega.\nde la hora en que nació.",223,0,35,241,"",18,10,"o",-1,0,-1,0,302,302,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0302-04",19,"Mañana se van los quintos,\nya se van los buenos mozos,\ny á las muchachas les quedan\nlos chiquitos y achacosos.",223,0,35,241,"",0,4,"oo",186,0,-1,0,302,302,"","",0,"rm_t2","","",10,0,0,[],"",""],["fernan_caballero-p0302-05",19,"Cásate y tendrás mujer\ny vivirás grandemente;\nllegarás á coronel\nsin haber sido teniente.",223,0,35,241,"",0,4,"ee",15,0,-1,0,302,302,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0303-01",19,"Si la casaca del rey\nno tuviera las resultas,\nvale más un soldadito\nque toda la España junta.",223,0,35,241,"",0,4,"ua",-1,0,-1,0,303,303,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0303-02",19,"Si el garbo de tu persona\nse ganara peleando,\nvieras á un hombre en la guerra\ncon una espada en la mano.",223,0,35,241,"",0,4,"ao",-1,0,-1,0,303,303,"","",0,"rm_t2, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0303-03",19,"Soldadito soy del rey,\naquí traigo mi registro,\ny si me muero en batalla,\nmuero por la fe de Cristo.",223,0,35,241,"",0,4,"io",-1,0,-1,0,303,303,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0303-04",19,"No se admire usted, señora,\nque un soldado es el que canta;\ncon el pan de munición\ntengo mala la garganta.",223,0,35,241,"",0,4,"aa",148,0,-1,0,303,303,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0303-05",19,"Cuatro cuartos me da el rey,\ny cuatro me da la reina,\ny cuatro mi coronel,\ny cuatro mi coronela.",223,0,35,241,"",0,4,"ea",-1,0,-1,0,303,303,"","",0,"rm_t4","","",6,0,0,[],"",""],["fernan_caballero-p0303-06",19,"Si salieras soldado\nyo te aguardaré,\nno digo yo ocho años,\naunque fueran diez.",223,0,35,241,"",0,4,"e",-1,0,-1,0,303,303,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0303-07",19,"Si salieras soldado\nen esta quinta,\npara tu charretera\nyo tengo cinta.",223,0,35,241,"",6,4,"ia",155,0,-1,0,303,303,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0304-01",19,"Mañana se van los quintos,\nse llevan los escogidos,\ny las muchachas se quedan\ncon los que el rey no ha querido.",223,0,35,241,"",0,4,"io",-1,0,-1,0,304,304,"","",0,"","","",10,0,0,[],"",""],["fernan_caballero-p0304-02",19,"Quiéreme, que soy buen mozo\ny escribo en la mayoría,\ny soy sargento primero\nque corre con compañía.",223,0,35,241,"",0,4,"ia",0,0,-1,0,304,304,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0304-03",19,"Adiós, Alicante hermoso,\ncon castillo y estandarte;\nadiós, puerta de la Reina,\ndonde yo solía hablarte.",223,0,35,241,"",0,4,"ae",8,0,-1,0,304,304,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0304-04",19,"Una plaza de armas\nforme en tu mano,\ny tus cinco deditos\nson los soldados.",223,0,35,241,"",6,4,"ao",-1,0,-1,0,304,304,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0304-05",19,"Capitanes de guerra\nson tus dos labios,\ny tus dientes en fila\nson los soldados.",223,0,35,241,"",6,4,"ao",-1,0,-1,0,304,304,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0304-06",19,"Cállate, morena mía,\ncállate y no tengas pena,\nque siendo yo coronel,\ntú serás la coronela.",223,0,35,241,"",0,4,"ea",-1,0,-1,0,304,304,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0304-07",19,"Dicen que la golondrina\npasó la mar en un vuelo;\nasí la pasaré yo\nen cumpliendo si no muero.",223,0,35,241,"",0,4,"eo",-1,0,-1,0,304,304,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0305-01",19,"Con un pie en el estribo\ny otro en el aire,\nse despide un soldado\nde su comadre.",223,0,35,241,"",6,4,"ae",-1,0,-1,0,305,305,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0305-02",19,"El amor del militar\nes como un plato de arena;\nen poniéndolo en la calle\nviene el viento y se lo lleva.",223,0,35,241,"",0,4,"ea",-1,0,-1,0,305,305,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0305-03",19,"Cuando estoy de centinela\ny te pones junto á mí,\nse me olvida la consigna\ny se me cae el fusil.",223,0,35,241,"",0,4,"i",-1,0,-1,0,305,305,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0305-04",19,"Si por hazañas de monta\nse pudiera á usted ganar,\nyo tomara por asalto\nel Peñón de Gibraltar.",223,0,35,241,"",0,4,"a",21,0,-1,0,305,305,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0305-05",19,"Son tus ojos, bien mío,\ndos baterías\nque están abriendo brecha\nal alma mía.",223,0,35,241,"",6,4,"ia",-1,0,-1,0,305,305,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0305-06",19,"El amor del soldado\nes de una hora;\nen tocando la marcha,\n¡adiós, señora!",223,0,35,241,"",6,4,"oa",107,0,-1,0,305,305,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0305-07",19,"Ya no quiero más campaña\nen el Bajo de Aragón,\nporque la ración de etapa\nse ha vuelto conversación.",223,0,35,241,"",0,4,"o",31,0,-1,0,305,305,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0306-01",19,"Si Dios me saca con bien\nde Cataluña y su reino,\nharé cuenta que he salido\nde los profundos infiernos.",223,0,35,241,"",0,4,"eo",-1,0,-1,0,306,306,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0306-02",19,"He salido por soldado\ny no tengo escarapela;\ndame una gota de sangre\nde tu corazón, morena.",223,0,35,241,"",0,4,"ea",-1,0,-1,0,306,306,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0306-03",19,"El cuartel es una venta,\nel sargento es el ventero,\nlos burros son los soldados,\nlos cabos son los arrieros.",223,0,35,241,"",0,4,"eo",-1,0,-1,0,306,306,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0306-04",19,"Los cuarteles son iglesias,\nlos soldados son los santos,\nlos cabos son los faroles\nque alumbran de cuando en cuando.",223,0,35,241,"",0,4,"ao",-1,0,-1,0,306,306,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0306-05",19,"Adelante, batidores,\ndad ejemplo al batallón,\nque la gente de bigote\ndebe ser gente de pro.",223,0,35,241,"",0,4,"o",-1,0,-1,0,306,306,"","",0,"palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0306-06",19,"Si por querer á un paisano\nolvidas á un militar,\nhazte cuenta que has cambiado\noro fino por metal.",223,0,35,241,"",0,4,"a",-1,0,-1,0,306,306,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0306-07",19,"Dicen que ya no me quieres\nporque he salido soldado;\nno creo que tú desprecies\nlo que el rey no ha despreciado.",223,0,35,241,"",0,4,"ao",14,0,-1,0,306,306,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0307-01",19,"¿Cómo quieres, nena,\nque te venga á ver,\nsi salgo de guardia\ny entro de retén?",223,0,35,241,"",0,4,"e",-1,0,-1,0,307,307,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0307-02",19,"Si por un momento\nyo falto á la lista,\nrecargo de guardia\nnadie me lo quita.",223,0,35,241,"",0,4,"ia",-1,0,-1,0,307,307,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0307-03",19,"Viene mi primero,\nme pone arrestado;\nmira aquí la gloria\ndel pobre soldado.",223,0,35,241,"",0,4,"ao",14,0,-1,0,307,307,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0307-04",19,"¿Cómo quieres que me case\nsiendo sargento no más?\n¿Cómo quieres que mantenga\nsalero con tanta sal?",223,0,35,241,"",0,4,"a",-1,0,-1,0,307,307,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0307-05",19,"Senté plaza de soldado,\nme dijeron que era chico,\ny yo dije: no hay cuidado,\nme subiré en un borrico.",223,0,35,241,"",1,4,"io",141,0,-1,0,307,307,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0308-01",19,"Tengo que morir cantando;\nya que llorando nací,\nque las penas de este mundo\nno todas son para mí.",223,0,35,242,"",0,4,"i",23,0,-1,0,308,308,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0308-02",19,"Quiero cantar ahora\nque tengo gana,\npor si acaso me toca\nllorar mañana.",223,0,35,242,"",6,4,"aa",4,0,-1,0,308,308,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0308-03",19,"Yo me llamo Pocas-penas,\npariente de Mala-gana,\ny por apellido tengo\ná mí no se me da nada.",223,0,35,242,"",0,4,"aa",-1,0,-1,0,308,308,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0308-04",19,"Como tú no me faltes,\npan de mi alforja,\ncomo tú no me faltes,\ntodo me sobra.",223,0,35,242,"",6,4,"oa",-1,0,-1,0,308,308,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0308-05",19,"En teniendo yo un cigarro\ny seguro mi jornal\ny mi morena en la reja,\n¿qué más puedo desear?",223,0,35,242,"",0,4,"a",-1,0,-1,0,308,308,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0309-01",19,"Cuando me parió mi madre\nme parió en un campanario;\ncuando vino la comadre\nestaba yo repicando.",223,0,35,242,"",0,4,"ao",-1,0,-1,0,309,309,"","",0,"lafuente_madrid","","",8,0,0,[],"",""],["fernan_caballero-p0309-02",19,"A la una nací yo,\ná las dos me bautizaron,\ná las tres me enamoré\ny á las cuatro me casaron.",223,0,35,242,"",0,4,"ao",41,0,-1,0,309,309,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0309-03",19,"En mi casa hay un patio\ntan particular,\nque en lloviendo se moja\ncomo los demás.",223,0,35,242,"",0,4,"a",-1,0,-1,0,309,309,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0309-04",19,"Cuatrocientas mujeres,\nquinientos loros,\narman una algazara\nde mil demonios.",223,0,35,242,"",6,4,"oo",-1,0,-1,0,309,309,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0309-05",19,"Esta noche y anoche\ny esta mañana,\nantes de levantarme\nestaba en cama.",223,0,35,242,"",6,4,"aa",-1,0,-1,0,309,309,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0309-06",19,"Dicen que tú no me quieres\nporque no tengo dinero;\nven á mi cuarto y verás\nun cuarto en un agujero.",223,0,35,242,"",0,4,"eo",38,0,-1,0,309,309,"","",0,"","","",11,0,0,[],"",""],["fernan_caballero-p0309-07",19,"Sé donde fueres,\nel que debieres;\ncobra y no pagues,\nsomos mortales.",223,0,35,242,"",6,4,"ae",-1,0,-1,0,309,309,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0310-01",19,"Solo soy, solo nací,\nsolo me parió mi madre,\ny solito me andaré\ncomo la pluma en el aire.",223,0,35,242,"",0,4,"ae",-1,0,-1,0,310,310,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0310-02",19,"En los montes de Jimena\nrobaron un cobertor;\nlos ladrones van diciendo:\nno lo hubieran puesto al sol.",223,0,35,242,"",0,4,"o",-1,0,-1,0,310,310,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0310-03",19,"La buena de mi suegra\nme dió unas medias;\ncada vez que reñimos\nme quedo en piernas.",223,0,35,242,"",6,4,"ea",-1,0,-1,0,310,310,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0310-04",19,"Tienes una carita\nde San Antonio,\ny una condicioncita\ncomo un demonio.",223,0,35,242,"",6,4,"oo",169,0,-1,0,310,310,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0310-05",19,"Yo ya no quiero apurarme\napúrese quien quisiere,\nporque he oído decir\nque el que se apura se muere:",223,0,35,242,"",0,4,"ee",115,0,-1,0,310,310,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0310-06",19,"¿Pues no es grande bobería\nel vivir así penando,\nsi podemos divertirnos\nuna vez de cuando en cuando?",223,0,35,242,"",0,4,"ao",33,0,-1,0,310,310,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0310-07",19,"Vivan las claras estrellas,\nviva el sol, viva la luna,\nvivan las niñas bonitas\ny el amor y la fortuna.",223,0,35,242,"",0,4,"ua",56,0,-1,0,310,310,"","",0,"lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0311-01",19,"En Málaga los serenos\ndicen que no beben vino,\ny con el vino que beben\npuede moler un molino.",223,0,35,242,"",0,4,"io",199,0,-1,0,311,311,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0311-02",19,"Cuando veo á mi suegra\n¡me alegro tanto!\nCuando el altar me alegra,\n¡qué será el santo!",223,0,35,242,"",6,4,"ao",30,0,-1,0,311,311,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0311-03",19,"Gitano, ¿por qué vas preso?\nSeñor, por cosa ninguna;\nporque he robado una soga...\ncon cuatro pares de mulas.",223,0,35,242,"",0,4,"ua",-1,0,-1,0,311,311,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0311-04",19,"Voy á hacer un castillo\ncon cien teleras\ny ciento treinta bollos\nde centinelas.",223,0,35,242,"",6,4,"ea",-1,0,-1,0,311,311,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0311-05",19,"El tabaco de polvo,\nsegún se dice,\nse toma en todas partes\npor las narices.",223,0,35,242,"",6,4,"ie",-1,0,-1,0,311,311,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0311-06",19,"Mi marido me dice\nque no le ayudo;\ncuando viene borracho,\nyo le rempujo.",223,0,35,242,"",6,4,"uo",-1,0,-1,0,311,311,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0311-07",19,"En la calle en que vives,\n¡maldita sea!,\nviven cuatro muchachas\ná cual más fea.",223,0,35,242,"",6,4,"ea",54,0,-1,0,311,311,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0312-01",19,"Si el casarse fuera un año,\nuna semanita ó dos,\npero por toda la vida...\n¡esa no la trago yo!",223,0,35,242,"",0,4,"o",-1,0,-1,0,312,312,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0312-02",19,"Si yo tuviese un chinito\nse lo tirara á esa higuera,\nque buena falta me hacía\nque me cayera esa breva.",223,0,35,242,"",0,4,"ea",-1,0,-1,0,312,312,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0312-03",19,"Amores, amores tengo,\nno los quisiera tener,\nque un hombre se pone tonto\nen queriendo á una mujer.",223,0,35,242,"",0,4,"e",20,0,-1,0,312,312,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0312-04",19,"Compadre, he visto un toro\nen la plaza de Jerez.\n¡Compadre, si usted lo viera!\nTodo se parece á usted.",223,0,35,242,"",0,4,"e",-1,0,-1,0,312,312,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0312-05",19,"En la calle no sé dónde\nmataron yo no sé á quién;\nel vivo cayó en el suelo,\nel muerto apretó á correr.",223,0,35,242,"",0,4,"e",-1,0,-1,0,312,312,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0312-06",19,"Un borracho se murió\ny dejó en el testamento\nque lo enterrasen en viña\npara chupar los sarmientos.",223,0,35,242,"",0,4,"eo",-1,0,-1,0,312,312,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0312-07",19,"A un hombre muy prevenido\nregalaron un pastel;\npor no saber lo que era,\nno se lo quiso comer.",223,0,35,242,"",0,4,"e",-1,0,-1,0,312,312,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0313-01",19,"¡Cómo corre, cómo trota\nun pobre tras una torta!\n¡Cómo trota, cómo corre\ndetrás de una torta un pobre!",223,0,35,242,"",5,4,"oe",-1,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0313-02",19,"Vamos, en gracia de Dios\nmaté mi mujer de un palo;\nsi esto es en gracia de Dios,\n¡qué será en gracia del diablo!",223,0,35,242,"",0,4,"ao",-1,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0313-03",19,"Mocitas, si queréis novios,\npintadlos en la pared,\nque los mocitos de España\nson de la reina Isabel.",223,0,35,242,"",0,4,"e",-1,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0313-04",19,"Mire usted con la gracia\nque mira un tuerto,\ncon un ojo cerrado\ny el otro abierto.",223,0,35,242,"",6,4,"eo",88,0,-1,0,313,313,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0313-05",19,"En el jardín de amores\nhay una mata\ndonde van por narices\ntodas las chatas.",223,0,35,242,"",6,4,"aa",-1,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0313-06",19,"Anoche en tu ventana\nvi un bulto negro,\npensando que era un hombre,\ny era un gallego.",223,0,35,242,"",6,4,"eo",-1,0,-1,0,313,313,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0313-07",19,"De tanto quererte á ti\nme quedé como una espina;\npor poco me lleva el viento\nal revolver de una esquina.",223,0,35,242,"",0,4,"ia",11,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0314-01",19,"Más valiera ser soldado,\nó en algún convento fraile,\nque no mantener mujer\nal precio que el trigo vale.",223,0,35,242,"",0,4,"ae",-1,0,-1,0,314,314,"","",0,"rm_t4, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0314-02",19,"Debajo de tu ventana\ntengo un ochavo escondido;\nno se lo digas á nadie,\nmira que somos perdidos.",223,0,35,242,"",0,4,"io",-1,0,-1,0,314,314,"","",0,"rm_t4","","",29,0,0,[],"",""],["fernan_caballero-p0314-03",19,"Tengo un dolor no sé dónde,\nnacido de un no sé qué,\nsanaré yo no sé cuándo,\nme sanará no sé quién.",223,0,35,242,"",0,4,"e",-1,0,-1,0,314,314,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0314-04",19,"La vista recogida\nmucho penetra;\neso decía una niña\nporque era tuerta.",223,0,35,242,"",6,4,"ea",-1,0,-1,0,314,314,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0314-05",19,"A un hombre viejo y á un mozo\nquiero con distinta ley;\nquiero al mozo por su cara,\ny al viejo por la del rey.",223,0,35,242,"",0,4,"e",133,0,-1,0,314,314,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0314-06",19,"A la puerta de un sordo\ncantaba un mudo,\ny un ciego le miraba\ncon disimulo.",223,0,35,242,"",6,4,"uo",-1,0,-1,0,314,314,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0314-07",19,"Ven acá, moza maldita,\ndime por qué me aborreces;\nsi no te gustan castañas,\nyo te regalaré nueces.",223,0,35,242,"",0,4,"ee",196,0,-1,0,314,314,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0315-01",19,"El bonete del cura\nva por el río,\ny el cura va diciendo:\n¡bonete mío!",223,0,35,242,"",6,4,"io",3,0,-1,0,315,315,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0315-02",19,"Supuesto que no quieres\nnada conmigo,\ncuando te pareciere\ntoma el camino.",223,0,35,242,"",6,4,"io",-1,0,-1,0,315,315,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0315-03",19,"Yo vide á un hombre llorar\ná la puerta de un estanco,\nque también los hombres lloran\nen faltándoles tabaco.",223,0,35,242,"",0,4,"ao",-1,0,-1,0,315,315,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0315-04",19,"Cada vez que paso y miro\nla cárcel ó el hospital,\nle digo á este cuerpo mío:\n¡aquí tienes de parar!",223,0,35,242,"",0,4,"a",-1,0,-1,0,315,315,"","",0,"","","",25,0,0,[],"",""],["fernan_caballero-p0315-05",19,"A mí me parió mi madre\ndebajo de una higuera;\ncuando llegó la comadre\nme encontró papando brevas.",223,0,35,242,"",0,4,"ea",-1,0,-1,0,315,315,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0315-06",19,"Cuando vengas á verme\nponte á lo obscuro,\npara que piense mi padre\nque eres el mulo.",223,0,35,242,"",6,4,"uo",-1,0,-1,0,315,315,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0315-07",19,"Niña de los veinte novios,\ny conmigo veintiuno;\nsi todos son como yo,\nte quedarás sin ninguno.",223,0,35,242,"",0,4,"uo",230,0,-1,0,315,315,"","",0,"rm_t3","","",11,0,0,[],"",""],["fernan_caballero-p0316-01",19,"Glorioso San Sebastián,\ntodo lleno de saetas;\nmi alma como la tuya,\ncomo tu cuerpo mi suegra.",223,0,35,242,"",0,4,"ea",-1,0,-1,0,316,316,"","",0,"lafuente_madrid, palau_cantares","","",9,0,0,[],"",""],["fernan_caballero-p0316-02",19,"No siento yo la caída,\nni que enseñase las piernas;\nsiento, sí, los cinco duros\nque me costó mi peineta.",223,0,35,242,"",0,4,"ea",-1,0,-1,0,316,316,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0316-03",19,"No tengo vicio ninguno\nsino el de fumar tabaco,\njugar á la treinta y una,\nsin contar que soy borracho.",223,0,35,242,"",0,4,"ao",-1,0,-1,0,316,316,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0316-04",19,"Mi padre me pega palos\ny mi madre me pellizca,\ny al són de los palos digo:\nsarna con gusto no pica.",223,0,35,242,"",0,4,"ia",-1,0,-1,0,316,316,"","",0,"palau_cantares, lafuente_madrid","","",12,0,0,[],"",""],["fernan_caballero-p0316-05",19,"Un cojo cojeando\ncogía coles,\ny otro cojo decía:\ncojo, ¿qué coges?",223,0,35,242,"",6,4,"oe",-1,0,-1,0,316,316,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0316-06",19,"Asómate á esa vergüenza,\ncara de poca ventana;\ntráeme una talla de sed,\nque vengo muerto de agua.",223,0,35,242,"",0,4,"aa",-1,0,-1,0,316,316,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0316-07",19,"Anda diciendo tu gente\nque no me quieres por viejo;\nanda y pregunta á las coles\nsi es bueno el tocino añejo.",223,0,35,242,"",0,4,"eo",264,0,-1,0,316,316,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0317-01",19,"Un jorobado me ronda\ncon su jorobita atrás;\nno lo quiero jorobado,\nporque me jorobará.",223,0,35,242,"",0,4,"a",-1,0,-1,0,317,317,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0317-02",19,"Cuando Dios crió al erizo\nlo crió de mala gana;\npor eso el animalito\ntiene tan suave la lana.",223,0,35,242,"",0,4,"aa",4,0,-1,0,317,317,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0317-03",19,"San Pedro, como era calvo,\nle picaban los mosquitos,\ny su madre le decía:\nponte el gorro, Periquito.",223,0,35,242,"",0,4,"io",-1,0,-1,0,317,317,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0317-04",19,"San Pedro, como era calvo,\ná Cristo le pidió pelos,\ny Cristo le respondió:\ndéjate de pelos, Pedro.",223,0,35,242,"",0,4,"eo",-1,0,-1,0,317,317,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0317-05",19,"En mi casa me llaman\ncalzones rotos,\ny yo digo: ¡caramba,\ncompradme otros!",223,0,35,242,"",6,4,"oo",-1,0,-1,0,317,317,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0317-06",19,"Dicen que he robado un cáliz;\n¡Jesús, qué mentira es esa!\nDesde que me bautizaron\nno he vuelto á entrar en iglesia.",223,0,35,242,"",0,4,"ea",-1,0,-1,0,317,317,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0317-07",19,"Una vieja seca, seca,\nseca, seca, se casó\ncon un viejo seco, seco,\nseco, seco, se quedó.",223,0,35,242,"",0,4,"o",2,0,-1,0,317,317,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0318-01",19,"¿Qué quieres que te diga,\nMaría Josefa,\nqué quieres que te diga\nque tú no sepas?",223,0,35,243,"",6,4,"ea",-1,0,-1,0,318,318,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0318-02",19,"Al que camela sin plata\ncon título de buen mozo,\ná ese llaman las mujeres\nla carabina de Ambrosio.",223,0,35,243,"",0,4,"oo",-1,0,-1,0,318,318,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0318-03",19,"La pimienta es chica y pica\ny sazona los guisados;\nmi amante se me picó\ny se ha ido y me ha dejado.",223,0,35,243,"",0,4,"ao",-1,0,-1,0,318,318,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0318-04",19,"No pienses de que te quiero\nporque te miro á la cara,\nque muchos van á la feria\ná ver, y no compran nada.",223,0,35,243,"",0,4,"aa",-1,0,-1,0,318,318,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0318-05",19,"Las mocitas de estos días\nson como las avellanas:\nparten una, parten dos,\ny toditas salen vanas.",223,0,35,243,"",0,4,"aa",263,0,-1,0,318,318,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0319-01",19,"Si porque te ves querida\nme niegas la voluntad,\nmira que una casa grande\nla derriba un temporal.",223,0,35,243,"",0,4,"a",-1,0,-1,0,319,319,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0319-02",19,"La mujer chiquitita\nes un regalo;\nmás vale poco y bueno\nque mucho y malo.",223,0,35,243,"",6,4,"ao",71,0,-1,0,319,319,"","",0,"rm_t2","","",3,0,0,[],"",""],["fernan_caballero-p0319-03",19,"Dices que no me quieres\nni me has querido;\nváyase lo ganado\npor lo perdido.",223,0,35,243,"",6,4,"io",101,0,-1,0,319,319,"","",0,"","","",15,0,0,[],"",""],["fernan_caballero-p0319-04",19,"Yo quiero á un zapatero\ny quiero á un sastre,\npara que uno me vista\ny otro me calce.",223,0,35,243,"",6,4,"ae",-1,0,-1,0,319,319,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0319-05",19,"Mi marido me dice\nque me componga;\n¿qué querrá ese demonio\nque yo me ponga?",223,0,35,243,"",6,4,"oa",300,0,-1,0,319,319,"","",0,"rm_t4","","",3,0,0,[],"",""],["fernan_caballero-p0319-06",19,"Una recién casada\npuso la olla\ncon un cubo de agua\ny una cebolla.",223,0,35,243,"",6,4,"oa",453,0,-1,0,319,319,"","",0,"palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0319-07",19,"Para cuando me case\nya tengo dote,\nque me lo dió mi padre\ncon un garrote.",223,0,35,243,"",6,4,"oe",292,0,-1,0,319,319,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["fernan_caballero-p0320-01",19,"Yo me llamo Juan Encina,\ny mi mujer Alcornoque,\nRoble se llama mi suegra;\n¡qué desparejado bosque!",223,0,35,243,"",0,4,"oe",-1,0,-1,0,320,320,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0320-02",19,"Amigo Blas, he intentado\nponer mi mujer en venta\npara comprar un caballo,\nporque me tiene más cuenta.",223,0,35,243,"",0,4,"ea",229,0,-1,0,320,320,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0320-03",19,"Si piensas que porque piensas\nha de ser mi casamiento,\nquítate de la cabeza\nesos vanos pensamientos.",223,0,35,243,"",0,4,"eo",-1,0,-1,0,320,320,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0320-04",19,"Que tengas amores nuevos,\nde eso no me maravillo;\nque siempre se va la abeja\nal almendro más florido.",223,0,35,243,"",0,4,"io",-1,0,-1,0,320,320,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0320-05",19,"Si quieres que te lo diga,\ncantando te lo diré:\nmi padre y mi madre fueron\nun hombre y una mujer.",223,0,35,243,"",0,4,"e",-1,0,-1,0,320,320,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0320-06",19,"A mi querer lo comparo\ncon los platos del vasar;\nen quebrándoseme uno,\notro pongo en su lugar.",223,0,35,243,"",0,4,"a",21,0,-1,0,320,320,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0320-07",19,"Si quieres que te lo diga,\ncantando te lo diré:\nel amor que te tenía,\ncomo se vino, se fué.",223,0,35,243,"",0,4,"e",77,0,-1,0,320,320,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0321-01",19,"La niña que quiere á dos\nno es tonta, que es advertida;\nsi se le apaga una vela,\notra le queda encendida.",223,0,35,243,"",0,4,"ia",37,0,-1,0,321,321,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0321-02",19,"A la mujer la comparo\ncon el águila real;\nen acercándose á ella,\nella se remonta más.",223,0,35,243,"",0,4,"a",-1,0,-1,0,321,321,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0321-03",19,"Ninguna por ser bonita\ná ningún galán desprecie;\nque un cordón de oro torcido\nda la vuelta y se destuerce.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,321,321,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0321-04",19,"¿De qué te sirve tener\nesa cara tan hermosa,\nsi tiene tu corazón\nespinas, como la rosa?",223,0,35,243,"",0,4,"oa",63,0,-1,0,321,321,"","",0,"rm_t3, lafuente_madrid","","",8,0,0,[],"",""],["fernan_caballero-p0321-05",19,"Como aquel refrán que dice:\npierde el pan y pierde el perro,\nasí me sucede á mí\ncon una novia que tengo.",223,0,35,243,"",0,4,"eo",-1,0,-1,0,321,321,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0321-06",19,"San Antonio está en el cielo;\n¡quién estuviese con él!\nSan Antonio hace milagros\ny yo no los puedo hacer.",223,0,35,243,"",0,4,"e",-1,0,-1,0,321,321,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0321-07",19,"La vara de San José\ntodos los años florece;\nla palabra de los hombres\nse ha perdido y no parece.",223,0,35,243,"",0,4,"ee",64,0,-1,0,321,321,"","",0,"rm_t4, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0322-01",19,"A la entrada de tu calle\nuna clavellina vi,\ny la dije: ¡Dios te guarde,\nbella flor, y no de mí!",223,0,35,243,"",0,4,"i",23,0,-1,0,322,322,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0322-02",19,"Mi padre y mi madre lloran\nporque me voy á casar;\npadre y madre, que no lloren,\nque no me van á matar.",223,0,35,243,"",0,4,"a",21,0,-1,0,322,322,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0322-03",19,"Dame la mano, María,\nque tu madre lo mandó.\n—Mi madre manda en lo suyo,\nen lo mío mando yo.",223,0,35,243,"",0,4,"o",2,0,-1,0,322,322,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0322-04",19,"¡Válgame Dios, salada,\nla sal qué comes!\n¡Qué crecidas que tienes\ntus condiciones!",223,0,35,243,"",6,4,"oe",-1,0,-1,0,322,322,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0322-05",19,"¡Válgame Dios del cielo\nlo que ha llovido!\nHasta las calabazas\nse han florecido.",223,0,35,243,"",6,4,"io",101,0,-1,0,322,322,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0322-06",19,"Parece que viene usted\nechándola de valiente,\ncon una espada de caña\nen una calle sin gente.",223,0,35,243,"",0,4,"ee",15,0,-1,0,322,322,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0322-07",19,"Si vienes, bien te recibo,\ny si no, no me haces falta;\npuedes tener entendido\nque no gusto templar gaitas.",223,0,35,243,"",0,4,"aa",-1,0,-1,0,322,322,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0323-01",19,"Una niña le echó á un calvo\npor una ventana cal;\ny por no decirle calvo,\nle dijo: ¡cal va, cal va!",223,0,35,243,"",0,4,"a",-1,0,-1,0,323,323,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0323-02",19,"La que se casa con calvo\ntiene penitencia entera;\nde día cruz y calvario,\ny de noche calavera.",223,0,35,243,"",0,4,"ea",44,0,-1,0,323,323,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0323-03",19,"Algún día por no verte\nsuspiros daba,\ny ahora por no verte\nvuelvo la cara.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,323,323,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0323-04",19,"Algún día por verte\nla misa perdí;\ny ahora me he quedado\nsin misa y sin ti.",223,0,35,243,"",0,4,"i",23,0,-1,0,323,323,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0323-05",19,"Mi marido fué á las Indias\ny me trajo una silleta;\npero aquella misma noche\nme la rompió en la cabeza.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,323,323,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0323-06",19,"Tiene mi morenito\nvena de loco;\nunas veces por mucho\ny otras por poco.",223,0,35,243,"",6,4,"oo",152,0,-1,0,323,323,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0323-07",19,"Alza la vista, María;\nmira la estrella con rabo;\nsabe Dios las ruinillas\nque nos vendrá anunciando.",223,0,35,243,"",0,4,"ao",-1,0,-1,0,323,323,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-01",19,"Me encontré con mi amante,\ny me dijo: prima,\nla torre de la iglesia\nte caiga encima.",223,0,35,243,"",6,4,"ia",302,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-02",19,"Si lo que tengo al lado\nfuera una bala,\ná la que tengo enfrente\nse la tirara.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-03",19,"A la Virgen del Carmen\nquiero y adoro,\nporque saca las almas\ndel purgatorio.",223,0,35,243,"",6,4,"oo",-1,0,-1,0,324,324,"","",0,"palau_cantares, murciano_antiguo","","",5,0,0,[],"",""],["fernan_caballero-p0324-04",19,"Cada vez que veo el cangrejo\nme pongo á considerar\nque se parece á mi dicha,\nque camina para atrás.",223,0,35,243,"",0,4,"a",-1,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-05",19,"Si quieres que te diga\ncuántas son cinco,\nlos dedos de la mano\nde mi marido.",223,0,35,243,"",6,4,"io",-1,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-06",19,"Por un peso que has perdido\nme has dado mil enojos.\n¿Tú sabes cuánto es un peso?\nCinco pesetas, mis ojos.",223,0,35,243,"",0,4,"oo",99,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0324-07",19,"Mala hora de Dios coja\ná una olla sin tocino,\ná una bolsa sin dinero,\ná una botella sin vino.",223,0,35,243,"",0,4,"io",199,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0325-01",19,"Yo estoy como San Alejo,\ndebajo de la escalera,\naguardando la fortuna,\ny la pícara no llega.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,325,325,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0325-02",19,"Como tengo este genio\ntan encogido,\nsi me lo dan lo tomo,\nsi no, lo pido.",223,0,35,243,"",6,4,"io",101,0,-1,0,325,325,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0325-03",19,"Me dices que soy fea,\nyo no lo ignoro;\ncomo los almanaques,\nDios sobre todo.",223,0,35,243,"",6,4,"oo",-1,0,-1,0,325,325,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0325-04",19,"Anda diciendo tu madre\nque eres tú mejor que yo:\n¿en qué libro lo ha leído?\n¿en qué sueño lo soñó?",223,0,35,243,"",0,4,"o",2,0,-1,0,325,325,"","",0,"","","",23,0,0,[],"",""],["fernan_caballero-p0325-05",19,"Anda diciendo tu madre\nque la reina para ti;\nanda ve y dile á tu madre\nque la reina está en Madrid.",223,0,35,243,"",0,4,"i",-1,0,-1,0,325,325,"","",0,"","","",23,0,0,[],"",""],["fernan_caballero-p0325-06",19,"Chato, no tienes narices\nporque Dios no te las dió;\ná feria se va por todo,\npero por narices, no.",223,0,35,243,"",0,4,"o",2,0,-1,0,325,325,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0325-07",19,"Para los hombres chicos\nviene la leva;\nyo meteré al mío\nen la faltriquera.",223,0,35,243,"",6,4,"ea",-1,0,-1,0,325,325,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0326-01",19,"La mujer que encuentre á un hombre\nconstante, firme y leal,\nllévelo cual cosa rara\ná la Historia Natural.",223,0,35,243,"",0,4,"a",1,0,-1,0,326,326,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0326-02",19,"A las doce de la noche\nechó un galán un requiebro\npensando que era una dama,\ny era un gato blanco y negro.",223,0,35,243,"",3,4,"eo",-1,0,-1,0,326,326,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0326-03",19,"Si me quieres dímelo,\ny si no, no me desprecies,\nque soy chino, y algún día\npuede ser que en mí tropieces.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,326,326,"","",0,"rm_t2","","",17,0,0,[],"",""],["fernan_caballero-p0326-04",19,"Dicen que no me quieres\nporque no tengo;\nveme tú regalando,\nyo iré teniendo.",223,0,35,243,"",6,4,"eo",-1,0,-1,0,326,326,"","",0,"","","",18,0,0,[],"",""],["fernan_caballero-p0326-05",19,"Dicen que no me quieres\nporque no tengo qué dar;\ncásate con el reloj,\nque á todas las horas da.",223,0,35,243,"",0,4,"a",-1,0,-1,0,326,326,"","",0,"","","",18,0,0,[],"",""],["fernan_caballero-p0326-06",19,"Cada vez que considero\nque tengo un amor ingrato,\nno sé cómo no me tiro\ncontra un colchón y me mato.",223,0,35,243,"",0,4,"ao",2,0,-1,0,326,326,"","",0,"palau_cantares, lafuente_madrid","","",14,0,0,[],"",""],["fernan_caballero-p0326-07",19,"Eres más fea que el mengue\n¿y tan bien sabes querer?\nAnda, que te coja un toro\ny te camele un inglés.",223,0,35,243,"",0,4,"e",-1,0,-1,0,326,326,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0327-01",19,"Dices que ya no me quieres;\nno me da pena maldita,\nque la mancha de la mora\ncon otra verde se quita.",223,0,35,243,"",0,4,"ia",50,0,-1,0,327,327,"","",0,"","","",21,0,0,[],"",""],["fernan_caballero-p0327-02",19,"No te quiero junto á mí;\nanda vete de mi vera,\nque tienes tú para mí\nsombra de verde higuera.",223,0,35,243,"",1,4,"ea",44,0,-1,0,327,327,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0327-03",19,"Me quisiste y te quise\ny agradecí tu fineza;\nme olvidaste, te olvidé,\ntú contento y yo contenta.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,327,327,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0327-04",19,"Si tus ojos son severos\ny no gustan de las chanzas,\nte aseguro que los míos\nen el casco me se saltan.",223,0,35,243,"",0,4,"aa",-1,0,-1,0,327,327,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0327-05",19,"Todos los hombre son falsos,\ntramoyistas y embusteros;\ná quien le toque esa china\nque la guarde en el sombrero.",223,0,35,243,"",0,4,"eo",-1,0,-1,0,327,327,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0327-06",19,"El viejo que se casa\ncon mujer niña,\nél mantiene la cepa\ny otro vendimia.",223,0,35,243,"",6,4,"ia",-1,0,-1,0,327,327,"","",0,"rm_t4","","",4,0,0,[],"",""],["fernan_caballero-p0327-07",19,"Si usted me quisiera á mí\ncomo yo la quiero á usted,\nnos llamaran á los dos\nlos amantes de Teruel.",223,0,35,243,"",0,4,"e",-1,0,-1,0,327,327,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0328-01",19,"Infeliz del que busca\ncon grande anhelo\nla perdiz, y se encuentra\ncon el mochuelo.",223,0,35,243,"",6,4,"eo",10,0,-1,0,328,328,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0328-02",19,"Cuando dos quieren á una\ny ésta quiere á uno no más,\nestá el otro que parece\nzorra que ha comido agraz.",223,0,35,243,"",0,4,"a",253,0,-1,0,328,328,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0328-03",19,"¡Ay!, viudita, viudita,\n¡qué bien le parece el luto!\nnos casaremos los dos;\nDios perdone á los difuntos.",223,0,35,243,"",0,4,"uo",-1,0,-1,0,328,328,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0328-04",19,"Si acaso piensas casarte\nbusca la novia morena,\nporque de las peli-rubias\nmilagro sale una buena.",223,0,35,243,"",0,4,"ea",59,0,-1,0,328,328,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0328-05",19,"Toda la mujer morena\nse consuela con decir,\nque en la tierra morenita\nnace bien el perejil.",223,0,35,243,"",0,4,"i",-1,0,-1,0,328,328,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0328-06",19,"Mi marido fué á las Indias\ny me trajo una navaja,\ncon un letrero que dice:\nsi quieres comer, trabaja.",223,0,35,243,"",0,4,"aa",393,0,-1,0,328,328,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0328-07",19,"Mariquita María,\nla de mi barrio,\nhasta el agua bendita\ntoma con garbo.",223,0,35,243,"",6,4,"ao",-1,0,-1,0,328,328,"","",0,"rm_t2, palau_cantares","","",12,0,0,[],"",""],["fernan_caballero-p0329-01",19,"Dicen que usted no me quiere,\ná mí no me da cuidado;\nmañana me pongo luto\nde tafetán encarnado.",223,0,35,243,"",0,4,"ao",14,0,-1,0,329,329,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0329-02",19,"Cásate, Juan, el domingo;\nlunes estarás casado,\ny el martes procurarás\ndónde dan el pan fiado.",223,0,35,243,"",0,4,"ao",14,0,-1,0,329,329,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0329-03",19,"Te pusiste á decir\nen una mesa de juego\nque te casabas conmigo...\nEso será si yo quiero.",223,0,35,243,"",0,4,"eo",-1,0,-1,0,329,329,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0329-04",19,"Ya se murió mi suegra,\nvoy al entierro;\nun casco de cebolla\nllevo en el seno.",223,0,35,243,"",6,4,"eo",-1,0,-1,0,329,329,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0329-05",19,"Tienes nubes como el cielo,\nmareas como la mar,\nmudanzas como los vientos,\ny luego te ha de pesar.",223,0,35,243,"",0,4,"a",21,0,-1,0,329,329,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0329-06",19,"Tienes el amor con otra\ny conmigo las bromitas;\nsi te quieres divertir\ncompra un trompo y una guita.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,329,329,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0329-07",19,"Te huele la ropa á clavo\ncomo si fueras tendera.\n¡Qué importa que seas blanca,\nsi tus partidas son negras!",223,0,35,243,"",0,4,"ea",-1,0,-1,0,329,329,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0330-01",19,"Cuando me dieron la nueva\nde que ya no me querías,\nhasta el gato de mi casa\nme miraba y se reía.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,330,330,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0330-02",19,"El día que me dijeron\nque tú ya no me querías,\nla cara se me quedó\nlo mismo que la tenía.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,330,330,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0330-03",19,"A Cupido lo pintan\nchiquirritito,\nporque se estila ahora\nquerer poquito.",223,0,35,243,"",6,4,"io",119,0,-1,0,330,330,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0330-04",19,"El que tuviere envidia\nllame á Cachano,\nque cuando tengo rabia\ntambién lo llamo.",223,0,35,243,"",6,4,"ao",-1,0,-1,0,330,330,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0330-05",19,"Allá va ese pimiento,\npique ó no pique;\nel que tuviese rabia\nque se la quite.",223,0,35,243,"",6,4,"ie",-1,0,-1,0,330,330,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0330-06",19,"La aceituna en el molino\necha aceite y alpechín;\nla mujer que quiere á muchos\nno puede tener buen fin.",223,0,35,243,"",0,4,"i",211,0,-1,0,330,330,"","",0,"rm_t4, carrizo_salta","","",4,0,0,[],"",""],["fernan_caballero-p0330-07",19,"¡Quién estuviera tan alto\ncomo la estrella del Norte,\npara ver lo que pasaba\nen cierta casa esta noche!",223,0,35,243,"",0,4,"oe",-1,0,-1,0,330,330,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0331-01",19,"Si te ha tocado la suerte\nde soldadito, bien mío,\nanda, cumple con el rey,\nque conmigo ya has cumplido.",223,0,35,243,"",0,4,"io",-1,0,-1,0,331,331,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0331-02",19,"Si queréis saber, señores,\nel nombre de mi querer,\nacordarse de aquel santo\nque tiene el diablo á los pies.",223,0,35,243,"",0,4,"e",-1,0,-1,0,331,331,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0331-03",19,"No te fíes de los hombres\naunque te juren mil cruces,\nque en el altar más pequeño\narden al menos dos luces.",223,0,35,243,"",0,4,"ue",194,0,-1,0,331,331,"","",0,"","","",16,0,0,[],"",""],["fernan_caballero-p0331-04",19,"Una Pepa, dos Pepas,\ntres Pepas tengo;\nsi se me muere una,\ncon dos me quedo.",223,0,35,243,"",6,4,"eo",-1,0,-1,0,331,331,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0331-05",19,"Eres una y eres dos,\neres tres y eres cincuenta;\neres la iglesia mayor,\ndonde todo el mundo entra.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,331,331,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0331-06",19,"Aunque me ves por aquí;\nsola, sin padre ni madre,\nno se cría la lechuga\npara tan flojo vinagre.",223,0,35,243,"",0,4,"ae",-1,0,-1,0,331,331,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0331-07",19,"No te fíes de los gatos,\naunque los veas sin uñas,\nporque en viéndose apretados\nhasta con el rabo arañan.",223,0,35,243,"",5,4,"aa",-1,0,-1,0,331,331,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0332-01",19,"No te fíes de mujeres\naunque las veas llorar,\nque con sus lágrimas riegan\nlas calabazas que dan.",223,0,35,243,"",0,4,"a",-1,0,-1,0,332,332,"","",0,"rm_t4, carrizo_salta, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0332-02",19,"No pienses que han de volver\nlas nueces al cantarillo;\ná él se le quebró la boca\ny á mí se me fué el cariño.",223,0,35,243,"",0,4,"io",-1,0,-1,0,332,332,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0332-03",19,"Aunque me carguen de hierro\nnunca diré la verdad,\nporque á buena confesión\nmala penitencia dan.",223,0,35,243,"",0,4,"a",-1,0,-1,0,332,332,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0332-04",19,"Mi corazón se quema,\nno sale humo;\neso sí que es quemarse\ncon disimulo.",223,0,35,243,"",6,4,"uo",-1,0,-1,0,332,332,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0332-05",19,"El clavel que está en agua\nes para Pepe,\ny el agua es para Antonio,\nque se refresque.",223,0,35,243,"",6,4,"ee",-1,0,-1,0,332,332,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0332-06",19,"Si me quieres, te quiero;\nsi me amas, te amo;\nsi me olvidas, te olvido:\ná todo hago.",223,0,35,243,"",6,4,"ao",-1,0,-1,0,332,332,"","",0,"rm_t3","","",6,0,0,[],"",""],["fernan_caballero-p0332-07",19,"Eres hermosa y robas\nlos corazones;\n¿dónde pondré yo el mío\nque no lo robes?",223,0,35,243,"",6,4,"oe",-1,0,-1,0,332,332,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0333-01",19,"Los amantes y la luna\nson en todo semejantes;\nentran con cuarto creciente,\ny salen con cuarto menguante.",223,0,35,243,"",0,4,"ae",-1,0,-1,0,333,333,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0333-02",19,"¡Qué alta que va la luna\ny el lucero en su compaña!\n¡Qué lucido que va un hombre\ncuando una mujer lo engaña!",223,0,35,243,"",0,4,"aa",213,0,-1,0,333,333,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0333-03",19,"Cuando tú vas, yo vuelvo,\nque soy un viento,\ny te tengo calados\nlos pensamientos.",223,0,35,243,"",6,4,"eo",-1,0,-1,0,333,333,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0333-04",19,"El pájaro que es dueño\nde una maceta,\nla pasea y la pica,\npica y no peca.",223,0,35,243,"",6,4,"ea",-1,0,-1,0,333,333,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0333-05",19,"En la ventana soy dama,\nen la sala soy señora,\nen la mesa cortesana\ny en el campo labradora.",223,0,35,243,"",0,4,"oa",107,0,-1,0,333,333,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0333-06",19,"Aquel lucero brillante\nque va detrás de la luna,\nese me acompaña á mí\nla noche que voy de tuna.",223,0,35,243,"",0,4,"ua",56,0,-1,0,333,333,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0333-07",19,"Cualquiera que me tratare\ndirá que no tengo pena,\ny tengo mi corazón\ncomo una morita negra.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,333,333,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0334-01",19,"El amor del forastero\nes como la golondrina,\nque así que llega el verano\ná su tierra se encamina.",223,0,35,243,"",0,4,"ia",11,0,-1,0,334,334,"","",0,"rm_t4, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0334-02",19,"¿Tan muchacha y tiene luto?\nDime quién te se murió;\nsi te se ha muerto tu amante,\nno llores, que aquí estoy yo.",223,0,35,243,"",0,4,"o",2,0,-1,0,334,334,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0334-03",19,"Es amor como el pleitista\ncuando dinero no tiene;\nni el escribano le escucha,\nni el abogado le atiende.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,334,334,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0334-04",19,"Delante de mi madre\nno me hagas señas,\nporque es liebre corrida\ny sabe las sendas.",223,0,35,243,"",6,4,"ea",-1,0,-1,0,334,334,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0334-05",19,"Dicen que no me quieres\ntú ni tu madre;\nsi una puerta se cierra,\nciento se abren.",223,0,35,243,"",6,4,"ae",-1,0,-1,0,334,334,"","",0,"rm_t3","","",18,0,0,[],"",""],["fernan_caballero-p0334-06",19,"Si tu marido es celoso\ndale á comer chicharrones,\ny verás con la manteca\nqué suavecito se pone.",223,0,35,243,"",0,4,"oe",-1,0,-1,0,334,334,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0334-07",19,"¿Quién sería la madre\nque parió á Judas?\n¡Qué hijos tan indignos\nparen algunas!",223,0,35,243,"",6,4,"ua",-1,0,-1,0,334,334,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0335-01",19,"Pajarito jilguero,\nno cantes tanto,\nno sea que la risa\nse vuelva llanto.",223,0,35,243,"",6,4,"ao",30,0,-1,0,335,335,"","",0,"leonesas_diez","","",2,0,0,[],"",""],["fernan_caballero-p0335-02",19,"Mi suegra me quiere dar\nuna cruz para un rosario,\ny tengo yo con su hija\npeana, cruz y calvario.",223,0,35,243,"",0,4,"ao",25,0,-1,0,335,335,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0335-03",19,"Quien tuviera un encargo\npara el infierno,\nla suegra de mi alma\nse está muriendo.",223,0,35,243,"",6,4,"eo",-1,0,-1,0,335,335,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0335-04",19,"Dicen que no me quieres,\nno me quieras, no;\ndonde no hay escritura\nno hay obligación.",223,0,35,243,"",0,4,"o",-1,0,-1,0,335,335,"","",0,"rm_t3","","",18,0,0,[],"",""],["fernan_caballero-p0335-05",19,"El candil se está apagando,\nla alcuza no tiene aceite;\nno te digo que te vayas\nni te digo que te quedes.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,335,335,"","",0,"rm_t3","","",2,0,0,[],"",""],["fernan_caballero-p0335-06",19,"Anda con Dios, bien te logres,\nno te deseo mal ninguno,\nsino unas tercianas dobles\nmientras vivas en el mundo.",223,0,35,243,"",0,4,"uo",-1,0,-1,0,335,335,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0335-07",19,"Yo me enamoré de noche\ny la luna me engañó;\notra vez que me enamore\nserá de día y con sol.",223,0,35,243,"",0,4,"o",-1,0,-1,0,335,335,"","",0,"rm_t3, palau_cantares, frenk_t2","","",9,0,0,[],"",""],["fernan_caballero-p0336-01",19,"En mi alma manda Dios,\nen mi persona mis padres;\npero en cuanto á mi gustito\nen eso no manda nadie.",223,0,35,243,"",0,4,"ae",-1,0,-1,0,336,336,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0336-02",19,"Mi madre, porque soy malo,\ná un presidio quiere echarme;\nyo le digo: madre mía,\n¿dónde irá el buey que no are?",223,0,35,243,"",0,4,"ae",-1,0,-1,0,336,336,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0336-03",19,"El demonio son los hombres,\ndicen todas las mujeres;\ny luego están deseando\nque el demonio se las lleve.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,336,336,"","",0,"","","",7,0,0,[],"",""],["fernan_caballero-p0336-04",19,"El diablo es el amor\ny el demonio las mujeres,\ny los tontos de los hombres.\npor el demonio se pierden.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,336,336,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0336-05",19,"Las mujeres al mundo\nperdido tienen;\ny los hombres al mundo\ny á las mujeres.",223,0,35,243,"",6,4,"ee",-1,0,-1,0,336,336,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0336-06",19,"En esta calle vive\nla miserable\nque hasta al agua del pozo\nle echa la llave.",223,0,35,243,"",6,4,"ae",-1,0,-1,0,336,336,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0336-07",19,"Si yo viera á mi suegra\nen un avispero,\nle dijera despacio\nlo que la quiero.",223,0,35,243,"",6,4,"eo",38,0,-1,0,336,336,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0337-01",19,"Me mandaste una carta\ncon la letra menudita,\ny á mí me parió mi madre\nmás pícara que bonita.",223,0,35,243,"",0,4,"ia",50,0,-1,0,337,337,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0337-02",19,"No es mucho lo que usted pide\nsi encuentra quien se lo dé;\nquede usted con Dios, señora,\nque otro día volveré.",223,0,35,243,"",0,4,"e",77,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0337-03",19,"Anoche, en el velatorio,\nde una prima hermana mía,\nme cortaron un vestido\nsin tomarme la medida.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0337-04",19,"Para no llegar á viejo\n¿qué remedio me darás?\nMétete á servir á un amo,\ny siempre mozo serás.",223,0,35,243,"",0,4,"a",51,0,-1,0,337,337,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0337-05",19,"Yo tengo una prima hermana\nque la quiero tanto y cuanto;\ntengo que llevarla á Roma\nque la vea el Padre Santo.",223,0,35,243,"",0,4,"ao",30,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0337-06",19,"El hambre con el demonio\napostaron un doblón\ná ver cuál era más feo,\ny fué el hambre quien ganó.",223,0,35,243,"",0,4,"o",-1,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-01",19,"Es usted como el suizo,\ndoña Rufina,\nque al sol que más calienta\ná ese se inclina.",223,0,35,243,"",6,4,"ia",11,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-02",19,"Del árbol sale la flor\ny de la flor sale el fruto;\nsi de chico eres tan bruto,\n¿qué serás cuando mayor?",223,0,35,243,"",11,4,"o",72,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-03",19,"Bendecida sea el alma\nde mi Bartolo,\nque le mandé por vaca\ny trajo toro.",223,0,35,243,"",6,4,"oo",-1,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-04",19,"Me ronda un lechuguino\nde tanta gracia,\nque se parece á un mono\nque hay en mi casa.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-05",19,"Me dijiste que era pobre,\ndigo que tienes razón;\nhombre pobre y leña verde\narden cuando hay ocasión.",223,0,35,243,"",0,4,"o",31,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0338-06",19,"Anda diciendo tu madre\nque la reina te mereces,\ny yo, como no soy reina,\nno pretendo merecerte.",223,0,35,243,"",0,4,"ee",-1,0,-1,0,338,338,"","",0,"","","",23,0,0,[],"",""],["fernan_caballero-p0338-07",19,"Mi marido fué á las Indias\npara aumentar su caudal;\ntrajo mucho que \"decir\",\npero poco que \"contar\".",223,0,35,243,"",0,4,"a",-1,0,-1,0,338,338,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0339-01",19,"Francisca, por tu tejado\nva subiendo una culebra.\n—¡Madre, cómo pica el sol!\n—Más pica una mala lengua!",223,0,35,243,"",0,4,"ea",-1,0,-1,0,339,339,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0339-02",19,"Quien pregunta no yerra,\ny yo pregunto\nsi se entierran los muertos\ncon los difuntos.",223,0,35,243,"",6,4,"uo",-1,0,-1,0,339,339,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0339-03",19,"Me quisistes, me olvidastes;\nme volvistes á querer;\nlos trapos que yo desecho\nno me los vuelvo á poner.",223,0,35,243,"",0,4,"e",20,0,-1,0,339,339,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0339-04",19,"Los trapos que yo desecho\ny los echo al muladar,\nque otro venga y se los ponga\ná mí poco se me da.",223,0,35,243,"",0,4,"a",-1,0,-1,0,339,339,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0339-05",19,"Más vale onza que libra\nen algunas ocasiones;\nmás vale un cuerpo chiquito,\nque no los zarangullones.",223,0,35,243,"",0,4,"oe",34,0,-1,0,339,339,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0339-06",19,"No te pongas tan alta,\nque no eres reina;\nyo me atrevo á alcanzarte\nsin escalera.",223,0,35,243,"",6,4,"ea",-1,0,-1,0,339,339,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0339-07",19,"De puerta en puerta, un pobre\njunta más cuartos\nque aquel que en una sola\nse está parado.",223,0,35,243,"",6,4,"ao",-1,0,-1,0,339,339,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0340-01",19,"Ni la doncella Teodora,\nni el sabio de Salomón\ncompiten con mis ideas\nen llegando la ocasión.",223,0,35,243,"",0,4,"o",31,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0340-02",19,"Dígale usted al mozo\nque está en la esquina,\nsi tiene calentura,\nque tome quina.",223,0,35,243,"",6,4,"ia",11,0,-1,0,340,340,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0340-03",19,"Si me pierdo, que me busquen\nen el sol de Mediodía,\ndonde nacen las morenas\ny donde la sal se cría.",223,0,35,243,"",0,4,"ia",0,0,-1,0,340,340,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0340-04",19,"Dices que no la quieres\nni vas á verla,\npero la veredita\nno cría hierba.",223,0,35,243,"",6,4,"ea",-1,0,-1,0,340,340,"","",0,"palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0340-05",19,"De la lana del erizo\ntiene mi madre un colchón,\ny lo tiene guardadito\npara en casándome yo.",223,0,35,243,"",0,4,"o",-1,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0340-06",19,"¡Quién tuviera la dicha\nde Adán y Eva,\nque jamás conocieron\nsuegro ni suegra!",223,0,35,243,"",6,4,"ea",-1,0,-1,0,340,340,"","",0,"suspiros_amor","","",7,0,0,[],"",""],["fernan_caballero-p0340-07",19,"Al patriarca le rezo\nseis veces en la semana;\nsi alguno tuviere envidia,\nyo rezo á quien me da gana.",223,0,35,243,"",0,4,"aa",4,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0341-01",19,"¿Aun antes de ser tuya\nya me amenazas?\nMira que tengo un huerto\nde calabazas.",223,0,35,243,"",6,4,"aa",725,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0341-02",19,"Compadre del alma mía,\nmis fatigas son mortales,\nque me veo en un camino\ncon dos veredas iguales.",223,0,35,243,"",0,4,"ae",26,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0341-03",19,"Compañero, si te casas,\nbusca la novia chiquita,\nque en la especia de la olla,\nla pimienta es la que pica.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,341,341,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0341-04",19,"Señor alcalde mayor,\nno prenda usté á los ladrones\nporque tiene usté una hija\nque roba los corazones.",223,0,35,243,"",0,4,"oe",34,0,-1,0,341,341,"","",0,"rm_t2, lafuente_madrid, palau_cantares","","",8,0,0,[],"",""],["fernan_caballero-p0341-05",19,"El dueño de una viña\nuvas brindaba,\ndespués que la tenía\nya vendimiada.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0341-06",19,"¿De qué te sirves que andes\ncon tanta retrechería?\nSabes que me pinto sola\ncomo la una del día.",223,0,35,243,"",0,4,"ia",0,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0341-07",19,"A rey muerto, rey puesto,\ndice mi madre;\nno pases, hija mía,\npenas por nadie.",223,0,35,243,"",6,4,"ae",-1,0,-1,0,341,341,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0342-01",19,"Te quiero porque has dado\nde puñaladas,\nque de ningún cobarde\nse ha escrito nada.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,342,342,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0342-02",19,"La calle está regada,\ndicen que han sido\nlágrimas de un amante\nque han despedido.",223,0,35,243,"",6,4,"io",101,0,-1,0,342,342,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0342-03",19,"Déjame, prenda, por Dios\nplaticar aunque sea pobre,\nque un grillo vale dos cuartos\ny con todo se le oye.",223,0,35,243,"",0,4,"oe",-1,0,-1,0,342,342,"","",0,"rm_t2, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0342-04",19,"Yo vivo de lo que como\ny como lo que me dan;\npero masco muchas cosas\nque no las puedo tragar.",223,0,35,243,"",0,4,"a",-1,0,-1,0,342,342,"","",0,"","","",5,0,0,[],"",""],["fernan_caballero-p0342-05",19,"Señora, quién fuera pollo\nde su recoba de usted,\npara andar todito el día\npío, pío tras de usted.",223,0,35,243,"",0,4,"e",-1,0,-1,0,342,342,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0342-06",19,"Ayer tarde me dijeron\nque era usted liebre corrida;\ná la liebre corredora,\nla escopeta prevenida.",223,0,35,243,"",0,4,"ia",37,0,-1,0,342,342,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0342-07",19,"Amor, no pongas amor\ndonde no hay correspondencia;\nmira que te quedarás\ná la luna de Valencia.",223,0,35,243,"",0,4,"ea",46,0,-1,0,342,342,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0343-01",19,"A la mujer comparo\ncon las sardinas,\nque mientras más saladas\nson más dañinas.",223,0,35,243,"",6,4,"ia",243,0,-1,0,343,343,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0343-02",19,"Son tantos los comercios\nde tus amores,\nque tu casa está llena\nde corredores.",223,0,35,243,"",6,4,"oe",5,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0343-03",19,"Entre dos que bien se quieren\ncon uno que coma basta;\ny esta ha de ser la mujer,\npor ser la parte más flaca.",223,0,35,243,"",0,4,"aa",-1,0,-1,0,343,343,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0343-04",19,"En la tienda del barbero\n¿sabe usted lo que se dice?\nQue el Señor le da pañuelo\nal que no tiene narices.",223,0,35,243,"",0,4,"ie",-1,0,-1,0,343,343,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0343-05",19,"El gran poder del verano,\nque todas las cosas seca,\nno ha podido madurar\nlos sesos de tu cabeza.",223,0,35,243,"",0,4,"ea",-1,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0343-06",19,"En el patio de mi casa\nme puse á considerar\nlo poco que vale un hombre\ncuando no tiene qué dar.",223,0,35,243,"",0,4,"a",21,0,-1,0,343,343,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0343-07",19,"Tienen las sevillanas\nen la mantilla\nun letrero que dice:\n¡viva Sevilla!",223,0,35,243,"",6,4,"ia",162,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0344-01",19,"En la mar hay una parra\nque echa las uvas azules,\ncon un letrero que dice:\nquien fuese tonto, que estudie.",223,0,35,243,"",0,4,"ue",-1,0,-1,0,344,344,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0344-02",19,"A Roma se va por bulas,\npor tabaco á Gibraltar,\npor manzanilla á Sanlúcar,\ny á Cádiz se va por sal.",223,0,35,243,"",0,4,"a",-1,0,-1,0,344,344,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0344-03",19,"Si tu madre no quiere,\nni tus hermanos,\npor encima de todos\ndame la mano.",223,0,35,243,"",6,4,"ao",-1,0,-1,0,344,344,"","",0,"rm_t2","","",2,0,0,[],"",""],["fernan_caballero-p0344-04",19,"Ay de mí, desgraciado,\nque andaba siempre\ndel perejil huyendo,\ny me dió en la frente.",223,0,35,243,"",6,4,"ee",-1,0,-1,0,344,344,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0344-05",19,"El pensamiento me asoma\nde querer á esta muchacha;\npero temo que me deje\ncon la vergüenza en la cara.",223,0,35,243,"",0,4,"aa",-1,0,-1,0,344,344,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0344-06",19,"Catalina me llamo,\nque no soy mora,\nbautizada en la pila\nde mi parroquia.",223,0,35,243,"",6,4,"oa",-1,0,-1,0,344,344,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0344-07",19,"Es verdad que yo te quise,\nque te he querido y te quiero;\npero casarme contigo...\nlímpiate, que estás de huevo.",223,0,35,243,"",0,4,"eo",-1,0,-1,0,344,344,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0345-01",19,"Yo me enamoré del aire,\ndel aire de una mujer;\ncomo la mujer es aire,\nen el aire me quedé.",223,0,35,243,"",0,4,"e",-1,0,-1,0,345,345,"","",0,"rm_t3, palau_cantares, isaacs_colombia, lafuente_madrid, murciano_antiguo","","",9,0,0,[],"",""],["fernan_caballero-p0345-02",19,"De los cielos á la tierra\nse oyó una voz en el aire:\nquien quiera vivir tranquilo\nno ponga su amor en nadie.",223,0,35,243,"",0,4,"ae",-1,0,-1,0,345,345,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0345-03",19,"Escuche usted, mozo bueno,\nno gaste usted fantasía,\nque el carro de la basura\ntambién gasta campanilla.",223,0,35,243,"",0,4,"ia",-1,0,-1,0,345,345,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0345-04",19,"Los enemigos del alma\ntodos dicen que son tres,\ny yo digo que son cuatro\ndesde que conozco á usted.",223,0,35,243,"",0,4,"e",-1,0,-1,0,345,345,"","",0,"","","",8,0,0,[],"",""],["fernan_caballero-p0345-05",19,"Tienes la cara alegre,\ndifunta el alma,\nporque no te confiesas\ncomo Dios manda.",223,0,35,243,"",6,4,"aa",-1,0,-1,0,345,345,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0345-06",19,"Si piensas que en ti pienso,\nhas pensado mal;\nni pienso ni he pensado,\nni pienso en pensar.",223,0,35,243,"",0,4,"a",-1,0,-1,0,345,345,"","",0,"rm_t3","","",4,0,0,[],"",""],["fernan_caballero-p0346-01",19,"Murió mi mujer en Marzo,\ná mediados de Cuaresma,\ny quiso Dios en un año\ndarme dos carnestolendas.",223,0,35,244,"",0,4,"ea",-1,0,-1,0,346,346,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0346-02",19,"Pañuelo á la cintura,\npañuelo al cuello;\nyo no sé de dónde salen\ntantos pañuelos.",223,0,35,244,"",6,4,"eo",-1,0,-1,0,346,346,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0346-03",19,"No me case mi madre\ncon hombre chico,\nque le lleve y le traiga\ncomo abanico.",223,0,35,244,"",6,4,"io",141,0,-1,0,346,346,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0346-04",19,"Ya viene la Cuaresma\npara sermones;\nen mi casa no faltan\npredicaciones.",223,0,35,244,"",6,4,"oe",34,0,-1,0,346,346,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0346-05",19,"Cuando se emborracha un pobre,\nle dicen el borrachón;\ncuando se emborracha un rico:\n¡qué gracioso está el señor!",223,0,35,244,"",0,4,"o",-1,0,-1,0,346,346,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0347-01",19,"Primero que suba al cielo\nel alma de un escribano,\ntintero, papel y pluma\nhan de bailar el fandango.",223,0,35,244,"",0,4,"ao",-1,0,-1,0,347,347,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0347-02",19,"Pájaros con muchas plumas\nno se pueden mantener;\nlos escribanos, con una,\nmantienen moza y mujer.",223,0,35,244,"",0,4,"e",20,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0347-03",19,"Médicos y cirujanos\nno van á misa mayor,\nporque les dicen los muertos:\nahí pasa el que me mató.",223,0,35,244,"",0,4,"o",-1,0,-1,0,347,347,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0347-04",19,"El amor y el cuchillo\nson dos extremos,\nmucho acero en la punta\ny al cabo hierro.",223,0,35,244,"",6,4,"eo",-1,0,-1,0,347,347,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0347-05",19,"Es el dón de aquel hidalgo\ncomo el dón del algodón,\nque no puede tener dón\nsin tener antes el algo.",223,0,35,244,"",11,4,"ao",726,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0347-06",19,"El amor de la mujer,\nla pluma del escribano,\nson dos cosas que se alcanzan\ncuando se unta la mano.",223,0,35,244,"",0,4,"ao",81,0,-1,0,347,347,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0347-07",19,"El cura de mi lugar\nmurió de una rozadura;\nese sí que era buen cura,\nque se sabía rascar.",223,0,35,244,"",11,4,"a",21,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0348-01",19,"Como las cañas huecas\nson las mujeres,\nque se llenan de aire\ncuando las quieren.",223,0,35,244,"",6,4,"ee",-1,0,-1,0,348,348,"","",0,"rm_t4, palau_cantares, murciano_antiguo","","",4,0,0,[],"",""],["fernan_caballero-p0348-02",19,"Es la mujer una nave\nque á todos vientos navega;\npoco prevenido es\naquel que se embarca en ella.",223,0,35,244,"",0,4,"ea",-1,0,-1,0,348,348,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0348-03",19,"De la costilla de Adán\ncrió Dios á la mujer;\npor eso tienen los hombres\nese hueso que roer.",223,0,35,244,"",0,4,"e",20,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0348-04",19,"Si te murieras, mujer,\n¡qué dicha para los dos!;\ntú ibas á ver á Dios\ny Dios me venía á ver.",223,0,35,244,"",11,4,"e",20,0,-1,0,348,348,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0348-05",19,"Mi marido se murió,\nDios en el cielo le tenga,\ny le tenga tan tenido\nque nunca por acá vuelva.",223,0,35,244,"",0,4,"ea",-1,0,-1,0,348,348,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0348-06",19,"Un escribano y un gato\nen un pozo se cayeron;\ncomo los dos tenían uñas,\npor la pared se subieron.",223,0,35,244,"",0,4,"eo",105,0,-1,0,348,348,"","",0,"","","",6,0,0,[],"",""],["fernan_caballero-p0348-07",19,"Quien de alpargatas se fía\ny á mujeres hace caso,\nno tendrá un cuarto en su vida\ny andará siempre descalzo.",223,0,35,244,"",0,4,"ao",-1,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0349-01",19,"Quien quisiera en este mundo\nde aruñones estar libre,\nque no juegue con los gatos\nni á las mujeres se arrime.",223,0,35,244,"",0,4,"ie",-1,0,-1,0,349,349,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0349-02",19,"Dios te libre, libro mío,\nde las manos del librero,\nque cuando te está alabando\nentonces te está vendiendo.",223,0,35,244,"",0,4,"eo",-1,0,-1,0,349,349,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0349-03",19,"Un desnudo vende ropa,\nun calvo vende los peines,\nun ciego los anteojos;\neste mundo, ¿quién lo entiende?",223,0,35,244,"",0,4,"ee",-1,0,-1,0,349,349,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0349-04",19,"Cuchillos de dos filos\nson las cuñadas;\n¡ay de mí!, que mi amante\ntiene una hermana.",223,0,35,244,"",6,4,"aa",-1,0,-1,0,349,349,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0349-05",19,"Por la calle abajito\nratones vienen;\nsube, niña, al tejado,\nno te atropellen.",223,0,35,244,"",6,4,"ee",-1,0,-1,0,349,349,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0349-06",19,"Todo el que quiere casarse\najusta la cuenta alegre,\ny luego que está casado\nla repasa y no la entiende.",223,0,35,244,"",0,4,"ee",-1,0,-1,0,349,349,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0349-07",19,"De suegras y cuñadas\nva un carro lleno;\n¡mirad qué linda carga\npara el infierno!",223,0,35,244,"",6,4,"eo",-1,0,-1,0,349,349,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0350-01",19,"No puedo ir á misa,\nporque estoy cojo;\nme voy á la taberna\npoquito á poco.",223,0,35,244,"",6,4,"oo",-1,0,-1,0,350,350,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0350-02",19,"Los calzones del padre\nde Catalina\ntienen cincuenta varas\nsin la pretina.",223,0,35,244,"",6,4,"ia",11,0,-1,0,350,350,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0351-01",19,"Ha venido Mayo,\nbien venido sea,\nque con su venida\nlas flores se alegran.",223,0,35,245,"",0,4,"ea",-1,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0351-02",19,"Los pájaros son clarines\nentre los cañaverales,\nque le dan los buenos días\nal sol de Dios cuando sale.",223,0,35,245,"",0,4,"ae",-1,0,-1,0,351,351,"","",0,"rm_t4","","",4,0,0,[],"",""],["fernan_caballero-p0351-03",19,"Allá arriba en el monte Calvario,\nmatita de oliva, matita de olor,\narrullaron la muerte de Cristo\ncuatro jilgueritos y un ruiseñor.",223,0,35,245,"",3,4,"o",72,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0351-04",19,"Cuando sale la aurora,\nsale llorando;\npobrecita, ¡qué noche\nhabrá pasado!",223,0,35,245,"",6,4,"ao",-1,0,-1,0,351,351,"","",0,"palau_cantares","","",2,0,0,[],"",""],["fernan_caballero-p0352-01",19,"Mira al cielo vestirse\nde ricas telas;\nde día azul y blanco,\nde noche estrellas.",223,0,35,245,"",6,4,"ea",-1,0,-1,0,352,352,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0352-02",19,"Palomita blanca,\nreina del cielo,\ntiéndeme tus alitas,\ndame tu vuelo.",223,0,35,245,"",6,4,"eo",10,0,-1,0,352,352,"","",0,"","","",12,0,0,[],"",""],["fernan_caballero-p0352-03",19,"El sol se va poniendo,\ndicen las flores;\nya se va quien nos daba\nbellos colores.",223,0,35,245,"",6,4,"oe",5,0,-1,0,352,352,"","",0,"rm_t4","","",2,0,0,[],"",""],["fernan_caballero-p0352-04",19,"Sevilla para regalo,\nMadrid para la nobleza,\npara tropas Barcelona,\npara jardines Valencia.",223,0,35,245,"",0,4,"ea",-1,0,-1,0,352,352,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0352-05",19,"Las golondrinas\nle quitaron á Cristo\ntres mil espinas.\nLos gorriones\nle quitaron á Cristo\ntres mil doblones.",223,0,35,245,"",9,6,"oe",34,0,-1,0,352,352,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0352-06",19,"Aunque mi color es negro,\nmi dinero es español,\ny tiene cruz y castillos,\narmas del rey mi señor.",223,0,35,245,"",0,4,"o",-1,0,-1,0,352,352,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0353-01",19,"Para alcarrazas Chiclana,\npara trigo Trebujena,\ny para niñas bonitas,\nSanlúcar de Barrameda.",223,0,35,245,"",0,4,"ea",-1,0,-1,0,353,353,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0353-02",19,"Abre la puerta, Culantro.\nPerejil, ¿quién está ahí?\nLa comadre Hierba-buena\nque viene por Toronjil.",223,0,35,245,"",0,4,"i",-1,0,-1,0,353,353,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0353-03",19,"No les temo á los ladrones,\nsi civiles me acompañan.\n¡Viva la Guardia civil,\nporque es la gloria de España!",223,0,35,245,"",0,4,"aa",-1,0,-1,0,353,353,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0353-04",19,"En las mañanas de Abril,\nal amanecer el día,\nse juntan los pajaritos,\ncantando el Avemaría.",223,0,35,245,"",0,4,"ia",0,0,-1,0,353,353,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0353-05",19,"Y apenas asoma el sol,\ná él de cara se vuelven,\ndándole gracias á Dios\ncon sus trinos más alegres.",223,0,35,245,"",0,4,"ee",-1,0,-1,0,353,353,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0354-01",19,"A la nana le cantaba\nla Virgen á sus amores:\ndulce hijo de mi vida,\nperdona á los pecadores.",223,0,35,246,"",0,4,"oe",5,0,-1,0,354,354,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0354-02",19,"En los brazos te tengo,\ny considero\n¡qué será de ti, niño,\nsi yo me muero!",223,0,35,246,"",6,4,"eo",38,0,-1,0,354,354,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0354-03",19,"A la puerta del cielo\nvenden zapatos\npara los angelitos\nque están descalzos.",223,0,35,246,"",6,4,"ao",-1,0,-1,0,354,354,"","",0,"leonesas_diez","","",2,0,0,[],"",""],["fernan_caballero-p0354-04",19,"A los niños que duermen\nDios los bendice,\ny á las madres que velan\nDios las asiste.",223,0,35,246,"",6,4,"ie",-1,0,-1,0,354,354,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0354-05",19,"Todo lo chiquitito\nme hace á mí gracia;\nhasta los pucheritos\nde media cuarta.",223,0,35,246,"",6,4,"aa",-1,0,-1,0,354,354,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-01",19,"A la rorro, mi niño,\nmi niño duerme\ncon los ojos abiertos\ncomo las liebres.",223,0,35,246,"",6,4,"ee",-1,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-02",19,"El niño de María\nno tiene cuna;\nsu padre es carpintero\ny le hará una.",223,0,35,246,"",6,4,"ua",56,0,-1,0,355,355,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0355-03",19,"No llores, Isabelita,\nque las flores se marchitan.\nIsabelita, no llores,\nque se marchitan las flores.",223,0,35,246,"",5,4,"oe",5,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-04",19,"Duérmete, niño, en los brazos\ny dormirás con descanso.\nDuérmete, niño, en la cuna\ny dormirás con fortuna.",223,0,35,246,"",5,4,"ua",56,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-05",19,"Cuando era chiquita\nen la cuna estaba,\nvenían los angelitos\ny me besaban.",223,0,35,246,"",6,4,"aa",-1,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-06",19,"Anda vete, morito,\ná la morería,\nque mi niño no entiende\ntu algarabía.",223,0,35,246,"",6,4,"ia",0,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0355-07",19,"Señora Santa Ana,\nseñor San Joaquín,\narrullad al niño,\nque quiere dormir.",223,0,35,246,"",0,4,"i",-1,0,-1,0,355,355,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0356-01",19,"Duérmete, niño chiquito,\nmira que viene la mora\npreguntando puerta en puerta\ncuál es el niño que llora.",223,0,35,246,"",0,4,"oa",107,0,-1,0,356,356,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0356-02",19,"Duérmete, niño chiquito,\nduérmete y no llores más,\nque se irán los angelitos\npara no verte llorar.",223,0,35,246,"",0,4,"a",-1,0,-1,0,356,356,"","",0,"palau_cantares","","",3,0,0,[],"",""],["fernan_caballero-p0356-03",19,"Al verte triste y malito\nse me parte el corazón;\nasí cuando canto, lloro,\ny se me apaga la voz.",223,0,35,246,"",0,4,"o",-1,0,-1,0,356,356,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0356-04",19,"Duérmete, niño mío\nde mi corazón;\nte acompaña la Virgen\ny el niño de Dios.",223,0,35,246,"",0,4,"o",-1,0,-1,0,356,356,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0356-05",19,"Este niño chiquito\nno tiene madre;\nlo parió una gitana\ny lo echó á la calle.",223,0,35,246,"",6,4,"ae",-1,0,-1,0,356,356,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0356-06",19,"Niño chiquirritito\nde pecho y cuna,\n¿dónde estará tu madre\nque no te arrulla?",223,0,35,246,"",6,4,"ua",-1,0,-1,0,356,356,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0356-07",19,"Duérmete, niño mío,\nduerme y no llores,\nque te mira la Virgen\nde los Dolores.",223,0,35,246,"",6,4,"oe",5,0,-1,0,356,356,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0357-01",19,"Arbolito chiquito,\néchame nueces;\néchamelas á pares,\ncuatro en dos veces.",223,0,35,246,"",6,4,"ee",196,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0357-02",19,"Corazoncito mío,\ncalla y no llores,\nque te traigo noticias\nde tus amores.",223,0,35,246,"",6,4,"oe",5,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0358-01",19,"A tu puerta está una campanilla;\nni te llama ella ni te llamo yo,\nque te llaman tu padre y tu madre\npara que por ellos le ruegues á Dios.\nY vamos allá,\ná rezarle el rosario á María,\nque es nuestra abogada, llena de piedad.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,358,358,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0358-02",19,"En el cielo se reza un rosario\ntodas las mañanas al amanecer;\nSantiago lleva el estandarte,\nSan Pedro la luz, la cruz San Miguel.\nPues vamos allá,\nque no hay cosa más santa y más dulce\nque el santo rosario que se va á rezar.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,358,358,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0358-03",19,"La corona se quitó María\ny á su propio hijo se la presentó,\ny le dijo: Yo ya no soy Reina\nsi tú no perdonas al pecador,\nJesús respondió:\nSi no fuese por tus ruegos, madre,\nya hubiera acabado con el pecador.",223,0,35,246,"Rosario de la aurora.",4,7,"o",-1,0,-1,0,358,359,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0359-01",19,"Una tarde se perdió Domingo,\nsus hijos llorosos lo van á buscar,\nlo encontraron en el paraíso\ncogiendo las rosas del santo rosal.\nY vamos allá,\ná pedirle á la Virgen María\npara que intercéda con Su Majestad.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0359-02",19,"Si te hallaras enfermo del alma\ny la medicina quisieres buscar,\nreza al punto el rosario á María,\nque por ese medio le habrás de alcanzar.\nRézalo y verás\nque el rosario mantiene la gracia\ny la fortaleza para no pecar.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0359-03",19,"A tu puerta está una campanilla;\nni te llama ella ni te llamo yo,\nque te llaman la peste y la guerra,\nque esos son avisos que nos manda Dios.\nY vamos allá,\ná pedirle á la Virgen clemente\npara que nos libre de culpa y de mal.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,359,359,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0359-04",19,"Dos pastores se arriman á un árbol,\nde una gran tormenta huyendo el rigor;\ncayó un rayo, ¡Jesús, Dios nos libre!,\ny al uno de ellos lo hizo carbón.\nPero al otro no,\npues el santo rosario traía\nmetido en el seno con gran devoción.",223,0,35,246,"Rosario de la aurora.",4,7,"o",-1,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0360-01",19,"¡Si supieses la entrada que tuvo\nel Rey de los cielos en Jerusalén,\nque ni coche ni calesa quiso,\nsino un jumentito que alquilado fué!\nPara demostrar\nque las puertas divinas del cielo\ntan sólo ha de abrirnos la santa humildad.",223,0,35,246,"Rosario de la aurora.",4,7,"a",-1,0,-1,0,360,360,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0360-02",19,"Es María la nave de gracia,\nSan José la vela, el niño el timón,\ny los remos son las buenas almas\nque van al rosario con gran devoción.",223,0,35,246,"Rosario de la aurora.",3,4,"o",31,0,-1,0,360,360,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0372-02",19,"Madre del Amor Hermoso,\nasí le dice á María,\ná Egipto irás con el Niño,\ny José en tu compañía.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,372,372,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0372-03",19,"Saldrás á la media noche,\nocultando al Sol divino;\npasaréis muchos trabajos\ndurante todo el camino.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,372,372,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0372-04",19,"Os irá bien con mi gente,\nos tratarán con cariño;\nlos ídolos, cuando entréis,\nvendrán al suelo rendidos.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,372,372,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-01",19,"Mirando al Niño divino,\nle decía enternecida:\n¡cuánto tienes que pasar,\nlucerito de mi vida!\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-02",19,"La cabeza de este Niño,\ntan hermosa y agraciada,\nluego la hemos de ver\ncon espinas traspasada.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-03",19,"Las manitas de este Niño,\ntan blancas y torneadas,\nluego las hemos de ver\nen una cruz enclavadas.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-04",19,"Los piececitos del Niño,\ntan chicos y sonrosados,\nluego los hemos de ver\ncon un clavo taladrados.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-05",19,"Andarás de monte en monte,\nhaciendo mil maravillas;\nen uno sudarás sangre,\nen otro darás la vida.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-06",19,"Morirás en Vera-Cruz,\nlevantada en el Calvario,\nque á tanto te obligará\nese tu amor extremado.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0373-07",19,"La más cruel de tus penas,\nte la prodigo con llanto,\nserá que en tus redimidos,\nSeñor, hallarás ingratos.\nLas cosas que sé, etc.",223,0,35,246,"La predicción de la gitana.",7,5,"e",-1,0,-1,0,373,373,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0380-01",19,"La Nochebuena se viene,\nla Nochebuena se va;\nnosotros también nos vamos,\npero no volvemos más.",223,0,35,247,"",0,4,"a",-1,0,-1,0,380,380,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0380-02",19,"Cuando la Virgen parió,\nse encontró en el portal sola:\nlo primero que acudió\nfué un pastor y una pastora.",223,0,35,247,"",0,4,"oa",-1,0,-1,0,380,380,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0380-03",19,"Un pastor, comiendo sopas,\nen el aire divisó\nun ángel que le decía:\nya ha nacido el Redentor.",223,0,35,247,"",0,4,"o",-1,0,-1,0,380,380,"","",0,"rm_t4, palau_cantares, frenk_t4, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0380-04",19,"La Virgen se fué á lavar\nsus manos blancas al río;\nel sol se quedó parado,\nla mar perdió su ruido.",223,0,35,247,"",0,4,"io",-1,0,-1,0,380,380,"","",0,"","","",3,0,0,[],"",""],["fernan_caballero-p0380-05",19,"Los pastores de Belén\ntodos juntos van por leña,\npara calentar al niño\nque nació la Nochebuena.",223,0,35,247,"",0,4,"ea",-1,0,-1,0,380,380,"","",0,"palau_cantares","","",5,0,0,[],"",""],["fernan_caballero-p0381-01",19,"La Virgen está lavando\ny tendiendo en el romero,\nlos pajaritos cantaban\ny el agua se iba riendo.",223,0,35,247,"",0,4,"eo",-1,0,-1,0,381,381,"","",0,"","","",4,0,0,[],"",""],["fernan_caballero-p0381-02",19,"La Virgen se está peinando,\nsu peine de marfil era,\nrayos del sol sus cabellos,\nla cinta la primavera.",223,0,35,247,"",0,4,"ea",44,0,-1,0,381,381,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0381-03",19,"Todos le llevan al niño,\nyo no tengo qué llevarle;\nle llevaré el corazón,\nque le sirva de pañales.",223,0,35,247,"",0,4,"ae",-1,0,-1,0,381,381,"","",0,"","","",9,0,0,[],"",""],["fernan_caballero-p0381-04",19,"Tomad ese capillito,\nhecho de flores está,\npara abrigar la cabeza\nde ese niño celestial.",223,0,35,247,"",0,4,"a",-1,0,-1,0,381,381,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0381-05",19,"San José era carpintero,\ny la Virgen costurera,\ny el niño labra la cruz,\nporque ha de morir en ella.",223,0,35,247,"",0,4,"ea",-1,0,-1,0,381,381,"","",0,"rm_t4, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0381-06",19,"Ven acá con esa bota,\nven acá, yo brindaré\ná la salud de María,\npara que crie á Manuel.",223,0,35,247,"",0,4,"e",-1,0,-1,0,381,381,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0381-07",19,"Los pastores daban saltos\ny bailaban de contento,\nal par que los angelitos\ntocaban los instrumentos.",223,0,35,247,"",0,4,"eo",-1,0,-1,0,381,381,"","",0,"palau_cantares, frenk_t4, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0382-01",19,"La Virgen iba á Belén,\nle dió el parto en el camino,\ny entre la mula y el buey\nnació el Cordero divino.",223,0,35,247,"",3,4,"io",199,0,-1,0,382,382,"","",0,"rm_t4, frenk_t4, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0382-02",19,"La Virgen va caminando,\nva caminando solita,\ny no lleva más compaña\nque el niño de la manita.",223,0,35,247,"",0,4,"ia",50,0,-1,0,382,382,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",12,0,0,[],"",""],["fernan_caballero-p0382-03",19,"La Virgen quiso sentarse\nal abrigo de un olivo,\ny las hojas se volvieron\ná ver al recién nacido.",223,0,35,247,"",0,4,"io",-1,0,-1,0,382,382,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0382-05",19,"En el portal de Belén\nha nacido un Manolito,\nque dicen que es más bonito\nque Juanito el de Isabel.",223,0,35,247,"",5,4,"e",-1,0,-1,0,382,382,"","",0,"","","",32,0,0,[],"",""],["fernan_caballero-p0382-06",19,"A Belén, Belén, pastores,\ná ver al nieto de Ana,\nque trae un león atado\ncon una cuerda de lana.",223,0,35,247,"",0,4,"aa",4,0,-1,0,382,382,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0383-01",19,"Mientras María cortaba\ny hacía las camisitas,\n¡qué de lágrimas de amor\ncorrían por sus mejillas!",223,0,35,247,"",0,4,"ia",-1,0,-1,0,383,383,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0383-02",19,"Una pandereta suena,\nyo no sé por dónde va;\ncamina para Belén\nhasta llegar al portal.",223,0,35,247,"",0,4,"a",-1,0,-1,0,383,383,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["fernan_caballero-p0383-03",19,"Al ruido que llevaba,\nel santo José salió;\nno me despertéis al niño,\nque ahora poco se durmió.",223,0,35,247,"",0,4,"o",2,0,-1,0,383,383,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0383-04",19,"Lo ha dormido entre sus brazos\naquella que lo parió,\ny su canto era tan dulce\nque pudo dormir á Dios.",223,0,35,247,"",0,4,"o",-1,0,-1,0,383,383,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0383-06",19,"Un soldadito ha llegado;\ncomo el orbe goza paz,\nse queda de centinela\ná la puerta del portal.",223,0,35,247,"",0,4,"a",-1,0,-1,0,383,383,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["fernan_caballero-p0384-01",19,"Y dijo un tambor:\ná este niño, que es mi soberano,\ngenerala y marcha\nle tocaré yo.",223,0,35,247,"",3,4,"o",-1,0,-1,0,384,384,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0384-02",19,"Esta noche nace el niño\nentre la paja y el hielo;\n¡quién pudiera, niño mío!\nvestirte de terciopelo!",223,0,35,247,"",0,4,"eo",10,0,-1,0,384,384,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["fernan_caballero-p0384-03",19,"San José tenía celos\ndel preñado de María,\ny en el vientre de su madre\nel niño se sonreía.",223,0,35,247,"",0,4,"ia",0,0,-1,0,384,384,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0384-04",19,"Esta noche ha de nacer\nManolito de Jesús,\npara morir por el hombre\nenclavado en una cruz.",223,0,35,247,"",0,4,"u",109,0,-1,0,384,384,"","",0,"rm_t4, lafuente_madrid, palau_cantares","","",4,0,0,[],"",""],["fernan_caballero-p0384-06",19,"En el portal de Belén\nhay estrella, sol y luna,\nla Virgen y San José\ny el niño que está en la cuna.",223,0,35,247,"",0,4,"ua",56,0,-1,0,384,384,"","",0,"carrizo_salta","","",32,0,0,[],"",""],["fernan_caballero-p0385-01",19,"El niño Dios se ha perdido,\nen el mundo no parece,\nestá á la orilla del río\nsentado pescando peces.",223,0,35,247,"",0,4,"ee",-1,0,-1,0,385,385,"","",0,"","","",2,0,0,[],"",""],["fernan_caballero-p0385-02",19,"En Belén tocan á fuego,\ndel portal sale la llama,\ny es que allí ha nacido Aquel\nque en llamas de amor se abrasa.",223,0,35,247,"",0,4,"aa",-1,0,-1,0,385,385,"","",0,"carrizo_salta","","",5,0,0,[],"",""],["fernan_caballero-p0385-03",19,"En el portal de Belén\nnació un clavel encarnado,\nque por redimir al mundo\nse ha vuelto lirio morado.",223,0,35,247,"",0,4,"ao",14,0,-1,0,385,385,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",32,0,0,[],"",""],["fernan_caballero-p0386-03",19,"Por los campos del Oriente\nsale dando envidia al sol\nla más bella criatura\nque de mujeres nació.",223,0,35,247,"",0,4,"o",-1,0,-1,0,386,386,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0386-04",19,"Bendita la Virgen pura,\nque es relicario de amor,\nporque lleva en sus entrañas\ntan soberano Señor.",223,0,35,247,"",0,4,"o",72,0,-1,0,386,386,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0386-05",19,"A las doce de la noche\nque más feliz no se vió,\nnació en un Ave María,\nsin romper el alba, el sol.",223,0,35,247,"",0,4,"o",-1,0,-1,0,386,386,"","",0,"rm_t4","","",8,0,0,[],"",""],["fernan_caballero-p0387-01",19,"Lástima sería el ver\nen las mejillas las perlas\nde Aquel que apenas nació\nhabiendo nacido apenas.",223,0,35,247,"",0,4,"ea",-1,0,-1,0,387,387,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0387-02",19,"La Virgen, como era pobre,\namasaba en el portal;\nel cedazo era plata\ny la pala de cristal.",223,0,35,247,"",0,4,"a",1,0,-1,0,387,387,"","",0,"","","",1,0,0,[],"",""],["fernan_caballero-p0387-03",19,"A Belén tengo que ir\naunque me riña mi amo,\nque yo también quiero ver\ná ese niño soberano.",223,0,35,247,"",0,4,"ao",-1,0,-1,0,387,387,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["fernan_caballero-p0387-05",19,"Cuando la Virgen fué á misa\nal templo de Salomón,\nel vestido que llevaba\nera de rayos del sol.",223,0,35,247,"",0,4,"o",-1,0,-1,0,387,387,"","",0,"","","",4,0,0,[],"",""],["suspiros_amor-p0013-01",20,"Yo no sé por qué la quiero\nY la adoro con afan,\nSi es tan fea y tan arisca\nComo un mono orangutan.",224,9,-1,248,"EL PRIMER CANTO (PARA ELLA)",5,4,"ua",-1,0,-1,0,13,13,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0013-02",20,"Es morena, mui morena,\nDel color de la callana;\nEs peluda y jorobada\nY se llama Cayetana.",224,9,-1,248,"EL PRIMER CANTO (PARA ELLA)",0,4,"aa",-1,0,-1,0,13,13,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0013-03",20,"Es gangosa y media-lengua,\nTiene un ojo solamente,\nY no tiene la monona\nDos milímetros de frente.",224,9,-1,248,"EL PRIMER CANTO (PARA ELLA)",0,4,"ee",15,0,-1,0,13,13,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0014-01",20,"Las orejas aparentan\nPicaron o sopaipilla;\nLa nariz es tan pequeña,\nQue parece rabadilla.",224,9,-1,248,"EL PRIMER CANTO (PARA ELLA)",0,4,"ia",162,0,-1,0,14,14,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0014-02",20,"Es tan fea, que entre jente\nNo la puedo presentar;\nPero tiene... diez mil pesos\nY una quinta en Miramar.",224,9,-1,248,"EL PRIMER CANTO (PARA ELLA)",0,4,"a",21,0,-1,0,14,14,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0014-03",20,"Me gustan mucho tus ojos,\nMe gusta mucho tu pelo,\nMe gusta mucho tu cara,\nMe gusta mucho tu cuerpo;\nTodo en tí me gusta mucho,\nDesde la planta al cabello;\nPero no te quiero, niña,\nY sabrás que no te quiero,\nPorque no puede una luz\nAlumbrar dos aposentos.",224,9,-1,248,"UN CORAZON SOLO QUIERO",18,10,"eo",-1,0,-1,0,14,14,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0014-04",20,"Si no pongo en tí los ojos,\nEs que en otra los he puesto,\nEs que si me gustas mucho,\nMe gusta mas la que quiero,\nEs que yo el corazon pongo\nDonde pongo el pensamiento,\nEs que para dos amores\nTengo el corazon pequeño;\nEs que no puedo adorar\nDos corazones a un tiempo.",224,9,-1,248,"UN CORAZON SOLO QUIERO",18,10,"eo",-1,0,-1,0,14,15,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0015-01",20,"La niña que yo idolatro\nTiene un ojo como cielo,\nCubierto con una nube\nQue está anunciando aguacero.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"eo",-1,0,-1,0,15,15,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0015-02",20,"El amor de nuestros dias\nSe parece a muchos pillos:\nPrimero nos empalica,\nDespues nos vácia el bolsillo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"io",-1,0,-1,0,15,15,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0015-03",20,"Mi marido y el tuyo\nVan a Linares,\nA buscar cuatro bueyes:\nVendrán tres pares.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",6,4,"ae",164,0,-1,0,15,15,"3","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0015-04",20,"Cuando sufro resignado\nMis penas y sufrimientos,\nEs cuando pienso que Cristo\nSiendo Dios bajó al infierno.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"eo",-1,0,-1,0,15,15,"4","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0016-01",20,"El hombre es locomotora,\nLos rieles son el dinero,\nLa esperanza el conductor,\nLa ambicion el fogonero.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"eo",38,0,-1,0,16,16,"5","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0016-02",20,"El dia en que yo nací\nCantó un chuncho en mi cabaña,\nPájaro de mal agüero\nQue anunciaba mis desgracias.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",-1,0,-1,0,16,16,"6","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0016-03",20,"Considero a la mujer\nCual botella de cerveza,\nQue en quitándole el tapon\nPierde ya toda la fuerza.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ea",-1,0,-1,0,16,16,"7","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0016-04",20,"La misma resistencia\nLa mujer tiene,\nQue una gasa prendida\nCon alfileres.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",6,4,"ee",-1,0,-1,0,16,16,"8","",77,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["suspiros_amor-p0016-05",20,"Te miré llorar un dia\nPorque un ave morir viste;\nHas dado muerte a mi alma\nY sin embargo te ries.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ie",-1,0,-1,0,16,16,"9","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0016-06",20,"La pimienta es chica y pica\nY sazona los guisados;\nTú eres chiquita y me tienes\nEl cuerpo desazonado.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ao",-1,0,-1,0,16,16,"10","",77,"","","",5,0,0,[],"",""],["suspiros_amor-p0017-01",20,"He de mandar que me entierren\nSentado cuando me muera,\nPara que puedas decir:\n—Se murió pero me espera.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ea",44,0,-1,0,17,17,"11","",77,"rm_t2","","",3,0,0,[],"",""],["suspiros_amor-p0017-02",20,"Ayer pasé por tu calle\nY te divisé al balcon:\nSiempre que se mira al cielo\nSe vé la gracia de Dios.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",-1,0,-1,0,17,17,"12","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0017-03",20,"Al alto cielo subí\nA confesar con un santo,\nY me echó de penitencia\nQue no te quisiera tanto.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ao",30,0,-1,0,17,17,"13","",77,"rm_t2","","",6,0,0,[],"",""],["suspiros_amor-p0017-04",20,"—Dame un besito, morena,\nQue tu madre lo mandó.\n—Mi madre manda en lo suyo,\nEn lo mio mando yo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",2,0,-1,0,17,17,"14","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0017-05",20,"Cuando veo a mi suegra\n¡Me alegro tanto!\nSi es que el altar me alegra,\n¿Qué será el santo?",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",6,4,"ao",30,0,-1,0,17,17,"15","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0017-06",20,"Si tu madre no me quiere,\nQue lance una maldicion:\nQue se le pierda su hija...\nY que me la encuentre yo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",-1,0,-1,0,17,17,"16","",77,"","","",5,0,0,[],"",""],["suspiros_amor-p0018-01",20,"Una morena me mata,\nUna rubia me hace el hoyo,\nY una muchacha de quince\nMe saca del Purgatorio.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"oo",-1,0,-1,0,18,18,"17","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0018-02",20,"Tienen las Sanfelipeñas\nLa sal de Dios en los labios,\nY en la punta de la lengua\nAzúcar, canela y clavo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ao",-1,0,-1,0,18,18,"18","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0018-03",20,"El primer amor que tuvé\nMe llevó a mí el corazon;\nNo hai amor como el primero,\nQue se lleva lo mejor.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",-1,0,-1,0,18,18,"19","",77,"","","",6,0,0,[],"",""],["suspiros_amor-p0018-04",20,"El que compra un desengaño\nEn los amores primeros,\nEn los amores segundos\nDesengaños va vendiendo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"eo",-1,0,-1,0,18,18,"20","",77,"rm_t4","","",2,0,0,[],"",""],["suspiros_amor-p0018-05",20,"He estado en el Purgatorio\nY he visto lo que son penas,\nY sé que por querer bien\nNinguna alma se condena.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ea",-1,0,-1,0,18,18,"21","",77,"","","",5,0,0,[],"",""],["suspiros_amor-p0018-06",20,"Las palabras amorosas\nSon las cuentas de un collar,\nQue en saliendo la primera\nSalen todas las demas.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"a",-1,0,-1,0,18,18,"22","",77,"rm_t4","","",5,0,0,[],"",""],["suspiros_amor-p0019-01",20,"Háganseme unos zapatos\nCon un tacon que levante,\nQue soi chiquita y no alcanzo\nA los labios de mi amante.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ae",47,0,-1,0,19,19,"23","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0019-02",20,"Las penas que por tí paso\nNo me salen a la cara;\nComo las paso por tí,\nLas pasó de buena gana.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",-1,0,-1,0,19,19,"24","",77,"","","",7,0,0,[],"",""],["suspiros_amor-p0019-03",20,"¡Quién tuviera la dicha\nDe Adan y Eva,\nQue jamás conocieron\nSuegro ni suegra!",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",6,4,"ea",-1,0,-1,0,19,19,"25","",77,"fernan_caballero","","",7,0,0,[],"",""],["suspiros_amor-p0019-04",20,"Hai dos cosas en el mundo\nQue no pueden olvidarse:\nEl primer amor del alma\nY el cariño de la madre.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ae",-1,0,-1,0,19,19,"26","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0019-05",20,"En la puerta de la cárcel\nHai escrito con carbon:\nAquí el bueno se hace malo\nY el malo se hace peor.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",-1,0,-1,0,19,19,"27","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0019-06",20,"Si por beber de una fuente\nHas dejado secar otra,\nOlvidar para querer\nEs una ignorancia loca.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"oa",-1,0,-1,0,19,19,"28","",77,"rm_t3","","",5,0,0,[],"",""],["suspiros_amor-p0020-01",20,"Mis amigos me desprecian\nPorque me ven abatido:\nTodo el mundo saca leña\nDel árbol que está caido.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"io",101,0,-1,0,20,20,"29","",77,"","","",6,0,0,[],"",""],["suspiros_amor-p0020-02",20,"¡Malhaya la ropa negra\nQue el tintorero pintó,\nQue está mi amada de luto\nSin haberme muerto yo!",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",2,0,-1,0,20,20,"30","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0020-03",20,"Es sombra lo pasado,\nNiebla el futuro;\nRelámpago el presente...\nLa vida es humo;\nSi bien se advierte,\nNo hai cierto en este mundo\nMas que la muerte.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",4,7,"ee",134,0,-1,0,20,20,"31","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0020-04",20,"Cuando te veo con pena,\nEn mí no reina alegría;\nQue como te quiero tanto,\nSufro la tuya y la mia.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ia",0,0,-1,0,20,20,"32","",77,"","","",8,0,0,[],"",""],["suspiros_amor-p0020-05",20,"Al pié de una cruz bendita\nLloraba por tu querer;\nLas lágrimas que lloraba\nSe quejaban al caer.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"e",20,0,-1,0,20,20,"33","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0021-01",20,"¡Cómo quieres que los aires\nCruce un pájaro sin alas!\n¡Cómo quieres que yo viva\nSin darme tú una esperanza!...",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",-1,0,-1,0,21,21,"34","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0021-02",20,"Para volar nace el ave,\nPara perfumar la flor;\nPara morir nace el hombre,\nPara amar el corazon.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",-1,0,-1,0,21,21,"35","",77,"carrizo_salta, palau_cantares","","",3,0,0,[],"",""],["suspiros_amor-p0021-03",20,"Cuando se ven en la calle\nPersonas que se han querido,\nSe tornan de otro color\nY se les quita el sentido.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"io",101,0,-1,0,21,21,"36","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0021-04",20,"La niña que está bailando\nParece un pimpollo de oro:\nPregúntele, compañero,\nSi es casada o tiene novio.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"oo",-1,0,-1,0,21,21,"37","",77,"","","",19,0,0,[],"",""],["suspiros_amor-p0021-05",20,"Cuando chiquito lloraba,\nCuando grande tambien lloro;\nCuando chiquito por papa,\nY hoi por el bien que adoro.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"oo",85,0,-1,0,21,21,"38","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0021-06",20,"Tienes una boca, niña,\nComo capullo cerrado;\nDe buena gana la abriera\nCon el soplo de mis labios.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ao",-1,0,-1,0,21,21,"39","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0022-01",20,"Cuando Dios te formó, quiso\nPonerte un lunar por firma;\nCojió el sello de su gracia\nY lo estampó en tu mejilla.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ia",-1,0,-1,0,22,22,"40","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0022-02",20,"Si el hoyo de tu barba\nFuera pilita,\nMas de cuatro tomaran\nAgua bendita.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",6,4,"ia",50,0,-1,0,22,22,"41","",77,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["suspiros_amor-p0022-03",20,"Dicen que la golondrina\nTiene la pechuga blanca;\nY mi serranilla tiene\nLa pechuga y la garganta.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",-1,0,-1,0,22,22,"42","",77,"rm_t2, palau_cantares, lafuente_madrid","","",12,0,0,[],"",""],["suspiros_amor-p0022-04",20,"La hermosura de los cielos\nCuando Dios la repartió,\nNo andarias tú mui lejos\nCuando tanta te tocó.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"o",2,0,-1,0,22,22,"43","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0022-05",20,"Un ánjel falta en la iglesia\nPara el altar de Jesus:\nLe voi a decir al Cura\nSi quiere que seas tú.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"u",-1,0,-1,0,22,22,"44","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0022-06",20,"Desde tu puerta a la iglesia\nHe de poner una parra,\nPara que, si vas a misa,\nNo te dé el sol en la cara.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",-1,0,-1,0,22,22,"45","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0023-01",20,"En la puerta de tu casa\nHe de poner un letrero\nCon letras de oro que diga:\nPor aquí se sube al cielo.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"eo",-1,0,-1,0,23,23,"46","",77,"lafuente_madrid","","",13,0,0,[],"",""],["suspiros_amor-p0023-02",20,"Los ojos de una viudita\nVan diciendo por la calle:\n\"¿Quién quiere alquilar el cuarto?\nPorque no lo habita nadie\"",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"ae",-1,0,-1,0,23,23,"47","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0023-03",20,"La primera que nació\nEngañó a mi padre Adan;\nSi esa fué la que Dios hizo,\n¡Las otras cómo serán!",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"a",147,0,-1,0,23,23,"48","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0023-04",20,"Un estudiante a una niña\nLe estaba dando besitos,\nY su madre les decia:\n—Miren qué par de anjelitos.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"io",254,0,-1,0,23,23,"49","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0023-05",20,"Las doncellas son de oro,\nLas viuditas son de plata,\nLas casadas son de cobre\nY las viejas de hojalata.",224,9,-1,248,"MOSTACILLAS (CINCUENTA)",0,4,"aa",74,0,-1,0,23,23,"50","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0043-01",20,"Mi suegra es aplanchadora\nY mi novia lavandera,\nY yo templado de oficio,\nQue no encuentro quien me quiera.",224,9,-1,249,"LOS PELIGROS DE UN AMANTE",0,4,"ea",44,0,-1,0,43,43,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0043-02",20,"Todo el dia se lo pasan\nEn el piso principal\nRasqueteando los fondillos\nDe un señor Municipal.",224,9,-1,249,"LOS PELIGROS DE UN AMANTE",0,4,"a",1,0,-1,0,43,43,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0043-03",20,"Cuando voi a visitarlas\nY les toco el aldabon,\nComo condenado a muerte\nMe palpita el corazon.",224,9,-1,249,"LOS PELIGROS DE UN AMANTE",0,4,"ao",-1,0,-1,0,43,43,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0043-04",20,"Pues yo sé que si en sus manos\nCae un dia mi persona,\nSi la suegra no me estruja,\nLa chiquilla me almidona.",224,9,-1,249,"LOS PELIGROS DE UN AMANTE",0,4,"oa",7,0,-1,0,43,43,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0044-01",20,"Eres como el trigo, rubia,\nEscojido grano a grano;\nEres la rubia mas linda\nQue mis ojos han mirado.",224,9,-1,249,"A MI IDEAL",0,4,"ao",-1,0,-1,0,44,44,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0044-02",20,"Manojitos de alfileres,\nChiquilla, son tus pestañas,\nQue cada vez que me miras\nEn el alma me los clavas.",224,9,-1,249,"A MI IDEAL",0,4,"aa",-1,0,-1,0,44,44,"","",77,"","","",5,0,0,[],"",""],["suspiros_amor-p0044-03",20,"Los dientes de tu boquita\nMe tienen cautivo y preso;\nEn mi vida he visto yo\nCadenas hechas de hueso.",224,9,-1,249,"A MI IDEAL",0,4,"eo",48,0,-1,0,44,44,"","",77,"rm_t2, palau_cantares, lafuente_madrid","","",6,0,0,[],"",""],["suspiros_amor-p0044-04",20,"¡Ai, qué dedos para anillos!\n¡Qué pecho para un diamante!\n¡Qué orejas para zarcillos!\n¡Qué niña para un amante!",224,9,-1,249,"A MI IDEAL",1,4,"ae",47,0,-1,0,44,44,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0044-05",20,"Desde que te ví te amé;\nPésame, que ha sido tarde;\nQue yo quisiera, bien mio,\nDesde que nací adorarte.",224,9,-1,249,"A MI IDEAL",0,4,"ae",-1,0,-1,0,44,44,"","",77,"rm_t2, palau_cantares, lafuente_madrid","","",17,0,0,[],"",""],["suspiros_amor-p0044-06",20,"Desde que te he conocido,\nNo me encuentro el corazon;\nMete la mano en el pecho\nY dime si tienes dos.",224,9,-1,249,"A MI IDEAL",0,4,"o",-1,0,-1,0,44,44,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0044-07",20,"Eres alta y buena moza,\nMas te falta lo mejor:\nUn relicario en el pecho\nY en medio mi corazon.",224,9,-1,249,"A MI IDEAL",0,4,"o",-1,0,-1,0,44,44,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0045-01",20,"Tengo celos del aire\nQue dá en tu cara:\nY si el aire fuera hombre,\nYo lo matara.",224,9,-1,249,"SOLO PARA MÍ",6,4,"aa",57,0,-1,0,45,45,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0045-02",20,"Anda, que no te quiero,\nQue estás besada...\nPues te besó tu madre\nCuando mamabas.",224,9,-1,249,"SOLO PARA MÍ",6,4,"aa",-1,0,-1,0,45,45,"","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0045-03",20,"Lo que no hayas de darme,\nNo me lo enseñes;\nQue Amor es como niño,\nQue en viendo quiere.",224,9,-1,249,"SOLO PARA MÍ",6,4,"ee",-1,0,-1,0,45,45,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0045-04",20,"Tú y yo nos parecemos\nMucho a la nieve:\nTú en lo blanca y lo fria,\nYo en deshacerme.",224,9,-1,249,"SOLO PARA MÍ",6,4,"ee",-1,0,-1,0,45,45,"","",77,"rm_t3, palau_cantares, frenk_t2","","",4,0,0,[],"",""],["suspiros_amor-p0045-05",20,"Me llaman el celoso,\n¡Mira qué pena!\nSoi labrador y quiero\nGuardar mi hacienda.",224,9,-1,249,"SOLO PARA MÍ",6,4,"ea",-1,0,-1,0,45,45,"","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0045-06",20,"Yo te quiero y no quiero,\nQue son dos cosas;\nYo te quiero y no quiero\nQue lo conozcas.",224,9,-1,249,"SOLO PARA MÍ",6,4,"oa",-1,0,-1,0,45,45,"","",77,"rm_t2, fernan_caballero","","",5,0,0,[],"",""],["suspiros_amor-p0046-01",20,"Al salir el sol dorado,\nEsta mañana te ví\nCojiendo, niña, en tu huerto\nMatitas de perejil.",224,9,-1,249,"LA PEREJILERA",0,4,"i",-1,0,-1,0,46,46,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0046-02",20,"Para verte mas de cerca,\nEn el huerto me metí,\nY sabrás que eché de menos\nMi corazon al salir?",224,9,-1,249,"LA PEREJILERA",0,4,"i",-1,0,-1,0,46,46,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0046-03",20,"Tu debistes encontrarle,\nQue en el huerto le perdí:\nDámelo, Perejilera,\nQue te lo vengo a pedir.",224,9,-1,249,"LA PEREJILERA",0,4,"i",-1,0,-1,0,46,46,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0046-04",20,"Cuando los ingleses están mui contentos,\nEstiran las piernas y se ponen tiezos;\nY con cara séria y el aire cortés\nMueven la cabeza en el baile inglés.\nYes, yes, yes.",224,9,-1,249,"LA CRUZ BLANCA",7,5,"e",218,0,-1,0,46,46,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0046-05",20,"Si ves una inglesa, siempre que te guste\nNo la mires nunca, porque te da un fuste\nY con cara séria y el aire cortés,\nMueve las caderas y tambien los piés.\nYes, yes, yes.",224,9,-1,249,"LA CRUZ BLANCA",7,5,"e",218,0,-1,0,46,46,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0047-01",20,"Siempre que los gringos buscan Margaritas\nLas aprecian mucho si se hallan solitas,\nY con cara larga y el aire cortés,\nDicen a las chicas; mi querer you a ustés.\nYes, yes, yes.",224,9,-1,249,"LA CRUZ BLANCA",7,5,"e",218,0,-1,0,47,47,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0047-03",20,"Sacaron a vender un burro cojo,\nSin orejas y sin patas, con un ojo;\nTenia su espinazo de manera,\nQue mui bien aserraba la madera.",224,9,-1,249,"PICO DE ORO",3,4,"ea",44,0,-1,0,47,47,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0047-04",20,"Lo supo el reverendo Frai Pimiento\nY al punto lo llevó para el convento;\nY así que con los frailes se encontraba,\nMui risueño Frai Pimiento les contaba:",224,9,-1,249,"PICO DE ORO",3,4,"aa",28,0,-1,0,47,47,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0047-05",20,"\"El que fué cocinero antes que fraile,\nLo que pasa en la cocina bien lo sabe;\nY si el fraile a la vez es cocinero,\nSe aprovecha de los rezos y el puchero.\"",224,9,-1,249,"PICO DE ORO",3,4,"eo",38,0,-1,0,47,47,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0047-06",20,"Sacaron a vender una escopeta\nAntigua, sin culata y sin baqueta;\nTenia su gatillo de manera\nQue nunca salió el tiro para afuera.",224,9,-1,249,"PICO DE ORO",3,4,"ea",44,0,-1,0,47,47,"2","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0048-01",20,"Lo supo el reverendo Frai Pimiento,\nY al punto la llevó para el convento;\nY así que con los frailes se encontraba,\nRisueño Frai Pimiento disparaba:",224,9,-1,249,"PICO DE ORO",3,4,"aa",28,0,-1,0,48,48,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0048-03",20,"Me acuerdo de una niña mui torera\nQue dicen que cosia para afuera,\nY ahora como es chica de talento\nElla cose para afuera y para dentro.",224,9,-1,249,"PICO DE ORO",3,4,"eo",-1,0,-1,0,48,48,"3","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0048-04",20,"Lo supo el reverendo Frai Pimiento,\nY al punto la llamó para el convento,\nY así que con los frailes se acostaba,\nRisueño Frai Pimiento la abrazaba...",224,9,-1,249,"PICO DE ORO",3,4,"aa",28,0,-1,0,48,48,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0065-01",20,"Peno por una Susana,\nPadezco por una Rita,\nSuspiro por una Anita,\nY muero por una Juana.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",11,4,"aa",4,0,-1,0,65,65,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0065-02",20,"La Lucrecia me dá pena\nSolo de oirla nombrar;\nPor celos con la Pilar\nOdio me tiene la Elena;\nSi miro a la Magdalena,\nSe agravia la Cayetana;\nPara ver a la Juliana\nHe de engañar a la Amelia;\nLo mismo que por la Celia\nPeno por una Susana.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",18,10,"aa",4,0,-1,0,65,65,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0065-03",20,"Me acaricia la Tadea,\nMe lisonjea la Ignacia;\nNo permite la Anastasia\nQue hable con la Dorotea;\nMucho mas que la Matea\nMe gusta la Margarita.\nUna Petronila quita\nA mi vida la existencia,\nY con mayor complacencia\nPadezco por una Rita.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",18,10,"ia",50,0,-1,0,65,66,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0066-01",20,"Adoro a la Estefanía,\nNunca dejaré a la Rosa,\nSolo por la Sinforosa\nPerderé a la Rosalía;\nSi me olvida la María,\nIré donde la Benita,\nY en caso que no me admita\nO me dijere que nó,\nLe daré a saber que yo\nSuspiro por una Anita.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",18,10,"ia",50,0,-1,0,66,66,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0066-02",20,"Dejar a la Carolina\nNo me place por la Antonia,\nSe morirá la Polonia\nSi me vé con la Martina;\nA mas que la Serafina\nSabe lo que es la Fabiana,\nAl pié de la Feliciana\nRendiré la última gota\nDe sangre por la Carlota\nY muero por un Juana.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",18,10,"aa",4,0,-1,0,66,66,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0066-03",20,"Por último, la Gabriela\nJunto con la Emperatriz,\nLa Irene y la Beatriz\nUna u otra me consuela;\nAbandonar la Fidela\nMe parece una injusticia.\nYo creo que la Mauricia\nMe proteje y la Leonor:\nEl dejarlas es mejor\nA todas por la Delicia.",224,9,-1,250,"MIS CUARENTA Y UNA QUERIDAS",18,10,"ia",391,0,-1,0,66,67,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0067-01",20,"La Gallina fué a quejarse\nA una competente Junta,\nY salió de la consulta,\nQue presente un Memorial.\n—Aquí te veré pagar,\nQue de dinero eres fallo,\nY no tienes un caballo\nQue vender, flojo, rotoso,\nPicaron, escandaloso,\nDijo la Gallina al Gallo.",224,9,-1,250,"LA DEMANDA DE LA GALLINA AL GALLO",18,10,"ao",102,0,-1,0,67,67,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0067-02",20,"Dijo el Gallo enfurecido:\n—Perra coja, pati-tuerta,\nNi tampoco una calceta\nMe habeis hecho para el frio.\n—¡Calla, le dice, atrevido!\nNo intentes que rabie mas;\nTe tengo bien conocido\nQue cuando con otra estás,\nNo me recuerdas jamás,\nPerro mal agradecido.",224,9,-1,250,"LA DEMANDA DE LA GALLINA AL GALLO",18,10,"io",101,0,-1,0,67,67,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0068-01",20,"Con tus locos pareceres\nMe das tú tan malos ratos,\nQue ni siquiera zapatos\nMe das por correr placeres\nCon otras varias mujeres.\nYa he visto mi desengaño,\nQue con tal de hacerme daño\nNo reparas que estoi clueca:\nY aunque esté con la jaqueca\nMe haces poner todo el año.",224,9,-1,250,"LA DEMANDA DE LA GALLINA AL GALLO",18,10,"ao",40,0,-1,0,68,68,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0068-03",20,"Viva misiá Fulanita,\nHermosísima colina,\nYa le canté la demanda\nDel Gallo con la Gallina.\nOiga ahora a él que opina\nY dice:—Yo subo y mando;\nAsí, no me andes cobrando\nSentimientos tan innobles;\nAdvierte que soi el hombre,\n¡Arriba y vamos andando!",224,9,-1,250,"LA DEMANDA DE LA GALLINA AL GALLO",18,10,"ao",33,0,-1,0,68,68,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0069-01",20,"Varias pasiones sustenta\nEl corazon mujeril:\nLos celos, la envidia vil,\nLa rabia y venganza cruenta;\nPero jamás alimenta\nEl amor bien entendido,\nSi no falaz y finjido,\nPero con tanta doblez,\nQue aún descubierto despues\nParece que fué sentido.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"io",101,0,-1,0,69,69,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0069-02",20,"Todas ellas siempre quieren\nSer tentadas por amores\nDe cumplidos amadores\nQue a complacerlas se dieren.\nY si acaso no se vieren\nDistinguidas y obsequiadas,\nEstán tristes y aquejadas,\nPero con tanto disfraz,\nQue al mas astuto y sagaz\nLe hacen creer son amadas.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"aa",282,0,-1,0,69,69,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0069-03",20,"La mas prudente y medida\nSi alguno le habla de amor,\nMuda al momento el color,\nSe pone rosa encendida;\nPero nunca se descuida\nDe finjirse indiferente,\nY se creyera imprudente\nSi no mostrara tibieza;\nPues en ellas es rareza\nDecir lo que el pecho siente.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"ee",15,0,-1,0,69,70,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0070-01",20,"No hai una que no se crea\nLa primera en hermosura,\nY es mui falta de cordura\nLa que se tiene por fea:\nDe cualquier modo que sea,\nTodas tratan de agradar,\nTodas quieren conquistar\nVoluntad y corazon\nSin mirar en condicion,\nFortuna, estado y lugar.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"a",21,0,-1,0,70,70,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0070-02",20,"No hai coloquio entre doncellas\nEn que amor no halle cabida,\nY es cosa mui bien sabida\nQue en conversaciones de ellas\nSe siguen siempre las huellas\nDe las damas mas arteras,\nEn ardides y maneras,\nLo mas propio a sus intentos\nDe novio y de casamientos,\nQue son sus ansias primeras.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"ea",103,0,-1,0,70,70,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0070-03",20,"Cuando lloran, antes miran\nSi hai hombres que las consuelen;\nSi lidian es porque suelen\nVencer de amor; si suspiran,\nSi se enfadan, rien o admiran,\nSiempre lo hacen con malicia,\nPues no conoce impericia\nPara finjirse abrasada,\nLa soltera, la casada,\nLa veterana o novicia.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"ia",391,0,-1,0,70,71,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0071-01",20,"Tiene tal tino y cordura\nPara ocultar sus fealdades\nEn todos tiempos y edades,\nQue si mucho se me apura\nDigo que es una locura\nPensar que mujer alguna\nMostrara falta ninguna\nCuando ocultarla pudiera;\nY si así no sucediera,\nDe mil se engañara a una.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"ua",56,0,-1,0,71,71,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0071-02",20,"Como siempre esperan todas\nCuando viudas o solteras,\nQue las estrechen de veras\nPara hablar luego de bodas;\nComo vestidos y modas\nMudan de amante a la vez,\nEntretienen seis o diez\nCon mil ardides y engaños,\nTrascursando así los años\nHasta que cae algun pez.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"e",150,0,-1,0,71,71,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0071-03",20,"Nunca son mas cariñosas\nQue cuando llegan a ver\nQue pueden enriquecer\nHaciéndose bondadosas:\nMas quien entiende estas cosas\nSabe bien que es el dinero\nY no el hombre el verdadero\nObjeto de su aficion;\nPues le aman de corazon\nComo a su galan primero.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"eo",38,0,-1,0,71,72,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0072-01",20,"Si entrasen en competencia\nPor alguna dama bella\nTres o cuatro que por ella\nGastan dinero y paciencia,\nDaria ella preferencia\nAl que mas pesetas tiene,\nPorque amor tambien previene\nQue se mire con decoro\nA doña Plata y don Oro,\nPues que a todos les conviene.",224,9,-1,250,"EL CORAZON DE LA MUJER",18,10,"ee",70,0,-1,0,72,72,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0072-02",20,"Guitarra dulce y querida,\nConsuélame con tus sones,\nPorque son tus vibraciones\nPaños que lavan mi herida;\nDeja que mi alma aterida\nPor helado sinsabor,\nPara sufrir su dolor\nTe nombre su compañera,\nY seas tú medianera\nDe su inconstancia y amor.",224,9,-1,250,"INCERTIDUMBRE",18,10,"o",72,0,-1,0,72,72,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0072-03",20,"Sigue, guitarra, mi canto\nCon tus notas elocuentes,\nPero no jimas si sientes\nQue te abraso con mi llanto.\nModula su nombre en tanto\nQue a mí me ahoga la pena,\nPorque ese acento serena\nCon su dulce poesía\nLa ansiedad que el alma mia\nFrenéticamente llena.",224,9,-1,250,"INCERTIDUMBRE",18,10,"ea",59,0,-1,0,72,73,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0073-01",20,"Modula, dulce guitarra,\nModula su nombre amado,\nQue ya un sufrimiento helado\nEl corazon me desgarra,\nY aunque sepas que me amarra\nSu rigor al padecer,\nNo desmayes, que es mujer,\nY yo sé que no es delito\nEste cariño infinito\nQue me persigue doquier.",224,9,-1,250,"INCERTIDUMBRE",18,10,"e",20,0,-1,0,73,73,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0073-02",20,"Deja que estalle en mi pecho\nEl volcan de mi pasion,\nDeja que mi corazon\nPalpite pedazos hecho;\nNo ha de infundirme el despecho\nRabia para maldecirla;\nHe de verla y he de oiría,\nY si me brinda veneno,\nLo beberé, no lo temo,\nSin dejar de bendecirla.",224,9,-1,250,"INCERTIDUMBRE",18,10,"ia",-1,0,-1,0,73,73,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0073-03",20,"Mas nó! ¡Yo mismo me afrento!\n¿Por qué he de quererla tanto\nSi ella rie de mi llanto,\nSi goza con mi tormento?\nTorna, guitarra el contento\nA mi alma con tu armonía:\nVibra notas de alegría;\nQuiero pensar que soi hombre!\nPero ¡ai! no puedo... su nombre\nVuelve a la memoria mia!",224,9,-1,250,"INCERTIDUMBRE",18,10,"a",0,0,-1,0,73,74,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0074-01",20,"Quizá en mi amargo delirio\nLa ofendo con mi dolor,\nPorque pienso que su amor\nTenga la vida de un lirio;\nQuién sabe si el cruel martirio\nQue fomenta mi tortura,\nEn su alma sensible y pura\nNo tiene tambien asiento,\nY mientras yo me lamento\nElla jime en su amargura!",224,9,-1,250,"INCERTIDUMBRE",18,10,"ua",17,0,-1,0,74,74,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0074-02",20,"Sin andar con indirectas\nNi palabras de doctores\nVoy a contarles, señores,\nLa historia de unas chancletas:\nSon ellas tan indiscretas\nQue en perjuicio de ña Juana\nSe han hecho cada ventana\nPara que les entre el fresco,\nQue les dan como refresco\nSeis resfrios por semana.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"aa",4,0,-1,0,74,74,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0075-01",20,"Y se puede figurar\nCómo será la cosiaca;\nPues pobre del que se atraca\nY las tiene que olfatear,\nSi no las llega a calar\nLe dá el cólera a la fija,\nPues son peor que una vasija\nLlena de mala conserva,\nY tienen, como reserva,\nUn poco de sabandija.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"ia",219,0,-1,0,75,75,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0075-02",20,"Y es lástima que así sea,\nPorque la dueña es buenaza;\nNo tiene mas que la trasa\nPoco, mui poquito fea;\nCabeza como azotea,\nPorque de crespa es porruda;\nEs por demás orejuda,\nY de nariz de picana;\nA mas tiene doña Juana\nUna boca bigotuda.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"ua",144,0,-1,0,75,75,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0075-03",20,"Lengua hasta de sobra tiene\nY charla hasta por los codos,\nPleitea de todos modos\nY en enredos se entretiene;\nMas esto al caso no viene,\nPerdonen mis distraimientos,\nVoy a seguir al momento\nMi empezada relacion,\nY a entrar de sopeton\nCon las chancletas del cuento.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"eo",-1,0,-1,0,75,75,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0076-01",20,"Ellas andan a disgusto\nToda la santa semana,\nPorque en los piés de ña Juana\nTienen medio siglo justo;\n¡Y cómo han de andar con gusto\nSi ya un esqueleto son!\nTienen cada costuron\nY cada parche poroso,\nQue es por demas doloroso\nVerlas aún en funcion.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"uo",-1,0,-1,0,76,76,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0076-02",20,"Tienen remiendos tamaños\nDe zaraza y terciopelo,\nDe pedazos de pañuelo\nY de diferentes paños;\nHace ya como veinte años\nQue la suela se acabó\nY de entonces empezó\nA arreglarlas con cartones,\nQue en mas de cien ocasiones\nA mí mismo me pidió.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"o",2,0,-1,0,76,76,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0076-03",20,"Y a pesar de tal cuidado,\nMientras que va caminando,\nLos dedos van asomando\nPor uno y por otro lado;\nMuchas veces se ha cortado\nCon vidrios que encuentra al paso,\nO se ha pegado un porrazo\nLastimándose la jeta;\nY ha sentido la chancleta\nMucho mas que el hocicazo.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"ao",43,0,-1,0,76,76,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0077-01",20,"Mas para eso es prudente,\nY si acaso ha rezongado,\nEs porque se ha desgraciado\nLa chancleta nuevamente;\nY si se halla casualmente\nDispuesta para zurcir,\nLa comienza así a fruncir\nPara no comprar terreno,\nPero si le hace otro agujero\nVuelve a hacerla relucir.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"i",157,0,-1,0,77,77,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0077-02",20,"A veces de sufrir harta\nLa pobrecita se sale,\nPero eso de nada vale,\nPorque ella otra vez la ensarta.\n¡Pucha la vieja lagarta,\nHereje con la chancleta!\nAunque ande como carreta,\nNunca es capaz de dejarla.\n¡Si debian de multarla!\n¡Pues que no sea trompeta!",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"ea",200,0,-1,0,77,77,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0077-03",20,"Tiene botas abrochadas\nPero son de los domingos,\nPues van unos cuantos gringos\nQue invita con empanadas;\nGracias a esas convidadas\nEs que ella hace gran derroche,\nPasan la tarde y la noche\nLas chancletas descansando,\nMientras tanto les va dando\nUn poquito a las de broche.",224,9,-1,250,"LAS CHANCLETAS DE ÑA JUANA",18,10,"oe",337,0,-1,0,77,77,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0093-01",20,"Niñas que a vender flores\nVais a Granada,\nNo paseis por los bosques\nDe la Alpujarra.",224,9,-1,251,"LA FLORISTA",6,4,"aa",-1,0,-1,0,93,93,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0093-02",20,"Si una niña es hermosa,\nSe la persigue;\nY si es fea no falta\nQuien la codicie.",224,9,-1,251,"LA FLORISTA",6,4,"ie",-1,0,-1,0,93,93,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0093-03",20,"Porque dice el adajio,\nLectores mios,\n\"Que nunca falta un roto\nA un descosido.\"",224,9,-1,251,"LA FLORISTA",6,4,"io",-1,0,-1,0,93,93,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0093-04",20,"Niñas que a vender flores\nVais descuidadas,\nNo paseis por los bosques\nDe la Alpujarra.",224,9,-1,251,"LA FLORISTA",6,4,"aa",-1,0,-1,0,93,93,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0094-01",20,"Una tarde en el Parque\nMe miró un viejo,\nSe puso los anteojos\nY me hizo un jesto...\n¿Sabes tú, madre,\nSi a rezar el rosario\nQuiso llevarme?",224,9,-1,251,"AMOR DE VIEJO NO QUIERO",4,7,"ae",-1,0,-1,0,94,94,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0094-02",20,"Viejo tonto de noche,\nTonto de dia,\nTonto por la mañana\nY al medio dia:\nNo me acordaba\nQue ese vejete es tonto\nDe madrugada.",224,9,-1,251,"AMOR DE VIEJO NO QUIERO",4,7,"aa",-1,0,-1,0,94,94,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0094-03",20,"Mi amor es una viña\nDonde yo miro\nPendientes de una cepa\nMuchos racimos:\nSepa el babieca\nQue yo no quiero ahora\nCepa tan seca.",224,9,-1,251,"AMOR DE VIEJO NO QUIERO",4,7,"ea",594,0,-1,0,94,94,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0094-04",20,"En el lado derecho\nDe mi corpiño\nTengo un Juan, un Antonio,\nUn Abelino:\nY al otro lado\nTengo un niñito muerto,\nCiego, vendado.",224,9,-1,251,"AMOR DE VIEJO NO QUIERO",4,7,"ao",14,0,-1,0,94,94,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0095-01",20,"Aunque algunos autores\nLo contradigan,\nLos primeros amores\nSon los que privan;\nSi no se logran,\nSiempre quedan impresos\nEn la memoria.",224,9,-1,251,"EL PRIMER AMOR",4,7,"oa",-1,0,-1,0,95,95,"","",77,"rm_t4","","",2,0,0,[],"",""],["suspiros_amor-p0095-02",20,"No me mires, que miran\nQue nos miramos;\nMiremos la manera\nDe no mirarnos.\nNo nos miremos,\nY cuando no nos miren\nNos miraremos.",224,9,-1,251,"EL PRIMER AMOR",4,7,"eo",127,0,-1,0,95,95,"","",77,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["suspiros_amor-p0095-03",20,"Si te preguntan, niña,\nA quién adoras,\nPrimero morir mártir\nQue confesora;\nQue el que confiesa\nTiene siempre segura\nLa penitencia.",224,9,-1,251,"EL PRIMER AMOR",4,7,"ea",-1,0,-1,0,95,95,"","",77,"rm_t2, fernan_caballero","","",3,0,0,[],"",""],["suspiros_amor-p0095-04",20,"El confesor me ha dicho\nQue no te quiera,\nY yo le he dicho:—¡Ai, padre,\nSi usted la viera!...\nY ayer me dijo:\n—Haces bien en quererla,\nQue ya la he visto.",224,9,-1,251,"EL PRIMER AMOR",4,7,"io",-1,0,-1,0,95,95,"","",77,"","","",4,0,0,[],"",""],["suspiros_amor-p0096-01",20,"Tengo yo un gacho moreno\nQue me camela con gracia;\nMas salado que mil sales,\nMas dulce que la miel blanca.\n¡Ai, moreno! ¡Ai mi alma,\nCamélame con gracia!",224,9,-1,251,"EL GACHO MORENO",9,6,"aa",-1,0,-1,0,96,96,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0096-02",20,"Mira, gacho, que no quiero\nQue a picos pardos te vayas,\nPorque tu gacha te quiere\nCon mas zandunga y mas gracia.\n¡Ai, moreno! ¡Ai, mi alma,\nCamélame con gracia!",224,9,-1,251,"EL GACHO MORENO",9,6,"aa",-1,0,-1,0,96,96,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0096-03",20,"Los hombres tiran la caña\nPor ver si pescan;\nPero pescando,\nEllos se salen riendo\nY ellas llorando.",224,9,-1,251,"ADANES Y EVAS",7,5,"ao",33,0,-1,0,96,96,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0096-04",20,"Es la mujer lo mismo\nQue leña verde;\nQue resiste, jime y llora\nY al fin se enciende.\nLuego encendida,\nNi resiste ni llora\nSino suspira.",224,9,-1,251,"ADANES Y EVAS",4,7,"ia",-1,0,-1,0,96,96,"","",77,"","","",5,0,0,[],"",""],["suspiros_amor-p0097-01",20,"Las mujeres de ahora\nSon como libros,\nQue por nuevos se compran\nY están leidos.\nY muchos de ellos,\nEstando remendados\nPasan por nuevos.",224,9,-1,251,"ADANES Y EVAS",4,7,"eo",-1,0,-1,0,97,97,"","",77,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["suspiros_amor-p0097-02",20,"Se parecen las liebres\nA las muchachas,\nEn que las corren unos\nY otros las cazan.\nAunque hoi sucede\nCorren los cazadores\nMas que las liebres.",224,9,-1,251,"ADANES Y EVAS",4,7,"ee",-1,0,-1,0,97,97,"","",77,"","","",3,0,0,[],"",""],["suspiros_amor-p0106-02",20,"Para jardines Granada,\nPara mujeres Madrid,\nY para amores tus ojos\nCuando me miran a mí.",224,9,-1,252,"LOS OJOS NEGROS",0,4,"i",-1,0,-1,0,106,106,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0106-03",20,"Sin luceros está la mañana,\nPues de envidia no pueden brillar,\nQue mi niña salió a la ventana\nY a los cielos se puso a mirar.",224,9,-1,252,"LOS OJOS NEGROS",3,4,"a",21,0,-1,0,106,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0107-01",20,"No levantes los ojos al cielo,\nTen al mundo mi niña, piedad,\nQue si al sol le causares enojo,\nCierra los ojos, la noche vendrá.",224,9,-1,252,"LOS OJOS NEGROS",3,4,"a",-1,0,-1,0,107,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0107-02",20,"En los ojos azules del cielo\nHai un mundo de límpido amor;\nMas los negros si anuncian querellas,\nSon centellas de ardiente pasion.",224,9,-1,252,"LOS OJOS NEGROS",3,4,"ao",-1,0,-1,0,107,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0107-03",20,"Vivan, vivan los ojos de fuego,\nQue son galas del suelo español;\nVivan, vivan las niñas morenas,\nQue alejan las penas de mi corazon.",224,9,-1,252,"LOS OJOS NEGROS",3,4,"ao",-1,0,-1,0,107,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0107-05",20,"De tus ojos lánguidos,\nNegros y bellísimos,\nUna chispa eléctrica\nMi pecho abrasó.",224,9,-1,252,"MI DELIRIO",5,4,"o",-1,0,-1,0,107,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0107-06",20,"Desde entonces muérome\nPor tu faz simpática\nY palpita rápido\nMi fiel corazon.",224,9,-1,252,"MI DELIRIO",6,4,"ao",-1,0,-1,0,107,107,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-01",20,"Dime, niña hermosa,\nFaro de mi amor,\nSi hallará en tu pecho\nEco mi pasion.",224,9,-1,252,"MI DELIRIO",6,4,"ao",-1,0,-1,0,108,108,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-02",20,"Pues si en vano late,\nÉl, niña, por tí,\nMe verás, ingrata,\nDe pena morir.",224,9,-1,252,"MI DELIRIO",0,4,"i",-1,0,-1,0,108,108,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-03",20,"Al ver de tus ojos\nEl vivo fulgor,\nEl alma suspira,\nDelira de amor.",224,9,-1,252,"MI DELIRIO",0,4,"o",72,0,-1,0,108,108,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-04",20,"Y loca te adora,\nSoñando placer\nDe hallar en tus brazos\nSu gloria, su eden.",224,9,-1,252,"MI DELIRIO",6,4,"ee",-1,0,-1,0,108,108,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-05",20,"Me gusta ver un soldado\nEn la puerta del cuartel\nEchar su fusil al hombro,\nSaludar su coronel.",224,9,-1,252,"EL SOLDADO",0,4,"e",32,0,-1,0,108,108,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0108-06",20,"El soldado que marcha a la guerra\nEn llevando fusil y tambor,\nEl resguarda los campos de gloria\nY no teme a los lances de honor.",224,9,-1,252,"EL SOLDADO",3,4,"o",72,0,-1,0,108,108,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0109-01",20,"Un soldado se quejaba\nDe su suerte tan fatal:\nDe haber servido a la Patria\nY del pago que le dan.",224,9,-1,252,"EL SOLDADO",0,4,"a",-1,0,-1,0,109,109,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0109-02",20,"Da risa ver a un soldado\nCuando sale a enamorar,\nSi se le acaba el dinero\nEcha mano a su morral.",224,9,-1,252,"EL SOLDADO",0,4,"a",-1,0,-1,0,109,109,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0109-03",20,"Si tú quieres ser soldado\nTienes que llevar dinero,\nPorque la vida que llevan\nEs peor que la de los perros.",224,9,-1,252,"EL SOLDADO",0,4,"eo",-1,0,-1,0,109,109,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0109-05",20,"Canela! Canela!\nQué gusto será\nCanela! Canela!\nLlamarse papá...",224,9,-1,252,"LOS SÁBADOS DE MANUELA",1,4,"a",9,0,-1,0,109,109,"","",77,"","","",2,0,0,[],"",""],["suspiros_amor-p0125-01",20,"Me abandonas, me abandonas,\nPorque quieres, porque quieres\nQuitar la vida, la vida,\nA quien por tí muere, muere.",224,9,-1,253,"LA TARTAMUDA",0,4,"ee",-1,0,-1,0,125,125,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0125-02",20,"¿Por qué causa, por qué causa\nMe blasonas, me blasonas?\n¿Por qué motivo, motivo\nMe abandonas, me abandonas,",224,9,-1,253,"LA TARTAMUDA",0,4,"oa",549,0,-1,0,125,125,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0125-03",20,"Esos tus ojos, tus ojos\nQue me miran, que me miran,\n¿Por qué pretenden, pretenden\nQuitar la vida, la vida?",224,9,-1,253,"LA TARTAMUDA",0,4,"ia",-1,0,-1,0,125,125,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0125-04",20,"Es tu pecho, es tu pecho\nEl puñal que hiere, hiere;\nPues no perdonas, perdonas\nA quien por tí muere, muere.",224,9,-1,253,"LA TARTAMUDA",0,4,"ee",115,0,-1,0,125,125,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-01",20,"Viva mi siá Fulanita,\nLa aborrezco, la aborrezco\nSi la gracia de su amor\nNo merezco, no merezco.",224,9,-1,253,"LA TARTAMUDA",0,4,"eo",355,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-02",20,"Yo tambien quiero... casarme\nComo todas las demas,\nCon un jóven de mi gusto,\nPor toda una eternidad.",224,9,-1,253,"LA SOLTERONA",0,4,"a",-1,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-03",20,"Si es gordo, será una estufa\nQue me ahogue de calor;\nSi es flaco, será un pescado\nSin gusto, sabor, ni olor.",224,9,-1,253,"LA SOLTERONA",0,4,"o",72,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-04",20,"Si es jóven, será un potrillo\nQue no se puede domar;\nSi es viejo, será un caballo\nQue no se podrá ensillar.",224,9,-1,253,"LA SOLTERONA",0,4,"a",21,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-05",20,"Si es alto, será jigante\nA quien no pueda mirar;\nSi es chico, será un juguete\nQue no podré respetar.",224,9,-1,253,"LA SOLTERONA",0,4,"a",21,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0126-06",20,"Si es rico, será orgulloso,\nTodo pura vanidad;\nSi es pobre, será el desprecio\nDe toda la vecindad.",224,9,-1,253,"LA SOLTERONA",0,4,"a",16,0,-1,0,126,126,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0127-01",20,"Con que, lo dicho, señores;\nNo pudiéndome casar,\nTendré que ir a vestir santos\nPor toda una eternidad.",224,9,-1,253,"LA SOLTERONA",0,4,"a",-1,0,-1,0,127,127,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0127-02",20,"Pero mejor es, señores,\nQue me quede sin casar...\nY que no me haga de un máula\nPor toda una eternidad.",224,9,-1,253,"LA SOLTERONA",0,4,"a",-1,0,-1,0,127,127,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0127-03",20,"Noche oscura, nada veo,\nPero llevo mi farol;\nPor tu puerta voi pasando\nY cantando con amor.",224,9,-1,253,"EL TORTILLERO",0,4,"o",-1,0,-1,0,127,127,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0127-04",20,"Mas, voi cantando\nCon harta pena:\n\"De rescoldo tostaitas,\nTortillas buenas.\"",224,9,-1,253,"EL TORTILLERO",6,4,"ea",-1,0,-1,0,127,127,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0127-05",20,"Bella ingrata, no respondes\nA este grito placentero,\nCuando pasa por tu casa\nPregonando el tortillero.",224,9,-1,253,"EL TORTILLERO",0,4,"eo",38,0,-1,0,127,127,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0128-01",20,"Señorita Carmen Rosa,\nVarillita de romero,\nLe suplico no se asome\nCuando pase el tortillero.",224,9,-1,253,"EL TORTILLERO",0,4,"eo",38,0,-1,0,128,128,"3","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0128-03",20,"Ya me voi a retirar\nDe este sitio placentero,\nSin que usted una compasion\nEche al pobre tortillero.",224,9,-1,253,"EL TORTILLERO",0,4,"eo",38,0,-1,0,128,128,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0128-05",20,"Soi el jóven solterito\nQue les vende verenjenas;\nComo yo no tengo dueña\nDuermo en mi cama solito.",224,9,-1,253,"EL SOLTERITO",5,4,"io",119,0,-1,0,128,128,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0128-06",20,"Abrazado con mi almohada\nLa noche se me hace dos:\nA nadie le falta Dios,\nSolo yo no tengo nada.",224,9,-1,253,"EL SOLTERITO",11,4,"aa",49,0,-1,0,128,128,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0129-01",20,"Miro a las niñas bonitas\nCuando las veo pasar\n¡Quién se pudiera casar\nCon toditas, con toditas!",224,9,-1,253,"EL SOLTERITO",11,4,"ia",258,0,-1,0,129,129,"","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0143-01",20,"Me llaman la Cantinera,\nPorque vendo buen licor,\nLos casados y solteros\nTodos me hacen el amor.",224,9,-1,254,"LA CANTINERA",0,4,"o",72,0,-1,0,143,143,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0143-03",20,"Cuando llega algun mocito\nY me pide una cerveza,\nLo saludo amablemente\nInclinando la cabeza.",224,9,-1,254,"LA CANTINERA",0,4,"ea",108,0,-1,0,143,143,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0144-02",20,"Un consejo a las muchachas\nVoi a darles por de pronto:\nSi casarse alguna quiere,\nQue se case con un tonto",224,9,-1,254,"VIVAN LOS TONTOS",0,4,"oo",555,0,-1,0,144,144,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0144-04",20,"En los tiempos que corremos\nHai mas tontos que callampas;\nY los hombres que son cuerdos\nYa no caen en la trampa.",224,9,-1,254,"VIVAN LOS TONTOS",0,4,"aa",-1,0,-1,0,144,144,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0145-02",20,"Hai algunas señoritas\nQue salen con el plumero:\nEn vez de dejarlo en casa\nLo llevan en el sombrero.",224,9,-1,254,"EL SOMBRERO DE LA MUJER",0,4,"eo",38,0,-1,0,145,145,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0145-04",20,"Cuando al teatro suelen ir,\nMas ejercen su imprudencia,\nY el que ha pagado la entrada\nPierde dinero y paciencia.",224,9,-1,254,"EL SOMBRERO DE LA MUJER",0,4,"ea",46,0,-1,0,145,145,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0146-02",20,"Yo soi la Chocolatera,\nLa que vendo chocolate,\nLa que con el molinillo\nVivo en eterno combate.",224,9,-1,254,"LA CHOCOLATERA",0,4,"ae",384,0,-1,0,146,146,"1","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0146-04",20,"Antes que amanezca el dia\nTengo todo preparado,\nY me compran chocolate\nCuantos llegan al Mercado.",224,9,-1,254,"LA CHOCOLATERA",0,4,"ao",14,0,-1,0,146,146,"2","",77,"","","",1,0,0,[],"",""],["suspiros_amor-p0147-02",20,"Gracias a Dios que ya tengo\nDos camisas que mudarme:\nUna que tengo en las tiendas\nY otra que Dios puede darme",224,9,-1,254,"LAS DOS CAMISAS",0,4,"ae",35,0,-1,0,147,147,"1","",77,"","","",6,0,0,[],"",""],["suspiros_amor-p0147-04",20,"No te creas de los hombres,\nAunque te digan: \"Te quiero;\"\nQue en volviendo las espaldas\nSi te he visto no me acuerdo.",224,9,-1,254,"LAS DOS CAMISAS",0,4,"eo",-1,0,-1,0,147,147,"2","",77,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0008-01",21,"A cantar el carnaval\ntodo el mundo se levanta\ncon tambores y guitarras\ny una buena garganta.",225,6,-1,255,"",0,4,"aa",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0008-02",21,"A causa del carnaval\ncamino de esta manera,\nsufriendo mis malas noches,\nvolviéndome calavera.",225,6,-1,255,"",0,4,"ea",44,0,-1,0,8,8,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0008-03",21,"A causa del carnaval\nchulla huevo voy a vender,\ndejando la media parte,\nla parte de mi mujer.",225,6,-1,255,"",0,4,"e",20,0,-1,0,8,8,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0008-04",21,"A causa del carnaval\nhasta mi gato vendí;\ngatito de cuatro sucres\nen real y medio vendí.",225,6,-1,255,"",0,4,"i",-1,0,-1,0,8,8,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0008-05",21,"A la una, a las dos,\na las tres de la mañana,\nse despide el carnaval\nmás de fuerza (susto) que de gana.",225,6,-1,255,"",3,4,"aa",4,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0008-06",21,"A mi carnaval le digo\nque deje esta ilusión,\npara cuando él se muera\nse vaya calvo al panteón.",225,6,-1,255,"",0,4,"o",31,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0009-01",21,"A mi lindo Carnaval\nquisiera tenerle un mes\npara dejar empeñadas\nsuegra, pelleja y mujer.",225,6,-1,255,"",0,4,"e",-1,0,-1,0,9,9,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0009-02",21,"A mi lindo Carnaval\ntres días lo he de tener,\ncon chichita y con traguito\nlo he de poder mantener.",225,6,-1,255,"",0,4,"e",20,0,-1,0,9,9,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0009-04",21,"Abra la puerta, señora,\nque le vengo a saludar;\nCarnaval es sinvergüenza,\nyo le vengo a molestar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0009-05",21,"Ahora sí cantemos todos\na este indo carnaval;\nnunca tuvo la venganza,\nsiempre ha sido un gamonal.",225,6,-1,255,"",0,4,"a",1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0009-06",21,"Al carnaval sinvergüenza\nen la cara le he de hablar;\nporque a toda casa a que entra,\nsolamente a murmurar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0009-07",21,"Al golpe del Carnaval\ntodo el mundo se levanta,\nmás conociendo la voz\ndel que suspirando canta.",225,6,-1,255,"",0,4,"aa",148,0,-1,0,9,9,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0010-01",21,"Así se hace, y así se hace\nasí se hace el carnaval,\ncon personas de buen gusto\ny de buena voluntad.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,10,10,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0010-02",21,"Ay, bandido carnaval.\nsobrino de taita Maño;\nde venir de mes en mes,\ny no, señor, de año en año.",225,6,-1,255,"",0,4,"ao",40,0,-1,0,10,10,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0010-02b",21,"Ay, qué carnaval\ntan disparatado;\ntodos toman trago\ny a mí no me han dado.",225,6,-1,255,"",0,4,"ao",-1,0,-1,0,10,10,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0010-03",21,"Cantaremos carnaval\nal uso de Magdalena;\npara unos es el gusto,\ny otros cargan con la peña.",225,6,-1,255,"",0,4,"ea",-1,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0010-04",21,"Cantaremos carnaval\ncon todita la emoción;\nguambrita, bien me comprendes\nque es tuyo mi corazón.",225,6,-1,255,"",0,4,"o",31,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0010-05",21,"Cantaremos carnaval\nya que Dios ha dado vida;\nno sea que para el otro año\nya estemos patas arriba.",225,6,-1,255,"",0,4,"ia",-1,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0010-06",21,"Canten, canten, compañeros,\nque versos no han de faltar;\nque adentro tengo una caja\ny un saco para empezar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,10,10,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0011-01",21,"Carnaval de mis amores\ncon pena te he de dejar;\ncuando tú ya te despidas\nllorando me he de quedar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,11,11,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0011-02",21,"Carnaval de mis amores,\nCarnaval, qué bien te quiero:\nno serás muy descontento\npor ti siempre yo me muero.",225,6,-1,255,"",0,4,"eo",-1,0,-1,0,11,11,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0011-03",21,"Carnaval dizque ha llegado\nDesde Guayas a Limón,\nfestejando el mundo entero\ncon maicena y cascarón.",225,6,-1,255,"",0,4,"o",31,0,-1,0,11,11,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0011-03b",21,"Carnaval dizque ha llegado,\nla fiesta más popular;\ncomo llega perfumado,\ncon gusto hemos de bailar.",225,6,-1,255,"",1,4,"a",21,0,-1,0,11,11,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0011-04",21,"Carnaval dizque ha llegado,\npara mí, pobre infeliz,\nsin tener un mediecito\npara comprar capulís.",225,6,-1,255,"",0,4,"i",58,0,-1,0,11,11,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0011-05",21,"Carnaval dizque ha llegado,\npor mi casa no ha pasado:\nchulla cuicito que tuve\nchamuscando hubiera dado.",225,6,-1,255,"",0,4,"ao",14,0,-1,0,11,11,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0011-06",21,"Carnaval dizque ha llegado,\nyo no sé cómo ni cuándo;\nyo lo he venido a encontrar\nen el pueblo de Guanando.",225,6,-1,255,"",0,4,"ao",33,0,-1,0,11,11,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0012-01",21,"Carnaval dizque ha venido,\ndomingo después de misa;\nasí mismo se despide\nel miércoles de ceniza.",225,6,-1,255,"",0,4,"ia",420,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0012-02",21,"Carnaval dizque ha venido,\npasando por San Fernando;\npensarás que no te veo\nlo que bailas coqueteando.",225,6,-1,255,"",0,4,"ao",33,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0012-03",21,"Carnaval ya dizque viene\nEchando polvo y ceniza;\nasí mismo se regresa\nlluchu pupo y sin camisa.",225,6,-1,255,"",0,4,"ia",68,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0012-04",21,"Carnaval ya dizque viene\nen busca de un nuevo amor,\ncon el dúo \"Riobambeño\",\nuna flauta y un tambor.",225,6,-1,255,"",0,4,"o",72,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0012-05",21,"Carnaval ya dizque viene\npasando por Santa Fe;\ny a causa del dulce trago\nahora no brindan café.",225,6,-1,255,"",0,4,"e",77,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0012-06",21,"Carnavalito,\ncarnavalero,\nsiendo tan pobre,\ntan funcionero.",225,6,-1,255,"",6,4,"eo",38,0,-1,0,12,12,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0012-07",21,"Carnavalito,\ncarnavalote;\nal que no juega,\ndale garrote.",225,6,-1,255,"",6,4,"oe",292,0,-1,0,12,12,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0013-01",21,"Cualquiera por carnaval\nsiquiera pela un pavito,\ny le dan, pues, preparando,\nsiquiera con un traguito.",225,6,-1,255,"",0,4,"io",119,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0013-02",21,"Cuando empieza el carnaval\nsalen las locas chiquillas\ncargadas de jeringuillas\nde abundante agua de olor.",225,6,-1,255,"",5,4,"o",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0013-03",21,"Cuando llega el carnaval\nse desborda la alegría:\nse olvidan viejos rencores\ny se baila noche y día.",225,6,-1,255,"",0,4,"ia",0,0,-1,0,13,13,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0013-04",21,"Cuando llega el carnaval\ntodos encuentran placer;\nunos cambian de camisa\ny otros cambian de mujer.",225,6,-1,255,"",0,4,"e",20,0,-1,0,13,13,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0013-05",21,"Cuando llegue el carnaval\nalegre me has de encontrar;\ncon pretexto de bailar\nsanjuanito me has de dar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0013-06",21,"Dale al carnaval con hierro,\nporque el hombre no ha de creer\nen lágrimas de mujer\nni en la renguera de perro.",225,6,-1,255,"",11,4,"eo",379,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0013-07",21,"De la costa estoy viniendo\nrozando mis arrozales,\ny ahora ya estoy por aquí\ncantando mis carnavales.",225,6,-1,255,"",3,4,"ae",26,0,-1,0,13,13,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0014-01",21,"De todos los carnavales,\nmi carnaval es mejor,\nporque mi carnaval tiene\nclavo, pimienta y olor.",225,6,-1,255,"",0,4,"o",72,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0014-02",21,"El cantar el carnaval\nno es fuerza ni obligación:\ny el estar con la familia\nnos alegra el corazón",225,6,-1,255,"",0,4,"o",31,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0014-03",21,"El carnaval está enfermo\ncon dolores de cabeza.\nY en dónde encontrar remedio?\nEn la tienda del Vinueza.",225,6,-1,255,"",0,4,"ea",108,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0014-04",21,"El carnaval ya se ha muerto,\nya lo llevan a enterrar,\ncon cuatro ceras de esperma\na las orillas del mar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,14,14,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0014-05",21,"En días de carnaval,\ntodos matan un chivito,\npero a mí no me ha tocado\nni siquiera el pajarito.",225,6,-1,255,"",0,4,"io",119,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0014-06",21,"En el mundo compartimos\nla alegría terrenal,\nporque viene para todos\nel señor don carnaval.",225,6,-1,255,"",0,4,"a",1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0014-07",21,"En una rama\ncanta el turpial;\ncanta, guambrita,\nel carnaval.",225,6,-1,255,"",6,4,"a",1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-01",21,"Entonces ya con la hembra\nse pone uno a jugar,\nechando pocos polvitos\npara poder perfumar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-02",21,"Esta tierra no es mi tierra,\n¿cuándo en mi tierra estaré?\nAusente de mis familias,\n¿qué carnaval pasaré?",225,6,-1,255,"",0,4,"e",77,0,-1,0,15,15,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0015-03",21,"Este corazón que tengo,\nyo te doy con voluntad;\nconservarás bien las señas\nde este lindo carnaval.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-04",21,"Este es mi carnavalito,\ncarnavalito chimbeño;\ncada año nos da alegría\ny hasta nos quita el sueño.",225,6,-1,255,"",0,4,"eo",138,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-05",21,"Ha llegado el carnaval\ny ahora yo pobre, qué haré,\nen quién romperé mis huevos,\nen quién desperdiciaré.",225,6,-1,255,"",3,4,"e",77,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-06",21,"Juguemos al carnaval\ncon todita la emoción;\nguambrita, bien me comprendes\nque te entrego el corazón.",225,6,-1,255,"",0,4,"o",31,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0015-07",21,"Las costumbres de mi tierra\nson bailar el carnaval\ncon la flauta y la guitarra\nfestejando el carnaval.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-01",21,"Lindo Carnaval\nque me haces gozar;\ncuando tú te vayas,\nme harás recordar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-02",21,"Los días de carnaval,\nqué linda vida se pasa;\nen pretexto de bailar,\na cualquier guambra se abraza.",225,6,-1,255,"",0,4,"aa",307,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-03",21,"Malcristiano carnaval,\nque no ha venido anunciando\npara tener preparado\ncuchi pata y maiz pelado.",225,6,-1,255,"",0,4,"ao",14,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-04",21,"Mapa carnaval,\nnada me ha dejado:\ntodos han tomado\ny a mí no me han dado.",225,6,-1,255,"",0,4,"ao",14,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-05",21,"Mentiroso, no es así;\ncarnaval es bien bonito;\nse principia de mañana\ny se acaba tempranito.",225,6,-1,255,"",0,4,"io",119,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-06",21,"Mujercita, si me chumo,\nlos días de carnaval;\ncuidarás que no me quede\ndormido en el chamanal.",225,6,-1,255,"",0,4,"a",1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0016-07",21,"No me mandes el boleto,\nque ya no me voy de viaje;\nporque el carnaval me trajo\nmujer con todo equipaje.",225,6,-1,255,"",0,4,"ae",231,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0017-01",21,"Para niños y mayores\ntrae un gesto liberal,\nporque es amigo de todos\nel señor don carnaval.",225,6,-1,255,"",0,4,"a",1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0017-02",21,"Por encima de la cresta\nde aquel monte colosal,\nya sonríe el sol naciente\nanunciando el carnaval.",225,6,-1,255,"",0,4,"a",1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0017-03",21,"¡Qué alegría, qué alegría;\nya ha llegado el carnaval!\ntodos gastan mucha plata,\npero yo no tengo un real.",225,6,-1,255,"",0,4,"a",1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0017-04",21,"Qué bonito es carnaval,\nque se ríe a carcajadas;\ndice chao a las solteras\ny se lleva a las casadas.",225,6,-1,255,"",0,4,"aa",282,0,-1,0,17,17,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0017-05",21,"Qué bonito es carnaval,\nsabiendo disimular;\nse lo coge de las patas,\nse lo mete en un costal.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,17,17,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0017-06",21,"Robando plata al marido\nfue y pagó a la autoridad;\npara que a mí me perdone\ny echar fuego al carnaval.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0017-07",21,"Señora dueña de casa,\nmate a ese pollo patojo;\nal pobre carnavalero,\nno le deje con antojo.",225,6,-1,255,"",0,4,"oo",400,0,-1,0,17,17,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0018-01",21,"Señores, ¿quieren saber\nlo que me pasó en febrero?\nCantando mis carnavales,\nme llevaron prisionero.",225,6,-1,255,"",0,4,"eo",38,0,-1,0,18,18,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0018-02",21,"Si el carnaval se muriera,\nyo le diera sepultura;\nyo cantara los responsos;\nno le diera plata al cura.",225,6,-1,255,"",0,4,"ua",17,0,-1,0,18,18,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0018-03",21,"Si el carnaval se muriera,\nyo solito le enterrara;\ndejándole en el panteón,\npor la viuda regresara-",225,6,-1,255,"",0,4,"aa",57,0,-1,0,18,18,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0018-04",21,"Si este carnaval\nte portaras bien,\nme dieras papita\ny cuyes también.",225,6,-1,255,"",0,4,"e",242,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0018-05",21,"Si lo que te digo\nte parece mal;\ncambiarás de genio\npor el carnaval.",225,6,-1,255,"",0,4,"a",1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0018-06",21,"Si me siento a descansar,\ncarnaval se ha de acabar;\nque se acabe, que se acabe,\ncosa que se ha de acabar.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0018-07",21,"Si no sabes, no te metas,\na cantar el carnaval;\nanda coge un burro viejo,\nque te enseñe a rebuznar.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,18,18,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0019-01",21,"Terminemos carnaval\na la moda de Licán;\nya han comido, ya han bebido;\nqué esperan que no se van.",225,6,-1,255,"",0,4,"a",147,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0019-02",21,"Un martes de carnaval\nun gallo, muerto de risa,\nsalió en mangas de camisa\ndel hospital general.",225,6,-1,255,"",11,4,"a",1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0019-03",21,"Una sola vez al año\nel carnaval nos visita:\ndomingo, lunes y martes,\ny el miércoles de ceniza.",225,6,-1,255,"",0,4,"ia",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0019-04",21,"Vamos todos a cantar\neste lindo carnaval;\ncon tambores y palmadas\nbailaremos sin cesar.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0019-05",21,"Ya aparece el carnaval,\ntocando su rondador;\nla mujer que le acompaña\nviene tocando el tambor.",225,6,-1,255,"",0,4,"o",72,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0019-06",21,"Ya ha llegado el Carnaval\ncon un grito de alegría;\nlindo lindo es carnaval,\nesperemos este día.",225,6,-1,255,"",1,4,"ia",0,0,-1,0,19,19,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0019-07",21,"Ya ha llegado el Carnaval\n(el lunes dieron noticia)\nel martes, su propio día,\ny el miércoles, la ceniza.",225,6,-1,255,"",0,4,"ia",-1,0,-1,0,19,19,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0020-01",21,"Ya le vengo conociendo\na la hija del carnaval:\nbuenamoza, linda ha sido,\ncapaz de pagarle un real.",225,6,-1,255,"",0,4,"a",1,0,-1,0,20,20,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0020-02",21,"Ya le vengo conociendo\nal señor don Carnaval:\nni muy viejo, ni muy joven;\nun hombre de buena edad.",225,6,-1,255,"",0,4,"a",-1,0,-1,0,20,20,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0020-03",21,"Ya le vengo enterrando\nal viejo del carnaval:\nojalá para el otro año\nno estemos todos tan mal.",225,6,-1,255,"",0,4,"a",1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0020-04",21,"Ya se acaba el carnaval\na mediados de semana;\nel que no canta ni baila\nse queda con esa gana.",225,6,-1,255,"",0,4,"aa",-1,0,-1,0,20,20,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0020-05",21,"Ya se acaba el carnaval;\nmuchachos, a trabajar,\npara el año venidero\ntener plata que gastar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,20,20,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0020-06",21,"Ya se muere el carnaval,\nya lo llevan a enterrar;\npara todos era padre;\ntodos debemos llorar.",225,6,-1,255,"",0,4,"a",21,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0020-07",21,"Yo me acuerdo de otros tiempos,\nCarnaval de mis amores,\nse han tenido grandes gustos\ny amargas decepciones.",225,6,-1,255,"",0,4,"oe",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-01",21,"Yo no me caso en carnaval,\nporque tu mama no deja;\nes un demonio la vieja,\nla vieja cara de oveja.",225,6,-1,255,"",0,4,"ea",165,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-02",21,"A ese lado del río\ntengo sembrado un cabuyo;\ntengo que pasar a ver\nqué tal amor es el tuyo.",225,6,-1,256,"",0,4,"uo",78,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-03",21,"A la muerte llamo a gritos.\nmuerte, no quieres venir;\nparece que hasta a la muerte\nle gusta verme sufrir.",225,6,-1,256,"",0,4,"i",157,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-04",21,"A la orilla de un estero\nlloraba un garrapatero:\nno lloraba por ser pobre\nsino por ser forastero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-05",21,"A la redondez del mundo\ntodo es una falsedad;\ntodo el amor es mentira,\nsolo la muerte es verdad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0021-06",21,"A la una nací yo,\na las dos me bauticé,\na las tres supe querer\ny a las cuatro me casé.",225,6,-1,256,"",0,4,"e",-1,0,-1,0,21,21,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0022-01",21,"A la vecina del frente\nse le ha muerto su marido,\ny por temor al difunto\nse viene a dormir conmigo.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,22,22,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0022-02",21,"A la vieja de mi suegra,\nla he de enterrar boca abajo,\npor si se quiere salir,\nque se vaya más abajo.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,22,22,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0022-03",21,"A la vieja de mi suegra,\npan con queso le voy dando,\nque a la chulla hija que tiene\nme la mande regalando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,22,22,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0022-04",21,"A las guayabas maduras\nse les chupan las pepitas;\na las muchachas bonitas\nse les chupan las trompitas.",225,6,-1,256,"",0,4,"ia",258,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0022-05",21,"A mi corazón le digo\nque sufra y tenga paciencia;\ny el infeliz me contesta:\nya no tengo resistencia.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,22,22,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0022-06",21,"A mí me dicen casate;\ncasarme, ni Dios permita;\nporque yo no me puedo ir\nde al lado de mi mamita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,22,22,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0022-07",21,"A mí me llaman el mudo\nporque quiero a una casada;\nel marido la mantiene,\ny a mí no me cuesta nada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-01",21,"A mí me llaman el tiro,\ny a mi mujer la escopeta,\na mis hijos, los cartuchos\ny a mi suegra la baqueta.",225,6,-1,256,"",0,4,"ea",200,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-02",21,"A mí me llaman soltero\nporque quiero a una soltera;\ny a quién no le va a gustar\ntener una cocinera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-03",21,"A mí no me gusta el vino,\nni tampoco la cerveza;\nninguna cosa es más buena\nque el amor, cuando se empieza.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,23,23,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0023-04",21,"A mi suegra por bonita\nen el bolsillo tuviera,\ny cada vez que le saque\nun besito yo le diera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-05",21,"A mi traguito lo quiero,\na mi traguito lo adoro;\ncon él yo tengo consuelo\ny me alegro el corazón.",225,6,-1,256,"",5,4,"o",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-06",21,"A un alto pino subí\na ver si te divisaba;\ncomo el pino era muy tierno\nde verme llorar, lloraba.",225,6,-1,256,"",0,4,"aa",28,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0023-07",21,"Abran puertas y ventanas,\ncortinas y pabellones,\nporque te vienen a ver\ntus amantes corazones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0024-01",21,"Agradezcamos la suerte\ny a los ojos de papá,\nque han salido buenos mozos\npor la boca de mamá.",225,6,-1,256,"",0,4,"a",9,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0024-02",21,"Agua blanca, cristalina,\nagüita de yo beber,\nno vine tanto por agua\nsino por venirte a ver.",225,6,-1,256,"",0,4,"e",20,0,-1,0,24,24,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0024-03",21,"Aguacate sin venita,\nchirimoya sin pepita\ncómo no te he de querer,\nbonita tentacioncita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0024-04",21,"Ahí arriba en ese cielo\ntengo una casita de oro,\ndonde guardo mis suspiros\ny las lágrimas que lloro.",225,6,-1,256,"",0,4,"oo",85,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0024-05",21,"Ahora que estamos reunidos,\nformemos una mentira:\nque una pulga fue volando\ncon cien arrobas encima.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0024-06",21,"Ahora sí que estoy con gusto,\nahora sí que no me he de ir,\nahora que estoy en tu casa,\naquí yo pienso vivir.",225,6,-1,256,"",0,4,"i",157,0,-1,0,24,24,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0024-07",21,"Ahora sí que estoy contento\ncon mi guambrita a mi lado,\npara entregarle con gusto\neste amor desesperado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,24,24,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0025-01",21,"Ahora sí, señores diablos,\nel infierno se acabó;\nya no nos condenaremos\nni mi guambrita, ni yo.",225,6,-1,256,"",0,4,"o",2,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0025-02",21,"Al agua me he de botar\nhasta dar con el pescuezo;\npara morir como el mono\ncon el dilindango tieso.",225,6,-1,256,"",0,4,"eo",48,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0025-03",21,"Al cielo dizque te vas\na mí solito dejando;\nyo también he de llegar\ndescansando, descansando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0025-04",21,"Al cielo llegan mis quejas;\nson señales de morir;\nmi cuerpo no es poderoso\npara sin alma vivir.",225,6,-1,256,"",0,4,"i",157,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0025-05",21,"Al ladito de mi casa\ntengo una mata de arroz;\npara darte de repente\ncuando me case con vos.",225,6,-1,256,"",0,4,"o",87,0,-1,0,25,25,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0025-06",21,"Al ladito de mi casa\ntengo una matita de higo,\npara brindarte poquito\ncuando me case contigo.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,25,25,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0025-07",21,"Al otro lado del río\nvi una vaquita preñada;\ny yo que me fijo bien,\nhabía sido mi cuñada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,25,25,"","",0,"","","",15,0,0,[],"",""],["ortiz_ecuador-p0026-01",21,"Al otro lado del río\nvide dos toros peleando,\nel uno era colorado,\nel otro era mi cuñado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,26,26,"","",0,"","","",15,0,0,[],"",""],["ortiz_ecuador-p0026-02",21,"Al otro lado del río\nvide un sapo con calzones\nabrazado de la sapa\ndándole satisfacciones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,26,26,"","",0,"","","",15,0,0,[],"",""],["ortiz_ecuador-p0026-03",21,"Al pasar por tu ventana\nme tirastes una flor;\nla próxima vez que pase:\nsin maceta, por favor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,26,26,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0026-04",21,"Al subir las escaleras\nte vi las ligas azules;\nmás arribita yo vi:\nsábado, domingo y lunes.",225,6,-1,256,"",0,4,"ue",-1,0,-1,0,26,26,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0026-05",21,"Al zapatero del barrio,\nal hacer un par de botas,\nse le resbaló el cuchillo\ny se cortó las pelotas.",225,6,-1,256,"",0,4,"oa",727,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0026-06",21,"Alhaja corazoncito,\nanoche con quién dormiste;\nun rato estabas conmigo\ny con otro amaneciste.",225,6,-1,256,"",0,4,"ie",153,0,-1,0,26,26,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0026-07",21,"Alhaja corazoncito\ncomo taja de sandía;\nno pierdo las esperanzas,\nque algún día serás mía.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,26,26,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0027-01",21,"Alhaja guambra,\nbien manabita;\na vos te quiero\nmás que a mamita.",225,6,-1,256,"",6,4,"ia",50,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-02",21,"Alhaja guambra\nde finos lentes,\nlabios rosados,\npero sin dientes.",225,6,-1,256,"",6,4,"ee",252,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-03",21,"Alhaja guambra\nde Gualanday,\nvos, ca, con guagua,\nyo, ca, ñañay.",225,6,-1,256,"",6,4,"a",469,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-04",21,"Alhaja guambra\nde Palictagua;\npara el otro año\nya tienes guagua.",225,6,-1,256,"",6,4,"aa",383,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-05",21,"Alhaja guambra\nde Pelileo;\nsi no te cuidas\nyo te pateo.",225,6,-1,256,"",6,4,"eo",66,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-06",21,"Alhaja guambra\nde San Vicente,\nvos, ca, bandida,\nyo, ca, inocente.",225,6,-1,256,"",6,4,"ee",15,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0027-07",21,"Alhaja guambra\nde Sigsiviche,\ncuando te agarre\nte hago ceviche.",225,6,-1,256,"",6,4,"ie",721,0,-1,0,27,27,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0028-01",21,"Alhaja guambra\nde suéter plomo,\nsi quieres plata,\nagacha el lomo.",225,6,-1,256,"",6,4,"oo",349,0,-1,0,28,28,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0028-02",21,"Alhaja guambra,\nla de la loma,\ncon vos me caso,\naunque no coma.",225,6,-1,256,"",6,4,"oa",86,0,-1,0,28,28,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0028-03",21,"Alhaja guambra\nla riobambeña,\nsal a la loma\ny hazme una seña.",225,6,-1,256,"",6,4,"ea",291,0,-1,0,28,28,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0028-04",21,"Alhaja guambra\nque Dios me ha dado;\nplata me cuesta,\nno es regalado.",225,6,-1,256,"",6,4,"ao",14,0,-1,0,28,28,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0028-05",21,"Alhaja guambrita\nde pelo dorado;\ndi por qué tan pronto\ntú me has olvidado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0028-06",21,"Allá arriba de ese cerro\ntengo un pozo de agua clara\ndonde se baña mi suegra\nen vino y agua rosada.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0028-07",21,"Allá arriba en una loma\nse paseaba un toro mocho;\ny una vieja lo laceaba\ncon las barbas del bizcocho.",225,6,-1,256,"",3,4,"oo",424,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0029-01",21,"Allá en la loma\nbaila una tuna,\nchola bandida,\nmoza de runa.",225,6,-1,256,"",6,4,"ua",56,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0029-02",21,"Allá viene el diablo\nen una batea;\nviene preguntando\npor la Dorotea.",225,6,-1,256,"",0,4,"ea",54,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0029-03",21,"Ama mía, señorita,\nusted ca plata tendría;\nyo para quererle mucho,\nusted ca bruja sería.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,29,29,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0029-04",21,"Ama mía, señorita,\nyo seré su huasicama,\npero con la condición\nque he de dormir en su cama.",225,6,-1,256,"",0,4,"aa",90,0,-1,0,29,29,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0029-05",21,"Amanece el día,\nya asoma la aurora;\nsoy hombre casado;\nsuélteme, señora.",225,6,-1,256,"",0,4,"oa",107,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0029-06",21,"Amor que tanto te quiero,\nno sé qué pago darás.\nMe querrás hasta la muerte\no de mí te olvidarás.",225,6,-1,256,"",0,4,"a",51,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0029-07",21,"Amorcito, qué querís,\nque tanto me perseguís;\npor dondequiera que voy\nal encuentro me salís.",225,6,-1,256,"",0,4,"i",58,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0030-01",21,"Anda, dichosa mujer,\nque alegre vas caminando;\ny no yo, pobre infeliz,\nen este mundo penando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0030-02",21,"Anda, guambra carishina,\namiga de los soldados;\nsi tú te metes a sapa,\nte han de dar por ambos lados.",225,6,-1,256,"",0,4,"ao",18,0,-1,0,30,30,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0030-03",21,"Anda, guambra carishina,\namiga de los varones;\nespérate que algún día\nyo te haré poner calzones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,30,30,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0030-04",21,"Anda, ingrata, que me debes\nmás de doscientos suspiros,\ny si en algo me has pagado,\npreséntame los recibos.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0030-05",21,"Anillito de oro fino,\nhecho del mejor platero,\npara darle a mi guambrita\nen prueba de amor primero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,30,30,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0030-06",21,"Anillito de oro fino,\nprincipio de mi fortuna;\nyo también te acompañé\ncomo lucero a la luna.",225,6,-1,256,"",0,4,"ua",56,0,-1,0,30,30,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0030-07",21,"Anillito de oro puro,\npasado por dos punteros;\nno tengas pena, negrita,\nque los dos somos solteros.",225,6,-1,256,"",0,4,"eo",22,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0031-01",21,"Ánimo, que canta el gallo;\nánimo, que amaneció;\nánimo, que ya consigo\nlo que otro no consiguió.",225,6,-1,256,"",0,4,"o",2,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0031-02",21,"Anoche estaba soñando\nque tu boquita besaba\ny me desperté llorando,\nporque a mi lado no estabas.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,31,31,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0031-03",21,"Anoche me fui a tu casa\ncobijado mi frazada;\nsalió tu mama y me dijo:\nmi hija está desocupada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0031-04",21,"Anoche me fui por verte,\ncargado chulla cobija;\nsalió tu mama y me dijo:\nentra, dormirás con mi hija.",225,6,-1,256,"",0,4,"ia",219,0,-1,0,31,31,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0031-05",21,"Anoche me fui por verte,\ndetrasito de un cabuyo;\nsalió tu mama y me dijo:\ntodo lo de mi hija es tuyo.",225,6,-1,256,"",0,4,"uo",78,0,-1,0,31,31,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0031-06",21,"Anoche me fui por verte\ny el perro me hizo correr;\nsi el perro tuvo la culpa,\nno le darás de comer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,31,31,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0031-07",21,"Anoche me fui por verte\ny me siguieron los perros;\nquise coger una piedra\npero me embarré los dedos.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,31,31,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0032-01",21,"Anoche me fui por verte,\ny tú te estabas bañando;\ny lo que quería ver\nte estabas enjabonando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,32,32,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0032-02",21,"Anoche soñé un sueñito,\nque me moría de risa;\nque hincadito de rodillas\nyo te alzaba la camisa.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0032-03",21,"Anoche vine por verte\ny te encontré dormidita;\npor no hacerte despertar,\nme acosté con tu hermanita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0032-04",21,"Aquí está el guambra Marcelo\nla flor de la manzanilla;\nanoche cayó sereno,\nretoñó una maravilla.",225,6,-1,256,"",0,4,"ia",162,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0032-05",21,"Aquí está mi corazón\nen cuatro partes partido;\nen esa sangre verás\nel amor que te he tenido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,32,32,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0032-06",21,"Arbolito de romero,\nnacido en el mes de enero;\ncómo quieres que te olvide,\nsi tú eres mi amor primero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0032-07",21,"Arbolito, sauce verde,\nhermano del olivar;\naunque tengas tres o cuatro\nde mí no te has de olvidar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,32,32,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0033-01",21,"Arrayán de la quebrada\nyo te mandaré a cortar,\nque no sirvas de alcahuete\nde las que van a lavar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0033-02",21,"Así es, así es\nel cura de San Andrés:\nse viste por la cabeza,\nse desviste por los pies.",225,6,-1,256,"",3,4,"e",218,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0033-03",21,"Asiqui-siqui,\nAsiqui-saca:\ndurmiendo juntos\nguagua se saca.",225,6,-1,256,"",6,4,"aa",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0033-04",21,"Atrasito de mi casa\nse ha formado una laguna,\ndonde lloran los solteros\nsin esperanza ninguna.",225,6,-1,256,"",0,4,"ua",56,0,-1,0,33,33,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0033-05",21,"Atrasito de mi casa\nsembré limas y limones,\npara cosechar los dos,\nuniendo los corazones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,33,33,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0033-06",21,"Atrasito de mi casa\nsilba y canta la torcaza\ny en el canto va diciendo:\nqué pendejo el que se casa.",225,6,-1,256,"",0,4,"aa",123,0,-1,0,33,33,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0033-07",21,"Atrasito de mi casa\ntengo un árbol de corozo;\ndonde canta el gallo grande,\nno canta ningún mocoso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,33,33,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0034-01",21,"Atrasito de mi casa\ntengo un árbol de eucalipto,\ny cada vez que me acerco\nse me para el pajarito.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,34,34,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0034-02",21,"Atrasito de mi casa\ntengo una matita de habas,\ndonde pasan los solteros\nregando mocos y babas.",225,6,-1,256,"",0,4,"aa",204,0,-1,0,34,34,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0034-03",21,"Ay, algún día entre sollozos,\ny entre lágrimas de amor;\nvendrás a mí pidiendo amor,\nay, cuando ya no exista yo.",225,6,-1,256,"",0,4,"o",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0034-04",21,"Ay de mí, ay de vos,\nen una cárcel los dos;\ncomidos o no comidos,\npero juntitos los dos.",225,6,-1,256,"",0,4,"o",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0034-05",21,"Ay, los hombres de este tiempo\nson como las hojas secas;\ncuando dan para el arroz,\nno dan para la manteca.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0034-06",21,"Ay, mi burro blanco,\ncargado de arroz;\npor el rebuznado\nse parece a vos.",225,6,-1,256,"",0,4,"o",87,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0034-07",21,"Ay, mi guambrita,\nzapato rojo;\ndame un besito,\nque tengo antojo.",225,6,-1,256,"",6,4,"oo",400,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0035-01",21,"Ay, yernito de mi vida,\npatitas de mirlo tierno;\nhasta cuándo te veré\nrevolcando en el infierno.",225,6,-1,256,"",0,4,"eo",225,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0035-02",21,"Ayayay, gritaba el puerco\ncuando le estaban capando;\ny la puerca le decía:\nlo mejor te están cortando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0035-03",21,"Ayer me fui a confesar\ncon el cura de Guaranda;\nme mandó de penitencia\nque duerma con esa guambra.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,35,35,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0035-04",21,"Ayer pasé por tu casa\ny hallé la casa sin gente;\nlas gallinas se rieron\ny el gallo arrugó la frente.",225,6,-1,256,"",0,4,"ee",15,0,-1,0,35,35,"","",0,"","","",10,0,0,[],"",""],["ortiz_ecuador-p0035-05",21,"Ayer te mandé una carta\nescrita en hojas de pera.\nManda la contestación,\nque mi amor se desespera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,35,35,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0035-06",21,"Bien dijo el rey Salomón\nen sus décimas cantando:\nel rabo que quiere beta\nsolito la anda buscando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0035-07",21,"Blanca Rosa de Castilla,\nblanca espumilla del mar,\naunque impida tu familia\nen tu pecho he de reinar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,35,35,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0036-01",21,"Blanquita tienes por nombre,\nbonito nombre tenís;\na cómo vendes las onzas\nde la gracia que tenís.",225,6,-1,256,"",0,4,"i",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-02",21,"Bolívar con su espada\nlibertó cinco naciones;\ny vos, con tus lindos ojos,\ncautivas los corazones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-03",21,"Bonita casa de teja\ncon pilares de ozogoche;\ndisculpará, comadrita\nla voz y la mala noche.",225,6,-1,256,"",0,4,"oe",337,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-04",21,"Bonita casa redonda.\nmás bonita el armazón,\nbonita la que está dentro,\ndueña de mi corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-05",21,"Bonita coloradita,\ncolorcito de sandía;\nno pierdo las esperanzas,\nque algún día serás mía.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-06",21,"Bonita esta casa grande,\npero tiene una gotera:\nseñora, por qué padece\nteniendo una hija soltera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0036-07",21,"Bonita flor de limón,\nflorcita de mi ilusión;\narrancándote pusiera\ndentro de mi corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0037-01",21,"Bonita flor de romero,\nnacida al amanecer;\naunque me cueste la vida\nmi esposa tendrás que ser.",225,6,-1,256,"",0,4,"e",20,0,-1,0,37,37,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0037-02",21,"Bonita flor de romero,\nsembrada en el mes de enero;\ncómo no te he de querer,\nsi tú eres mi amor primero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,37,37,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0037-03",21,"Bonita guambra,\ncalzón de cuero,\npor tu sombrero\nme muero yo.",225,6,-1,256,"",6,4,"o",-1,0,-1,0,37,37,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0037-04",21,"Bonita guambra\nde labios rojos;\ndame un besito\nque tengo antojo.",225,6,-1,256,"",6,4,"oo",-1,0,-1,0,37,37,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0037-06",21,"Bonita la casa grande,\nbonita la posición,\nbonita la que está dentro,\ndueña de mi corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0037-07",21,"Bonita la palomita\nque vuela de rama en rama;\nregálame una plumita\npara abrigo de mi cama.",225,6,-1,256,"",1,4,"aa",90,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0038-01",21,"Bonita, mucho te quiero,\npero más quiero a tus padres,\nque te hicieron tan bonita\npara alivio de mis males.",225,6,-1,256,"",0,4,"ae",-1,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0038-02",21,"Bonito es tocar guitarra\nsabiendo templar clavijas;\nbonita vida se pasa\ndebajo de las cobijas.",225,6,-1,256,"",0,4,"ia",635,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0038-03",21,"Bonitos ojitos tienes,\nbonito modo de ver;\nsi todo me cae en gracia,\ncómo no te he querer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,38,38,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0038-04",21,"Bonitos ojitos tienes\ndebajo de esas dos cejas\npero si tú no los dejas\nni siquiera parpadear.",225,6,-1,256,"",5,4,"a",-1,0,-1,0,38,38,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0038-05",21,"Bonitos ojitos tienes\nen esa cara morena;\nte quiero y te he de querer\naunque me muera de pena.",225,6,-1,256,"",0,4,"ea",59,0,-1,0,38,38,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0038-06",21,"Bonitos ojitos tienes,\nlas pestañas de dublé;\nuna esperanza sí tengo:\nme casaré con usté.",225,6,-1,256,"",0,4,"e",77,0,-1,0,38,38,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0038-07",21,"Bonitos ojitos tienes,\npor eso te dicen la ojona,\nporque juegas con los hombres\nte llaman la coquetona.",225,6,-1,256,"",0,4,"oa",7,0,-1,0,38,38,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0039-01",21,"Bonitos ojos que tienes\ncomo flor de capulí;\nsi no me quieren tus padres,\ntendrás que llorar por mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,39,39,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0039-02",21,"Buenas noches, comadrita;\nbuenas noches, su mercé;\nya vengo por lo que dijo:\nque me muero por usté.",225,6,-1,256,"",0,4,"e",77,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0039-03",21,"Buenas noches ten, cielito,\nbello clavel nacarado;\nvengo a ver si he de ser tuyo\no he de salir desairado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0039-04",21,"Buenos gustos he pasado;\nbuenos trabajos también;\nen cama buena he dormido;\ny en basureros también.",225,6,-1,256,"",0,4,"e",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0039-05",21,"Calla, calla, mentiroso,\nmintiendo no más estás;\nyo soy el más desgraciado\nentre los hijos de Adán.",225,6,-1,256,"",0,4,"a",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0039-06",21,"Calle arriba, calle abajo,\ntodo me cuesta trabajo;\npor querer a la de arriba\nse ha enojado la de abajo.",225,6,-1,256,"",0,4,"ao",168,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0039-07",21,"Camisa blanca,\ncuello virado,\npantalón negro\ny enamorado.",225,6,-1,256,"",6,4,"ao",14,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-01",21,"Canta, canta el pajarillo\nencima de su limón;\nanda, dile que no cante,\nque me parte el corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-02",21,"Canta, canta, güiracchuro\nencima de una solera;\nyo también quiero cantar\nencima de una soltera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-03",21,"Cantando me he de morir\nya que llorando nací,\npues las penas de este mundo\nno son todas para mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-04",21,"Cantaremos, bailaremos\ny al muerto lo enterraremos;\npero a la viudita todos\ncon fervor le adoraremos.",225,6,-1,256,"",0,4,"eo",127,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-06",21,"Cásate, casamentero (a);\ncasado (a) te quiero ver;\nlos gustitos de soltero (a)\nya no has de poder tener.",225,6,-1,256,"",1,4,"e",20,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0040-07",21,"Casi casi me quisiste,\ncasi casi te he querido;\nsi no es por el casi casi,\ncasi me caso contigo.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0041-01",21,"Chulla camisa que tengo,\nsin cuello ni delantera;\npor eso, no necesito\nni jabón, ni lavandera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0041-02",21,"Chulla guambrita que tuve\nlos guardas me van quitando;\nno les pude reclamar,\nporque era de contrabando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0041-03",21,"Chulla mujercita tengo;\ndizque es bueno tener par,\nporque si muere la una,\nla otra queda en su lugar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0041-04",21,"Cinco sentidos tenemos;\ncinco sentidos usamos;\ncinco sentidos perdemos\ncuando nos enamoramos.",225,6,-1,256,"",1,4,"ao",116,0,-1,0,41,41,"","",0,"frenk_t2","","",8,0,0,[],"",""],["ortiz_ecuador-p0041-05",21,"Clavelito colorado\nque ayer tarde te cogí;\nla mata quedó llorando\ncomo yo lloro por ti.",225,6,-1,256,"",0,4,"i",23,0,-1,0,41,41,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0041-06",21,"Comienza mi sufrimiento,\ncomienza mi padecer;\nmis ojos tienen la culpa\nque te miraron, mujer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0041-07",21,"Cómo dicen que no se goza\ncon gusto lo que es ajeno;\nsabiendo disimular\nse goza mejor que el dueño.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-01",21,"Cómo quieres que me sane,\ncon remedios desiguales,\nen tus manitos teniendo\nel remedio de mis males.",225,6,-1,256,"",0,4,"ae",26,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-02",21,"Cómo quieres que una luz\nalumbre dos aposentos;\ncómo puedes, pues, tener\ndos corazones contentos.",225,6,-1,256,"",0,4,"eo",234,0,-1,0,42,42,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0042-03",21,"Compadre, tómese un trago,\ny verá como las penas volando se van,\nporque el trago es bueno,\nmás bueno que el pan.",225,6,-1,256,"",3,4,"a",147,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-04",21,"Compré saraza\nme salió gasa\ncompré por fina\nme salió falsa.",225,6,-1,256,"",6,4,"aa",-1,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-05",21,"Cómpreme, que estoy vendiendo,\namores que me han sobrado:\ncomo tengo demasiado,\nfiadito estoy dando.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-06",21,"Con el tiempo y la distancia\nme llegarás a olvidar;\nescuchando estas mis quejas\nme tendrás que recordar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0042-07",21,"Con el trago tengo iras,\nque no llena la barriga;\nyo le mando para abajo,\ny él se vuelve para arriba.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0043-01",21,"Con este mi genio alegre\ncuatro y cinco he de tener;\npuedo ajustar la docena,\nsin contar con mi mujer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0043-02",21,"Con esto no digo más;\nmañana diré otro poco;\nporque ha de pensar la gente\nque este guambra se ha hecho loco.",225,6,-1,256,"",0,4,"oo",152,0,-1,0,43,43,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0043-03",21,"Con los huesos de mi suegra\nvoy a hacer una escalera,\npara subir a su tumba\ny patear su calavera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,43,43,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0043-04",21,"Con razón o sin razón,\nquerida negra del alma:\nla vida nos tiene así\nquerida negra del alma.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0043-05",21,"Con traguito y con chichita,\nasí hemos de festejar;\ncon talquito y con carioca\ntambién hemos de jugar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0043-06",21,"Coquetas son estas tontas\nque dan a torcer el brazo;\nyo no soy de los que gasto\nmi pólvora en gallinazo.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0043-07",21,"Corazón abandonado,\nno desprecies mi cariño;\nven a mi pecho a rendir\nun amor como de niño.",225,6,-1,256,"",0,4,"io",176,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-01",21,"Cuál rico te ofrecería\ncasa de teja en Riobamba;\nyo, pobrecito, te ofrezco\nlas playas de Cajabamba.",225,6,-1,256,"",0,4,"aa",728,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-02",21,"Cualquiera quiere a cualquiera\npor interés de algún fruto;\npero yo por este bruto\nni siquiera, ni siquiera.",225,6,-1,256,"",11,4,"ea",44,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-03",21,"Cuando el pobre pone un poncho,\nel rico queda admirado;\nse hace loco preguntando\nsi es comprado o es robado.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-04",21,"Cuando era soltero\nquería casarme:\nahora, de casado,\nquiero divorciarme.",225,6,-1,256,"",0,4,"ae",35,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-05",21,"Cuando esté el río crecido\nal agua me he de botar;\na ver si en el agua encuentro\nremedio para olvidar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-06",21,"Cuando la esperanza muere,\nno muere el alma con ella:\nel rosal queda sin rosas,\npero las espinas quedan.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0044-07",21,"Cuando mates tu gallina\nno me darás la costilla;\ndarásme lo que me gusta:\nla pierna y la rabadilla.",225,6,-1,256,"",0,4,"ia",162,0,-1,0,44,44,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-01",21,"Cuando me acuerdo, me acuerdo;\ncuando me olvido, me olvido;\nguambrita, si no me quieres,\nno me echarás al olvido.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-02",21,"Cuando me vaya, cuando me ausente,\ntendrás presente de no llorar;\nporque tu llanto sirve de espanto,\ncapaz de a un muerto resucitar.",225,6,-1,256,"",3,4,"a",21,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-03",21,"Cuando paso mala noche,\nlas piedras sirven de cama;\nlas vereditas de almohada\ny el sereno, sobrecama.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-04",21,"Cuando salí de mi casa,\nde nadie me despedí;\nsolo de una hojita verde\nque se cayó sobre mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-05",21,"Cuando se muera mi suegra\nla he de enterrar boca abajo,\npor si se quiere salir,\nque se vaya más abajo.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,45,45,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0045-06",21,"Cuando suena la guitarra\nal frente de tu balcón,\nmi amor es el que te canta,\nporque tú eres mi ilusión.",225,6,-1,256,"",0,4,"o",31,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0045-07",21,"Cuando te vayas a misa,\nmirarás para el panteón,\nrezarás un padrenuestro\nde pena o de compasión.",225,6,-1,256,"",0,4,"o",31,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0046-01",21,"Cuando un blanco está comiendo\ncon un negro en compañía,\nel blanco le debe al negro,\no es del negro la comida.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,46,46,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0046-02",21,"Cuando un viejo pida un beso,\nno se lo vayas a dar;\nporque los besos de un viejo\nson como huevo sin sal.",225,6,-1,256,"",0,4,"a",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0046-03",21,"Cuando va mi guambra a misa,\nla iglesia se resplandece,\nhasta la hierba que pisa,\nsi está seca, reverdece.",225,6,-1,256,"",1,4,"ee",64,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0046-04",21,"Cuando vengo no más vengo;\nya sabrás a lo que vengo;\na darte mi corazón,\nque es lo único que tengo.",225,6,-1,256,"",0,4,"eo",124,0,-1,0,46,46,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0046-05",21,"Cuando yo era chiquitita\nme engañaban con las flores;\nahora que soy grandecita\nme engañan con los amores.",225,6,-1,256,"",1,4,"oe",5,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0046-06",21,"Cuando yo era chiquitito,\nlloraba por queso tierno;\ny ahora que soy grandecito\nme muero por ser su yerno.",225,6,-1,256,"",3,4,"eo",225,0,-1,0,46,46,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0046-07",21,"Cuando yo era chiquitito,\nlloraba por un helado;\nahora que soy grandecito,\nlloro por enamorado.",225,6,-1,256,"",1,4,"ao",14,0,-1,0,46,46,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0047-01",21,"Cuando yo era chiquitito\nlloraba por una flor,\nahora que soy grandecito\nyo lloro por un amor.",225,6,-1,256,"",1,4,"o",72,0,-1,0,47,47,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0047-02",21,"Cuando yo era chiquitito,\nme gustaba queso tierno;\ny ahora que soy grandecito\nme muero por ser su yerno.",225,6,-1,256,"",3,4,"eo",225,0,-1,0,47,47,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0047-03",21,"Cuando yo era chiquitito,\ntodos me querían besar;\ny ahora que soy grandecito,\nni pidiendo quieren dar.",225,6,-1,256,"",3,4,"a",21,0,-1,0,47,47,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0047-04",21,"Cuando yo era chiquitito,\ntomaba leche en botella;\ntomaba chicha y ahora que soy grandecito,\nme gusta mujer doncella.",225,6,-1,256,"",3,4,"ea",6,0,-1,0,47,47,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0047-05",21,"Cuando yo era soltero\ncomía cuyes asados;\ny ahora que soy casado,\nni asados ni chamuscados.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0047-06",21,"Cuando yo me esté muriendo,\nsiéntate a mi cabecera;\nroza tu boca a la mía\ny evita que yo me muera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,47,47,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0047-07",21,"Cuatro calles vengo andando;\npasé por el callejón;\nlas mujeres que me amen,\nque me den un pantalón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,47,47,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0048-01",21,"Cuatro, cinco corazones\nte los diera, si pudiera;\npero el chullita que tengo\ndispónelo como quieras.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,48,48,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0048-02",21,"Cuchillo, por qué te doblas,\nsi eres del mejor acero;\nasí se doblan los hombres\ncuando les falta dinero..",225,6,-1,256,"",0,4,"eo",38,0,-1,0,48,48,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0048-03",21,"De dos amores que tengo,\nme dicen que deje el uno;\ncomo soy tan amoroso,\nno puedo dejar ninguno.",225,6,-1,256,"",0,4,"uo",230,0,-1,0,48,48,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0048-04",21,"De ese par que están bailando,\nsi me dieran a escoger;\nyo, como más inocente,\nescogiera a la mujer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,48,48,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0048-05",21,"De esta banda a la otra banda\nvoy a tender un gran puente,\npara que pase mi suegra\ncon su churito en la frente.",225,6,-1,256,"",0,4,"ee",15,0,-1,0,48,48,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0048-06",21,"De esta calle para arriba\ndizque me juran matar,\ncuál será ese valeroso,\nque me deje confesar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,48,48,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0048-07",21,"De esta calle para arriba\nvoy a mandar a huequear,\npara que caiga mi suegra\ncuando me siga a pegar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,48,48,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0049-01",21,"De la costa estoy llegando\ncon naranjas y limones\na buscar guambras bonitas\ny robar los corazones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,49,49,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0049-02",21,"De la lengua de mi suegra,\nsabiéndola recortar,\nsalen cincha, gurupera\ny sillón para montar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0049-03",21,"De la peña brota el agua;\nde la manzana una flor;\nen los ojos te conozco\nque no me tienes amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0049-04",21,"De la peña vierte el agua;\nde los páramos el viento;\nde tu corazón y el mío\nnacieron los pensamientos.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,49,49,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0049-05",21,"De la pila vierte el agua,\nde la manzana una flor;\nen la cara te conozco\nque no me tienes amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0049-06",21,"De las peñas vierte el agua;\ndel agua brotan brocales;\nde los pechos de las guambras\nbrotan flores a raudales.",225,6,-1,256,"",0,4,"ae",26,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0049-07",21,"De mi vida dizque me hablan,\nde mi vida qué han de hablar;\nbien pudiera de mi vida\nhacer bandera y marchar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0050-01",21,"De por arriba yo vengo,\npara abajo me estoy yendo;\ndiciendo no más estoy,\nacá mismo estoy viniendo.",225,6,-1,256,"",0,4,"eo",52,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0050-02",21,"De tantas guambras\nque yo tenía,\nal canchis-canchis\nde noche y día.",225,6,-1,256,"",6,4,"ia",0,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0050-03",21,"De todos los animales\nyo quisiera ser el gato,\npara sacar las uñitas\ny agarrar el garabato.",225,6,-1,256,"",0,4,"ao",19,0,-1,0,50,50,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0050-04",21,"De todos los animales\nyo quisiera ser gorrión,\npara sentarme en tu pecho\ny sacarte el corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,50,50,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0050-05",21,"De todos los animales\nyo quisiera ser el zorro;\npara llevarme a la polla\ny dejar el pollo solo.",225,6,-1,256,"",0,4,"oo",-1,0,-1,0,50,50,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0050-06",21,"De todos los animales\nyo quisiera ser la araña,\npara subir por tus piernas\na conocer la montaña.",225,6,-1,256,"",0,4,"aa",213,0,-1,0,50,50,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0050-07",21,"De un palazo que te di\nlas costillas te rompí;\nese hueso para otro,\nya no sirve para mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0051-01",21,"Decías que me querías,\nque me querías decías;\ny en tu corazón tenías\notro con quien me ofendías.",225,6,-1,256,"",0,4,"ia",214,0,-1,0,51,51,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0051-02",21,"Decías que tú me amabas\ncomo ser yo tu marido;\nya ves cómo me engañabas,\notro ha sido tu elegido.",225,6,-1,256,"",1,4,"io",101,0,-1,0,51,51,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0051-03",21,"Del tronco nace una rama\ny de la rama, el ciprés;\nlas madres crían sus hijos,\nsin saber para quién es.",225,6,-1,256,"",0,4,"e",218,0,-1,0,51,51,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0051-04",21,"Dentro de mi pecho tengo\nun gusanito de seda;\npor más que quiero olvidarme,\nen ello mismo se enreda.",225,6,-1,256,"",0,4,"ea",266,0,-1,0,51,51,"","",0,"","","",32,0,0,[],"",""],["ortiz_ecuador-p0051-05",21,"Dentro de mi pecho tengo\nun perrito carnicero,\nguambra, no te olvidarás,\nque tú eres mi amor primero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,51,51,"","",0,"","","",32,0,0,[],"",""],["ortiz_ecuador-p0051-06",21,"Dentro de mi pecho tengo\nuna espina y una flor;\ntú me sacarás la espina\ncuando me brindes tu amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,51,51,"","",0,"","","",32,0,0,[],"",""],["ortiz_ecuador-p0051-07",21,"Desde aquí te estoy mirando\nla punta de la enagüita;\nla boca se me hace agüita\ny el corazón me palpita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,51,51,"","",0,"","","",20,0,0,[],"",""],["ortiz_ecuador-p0052-01",21,"Desde Chimbo yo me vengo,\nguiado por un lucero,\ny solamente me vengo\npor un amor verdadero.",225,6,-1,256,"",1,4,"eo",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0052-02",21,"Desde Cuenca para arriba\nhan rebajado las papas;\nestán a cuatro por medio\ny una morlaca de yapa.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0052-03",21,"Desde entonces yo no duermo,\nyo no sé qué va a pasar;\ndéme no más otro cuarto,\ntengo ganas de llorar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0052-04",21,"Desde lejos vengo andando\nen un puro padecer,\npero así me determino\nsolo por volverte a ver.",225,6,-1,256,"",0,4,"e",20,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0052-05",21,"Desde muy lejos yo vengo\nuna montaña pasando;\npor venir a estar contigo\ncasi me muero rodando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,52,52,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0052-06",21,"Desde que le vi, señora,\nle dije a mi corazón:\nqué bonita piedrecita\nvoy a darme un tropezón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0052-07",21,"Desde que te conocí,\ntodo mi afán era verte;\nparece que yo nací\ncon destino de quererte.",225,6,-1,256,"",1,4,"ee",134,0,-1,0,52,52,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0053-01",21,"Desde Quito estoy viniendo\nen busca de flor morada;\nno te quiero por bonita\nsino por mujer honrada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0053-02",21,"Despedida, despedida,\ndespedirme no quisiera;\nal encadenar mis brazos,\nme muriera, me muriera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0053-03",21,"Después de mis días muerto,\nde los gusanos comido,\nmis huesos serán letreros\nde lo bien que te he querido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0053-04",21,"Dicen que a todas las suegras\nvan a botar a la mar;\ny la vieja de la mía\nya está aprendiendo a nadar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,53,53,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0053-05",21,"Dicen que la ausencia borra\nsin remedio una pasión.\nEsto fuera si del pecho\nse ausentara el corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0053-06",21,"Dicen que la esperanza,\nseñora, mantiene al hombre;\nyo digo que así ha de ser;\nseñora, me hallo conforme.",225,6,-1,256,"",0,4,"oe",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0053-07",21,"Dijiste que me querías,\nno sé en qué tiempo sería;\ntalvez sería en verano\ny el viento lo llevaría.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,53,53,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0054-01",21,"Dijiste que me querías,\nyo creí que era verdad;\ncuando conociste a otro\nme dejaste en la orfandad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,54,54,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0054-02",21,"Dios se lo pague, señora,\npor su buena caridad,\nque me ha tenido en su casa\ncon tan buena voluntad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,54,54,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0054-03",21,"Dizque dices que me quieres\nde los labios para afuera;\nde los labios para adentro,\npidiendo a Dios que me muera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,54,54,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0054-04",21,"Dizque dices que me quieres;\nyo digo que así será;\nlas caricias son conmigo,\ny el amor, con quién será.",225,6,-1,256,"",0,4,"a",-1,0,-1,0,54,54,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0054-05",21,"Dizque le gustan\nlas buenas mozas,\ny que en amores\nno anda con cosas.",225,6,-1,256,"",6,4,"oa",61,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0054-06",21,"Dizque me cierran caminos\npor separarme de ti;\nsepararme no podrán,\nquitarme la vida, sí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0054-07",21,"Dizque te andas alabando\ndiciendo que te he querido,\npara qué mientes, bonita,\nlo que nunca ha sucedido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,54,54,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0055-01",21,"Dizque te andas alabando\nque me has dejado llorando;\nyo primero te dejé\ncomo chirote silbando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,55,55,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0055-02",21,"Dizque te andas alabando\nque mi amor no te merece;\ncómo te va a merecer,\nsi tienes otros quereres.",225,6,-1,256,"",0,4,"ee",-1,0,-1,0,55,55,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0055-03",21,"Dizque te andas alabando\nque mi amor no te merece;\nde rogar, no te he rogado,\nquiéreme si te parece.",225,6,-1,256,"",0,4,"ee",64,0,-1,0,55,55,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0055-04",21,"Dizque te andas alabando\nque tu enamorado es gato;\npero nunca has descubierto\nque es un pobre mojigato.",225,6,-1,256,"",0,4,"ao",19,0,-1,0,55,55,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0055-05",21,"Dos corazones heridos\npuestos en una balanza;\nuno le pide perdón.\ny otro le clama venganza.",225,6,-1,256,"",0,4,"aa",163,0,-1,0,55,55,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0055-06",21,"Dos flores perdiste, loca,\nambas en edades tiernas:\nuna por abrir la boca,\notra por abrir las piernas.",225,6,-1,256,"",1,4,"ea",690,0,-1,0,55,55,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0055-07",21,"El aguardiente de caña\nes un hombre caballero:\nrectito va a la cabeza\ncomo si fuera sombrero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,55,55,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0056-01",21,"El ají, querida mía,\nno me gusta a mí:\npero el ají que te gusta\ncolgado lo tengo aquí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0056-02",21,"El amor de las mujeres\nes como el de las gallinas;\napenas les falta el gallo,\ncualquier pollo les domina.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,56,56,"","",0,"","","",18,0,0,[],"",""],["ortiz_ecuador-p0056-03",21,"El amor de las mujeres\nes como el perro cutucho:\ncara al uno, cara al otro,\ncomo si valiera mucho.",225,6,-1,256,"",0,4,"uo",415,0,-1,0,56,56,"","",0,"","","",18,0,0,[],"",""],["ortiz_ecuador-p0056-04",21,"El amor de un hombre pobre\nes como perro de chagra;\ncuando ve que el otro puede,\nalzando el rabo se larga.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0056-05",21,"El amor que tú me diste\nen la rama lo dejé;\nvino un viento de verano,\nrama y amor se me fue.",225,6,-1,256,"",0,4,"e",77,0,-1,0,56,56,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0056-06",21,"El amor que yo te tengo\nme palpita el corazón;\namores que van y vienen\nson pagados con traición.",225,6,-1,256,"",0,4,"o",31,0,-1,0,56,56,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0056-07",21,"El amor y las mujeres\nparecen al gavilán;\ncada vez que tienen ganas,\nalzan el vuelo y se van.",225,6,-1,256,"",0,4,"a",147,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-01",21,"El anillo que me diste\nfue de coco y se rompió;\nel amor que me tuviste\nduró poco y se acabó.",225,6,-1,256,"",1,4,"o",2,0,-1,0,57,57,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0057-02",21,"El baile de mi sombrero\nse baila de esta manera,\nponiéndolo bajo el brazo\ny dando la vuelta entera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-03",21,"El buey solito,.\nqué bien se lame;\nel solterito\nsiempre está bien.",225,6,-1,256,"",6,4,"e",-1,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-04",21,"El cariño que me diste\nen el río lo mandé;\nun cariño traicionero\nconservarlo, para qué.",225,6,-1,256,"",0,4,"e",77,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-05",21,"El cariño que te di,\nni buscando has de encontrar;\ncuídate no más guambrita,\nno te vayan a engañar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-06",21,"El corazón que yo tengo\nal borrego le he de dar;\nel borrego me da lana,\nvos, llucha ca, qué has de dar!",225,6,-1,256,"",0,4,"a",-1,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0057-07",21,"El curita de mi pueblo\nde la torre se cayó;\nqué suerte que tuvo el cura,\nque del suelo no pasó.",225,6,-1,256,"",0,4,"o",2,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0058-01",21,"El día en que me casé,\nloco, borracho estaría,\nantes de entrar a la iglesia,\n¿por qué no me correría?",225,6,-1,256,"",0,4,"ia",0,0,-1,0,58,58,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0058-02",21,"El día en que tú naciste\nnacieron todas las flores;\ny en la pila del bautismo\ncantaron los ruiseñores.",225,6,-1,256,"",0,4,"oe",5,0,-1,0,58,58,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0058-03",21,"El día en que yo me muera,\nno me lloren mis parientes;\nllórenme los alambiques\nque destilan aguardiente.",225,6,-1,256,"",0,4,"ee",-1,0,-1,0,58,58,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0058-04",21,"El día en que yo me muera,\nque me entierren con guitarra;\npor si acaso se me ofrezca\ncon taita Dios una farra.",225,6,-1,256,"",0,4,"aa",308,0,-1,0,58,58,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0058-05",21,"El día en que yo me vaya\nni la cama he de ir haciendo,\na que no quedes, ingrata,\ncon otro perro durmiendo.",225,6,-1,256,"",0,4,"eo",52,0,-1,0,58,58,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0058-06",21,"El día en que yo nací\njuntos nacimos los dos;\nvos para quererme a mí,\nyo, para quererte a vos.",225,6,-1,256,"",1,4,"o",87,0,-1,0,58,58,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0058-07",21,"El hombre debe tener\nun perro y una mujer;\nel perro cuida la casa,\nla mujer da de comer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,58,58,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0059-01",21,"El hombre que se ha casado\ncon una mujer bonita,\nhasta que no llegue a vieja,\nel temor no se le quita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-02",21,"El marido es el piloto;\nla mujer, el capitán;\nlos hijos, los malos vientos\ny la suegra, el huracán.",225,6,-1,256,"",0,4,"a",147,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-03",21,"El perro que bebe suero\nnunca padece de empacho;\nsi has venido por manteca\nahí te queda el carapacho.",225,6,-1,256,"",0,4,"ao",310,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-04",21,"El que tiene padre y madre\ntiene una corona de oro,\nporque siempre son los padres\nde sus hijos los tesoros.",225,6,-1,256,"",0,4,"oo",-1,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-05",21,"El querer a una casada,\nparece una golosina;\nes como comer papitas\ncon pechuga de gallina.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-06",21,"El rico dizque te ofrece\ncasa de teja en Talagua;\nyo como pobre te ofrezco\na los nueve meses guagua.",225,6,-1,256,"",0,4,"aa",383,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0059-07",21,"El verso que tú me cantas\ncantas como caballero;\nsolo la cola te falta,\npara ser caballo entero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0060-01",21,"En el fondo de la mar\nsuspiraba un peje mocho,\ny en el suspiro decía:\napura con el sancocho.",225,6,-1,256,"",0,4,"oo",424,0,-1,0,60,60,"","",0,"","","",9,0,0,[],"",""],["ortiz_ecuador-p0060-02",21,"En el fondo de la mar\nsuspiraba una ballena,\ny en el suspiro decía:\nel que la seca, la llena.",225,6,-1,256,"",0,4,"ea",59,0,-1,0,60,60,"","",0,"andina_t2","","",9,0,0,[],"",""],["ortiz_ecuador-p0060-03",21,"En el monte crían palos;\nen el agua, camarones;\nen la boca de los hombres\ncucarachas y ratones.",225,6,-1,256,"",0,4,"oe",-1,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0060-04",21,"En el río de Guanando\nmi sombrero va nadando\ny en la copa va diciendo\nque mi amor se está acabando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0060-05",21,"En esa bonita boca\ncómo no te diera yo\nuna B con una E,\nuna S y una O.",225,6,-1,256,"",0,4,"o",2,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0060-06",21,"En esta cuevita\nhabitan ladrones;\nno roban dinero\nsino corazones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0060-07",21,"En esta esquina\nbaila un payaso;\nsale, negrita,\ndale un abrazo.",225,6,-1,256,"",6,4,"ao",43,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0061-01",21,"En la esquina de la plaza\nse ha formado un baratillo:\nlas mujeres valen plata\ny los hombres ni un cuartillo.",225,6,-1,256,"",0,4,"io",228,0,-1,0,61,61,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0061-02",21,"En la esquina de Licán\ntodos queman las chamizas;\ny salen las licaneñas\nsin ponerse las camisas.",225,6,-1,256,"",0,4,"ia",729,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0061-03",21,"En la loma de Igualata\nhice una compra barata:\ncuatro solteras por medio\ny una casada de yapa.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0061-04",21,"En la palma de mi mano\nvoy a hacer una escritura,\nhaciendo firmar tu nombre\ny pintando tu hermosura.",225,6,-1,256,"",0,4,"ua",17,0,-1,0,61,61,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0061-05",21,"En tu pecho la cadena\nqué bonita se refleja;\nsi tu amor es para mí\npor qué dices: deja, deja.",225,6,-1,256,"",0,4,"ea",165,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0061-06",21,"En tu puerta sembré un pino;\nen tu ventana una flor;\nen tu pecho tres claveles\ny una azucena de amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,61,61,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0061-07",21,"Entre las flores, la rosa,\nentre los signos, la cruz;\nentre los seres, mi madre,\ny entre los amigos, tú.",225,6,-1,256,"",0,4,"u",-1,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-01",21,"Esa vela se consume\nal rigor del candelero;\nasí me consumo yo,\nguambrita, porque te quiero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-02",21,"Escogí las cinco flores,\nlas mejores del jardín,\ny son mis cinco sentidos\nque tengo puestos en ti.",225,6,-1,256,"",0,4,"i",-1,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-03",21,"Ese joven que está allá,\nestá con cara de macho;\npero cuando llega el caso,\nes un pobre mamarracho.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-04",21,"Ese par que están bailando,\nse parecen hermanitos:\nel uno lleva la jaula,\ny el otro los pajaritos.",225,6,-1,256,"",0,4,"io",254,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-05",21,"Eso de quererte,\nqué facilidad;\neso de olvidarte,\nqué dificultad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0062-06",21,"Esperarán, compadritos,\nirán tomando cuajada;\nya está el toro con la vaca;\nojalá quede preñada.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,62,62,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0062-07",21,"Esperarán, compadritos,\nirán tomando un caldito;\nya está la cuya preñada,\nquizá salga caricito.",225,6,-1,256,"",0,4,"io",119,0,-1,0,62,62,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0063-01",21,"Espero que las mujeres\nhagan algo en el hogar;\npues, metidas en la cama,\nno quieren ni cocinar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,63,63,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0063-02",21,"Esta caña me chupara\ndel cogollo a la mitad,\ny no ver aquel desprecio\ny esa mala voluntad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0063-03",21,"Esta noche a media noche\nme he de ir por el potrero;\ntu mama es corta de vista,\nha de creer que es el ternero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0063-04",21,"Esta noche voy a andar\nigual igual con la luna,\na ver si puedo sacar\nde las dos hermanas, una.",225,6,-1,256,"",1,4,"ua",56,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0063-05",21,"Esta vida de casados\nes una gran diversión;\ndentro de las cobijitas,\narrarray, qué comezón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0063-06",21,"Estaba subiendo al cielo\ncargadito mi vihuela,\npor si acaso se me ofrezca\nhacer bailar a tu abuela.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0063-07",21,"Estamos cuatro a tus puertas;\ntodos cuatro te queremos;\nescoge al que más te guste,\ny los tres regresaremos.",225,6,-1,256,"",0,4,"eo",127,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0064-01",21,"Estando subiendo al cielo\nSan Pedro me dijo: abajo;\nsalió Jesucristo y dijo:\ndeja que suba, carajo!",225,6,-1,256,"",0,4,"ao",168,0,-1,0,64,64,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0064-02",21,"Este tambor que yo toco\nes del cuero de la oveja,\npor más duro que le dé\nla oveja nunca se queja.",225,6,-1,256,"",0,4,"ea",165,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0064-03",21,"Esto dijo el aguardiente\ncuando lo estaban bebiendo:\nbeberánme con cuidado,\nno vayan a estar cayendo.",225,6,-1,256,"",0,4,"eo",52,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0064-04",21,"Esto dijo la gallina\ncuando le iban a matar:\nde este mal ya no hay remedio,\npongan agua a calentar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,64,64,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0064-05",21,"Esto dijo Salomón\nmontado en su rico macho:\nsi no hubiera el aguardiente,\nno hubiera tanto borracho.",225,6,-1,256,"",0,4,"ao",310,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0064-06",21,"Estos sustos de mi vida,\nambos hemos de pagar;\ntú por haberme querido;\nyo por amigo de amar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0065-01",21,"Fiera guambra carishina,\namante de los varones;\nen la esquina silbadora,\ny en la casa gran señora.",225,6,-1,256,"",5,4,"oa",107,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0065-02",21,"Gavilán chiquito soy;\ngrande, no podría volar;\njuro que me he de llevar\nla prenda de este lugar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0065-03",21,"Gavilán, ¿qué andas haciendo,\nde la montaña a la sierra?.\nLa paloma tiene dueño,\ngavilán, vuelve a tu tierra.",225,6,-1,256,"",0,4,"ea",80,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0065-04",21,"Gracias a Dios que ya tengo\ndos camisas que mudar:\nuna que se fue en el viento\ny otra que Dios me ha de dar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,65,65,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0065-05",21,"Guambrita de veinte novios,\nconmigo cuentas veintiuno;\nsi no te casas conmigo,\nno te casas con ninguno.",225,6,-1,256,"",0,4,"uo",230,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0065-06",21,"Hermanito perejil,\ncantemos la hierba buena,\nel que sabe querer, sabe\nlo que es una cosa buena.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-01",21,"Hombre feo, mentiroso,\nte haces el disimulado;\nte haces el que no me quieres,\ncuando por mí has llorado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-02",21,"Infeliz el que se casa,\npudiendo vivir soltero;\nsabiendo que en este tiempo\nel amor es traicionero.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-03",21,"Ingrata, toma el puñal\ny despedaza este pecho;\ny en esa sangre verás\nlas acciones que me has hecho.",225,6,-1,256,"",0,4,"eo",60,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-04",21,"Ingrata, toma esta flor\nque en el campo yo cogí;\nla mata quedó llorando\ncomo yo lloro por ti.",225,6,-1,256,"",0,4,"i",23,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-05",21,"Juro a la vara,\njuro al bastón;\njuro que es tuyo\nmi corazón.",225,6,-1,256,"",6,4,"o",31,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-06",21,"Juro a la bala,\njuro al cañón,\njuro que es mío\ntu corazón.",225,6,-1,256,"",6,4,"o",31,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0066-07",21,"Juro que te he de querer\npor mi palabra de honor;\njuro que he de padecer\ntrabajando por tu amor.",225,6,-1,256,"",1,4,"o",72,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0067-01",21,"La cinta para ser cinta\nno ha de ser de dos colores;\nla mujer para casada\nno ha de tener dos amores.",225,6,-1,256,"",0,4,"oe",5,0,-1,0,67,67,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0067-02",21,"La cinta rosada\nno pierde el color;\nyo con mi guambrita\nno pierdo el amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0067-03",21,"La culebra entre las ramas\nlas duras penas padece;\nel hombre que quiere a dos,\ndoscientos palos merece.",225,6,-1,256,"",0,4,"ee",64,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0067-04",21,"La desgracia solo en mí\nno se quiere separar;\ncomo con ella nací,\ncon ella me he de enterrar.",225,6,-1,256,"",1,4,"a",21,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0067-05",21,"La flor de la maravilla\necha la fragancia en gajos;\nel que está para irse abajo\nsolito busca la orilla.",225,6,-1,256,"",5,4,"ia",162,0,-1,0,67,67,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0067-06",21,"La guayabita madura\nle dijo a la verde verde:\nel hombre cuando es celoso\nse acuesta, pero no duerme.",225,6,-1,256,"",0,4,"ee",-1,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0067-07",21,"La naranja para dulce\ny el limón para espinoso;\nmi corazón para firme\ny el tuyo para engañoso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0068-01",21,"La niña que está bailando,\nestá bailando en ayunas;\nmaten pronto a la gallina,\ndenle de comer las plumas.",225,6,-1,256,"",0,4,"ua",-1,0,-1,0,68,68,"","",0,"","","",19,0,0,[],"",""],["ortiz_ecuador-p0068-02",21,"La noche en que me casé\nla cama se me rompió;\ny como era carpintero,\nmete clavo estaba yo.",225,6,-1,256,"",0,4,"o",2,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0068-03",21,"La paloma de la Costa\nno come trigo ni arroz;\nsolamente se mantiene\ncon el amor de los dos.",225,6,-1,256,"",0,4,"o",87,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0068-04",21,"La paloma es muy ingrata,\naunque le den de comer;\nasí mismo es la mujer,\naunque le llenen de plata.",225,6,-1,256,"",11,4,"aa",74,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0068-05",21,"La piña madura\nsin querer pelarse;\nasí está mi guambra\nsin querer casarse.",225,6,-1,256,"",0,4,"ae",250,0,-1,0,68,68,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0068-06",21,"La suegra dijo a la nuera\nmirando por la ventana:\nqué te pasa, sinvergüenza,\nque no bajas de la cama.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0068-07",21,"Las aves de la montaña\nhacen nido de algodón;\nasí pienso hacer, guambrita,\ndentro de tu corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0069-01",21,"Las aves en la montaña\nbuscan rama en que sentar,\nasí como busco yo\nbrazos en que descansar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,69,69,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0069-02",21,"Las aves en la montaña\ntienen pepas que comer;\nasí mismo tengo yo\namores al escoger.",225,6,-1,256,"",0,4,"e",20,0,-1,0,69,69,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0069-03",21,"Las campanas dicen dan,\nlas mujeres dicen den;\nmás me gustan las campanas\nporque dan sin que les den.",225,6,-1,256,"",0,4,"e",-1,0,-1,0,69,69,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0069-04",21,"Las moras verdes\nse van secando;\ntodas mis guambras\nse van casando.",225,6,-1,256,"",6,4,"ao",33,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0069-05",21,"Las mujeres de este tiempo\nson como el pan de la mesa:\ncara al uno, cara al otro,\nqué cara tan sinvergüenza.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,69,69,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0069-06",21,"Las mujeres de este tiempo\nson como la bicicleta;\nmonta el uno, monta el otro\ny el dueño no monta nada.",225,6,-1,256,"",5,4,"aa",-1,0,-1,0,69,69,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0069-07",21,"Las piedras en la ladera,\nqué paradero tendrán.\nLas guambras de este tiempo,\nqué palabra cumplirán.",225,6,-1,256,"",0,4,"a",147,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-01",21,"Las promesas que me hiciste\naquí las llevo guardadas;\nen el corazón escritas\ny en el pecho sepultadas.",225,6,-1,256,"",0,4,"aa",282,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-02",21,"Linda es mi guambra,\nflor de romero;\nbella es mi niña,\nmi amor primero.",225,6,-1,256,"",6,4,"eo",38,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-03",21,"Llorando, llorando\nse engaña a los niños;\nasí me engañaron\ntus falsos cariños.",225,6,-1,256,"",0,4,"io",625,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-04",21,"Lo que ha trabajado un año,\nsufriendo con tanto afán,\nsi no gastamos en trago,\nla gente ¿qué nos dirá?",225,6,-1,256,"",0,4,"a",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-05",21,"Los diablos en el infierno\nse están muriendo de risa\nal ver a un flaco como este\ncon piernas de longaniza.",225,6,-1,256,"",0,4,"ia",420,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-06",21,"Los hombres son como el diablo,\nparientes de Lucifer;\nse visten por la cabeza,\nse desvisten por los pies.",225,6,-1,256,"",0,4,"e",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0070-07",21,"Los ojos de mi guambrita\nluceros del cielo son;\nellos son los que me inspiran\nlatidos del corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0071-01",21,"Los pájaros son clarines\nentre los cañaverales,\nque le dan los buenos días\nal sol de Dios cuando nace.",225,6,-1,256,"",0,4,"ae",-1,0,-1,0,71,71,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0071-02",21,"Lucero de la mañana,\nde la mañana lucero,\npara vivir mal casado,\nprefiero vivir soltero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,71,71,"","",0,"","","",22,0,0,[],"",""],["ortiz_ecuador-p0071-03",21,"Lucero de la mañana,\npréstame tu claridad,\npara seguirle a una ingrata\nque no tuvo caridad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,71,71,"","",0,"","","",22,0,0,[],"",""],["ortiz_ecuador-p0071-04",21,"Malhaya, malhaya suerte,,\nmalhaya mi ceguedad,\nmalhaya haber puesto yo\nmi amor en tu falsedad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,71,71,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0071-05",21,"Mamita, mamita,\nme pica el quiquiriquí;\ndeja no más, hijita,\nque también me picó a mí.",225,6,-1,256,"",1,4,"i",23,0,-1,0,71,71,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0071-06",21,"Mamita mucho me pega\ncon el rabito de oveja;\nel culito hecho cendales,\ny el amor que no me deja.",225,6,-1,256,"",0,4,"ea",165,0,-1,0,71,71,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0071-07",21,"Mañana cuando me vaya,\nme iré por la cordillera,\ncargado mi bicicleta,\nllevándome una soltera.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,71,71,"","",0,"","","",9,0,0,[],"",""],["ortiz_ecuador-p0072-01",21,"Mañana de mañanita\nyo siempre recordaré,\nde esa boquita tan linda\nque hace tiempos yo besé.",225,6,-1,256,"",0,4,"e",77,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0072-02",21,"Mañana madrugo al cielo\na comprar papel sellado,\npara hacer las escrituras\nde mi amor desesperado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0072-03",21,"Mañana madrugo al monte\na abrazarme de una nube,\na ver si por ahí encuentro\na una negrita que tuve.",225,6,-1,256,"",0,4,"ue",348,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0072-04",21,"Mañana, mañana,\nmuy demañanita,\nte espero en la playa\npero a vos solita.",225,6,-1,256,"",0,4,"ia",50,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0072-05",21,"Mañana me muero yo;\nmi viuda va a quedar moza:\nya el otro estará viniendo\na disponer cualquier cosa.",225,6,-1,256,"",0,4,"oa",63,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0072-06",21,"Mañana me voy de aquí\npero tengo que volver,\na pagarle una fineza\nque le debo a esta mujer,",225,6,-1,256,"",0,4,"e",20,0,-1,0,72,72,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0072-07",21,"Más arriba o más abajo\nhay un huerto naranjal;\nentre Ud., señora, y tome\nlo que fuera principal.",225,6,-1,256,"",0,4,"a",1,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-01",21,"Matita de ají reseco,\nqué provecho vas a dar;\nde vos, fiero sinvergüenza,\nqué es lo que voy a sacar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-02",21,"Me has dicho que eres cantor\ny que cantas de arrebato,\npero no puedes saber\ncuántos pelos tiene el gato.",225,6,-1,256,"",0,4,"ao",19,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-03",21,"Me mandaron a la cárcel\npor querer a una casada;\npero ella siempre me daba\nuna vida regalada.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-04",21,"Me puse a sembrar corales\na ver si me producían;\nnacieron tan colorados\nque tus labios parecían.",225,6,-1,256,"",0,4,"ia",500,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-05",21,"Mentiroso, mentiroso,\nmintiendo no más estás\npara ver si yo te digo:\nquédate un ratito más.",225,6,-1,256,"",0,4,"a",51,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-06",21,"Mi casita ya está vieja,\nllena de tantas goteras;\npor qué no me casaría\ncuando hubo tantas solteras.",225,6,-1,256,"",0,4,"ea",103,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0073-07",21,"Mi corazón agoniza\nsolo por quererte tanto;\nno tengo tranquilidad;\nhoy mi vida es un quebranto.",225,6,-1,256,"",0,4,"ao",30,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0074-01",21,"Mi mamá de gana pega,\nporque salgo a la ventana;\nes que ella no considera\nque también yo tengo gana.",225,6,-1,256,"",0,4,"aa",4,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0074-02",21,"Mi mamita me parió\nencima del soberado;\npor eso nací bandido,\nbandido y enamorado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,74,74,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0074-03",21,"Mi marido se murió,\nel diablo se lo cargó;\npero allá ya habrá pagado\nlas patadas que me dio.",225,6,-1,256,"",0,4,"o",2,0,-1,0,74,74,"","",0,"","","",12,0,0,[],"",""],["ortiz_ecuador-p0074-04",21,"Mi mujer ya no me quiere\nporque tomo el aguardiente:\ntambién lo saben tomar\nlos curas y los tenientes.",225,6,-1,256,"",0,4,"ee",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0074-05",21,"Mi Riobamba es tierra linda,\nla mejor del Ecuador,\ndonde el pobre se hace rico\ntrabajando con amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0074-06",21,"Mi suegra, porque me quiere\nme ha regalado un rosario,\ny con mi suegra yo tengo\ncorona, cruz y calvario.",225,6,-1,256,"",0,4,"ao",25,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0074-07",21,"Mi suegra se está muriendo;\nyo estoy a la cabecera,\ncon un rosario en la mano,\npidiendo a Dios que se muera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0075-01",21,"Morenito soy, señora,\ny no lo digo en broma;\nque de negro se ha vestido\nel Papa Santo de Roma.",225,6,-1,256,"",0,4,"oa",86,0,-1,0,75,75,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0075-02",21,"Naranja dulce,\nlimón partido,\ndame un besito\nsi me has querido.",225,6,-1,256,"",6,4,"io",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0075-03",21,"No digas que me has querido\nni que me has aborrecido;\nno quiero que nadie sepa\nlo que nos ha sucedido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,75,75,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0075-04",21,"No digo que soy bonito,\nni que derramo colores,\ncon mi propio colorcito\nhago privar a mejores.",225,6,-1,256,"",1,4,"oe",5,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0075-05",21,"No importa que no me quieras\ndespués de haberme querido;\nel consuelo que me queda\nque en tus brazos me he dormido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0075-06",21,"No llores, ojos bonitos;\nno llores que me da pena;\nllorarás cuando me veas\nsepultado en tierra ajena.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,75,75,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0075-07",21,"No llores, ojos bonitos;\nno tienes por qué llorar;\nsi alguna pena te aflige,\ntú tienes a quien contar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,75,75,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0076-01",21,"No me gusta, no me gusta,\nel locrito de zapallo;\nasimismo no me gusta\ngallina de tanto gallo.",225,6,-1,256,"",1,4,"ao",102,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0076-02",21,"No me gustan, no me gustan,\nlas leyes del Presidente,\nporque nos está quitando\nde la boca el aguardiente.",225,6,-1,256,"",0,4,"ee",15,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0076-03",21,"No me mates con cuchillo\nque tenga el acero fuerte;\nmátame con un suspiro,\nque te perdono la muerte.",225,6,-1,256,"",0,4,"ee",134,0,-1,0,76,76,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0076-04",21,"No me niegues tu cariño,\namor puro de mi vida;\nla llama del corazón\npor ti siempre está encendida.",225,6,-1,256,"",0,4,"ia",37,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0076-05",21,"No puedo acusar a nadie\nde mi negra desventura;\npues las penas que me matan\nson obra de mi locura.",225,6,-1,256,"",0,4,"ua",17,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0076-06",21,"No quiero pañuelo blanco\nni tampoco de color;\nyo quiero pañuelo negro\npara llorar por mi amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0076-07",21,"No solamente el puñal\ndeja herido el corazón;\nqué más puñal en la vida\nque el engaño y la traición.",225,6,-1,256,"",0,4,"o",31,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-01",21,"No sufra, suegra querida,\npor su hijita que se va,\nque al transcurrir nueve meses,\nacompañada vendrá.",225,6,-1,256,"",0,4,"a",9,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-02",21,"No te darás a beber;\nla fortuna has de perder;\ncomo el perro has de quedar,\nsolo y triste a padecer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-03",21,"Nunca en mi vida había visto\nlo que he visto esta mañana:\nun gallinazo en la torre,\nrepicando las campanas.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-04",21,"Pagar un bien con un bien\nno lo he visto todavía;\npagar un bien con un mal,\nlo veré toda la vida.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-05",21,"Palomita de mi amor,\nojos de dulce mirar;\nlo que quiero es que me tengas\nen tu lindo palomar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-06",21,"Palomita que comiste\nla pepa del capulí,\ncomiendo esas pepas verdes\nte has olvidado de mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0077-07",21,"Palomita que te vas,\npublicando tu retiro;\nno vayas a estar volviendo\na tu despreciado nido.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0078-01",21,"Pantalones bien fajados\ncon una tira de beta,\npara hacerme respetar\nde toda mujer coqueta.",225,6,-1,256,"",0,4,"ea",200,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0078-02",21,"Para adentro me han llamado,\npara adentro yo entraré,\nsi me muestran su mal modo,\npor donde vine me iré.",225,6,-1,256,"",0,4,"e",77,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0078-03",21,"Para arriba corre el agua,\npara abajo las piedritas;\npensarán las de allá arriba,\nque aquí abajo no hay bonitas.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,78,78,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0078-04",21,"Para arriba de esta calle\nhabía un burro pelado;\ny yo que le quedo viendo,\nha sido el burro de al lado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0078-05",21,"Para pasar por tu calle\nno necesito farol;\ntus ojos son dos luceros\nque me alumbran más que el sol.",225,6,-1,256,"",0,4,"o",24,0,-1,0,78,78,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0078-06",21,"Para qué pariste, madre,\nun hijo tan desgraciado;\ncon dos pelotas al lado\ny un mojigato parado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0078-07",21,"Para qué tantos teneres,\nen vida tan acabada,\nsi todo se ha de volver\npolvo, sombra, viento, nada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-01",21,"Páseme un pilche de chicha,\nde esa que es bien chumadora.\nquiero ahogar mi desdicha,\nen chicha de pura jora.",225,6,-1,256,"",1,4,"oa",107,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-02",21,"Pensarás que yo al perderte\nel corazón tengo herido;\nyo me río, yo me río;\nyo siempre he sido bandido.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-03",21,"Pobrecitas las mujeres,\nsi los hombres se murieran,\nbajándose a las quebradas\ncon agua se mantuvieran.",225,6,-1,256,"",0,4,"ea",693,0,-1,0,79,79,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0079-04",21,"Pobrecitos de los hombres\nsi las mujeres no hubiera;\nse fueran a los potreros;\ncon hierba se mantuvieran.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-05",21,"Por allá, por no sé dónde,\nmataron a no sé quién,\nsi no me vengo corriendo,\nme matan a mí también.",225,6,-1,256,"",0,4,"e",242,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-06",21,"Por el valle voy cantando,\nentonando una canción;\na ver si te llega al alma\ny un poquito al corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0079-07",21,"Por esas felices calles\nvive la que adoro yo,\nla que me robó la calma.\ndueña de mi corazón.",225,6,-1,256,"",0,4,"o",-1,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0080-01",21,"Por ese cerro nevado,\nvide bajar un venado,\ny yo que regreso a ver,\nhabía sido mi cuñado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0080-02",21,"Por este maldito gato\nalgo me ha de suceder;\na la vieja de mi suegra\nlas uñas ha de prender.",225,6,-1,256,"",0,4,"e",20,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0080-03",21,"Por un momento de gusto,\nnueve meses de susto;\ncuarenta días de cama,\ny toda la vida, mama.",225,6,-1,256,"",5,4,"aa",90,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0080-04",21,"Porque te quiero, te celo,\ny de no, no te celara;\ncon ambos ojos te viera,\nasí el diablo te cargara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,80,80,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0080-05",21,"Porque te quise\nyo te he rogado;\npor traicionera\nyo te he dejado.",225,6,-1,256,"",6,4,"ao",14,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0080-06",21,"Porque te quise me vine,\nporque te quiero aquí estoy;\nsi te sirvo de molestia,\nadiós, adiós, ya me voy.",225,6,-1,256,"",0,4,"o",112,0,-1,0,80,80,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0080-07",21,"Porque te quise me vine,\nporque te quise, aquí estoy;\ncomo vine por mi gusto,\nsi no me quieres me voy.",225,6,-1,256,"",0,4,"o",112,0,-1,0,80,80,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0081-01",21,"Qué bonita es esta casa\ncon una sola ventana:\nqué bonita es esta guambra\npara nuera de mi mama.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,81,81,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0081-02",21,"Qué bonita es esta casa;\nmás bonita la armazón;\nqué bonita la de adentro,\nle daré mi corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,81,81,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0081-03",21,"Qué bonita es esta casa,\nmetro y medio de solera;\nseñora, de gana sufre,\nteniendo una hija soltera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,81,81,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0081-04",21,"Qué bonita es esta tierra\nentre pampas y laderas;\nqué bonito es un amor\ncuando se quiere de veras.",225,6,-1,256,"",0,4,"ea",103,0,-1,0,81,81,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0081-05",21,"Qué bonita es mi amiguita\ncomo la flor del café;\ntan fragante y olorosa\nque hasta la vida daré.",225,6,-1,256,"",0,4,"e",77,0,-1,0,81,81,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0081-06",21,"Qué bonito brilla el sol\nen medio de una chorrera;\nqué bonito se ve al hombre\nen brazos de una soltera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,81,81,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0081-07",21,"Qué bonito corre el agua\ndebajo de las almendras;\nasí corriera mi amor\nsi no hubiera malas lenguas.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,81,81,"","",0,"frenk_t2","","",5,0,0,[],"",""],["ortiz_ecuador-p0082-01",21,"Qué bonito es ser soldado,\na la puerta de un cuartel,\ncon el fusilito al hombro,\nsaludando al coronel.",225,6,-1,256,"",0,4,"e",32,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0082-02",21,"Qué bonito que cantaba\nel pajarito en su nido!\nAsí debo yo cantar\ncuando me encuentro contigo.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,82,82,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0082-03",21,"Qué bonito que era yo;\nqué feo me estoy poniendo;\ndesde que comí conejo,\nal diablo estoy pareciendo.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0082-04",21,"Qué bonitos ojos tiene\nla longa de la Rosario;\npero lo malo es que tiene\nla barba del comisario.",225,6,-1,256,"",1,4,"ao",25,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0082-05",21,"Qué bonitos ojos tienes\ndebajo de tus pestañas.\ncómo quisiera saber\nsi me quieres o me engañas.",225,6,-1,256,"",0,4,"aa",42,0,-1,0,82,82,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0082-06",21,"¡Qué dichosa es una pulga\nque duerme en siete colchones!\nY no yo, pobre infeliz,\ntirado por los rincones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0082-07",21,"¡Qué linda guambra\nla melenuda;\npescuezo largo\nla fiera muda!",225,6,-1,256,"",6,4,"ua",144,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0083-01",21,"¡Qué linda la luna,\nqué bellos luceros!\nQuiéreme, guambrita,\nque somos solteros.",225,6,-1,256,"",0,4,"eo",22,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0083-02",21,"¡Qué linda tierra\nla de mi pais,\nque hasta el morocho\nse vuelve maiz!",225,6,-1,256,"",6,4,"a",335,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0083-03",21,"¡Qué lindas guambras\nlas de Riobamba!\nTodas me siguen,\nmenos yarucas.",225,6,-1,256,"",6,4,"ua",-1,0,-1,0,83,83,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0083-04",21,"¡Qué lindas guambras\nlas del caliente!\nQue cuando quieren,\nquieren de frente.",225,6,-1,256,"",6,4,"ee",-1,0,-1,0,83,83,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0083-05",21,"Qué lindas guambras\nlas guarandeñas,\nlindas trigueñas,\nprecioso emblema.",225,6,-1,256,"",6,4,"ea",-1,0,-1,0,83,83,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0083-06",21,"Qué loco estaría;\nqué me pasaría,\npor haber amado\ntan disparatado.",225,6,-1,256,"",5,4,"ao",14,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0083-07",21,"Qué más voy a hacer, cariño.\ncorresponder a tu amor.\namor con amor se paga;\namorcito, eres primor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-01",21,"Que me haces sufrir,\nque me haces llorar,\ncon mi rondador\nme he de consolar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-02",21,"¿Qué me ves, que me estás viendo,\nqué tengo que no te doy?\nSi alguna cosa has perdido,\nvele bien, que yo no soy.",225,6,-1,256,"",0,4,"o",112,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-03",21,"Que se acabe, que se acabe,\nque se acabe en hora buena;\nya tengo quien me dé gusto,\nquien me dé gusto y no pena.",225,6,-1,256,"",0,4,"ea",59,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-04",21,"Que se acaben, que se acaben,\ncosas que se han de acabar;\nya pagando mis derechos,\ncualquiera me ha de enterrar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-05",21,"Qué solteros de este tiempo.\nsolteros de tanta fama;\ncuando ya le rinde el sueño,\nél mismo tiende la cama.",225,6,-1,256,"",0,4,"aa",90,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-06",21,"Qué triste ha sabido ser\nel perderse en la montaña;\nmás triste ha sabido ser\ncuando una mujer le engaña.",225,6,-1,256,"",1,4,"aa",213,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0084-07",21,"Qué triste se siente el hombre\nal amar sin ser amado,\nsolo desea morir\nal sentirse desgraciado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-01",21,"Querida guambrita,\npor venirte a ver\ncadenas de hierro\nme has hecho poner.",225,6,-1,256,"",6,4,"e",20,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-02",21,"Queriendo y amando\nse tiene el amor,\nno esperando pago\ndel mundo traidor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-03",21,"Queriéndote mismo estaba\ncon ese mayor cuidado;\nparece cosa de adrede\nque de mí te has olvidado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-04",21,"Quien bien ama de verdad,\nfiero es con su cariño;\nnunca existe mezquindad,\nporque estima como un niño.",225,6,-1,256,"",1,4,"io",176,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-05",21,"Quien te dio la cinta verde,\nque te dé la colorada;\nquien te dio la mala noche,\nque te dé la madrugada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0085-06",21,"Quiero, aborrezco y olvido;\nquiero olvidar y no puedo;\naborrezco y quiero más\na quien olvidar debo.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,85,85,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0085-07",21,"Quiero contar al revés\nlos golpes de mi fortuna:\nnueve, ocho, siete, seis,\ncinco, cuatro, tres, dos, una.",225,6,-1,256,"",0,4,"ua",56,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0086-01",21,"Quisiera con la mirada\narrancarte el corazón,\nque no tengas ya con qué\nencender más mi pasión.",225,6,-1,256,"",0,4,"o",31,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0086-02",21,"Quisiera con un suspiro\nterraplenar esa loma,\npara ver a mi negrita,\nojos de mansa paloma.",225,6,-1,256,"",0,4,"oa",86,0,-1,0,86,86,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0086-03",21,"Quisiera hacer una barca\ncon alas de cucaracha,\npara embarcar a la vieja,\nquedarme con la muchacha.",225,6,-1,256,"",0,4,"aa",556,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0086-04",21,"Quisiera, más bien, guambrita\nel no haberte conocido;\ncon eso no hubiera sido\nmi amor mal correspondido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0086-05",21,"Quisiera, pero no puedo\nhacer mi casa en el aire,\npara en el aire vivir,\ny no molestar a nadie.",225,6,-1,256,"",0,4,"ae",-1,0,-1,0,86,86,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0086-06",21,"Quisiera ser el pintor\npara pintar tu hermosura;\nte haré un ángel de ternura\ny la madre del amor.",225,6,-1,256,"",11,4,"o",72,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0086-07",21,"Quisiera ser picaflor\ny que tú fueras clavel,\npara chuparte la miel\ndel capullo de tu boca.",225,6,-1,256,"",5,4,"oa",-1,0,-1,0,86,86,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0087-01",21,"Quisiera ser un cocuyo\ny palpitar en tu seno;\ny ser para siempre tuyo,\ny brillar con el sereno.",225,6,-1,256,"",1,4,"eo",76,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0087-02",21,"Quisiera tener la pluma\ndel santo San Agustín,\npara escribir tus finezas\ndesde el principio hasta el fin.",225,6,-1,256,"",0,4,"i",211,0,-1,0,87,87,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0087-03",21,"Quisiera tener un carro\ncomo el carro del gobierno\npara llevar a mi suegra\na la puerta del infierno.",225,6,-1,256,"",0,4,"eo",225,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0087-04",21,"Quisiera yo que las viejas\nfueran como lagartijas;\npara matarlas a piedras\ny quedarme con las hijas.",225,6,-1,256,"",0,4,"ia",635,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0087-05",21,"Quítate de mi delante,\ncara de locro sin sal,\nhas de ver que te aborrezco\ncomo al pecado mortal.",225,6,-1,256,"",0,4,"a",1,0,-1,0,87,87,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0087-06",21,"Quítate de mi delante,\ncara de tusa quemada;\nporque ha de decir la gente\nque eres alma condenada-",225,6,-1,256,"",0,4,"aa",49,0,-1,0,87,87,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0087-07",21,"Quítate de mi delante,\ncon tu calzón remendado,\nporque ha de creer la gente\nque tú eres mi enamorado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,87,87,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0088-01",21,"Quítate de mi delante,\ncon tu cara de borrico;\nsi quieres hablar conmigo,\nanda lávate el hocico.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,88,88,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0088-02",21,"Quítate de mi delante,\ncon tu cara de elefante;\nsi a mejores no he querido,\nmucho más, a semejante.",225,6,-1,256,"",0,4,"ae",47,0,-1,0,88,88,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0088-03",21,"Quítate de mi delante,\ncon tu cara de sufrido;\nsabes que ya no te quiero:\nese amor está perdido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,88,88,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0088-04",21,"Recordarás, negra ingrata,\nel recuerdo que te di:\ncon la h, con la i,\ncon la j y con la o.",225,6,-1,256,"",3,4,"o",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0088-05",21,"Recordarás, tamborcito,\nlos gustos que hemos pasado,\nno sea cosa que el otro año\nyo muerto, vos pedaceado.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0088-06",21,"Recordaráste, guitarra,\nlos gustos que hemos pasado,\npara el otro hemos de estar\nvos quebrada, yo enterrado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0088-07",21,"Recuerda cuando ponías\ntus manos sobre las mías,\ny llorando me decías\nque nunca me olvidarías.",225,6,-1,256,"",0,4,"ia",214,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-01",21,"Riobamba de los diablos,\nsepultura de hombres vivos,\ndonde se amansan los bravos\ny lloran los afligidos.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-02",21,"Rosadita y sin pintura,\nay, mi guambra es un primor;\ntiene saco cardenillo\ny falda de otro color.",225,6,-1,256,"",0,4,"o",72,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-03",21,"Sacristán que vende cera,\nsin ser de la cerería;\n¿de dónde, pecata mea,\nsino de la sacristía?",225,6,-1,256,"",0,4,"ia",0,0,-1,0,89,89,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0089-04",21,"ale, cashanga,\nte peinaré;\ncon ese cabo\nte amarraré.",225,6,-1,256,"",6,4,"e",77,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-05",21,"Salí al campo a coger moras;\nen el camino, mortiños;\nqué feo ha sabido ser\nel amor entre vecinos.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-06",21,"Salí, lucero del cielo:\nsalí si sabes querer;\naunque te tapen las nubes,\nsalí si sabes querer.",225,6,-1,256,"",0,4,"e",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0089-07",21,"Salió la gata,\nsalió a mear;\ny vino el chúshig,\nle hizo llorar.",225,6,-1,256,"",6,4,"a",21,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0090-01",21,"San Juan me ha hecho un pedido;\nRiobamba me ha de llevar;\nlas muchachitas de Calpi\nllorando se han de quedar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0090-02",21,"San Juan y la Magdalena\nse fueron a coger guabas,\nSan Juan volvió sin calzones,\nla Magdalena, sin naguas.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,90,90,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0090-03",21,"San Pedro se entretenía\ntirando bombas abajo;\nsalió Jesús y le dijo:\nestate quieto, carajo.",225,6,-1,256,"",0,4,"ao",168,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0090-04",21,"Sapito de la quebrada,\nchiquito, pero ruidoso;\nsapito de las mujeres,\nhediondo, pero sabroso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,90,90,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0090-05",21,"Sarampión golpea la puerta;\nviruela, ve a ver quién es:\ncuchimuro soy, señora,\nlos cursos vendrán después.",225,6,-1,256,"",0,4,"e",218,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0090-06",21,"Saturnino fue por vino,\nperdió el jarro en el camino.\nPobre jarro, pobre vino,\npobre culo de Antonino.",225,6,-1,256,"",0,4,"io",199,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0090-07",21,"Se fue, se fue,\nse fue mi palomita;\nentre el llanto y la amargura\nse fue, se fue.",225,6,-1,256,"",3,4,"e",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-01",21,"Se juega con agua,\ntambién con polvito;\nse baila con guambras\nbien abrazaditos.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-02",21,"Semana catorce días\nhace que yo no te he visto,\npero ahora que te veo,\nhasta el pico tienes güisto.",225,6,-1,256,"",0,4,"io",273,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-03",21,"Sembré lenteja,\ncoseché alverja,\nsaqué una guambra,\nme salió vieja.",225,6,-1,256,"",6,4,"ea",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-04",21,"Sentadita me amanezco,\narrimadita a mi almohada,\nesperando que se vaya\nesta vieja condenada.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-05",21,"eñora, amarre a su perro,\nque mucho me martiriza,\nya me ha roto el calzoncillo\ny el cuello de la camisa.",225,6,-1,256,"",0,4,"ia",68,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-06",21,"Señora de centro blanco\ny debajero amarillo,\nahora tengo una cosita\ndentro de mis calzoncillos.",225,6,-1,256,"",0,4,"io",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0091-07",21,"Señora dueña de casa,\naliste tamal y taza;\nsi no tiene qué brindar,\ncorra detrás de la casa.",225,6,-1,256,"",0,4,"aa",123,0,-1,0,91,91,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0092-01",21,"Señora dueña de casa,\nprésteme su corredor,\npara cantarle un versito\na la dueña de mi amor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,92,92,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0092-02",21,"Señora María Rosa,\npóngase bien los calzones,\nporque me estoy yendo a misa:\nno quiero ver tentaciones.",225,6,-1,256,"",0,4,"oe",34,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0092-03",21,"Señora, no soy de aquí,\nyo soy de aquí al otro lado,\ncon mi camisa bordada\ny mi calzón colorado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0092-04",21,"Señora, prenda la luz,\nque aquí le traigo el candil;\nsaque chicha del bototo\ny aguardiente del barril.",225,6,-1,256,"",0,4,"i",290,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0092-05",21,"Señores, les vendo un gallo\nde la cría de Juan Vara;\nes un gallo misterioso:\nsin tener patas, se para.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0092-06",21,"Señores, no sé qué pasa,\nque se le ha dado en parar\na mi caballo en la esquina,\ny no quiere caminar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0092-07",21,"Señores, no soy de aquí,\nque yo soy de Manabí,\ny esta es la primera vez\nque yo canto por aquí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,92,92,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0093-01",21,"Señores, no soy de aquí,\nyo soy del gran Pelileo;\nsi no me dan chicha y trago,\nseguro que les peleo.",225,6,-1,256,"",0,4,"eo",66,0,-1,0,93,93,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0093-02",21,"Señores, no soy de aquí,\nyo nací al otro lado,\nhijo de gallina fina\ny de gallo colorado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,93,93,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0093-03",21,"Señores que están oyendo\nno hablen mal de aquel que canta,\nporque el polvo del camino\nle ha secado la garganta.",225,6,-1,256,"",0,4,"aa",148,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0093-04",21,"Señores, ¿quieren saber\ncómo enamora el soldado?\nOfreciendo cuatro reales\ny el borreguito robado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,93,93,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0093-05",21,"Señores, ¿quieren saber\ncómo enamoran los chagras?:\nSeñora, quiérame a mí,\nyo tengo yunta de guagras.",225,6,-1,256,"",0,4,"aa",730,0,-1,0,93,93,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0093-06",21,"Señores, ¿quieren saber\nel genio de mi mujer?\nA la otra no puede ver;\nella sola quiere ser.",225,6,-1,256,"",0,4,"e",20,0,-1,0,93,93,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0093-07",21,"Si aborreciéndome estás,\nmás y más te he de querer;\nsi prueba quieres hacer,\naborréceme y verás.",225,6,-1,256,"",11,4,"a",51,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-01",21,"Si acaso no tengo plata,\nvendería mi camisa,\ncon tal de pasar jugando\nhasta el día de ceniza.",225,6,-1,256,"",0,4,"ia",420,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-02",21,"Si alguna felicidad\nme ha de venir con tardanza,\nmejor quisiera morir\nsepultando a la esperanza.",225,6,-1,256,"",0,4,"aa",163,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-03",21,"Si aún de muerto yo te recuerdo,\nvos en la vida me olvidarás;\nlleva mi alma desilusión,\nhas destrozado mi corazón.",225,6,-1,256,"",3,4,"o",31,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-04",21,"Si cien años te perdieras\ndoscientos te buscaría;\nno encontrándote en el suelo,\nhasta el cielo pasaría.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-05",21,"Si creyera en tu pasión,\nyo adoraría tus prendas;\nte entregara el corazón,\npero temo que lo vendas.",225,6,-1,256,"",1,4,"ea",536,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-06",21,"Si de veras me quisieras\nno me vieras padecer;\nrompieras dificultades\ny me vinieras a ver.",225,6,-1,256,"",0,4,"e",20,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0094-07",21,"Si el amor fuera pecado\nya debían perdonarme,\ny no por haberte amado\nsino por seguirte amando.",225,6,-1,256,"",5,4,"ao",-1,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-01",21,"Si el intestino del mono\nse pudiera sazonar,\nhiciera locro de tripas\ny huasca para enlazar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-02",21,"Si el quererte ha sido un crimen,\ncriminal no he sido yo;\ncriminal fue tu hermosura\nque a quererte me obligó.",225,6,-1,256,"",0,4,"o",2,0,-1,0,95,95,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0095-03",21,"Si el verte me da la muerte,\ny el no verte me da vida;\nquiero mil veces la muerte\ny no, sin verte, la vida.",225,6,-1,256,"",1,4,"ia",-1,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-04",21,"Si es que te vas a casar,\nyo no te aconsejo, hermano,\nporque las suegras entregan\nhijas de segunda mano.",225,6,-1,256,"",0,4,"ao",81,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-05",21,"Si esta casa se cayera\na todos nos aplastara\ny a la vieja de mi suegra\nhecha cacho le dejara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-06",21,"Si esta vida es un martirio,\nel suicidio es un deber,\nporque solo con la muerte\nse deja de padecer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0095-07",21,"Si estuviera prisionero\nen la más negra prisión,\nno sufriera tantas penas\nlejos de tu corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,95,95,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-01",21,"Si la luna fuera queso,\nalcanzando me comiera;\nsi la guambra fuera mía,\nadorándola tuviera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,96,96,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0096-02",21,"Si me caso y tengo suegra\nha de ser a condición\nque si al año no se muere\nla boto por el balcón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-03",21,"Si mi cholita quisiera,\ncasa de teja le diera;\ntodas las cosas vendiera,\ny hasta el ponchito empeñara.",225,6,-1,256,"",5,4,"aa",-1,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-04",21,"Si mi suegra fuera buena\ny no, como es, resentida,\nmi mujer sería santa\ny no serpiente dormida.",225,6,-1,256,"",0,4,"ia",37,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-05",21,"Si mi suegra fuera cárcel\ny mi suegro calabozo,\ny mi mujer carcelera,\nyo fuera el preso dichoso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-06",21,"Si mis amigos perdiera\ndoscientos años buscara;\nsi supiera que se han muerto\nal otro mundo pasara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0096-07",21,"Si no me quieres,\nblanca azucena;\nsi la azucena es blanca,\ntú eres morena.",225,6,-1,256,"",6,4,"ea",59,0,-1,0,96,96,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0097-01",21,"Si no sabes, no te metas\nen lo profundo a nadar;\na la primer zambullida\nlos diablos te han de cargar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,97,97,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0097-02",21,"Si plata tuviera\nalcalde yo fuera,\na que no le nombren\na un bruto cualquiera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,97,97,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0097-03",21,"Si plata tuviera\ntrapiche comprara;\nel jugo bebiera\ny me emborrachara.",225,6,-1,256,"",1,4,"aa",57,0,-1,0,97,97,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0097-04",21,"Si pluma de oro tuviera,\npapel de plata comprara;\ncon la sangre de mis venas\nhasta tu nombre firmara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,97,97,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0097-05",21,"Si por pobre me desprecias\npégate de un mercader\nque te vista toda en seda;\nojos tengo para ver.",225,6,-1,256,"",0,4,"e",20,0,-1,0,97,97,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0097-06",21,"Si por pobre me desprecias\nyo te concedo razón;\na cambio de mi pobreza\nyo te doy mi corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,97,97,"","",0,"","","",8,0,0,[],"",""],["ortiz_ecuador-p0097-07",21,"Si por ti yo vivo triste;\nsi por ti vivo sufriendo;\nguambrita, por qué te fuiste,\ndejándome padeciendo.",225,6,-1,256,"",1,4,"eo",52,0,-1,0,97,97,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0098-01",21,"Si pudiera ser tu gallo\nen tu palte cantaría,\ny antes de que te despiertes:\nbuenos días te diría.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,98,98,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0098-02",21,"Si pudieras caminar,\ncorazón, yo te enviaría,\na que vayas a cambiar\ntristeza por alegría.",225,6,-1,256,"",1,4,"ia",0,0,-1,0,98,98,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0098-03",21,"Si quieres que yo te escriba,\nharemos un documento;\nvos firmarás en el agua,\nyo he de firmar en el viento.",225,6,-1,256,"",0,4,"eo",94,0,-1,0,98,98,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0098-04",21,"Si taita Dios me pidiera\nque aleje de ti mi amor;\nyo le dijera llorando:\neso no puedo, Señor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,98,98,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0098-05",21,"Si tu boquita fuera\nde chocolate;\nyo me la pasaría\nbate que bate.",225,6,-1,256,"",6,4,"ae",384,0,-1,0,98,98,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0098-06",21,"Si tu casa fuera cárcel\ny tú fueras mi carcelera,\ndurante toda mi vida\nde tu casa no saliera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,98,98,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0098-07",21,"Si tu casa fuera iglesia\ny tu cuarto fuera altar,\ny tu cama, sepultura,\nvivo me fuera a enterrar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,98,98,"","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",4,0,0,[],"",""],["ortiz_ecuador-p0099-01",21,"Si tu marido es celoso,\ndale a comer mazamorra;\ny si te sigue celando,\nsíguele mazamorreando.",225,6,-1,256,"",5,4,"ao",33,0,-1,0,99,99,"","",0,"","","",7,0,0,[],"",""],["ortiz_ecuador-p0099-02",21,"Si tú me olvidas,\nblanca azucena;\nsi la azucena es blanca,\ntú eres morena.",225,6,-1,256,"",6,4,"ea",59,0,-1,0,99,99,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0099-03",21,"Si tú me quieres,\nflor de amapola,\nvente conmigo,\nno estarás sola.",225,6,-1,256,"",6,4,"oa",321,0,-1,0,99,99,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0099-04",21,"Si tu mujer es celosa,\ndale a tomar chocolate;\ny si te sigue celando,\nsíguele chocolateando.",225,6,-1,256,"",5,4,"ao",33,0,-1,0,99,99,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0099-05",21,"Si tú tienes corazón,\ncompadécete de mí.\nSi no tienes corazón,\nyo te daré, yo te daré.",225,6,-1,256,"",5,4,"e",-1,0,-1,0,99,99,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0099-06",21,"Si una vela se te apaga,\nno la vuelvas a encender;\ny si un amor te traiciona,\nno lo vuelvas a querer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,99,99,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0099-07",21,"Si yo fuera el confesor,\ny ella a mis pies se postrara,\nle diera de penitencia\nel mirarnos cara a cara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,99,99,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-01",21,"Si yo fuera pajarillo\na tu sombra diera un vuelo;\nte pediría un besito,\nlástima que no lo puedo.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,100,100,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0100-02",21,"Si yo me casé contigo\nfue por dormir en tu cama;\ny ahora sales con el cuento,\nque el colchón es de tu mama.",225,6,-1,256,"",3,4,"aa",90,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-03",21,"Siento que me he de morir;\nque me he de morir yo siento;\nsiento que otros gozarán\nlo que yo he gozado un tiempo.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-04",21,"Siento que te has de morir\ny te has de hacer calavera;\nantes de que eso suceda,\nanda dando como quiera.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-05",21,"Sin duda que tienes\ntu amor ocupado\npara que tan pronto\nme hayas olvidado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-06",21,"Sobre las olas\nme he de embarcar:\nsi tú me olvidas,\nte he de olvidar.",225,6,-1,256,"",6,4,"a",21,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0100-07",21,"Solo por quererte a ti,\nhasta mi gato vendí;\ngatito de cuatro reales,\nen real y medio vendí.",225,6,-1,256,"",0,4,"i",-1,0,-1,0,100,100,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-01",21,"Solterita soy, señores;\nno me gusta ser casada,\npara no vivir sufriendo\ndel marido traicionada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-02",21,"Sonarás, tambor,\nno me harás hablar;\nsi me hacer hablar,\npalo te he de dar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-03",21,"Sortijita de oro fino,\npasada por tres punteros;\nnegrita, dame tus brazos,\nque los dos somos solteros.",225,6,-1,256,"",0,4,"eo",22,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-04",21,"Soy como el colibrí\nque anda de flor en flor;\npica acá, pica allá,\nhasta dar con lo mejor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-05",21,"Soy soltero y no me caso;\nsoy casado y no hago vida;\npara vivir mal casado,\nmejor vivo amancebado.",225,6,-1,256,"",5,4,"ao",14,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-06",21,"Suene la orquesta animada\ny no cese ni un momento,\npues quiero bailar un \"alza\"\ncon mi adorado tormento.",225,6,-1,256,"",0,4,"eo",94,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0101-07",21,"Tanta cinta colorada,\ntanto zarcillito de oro;\nsi la vaca fuera honrada,\ncuernos no tuviera el toro.",225,6,-1,256,"",1,4,"oo",85,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0102-01",21,"Tantas idas y venidas,\ny pasadas por aquí,\nse acabarán tus zapatos;\nnada sacarás de mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,102,102,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0102-02",21,"Tanto subir por acá;\ntanto bajar por aquí;\nse acabarán mis zapatos\ny otros gozarán de ti.",225,6,-1,256,"",0,4,"i",23,0,-1,0,102,102,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0102-03",21,"Tanto te amo que te aguardo,\nte espero en el Aguarico,\npara darte un beso rico\nen tu boquita de nardo.",225,6,-1,256,"",11,4,"ao",210,0,-1,0,102,102,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0102-04",21,"Tarde de la noche vengo\nporque de día no puedo;\ncomo como de lo ajeno,\ntemo que me coja el dueño.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,102,102,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0102-05",21,"Te mandé ayer una carta\ncon la sangre de mis brazos;\nla cogiste y la olvidaste;\nmi amor hiciste pedazos.",225,6,-1,256,"",0,4,"ao",132,0,-1,0,102,102,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0102-06",21,"Te quiero como a mis ojos,\ncomo a mis ojos te quiero;\npero más quiero a los míos\nporque ellos te conocieron.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,102,102,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0102-07",21,"Te quiero y te he de querer\nhasta que la suerte quiera,\nhasta sepultar mis huesos\nen el centro de la tierra.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,102,102,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0103-01",21,"Te quise y te he de querer,\nhasta que me dé la gana.\nen esto no tienen parte\nni tu taita, ni u mama.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-02",21,"Te quise y tú me dejaste,\ncon una pena en el alma;\nte ruego regreses pronto\na devolverme la calma.",225,6,-1,256,"",0,4,"aa",125,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-03",21,"Te vi, te quise y te amé,\nmas todo fue de improviso;\nrecordarás, vida mía,\nde este amor que bien te quiso.",225,6,-1,256,"",0,4,"io",92,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-04",21,"Tejerás una corona\nde laureles y de olivos\ny en la tarjeta pondrás\nque estoy muerto entre los vivos.",225,6,-1,256,"",0,4,"io",513,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-05",21,"Tengo una guambra bonita.\ny es tan bonita y señora,\nque hasta le gusta embriagarse\ncon chicha de pura jora.",225,6,-1,256,"",3,4,"oa",107,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-06",21,"Tengo una muchacha adentro,\ncarita de remolacha,\nboquita de puerco tierno\ny ojitos de cucaracha.",225,6,-1,256,"",0,4,"aa",556,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0103-07",21,"Tente, Ramírez,\ntente en tu silla,\nno te suceda\nlo que a Castilla.",225,6,-1,256,"",6,4,"ia",162,0,-1,0,103,103,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0104-01",21,"Tienes los ojos negros\ncomo mi suerte;\nmírame aunque por ellos\nme des la muerte.",225,6,-1,256,"",6,4,"ee",134,0,-1,0,104,104,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0104-02",21,"Tira la lanza\npor la ventana;\nhiéreme (rómpeme) el pecho,\nmenos el alma.",225,6,-1,256,"",6,4,"aa",-1,0,-1,0,104,104,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0104-03",21,"Tirana guambra,\nno seas así;\ndéjale al otro,\nquiéreme a mí.",225,6,-1,256,"",6,4,"i",23,0,-1,0,104,104,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0104-04",21,"Toca, toca la tambora,\ny acábala de romper,\nque aquí tengo cuatro reales,\npara mandarle a coser.",225,6,-1,256,"",3,4,"e",20,0,-1,0,104,104,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0104-05",21,"Toda la noche he pasado,\nagarrada a mi denario,\npidiendo a Dios que se muera\nel bandido Comisario.",225,6,-1,256,"",0,4,"ao",25,0,-1,0,104,104,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0104-06",21,"Toda la noche he pasado\narrimado en el pilar;\nsalí, pues, guambrita linda,\nya son horas de orinar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,104,104,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0104-07",21,"Toda la noche pasaré\njunto a mi longa con amor;\ntalvez mañana lloraré\nmi soledad y mi amargor.",225,6,-1,256,"",1,4,"o",72,0,-1,0,104,104,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0105-01",21,"Toda la vida te he dicho\nque amándote he de morir;\nsin tu sombra, sin tu abrigo,\nqué alivio voy a sentir.",225,6,-1,256,"",0,4,"i",157,0,-1,0,105,105,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0105-02",21,"Todas las mujeres de hoy\nse parecen a la uvilla;\ncuando las miran los hombres\nmueven más la rabadilla.",225,6,-1,256,"",0,4,"ia",162,0,-1,0,105,105,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0105-03",21,"Todas las mujeres tienen\nen el ombligo un dedal\ny más abajito tienen\nla vaina de mi puñal.",225,6,-1,256,"",1,4,"a",1,0,-1,0,105,105,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0105-04",21,"Todas las mujeres tienen\nen el ombligo un piano;\ny más abajito tienen\nlo que gusta al Feliciano.",225,6,-1,256,"",1,4,"ao",81,0,-1,0,105,105,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0105-05",21,"Todas las mujeres tienen\nen el ombligo un rosario\ny más abajito tienen\nlas barbas del comisario.",225,6,-1,256,"",1,4,"ao",25,0,-1,0,105,105,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0105-06",21,"Todas las mujeres tienen\nen el ombligo una flor;\nnosotros también tenemos\nal señor Gobernador.",225,6,-1,256,"",0,4,"o",72,0,-1,0,105,105,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0105-07",21,"Todas las mujeres tienen\nen su pecho dos penachos,\ny más abajito tienen\nla fábrica de muchachos.",225,6,-1,256,"",1,4,"ao",463,0,-1,0,105,105,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0106-01",21,"Todo es a la buena vida,\nen especial la mujer\nes fortuna para el hombre,\npero sabiendo escoger.",225,6,-1,256,"",0,4,"e",20,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-02",21,"Todo es capricho,\ntodo es venganza;\ncon esta guambra\nya no hay confianza.",225,6,-1,256,"",6,4,"aa",-1,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-03",21,"Todos los hombres parecen\nparientes del gallinazo;\ndespués de comer la carne\ndel hueso ya no hacen caso.",225,6,-1,256,"",0,4,"ao",145,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-04",21,"Todos los palos del monte\nnacen con destinación;\nunos nacen para santos,\ny otros para hacer carbón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-05",21,"Todos son chistes,\ntodos son vainas;\nhasta los cholos\nponen polainas.",225,6,-1,256,"",6,4,"aa",731,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-06",21,"Toma la vida,\ndame la muerte;\npara qué quiero\nvida sin suerte.",225,6,-1,256,"",6,4,"ee",134,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0106-07",21,"Toma, para qué queriendo,\ntoma, para qué buscando\namores en tierra ajena;\nahora ya estarás llorando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,106,106,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-01",21,"Tomaremos una copa,\ny con ella a divertirnos;\ndivirtiéndonos, señores,\nni la muerte ha de venir.",225,6,-1,256,"",5,4,"i",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-02",21,"Tormentos y penas rasgan\nmi pecho despedazado;\nno fuera tan desgraciado,\nay, corazón, si pensaras.",225,6,-1,256,"",5,4,"aa",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-03",21,"Toro blanco, toro negro,\ntorito de mil colores,\nno me mates con tus astas,\nmátame con tus amores.",225,6,-1,256,"",0,4,"oe",5,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-04",21,"Toro blanco, toro pinto,\nhijo de la vaca mora;\nvení para hacerte un lance\ndelante de mi señora.",225,6,-1,256,"",0,4,"oa",107,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-05",21,"Tras de la loma\ncanta un payaso,\ngracias, guambrita,\ndel canelazo.",225,6,-1,256,"",6,4,"ao",43,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-06",21,"Tras la loma de mi casa\ncanta y llora una torcaza;\ny en el canto va diciendo:\nque es fregado el que se casa.\nqué pendejo",225,6,-1,256,"",7,5,"eo",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0107-07",21,"Tres años catorce meses\nhacen mis ojos no verte;\nese modo de ausentarte\nes causa para mi muerte.",225,6,-1,256,"",0,4,"ee",134,0,-1,0,107,107,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-01",21,"Tres ciudades vengo andando:\nCuenca, Loja, Manabí;\ndía y noche padeciendo,\nnegrita, por verte a ti.",225,6,-1,256,"",0,4,"i",23,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-02",21,"Tres cosas hay en la vida:\nsalud, dinero y amor;\ny el que tenga estas tres cosas\ndebe dar gracias a Dios,",225,6,-1,256,"",0,4,"o",-1,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-03",21,"Tres cosas te respondí,\nlas que son firmes en mí:\nel quererte, el adorarte,\ny el no olvidarme de ti.",225,6,-1,256,"",0,4,"i",23,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-04",21,"Tres veces me fui a la iglesia;\ntres veces a confesar;\ntres veces le dije al cura,\nque contigo me he de casar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-05",21,"Tu chicha y trago\nme tiene así,\nprevaricando\nfuera de mí.",225,6,-1,256,"",6,4,"i",23,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0108-06",21,"Tú dices que no me quieres,\nsolo por verme llorar;\nlloraré porque te quise,\nno porque me ha de faltar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,108,108,"","",0,"","","",12,0,0,[],"",""],["ortiz_ecuador-p0108-07",21,"Tú dices que tengo dos.\nno es cierto, todo es mentira;\nyo no tengo ni uno ni otro,\nsolo tú, vidita mía.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,108,108,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-01",21,"Tú dices que yo estoy loco\nporque me muero sin verte;\nsi tú te burlas de mí,\nde qué me sirve quererte.",225,6,-1,256,"",0,4,"ee",134,0,-1,0,109,109,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-02",21,"Tú eres el sol que idolatro\ny la luna que venero;\ntú eres la cadena de oro\nque me tiene prisionero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,109,109,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-03",21,"Tú eres la niña bonita;\ntú eres la niña de fama,\nla única seleccionada\npara nuera de mi mama.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,109,109,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-04",21,"Tú me quieres, yo te quiero más;\ntu familia no me puede ver;\npero a pesar de todo ello,\nserás mía.",225,6,-1,256,"",3,4,"ia",-1,0,-1,0,109,109,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-05",21,"Tú mismo tienes la culpa\npor andar enamorado;\nasí como pagas tú,\nasí mismo te he pagado.",225,6,-1,256,"",0,4,"ao",14,0,-1,0,109,109,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0109-06",21,"Tú representas las olas;\nyo las orillas del mar:\ntú te acercas y me besas;\nyo te acaricio y te vas.",225,6,-1,256,"",0,4,"a",-1,0,-1,0,109,109,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0109-07",21,"Tus ojos son dos luceros;\nque alumbran los basureros;\ntus patas son dos estacas;\npara amarrar a las vacas,\na que mamen los terneros.",225,6,-1,256,"",7,5,"eo",22,0,-1,0,109,109,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0110-01",21,"Tuviste valor, mujer,\npara dejarme burlado;\npero un día te he de ver\ncon algún tonto porfiado.",225,6,-1,256,"",1,4,"ao",14,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-02",21,"Un abrazo vale medio,\nuna mucha vale real:\ny subiéndote a la cama,\nreal y medio te he de dar.",225,6,-1,256,"",0,4,"a",-1,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-03",21,"Un cofrecito tengo\npara ir guardando\ngoces y pesadumbres\nque me has causado.",225,6,-1,256,"",6,4,"ao",-1,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-04",21,"Un día de esta semana\nnos iremos a Otavalo,\npara comprar ropa fina,\ny hasta un bonito regalo.",225,6,-1,256,"",0,4,"ao",71,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-05",21,"Un día, junto a un panteón,\nme juraste amor eterno;\ndespués, a los pocos días,\nviolaste tu juramento.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-06",21,"Un día le vi a la muerte\nencima de un campanario,\ny le dije: muerte mía,\ntócame las siete.",225,6,-1,256,"",5,4,"ee",-1,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0110-07",21,"Un día le vi a mi novia\ndebajo de un floripondio;\ny el rato que me acerqué\nella se escondio.",225,6,-1,256,"",3,4,"oo",732,0,-1,0,110,110,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0111-01",21,"Un indio se fue corriendo\ny se pegó un resbalón;\nvolteando la cara dijo:\neste indio sí que es cabrón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,111,111,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0111-02",21,"Un lucero se ha perdido\ny en el cielo no parece;\npor tu techo pasa el rastro\ny en tu pecho resplandece.",225,6,-1,256,"",0,4,"ee",64,0,-1,0,111,111,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0111-03",21,"Un negrito bien negrito\nse subió a una terraza;\nla vieja dueña creía\nque el diablo estaba en su casa.",225,6,-1,256,"",0,4,"aa",123,0,-1,0,111,111,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0111-04",21,"Un negro con una negra\nse casaron en Ambato;\ny ellos tuvieron un guagua\ncon una cara de gato.",225,6,-1,256,"",0,4,"ao",19,0,-1,0,111,111,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0111-05",21,"Un viejito y una vieja\nno tenían dentadura;\nal viejo le dieron sopa,\ny a la vieja, carne dura.",225,6,-1,256,"",0,4,"ua",17,0,-1,0,111,111,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0111-06",21,"Un viejito y una vieja\nse fueron de remolacha;\nla viejita que se agacha\ny el viejo que la remacha.",225,6,-1,256,"",0,4,"aa",556,0,-1,0,111,111,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0111-07",21,"Un viejito y una vieja\nfueron a jugar futbol;\nla viejita que se agacha\ny el viejo le mete un gol.",225,6,-1,256,"",0,4,"o",24,0,-1,0,111,111,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0112-01",21,"Una blanca vale un peso,\nlas morenas, dos tamales;\nuna chica, pan con queso,\nuna negra, dos tamales.",225,6,-1,256,"",1,4,"ae",-1,0,-1,0,112,112,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0112-02",21,"Una carta te mandé\nescrita en hojas de tambo;\ny en los renglones decía:\nAdiós, señora de Chambo.",225,6,-1,256,"",0,4,"ao",733,0,-1,0,112,112,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0112-03",21,"Una estrella se ha perdido\ny en el cielo no aparece;\npor tu puerta pasa el rastro\ny en tu pecho resplandece.",225,6,-1,256,"",0,4,"ee",64,0,-1,0,112,112,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0112-04",21,"Una guambra estoy queriendo\nmedio chusca y corcovada;\ndesobligo me está dando\nporque se orina parada.",225,6,-1,256,"",0,4,"aa",49,0,-1,0,112,112,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0112-05",21,"Una guambra me decía\ncuando le tuve debajo,\najusta, hombre cobarde,\nno malogres tu trabajo.",225,6,-1,256,"",0,4,"ao",168,0,-1,0,112,112,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0112-06",21,"Una guambra se durmió\na la puerta del alcalde;\npagó 3 pesos de multa\npudiendo dormir de balde.",225,6,-1,256,"",0,4,"ae",734,0,-1,0,112,112,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0112-07",21,"Una monja se empachó\npor tomar agua bendita\ny en el empacho tenía\nuna monja chiquitita.",225,6,-1,256,"",0,4,"ia",-1,0,-1,0,112,112,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0113-01",21,"Una palma en la ladera,\n¿cuántos años durará?\nY un amorcito que tengo,\n¿cuántas traiciones me hará?",225,6,-1,256,"",0,4,"a",9,0,-1,0,113,113,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0113-02",21,"Una posada, por Dios;\nno pido con grosería;\ncansado de tanto andar,\nvengo de la romería.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,113,113,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0113-03",21,"Una prueba de cariño\nes lo que espero de ti,\npara no vivir dudando\nsi has nacido para mí.",225,6,-1,256,"",0,4,"i",23,0,-1,0,113,113,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0113-04",21,"Una tarde pajariando\ndebajo de un arbolito;\nyo vide una celemba\ndurmiendo como un mosquito.",225,6,-1,256,"",0,4,"io",119,0,-1,0,113,113,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0113-05",21,"Una vez que ya nos vamos\ncantemos la despedida;\nmos de volver a cantar\notro año, si Dios da vida.",225,6,-1,256,"",0,4,"ia",37,0,-1,0,113,113,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0113-06",21,"Una vieja con un viejo\nse fueron a hacer un guiso;\nla vieja puso la carne (la papa)\ny el viejo puso el chorizo.",225,6,-1,256,"",3,4,"io",95,0,-1,0,113,113,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0113-07",21,"Una vieja me dio un beso,\nque me supo a cucaracha;\nqué vieja tan atrevida,\nhabiendo tanta muchacha.",225,6,-1,256,"",0,4,"aa",556,0,-1,0,113,113,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0114-01",21,"Una vieja se cayó\ndesde encima de una iglesia;\nno se hizo nada los pies,\nporque cayó de cabeza.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,114,114,"","",0,"","","",4,0,0,[],"",""],["ortiz_ecuador-p0114-02",21,"Una vieja se echó un pedo\ndetrás del altar mayor,\ntodos salieron corriendo\ncreyendo que era temblor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,114,114,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0114-03",21,"Una vieja se meó\nen el pretil de la iglesia\ny el cura se lo tomó\ncreyendo que era cerveza.",225,6,-1,256,"",0,4,"ea",-1,0,-1,0,114,114,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0114-04",21,"Una vieja se sentó\nencima de un avispero,\ny las pícaras avispas\nle picaron el trasero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,114,114,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0114-05",21,"Una vieja se sentó\nencima de un hormiguero;\ny las pícaras hormigas\nse equivocaron de agujero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,114,114,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0114-06",21,"Una vieja se sentó\nencima de un puerco flaco;\ny se levantó gritando\nporque el puerco era berraco.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,114,114,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0114-07",21,"Una vieja se sentó\npor encima de un papayo;\nsalió un sapito y le dijo:\nHola, cómo estás, tocayo.",225,6,-1,256,"",0,4,"ao",293,0,-1,0,114,114,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0115-01",21,"Una vieja y un viejito\nse cayeron en un pozo\ny la viejita decía:\nqué viejito tan sabroso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,115,115,"","",0,"","","",9,0,0,[],"",""],["ortiz_ecuador-p0115-02",21,"Una viudita lloraba\ncon llanto disimulado,\nporque ya estaba pensando\nen su querido arropado.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,115,115,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0115-03",21,"Una viudita lloraba\nla muerte de su marido;\ny debajito del catre\ntenía al otro escondido.",225,6,-1,256,"",0,4,"io",101,0,-1,0,115,115,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0115-04",21,"Vámonos de estos terrenos\na vivir en Manabí;\nponete los zapatitos,\nlevanta y vamos de aquí.",225,6,-1,256,"",3,4,"i",23,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0115-05",21,"Vamos conmigo,\ncon quien te adora;\nsoy solterito\ny riobambeño.",225,6,-1,256,"",6,4,"eo",-1,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0115-06",21,"Vamos, guambra de mi vida,\nvamos prontito a bailar,\nsi acaso te faltan fuerzas\nun traguito te he de dar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0115-07",21,"Vamos, guambrita,\nbótate al río;\nasí botale\nal amor mío.",225,6,-1,256,"",6,4,"io",3,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0116-01",21,"Van y vienen los pesares\ncomo las olas del mar,\ny tengo que lamentarme\nde no poderte olvidar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0116-02",21,"Veinticinco limones\ntiene una rama,\ny amanecen cincuenta\npor la mañana.",225,6,-1,256,"",6,4,"aa",-1,0,-1,0,116,116,"","",0,"andina_t2, barcenas_marinera","","",6,0,0,[],"",""],["ortiz_ecuador-p0116-03",21,"Versos van y versos vienen;\nno se me han de terminar;\naquí tengo un saco lleno\ny otrito por empezar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,116,116,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0116-04",21,"Virgen pura inmaculada,\nte pido hacer un favor,\nque cuides a mi negrita\nque causa mucho dolor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0116-05",21,"Viva el sol, viva la luna,\nviva la flor de romero;\nviva la fortuna mía,\nla gloria de ser soltero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,116,116,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0116-06",21,"Vuelve, palomita ausente,\nmi pecho es tu palomar;\ncomo supe amar ardiente,\nasí sepa perdonar.",225,6,-1,256,"",1,4,"a",21,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0116-07",21,"Y como el jueguito es juego,\nno se pasa por mojar;\nno hay mejor con una hembra\nirse a la cama a acostar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-01",21,"Y esas tus caricias son\nmisas de cuerpo presente;\ncuando me ves, me acaricias,\nte olvidas estando ausente.",225,6,-1,256,"",0,4,"ee",15,0,-1,0,117,117,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0117-02",21,"Y este trago tan bonito,\nnacido de verdes matas,\nal hombre más poderoso\nle hace andar en cuatro patas.",225,6,-1,256,"",0,4,"aa",328,0,-1,0,117,117,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-03",21,"Ya las nubes vienen bajas\namenazando llover;\nasí estará mi guambrita\ncomenzando a padecer.",225,6,-1,256,"",0,4,"e",20,0,-1,0,117,117,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-04",21,"Ya los jueces sentenciaron\na diez años de prisión;\nlo que pido es a mi madre\nque me dé su bendición.",225,6,-1,256,"",0,4,"o",31,0,-1,0,117,117,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-05",21,"Ya me voy de estos terrenos,\ndejando a mi amor en calma,\ny si vuelvo, volveré.\ny si no, volverá mi alma.",225,6,-1,256,"",0,4,"aa",125,0,-1,0,117,117,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-06",21,"Ya me voy de tu terreno;\nya no te he de molestar;\nlas yerbitas de tu casa\npronto se han de marchitar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,117,117,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0117-07",21,"Ya me voy, ya me estoy yendo,\nya me estarán esperando;\nsi me demoro un poquito\nya me estarán regañando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,117,117,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0118-01",21,"Ya no paso por tu casa\nni de noche ni de día,\nporque ha de pensar la gente,\nque te quiero todavía.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,118,118,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0118-02",21,"Ya no quiero ser soldado,\nla guerra me tiene loco:\nel trabajo es redoblado,\ny el sueldo que gano es poco.",225,6,-1,256,"",1,4,"oo",152,0,-1,0,118,118,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0118-03",21,"Ya no se juega\ncon serpentinas,\nporque están caras\nlas cosas finas.",225,6,-1,256,"",6,4,"ia",243,0,-1,0,118,118,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0118-04",21,"Ya que por fin has vivido,\npuedes morir, corazón;\namaste ya y sufriste,\nhas cumplido tu misión.",225,6,-1,256,"",0,4,"o",31,0,-1,0,118,118,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0118-05",21,"Ya repican las campanas,\nya sale la procesión;\nya salen las cabezonas\na servir de tentación.",225,6,-1,256,"",0,4,"o",31,0,-1,0,118,118,"","",0,"andina_t2","","",3,0,0,[],"",""],["ortiz_ecuador-p0118-06",21,"Ya sale la luna hermosa,\nalumbrando el carrizal:\nya viene esta buenamoza\ncon las tortillas sin sal.",225,6,-1,256,"",1,4,"a",1,0,-1,0,118,118,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0118-07",21,"Ya sale la luna hermosa\nredonda como un colchón,\nasí está mi corazón\ntriste como una escopeta.",225,6,-1,256,"",5,4,"ea",-1,0,-1,0,118,118,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0119-01",21,"Ya salieron a bailar,\nel diablo con el demonio;\npor eso yo me encomiendo\na mi padre San Antonio.",225,6,-1,256,"",0,4,"oo",169,0,-1,0,119,119,"","",0,"","","",5,0,0,[],"",""],["ortiz_ecuador-p0119-02",21,"Ya salió la luna hermosa\nrelumbrando las paredes,\nasí relumbra tu cara\nentre todas las mujeres.",225,6,-1,256,"",0,4,"ee",-1,0,-1,0,119,119,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0119-03",21,"Ya te dije, corazón,\nque en mí no tengas confianza;\nvos sin quererme creer\ntuviste tanta esperanza.",225,6,-1,256,"",0,4,"aa",163,0,-1,0,119,119,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0119-04",21,"Yo del pavo me comiera\nla pechuga y el alón;\nde mi guambra me bebiera\nla sangre del corazón.",225,6,-1,256,"",1,4,"o",31,0,-1,0,119,119,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0119-05",21,"Yo formé del pecho mío\nun nido para ti, infiel,\nmas tú lo dejas vacío:\nay, paloma, eres muy cruel.",225,6,-1,256,"",1,4,"e",32,0,-1,0,119,119,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0119-06",21,"Yo me entrego ya en tus brazos\ncon sola una condición\nque me des hoy de a de veras\ntu amorcito corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,119,119,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0119-07",21,"Yo me sentía enfermo\ncon un dolor de la espalda,\ny solo se me pasaba\nal ver las de minifalda.",225,6,-1,256,"",0,4,"aa",-1,0,-1,0,119,119,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-01",21,"Yo me siento muy contenta\ncon mi lindo policía;\naunque me hace tener miedo\ncon su mujer, la Lucía.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,120,120,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-02",21,"Yo me vine por acá,\nno por pena ni pasión;\npor darle gusto a mis ojos\ny alegría al corazón.",225,6,-1,256,"",0,4,"o",31,0,-1,0,120,120,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-03",21,"Yo no sé lo que tienen\nlas flores del camposanto\nque cuando las mece el viento\nparece que están llorando.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,120,120,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-04",21,"Yo no soy de por aquí,\nyo soy de por otro lado;\nun capuchino me trajo\nen las barbas enredado.",225,6,-1,256,"",0,4,"ao",-1,0,-1,0,120,120,"","",0,"","","",11,0,0,[],"",""],["ortiz_ecuador-p0120-05",21,"Yo no soy tan tonto\npara aguantar:\nsi él también me pega,\nyo también le he de dar.",225,6,-1,256,"",3,4,"a",21,0,-1,0,120,120,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-06",21,"Yo no soy un abogado\nni tampoco un ingeniero;\npero con lo que yo soy\nconsigo lo que yo quiero.",225,6,-1,256,"",0,4,"eo",38,0,-1,0,120,120,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0120-07",21,"Yo no vengo a ver si puedo,\nsino porque puedo, vengo;\ny cada vez que yo vengo,\nvengo a darte lo que tengo.",225,6,-1,256,"",0,4,"eo",124,0,-1,0,120,120,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0121-01",21,"Yo que infeliz he nacido,\nfelicidad nunca espero:\nquerido de quien no quiero;\nde quien quiero aborrecido.",225,6,-1,256,"",11,4,"io",101,0,-1,0,121,121,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0121-02",21,"Yo quisiera, maridito,\nque un lagarto te tragara,\ny no encontrarte celoso\ny me muestres mala cara.",225,6,-1,256,"",0,4,"aa",57,0,-1,0,121,121,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0121-03",21,"Yo quisiera que mi suegra\nsea como lagartija\npara matarle a pedradas\ny quedarme con la hija.",225,6,-1,256,"",0,4,"ia",219,0,-1,0,121,121,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0121-04",21,"Yo quisiera retratarte\nen la palma de mi mano,\npara cuando estés ausente\nalzar la mano y besarte.",225,6,-1,256,"",5,4,"ae",8,0,-1,0,121,121,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0121-05",21,"Yo quisiera ser el quinde,\ny el más fino silbador,\npara sacarle a mi negra\nde la sala al corredor.",225,6,-1,256,"",0,4,"o",72,0,-1,0,121,121,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0121-06",21,"Yo quisiera ser el quinde\ny volar de rama en rama;\nyo quisiera ser la pulga\npara dormir en tu cama.",225,6,-1,256,"",0,4,"aa",90,0,-1,0,121,121,"","",0,"","","",3,0,0,[],"",""],["ortiz_ecuador-p0121-07",21,"Yo quisiera ser un gato,\ny subirme a la solera;\nhacer dormir a los viejos\ny sacarme a la soltera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,121,121,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-01",21,"Yo quisiera ser un quinde,\npero no de los azules,\npara andarte visitando\nsábado, domingo y lunes.",225,6,-1,256,"",0,4,"ue",-1,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-02",21,"Yo quisiera ser veloz\ncomo luz del pensamiento,\ny no olvidar ni un momento\nla dicha de estar con vos.",225,6,-1,256,"",11,4,"o",87,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-03",21,"Yo saqué mi maiz al sol,\npensando que no lloviera,\ny me cogió el aguacero\ncon todito el maiz afuera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-04",21,"Yo sé que me he de ir al cielo\ny he de llevar mi escopeta;\npero antes le he de ir matando\na esa guambra tan coqueta.",225,6,-1,256,"",0,4,"ea",200,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-05",21,"Yo soy aquel panadero\nque trabaja con afán,\npasando las malas noches,\npara que otros coman pan.",225,6,-1,256,"",0,4,"a",147,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0122-06",21,"Yo soy como el escorpión,\nchico, pero venenoso;\nsoy como el piojo e' gallina,\nchico, pero fastidioso.",225,6,-1,256,"",0,4,"oo",160,0,-1,0,122,122,"","",0,"andina_t2","","",2,0,0,[],"",""],["ortiz_ecuador-p0122-07",21,"Yo soy el tigre chonero,\nbajado a la serranía;\ntraigo las uñas gastadas,\nde pelear todito el día.",225,6,-1,256,"",0,4,"ia",0,0,-1,0,122,122,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-01",21,"Yo soy hecho a la pobreza\ny la pobreza hecha a mí;\nsin la pobreza no vivo,\nni la pobreza sin mí.",225,6,-1,256,"",0,4,"i",-1,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-02",21,"Yo soy la media naranja;\ntambién la naranja entera;\nme dicen la flor de rosa,\npero no para cualquiera.",225,6,-1,256,"",0,4,"ea",44,0,-1,0,123,123,"","",0,"","","",6,0,0,[],"",""],["ortiz_ecuador-p0123-03",21,"Yo también estoy contento\nguambrita, juntito a vos\npara pasar abrazados\nambos juntitos los dos.",225,6,-1,256,"",0,4,"o",87,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-04",21,"Yo te dije: vámonos;\nvos dijiste: vamos, pues;\nyo no te traje cargando;\nvos viniste con tus pies.",225,6,-1,256,"",0,4,"e",218,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-05",21,"Yo te escribo y no te firmo\npara que no corra fama;\nel hombre que bien te quiere\ntú sabrás cómo se llama.",225,6,-1,256,"",0,4,"aa",90,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-06",21,"Yo te quise, no lo niego,\nyo te tuve voluntad;\ncomo vos te retiraste\nbusqué mi comodidad.",225,6,-1,256,"",0,4,"a",16,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0123-07",21,"Yo te quisiera contar\nla vida que estoy pasando,\npara que sepas muy bien\ncómo vivo lamentando.",225,6,-1,256,"",0,4,"ao",33,0,-1,0,123,123,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0124-01",21,"Yo te vengo a saludar\ny a darte mis consejos:\nno te dejes engañar\nde la astucia de los viejos.",225,6,-1,256,"",1,4,"eo",149,0,-1,0,124,124,"","",0,"","","",1,0,0,[],"",""],["ortiz_ecuador-p0124-02",21,"Yo tengo una mala maña\nque yo mismo no me entiendo,\nme acuesto en mi propia cama\ny en cama ajena amanezco.",225,6,-1,256,"",0,4,"eo",-1,0,-1,0,124,124,"","",0,"","","",2,0,0,[],"",""],["ortiz_ecuador-p0124-03",21,"Yo tuve una longuita,\ny hasta le enseñé a sumar;\ny al cabo de algunos meses\nsabía multiplicar.",225,6,-1,256,"",0,4,"a",21,0,-1,0,124,124,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0005-01",22,"Ahora que viene mayo,\nla flor de la primavera,\ncuando los quintos se marchan\nvoluntarios a la guerra.",226,0,36,257,"",0,4,"ea",-1,0,-1,0,5,5,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0005-02",22,"Allá va la despedida,\nte suplico que no llores,\nque vendrá la primavera\ny te cubrirá de flores.",226,0,36,257,"",0,4,"oe",5,0,-1,0,5,5,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0005-03",22,"En el portal de Belén\nen invierno es primavera,\nque el Mesías esperado\nen Jesús baja a la tierra.",226,0,36,257,"",0,4,"ea",-1,0,-1,0,5,5,"","",0,"","","",32,0,0,[],"",""],["leonesas_diez-p0005-04",22,"En tiempo de primavera,\nen otoño y en verano\ntodas las flores del campo,\ntoditas se van secando.",226,0,36,257,"",0,4,"ao",-1,0,-1,0,5,5,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0005-05",22,"¿Para qué me pides peras\nsi mi peral no las tiene?\nYa te las darán a ti\nla primavera que viene.",226,0,36,257,"",0,4,"ee",70,0,-1,0,5,5,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0005-06",22,"Qué alegres los pajarillos\nque cantan en la arboleda\nal ver pasar por allí\nla flor de la primavera.",226,0,36,257,"",0,4,"ea",-1,0,-1,0,5,6,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0006-01",22,"Virgen de la Concepción,\neres flor de primavera,\ncon ese vestido blanco\nparecido a la azucena.",226,0,36,257,"",0,4,"ea",-1,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0006-02",22,"Ya está la primavera\nsembrando flores,\nya los campos se visten\nde mil colores.",226,0,36,257,"",6,4,"oe",5,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0006-03",22,"Ya viene la primavera,\nya florecen los espinos,\npara ponerte a la sombra\na remendar el vestido.",226,0,36,257,"",0,4,"io",-1,0,-1,0,6,6,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0006-04",22,"Allá va la despedida\na todos en general,\nque mi corazón no quiere\ncon ninguno quedar mal.",226,0,36,258,"",0,4,"a",1,0,-1,0,6,6,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0006-05",22,"Cantar que del alma sale\nes pájaro que no muere,\nporque canta los sentires\ny el corazón siempre siente.",226,0,36,258,"",0,4,"ee",-1,0,-1,0,6,7,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0007-01",22,"Canto triste, canto triste,\nno puedo cantar alegre,\ntengo el corazón herido\ny las heridas me duelen.",226,0,36,258,"",0,4,"ee",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0007-02",22,"¿Cómo quieres que tenga\ndos corazones:\nuno de filigrana\ny otro de amores?",226,0,36,258,"",6,4,"oe",-1,0,-1,0,7,7,"","",0,"","","",14,0,0,[],"",""],["leonesas_diez-p0007-03",22,"Corazón que no quiera\nsufrir dolores,\npase la vida entera\nlibre de amores.",226,0,36,258,"",6,4,"oe",5,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0007-04",22,"Corazones partidos\nyo no los quiero,\nque cuando doy el mío\nlo doy entero.",226,0,36,258,"",6,4,"eo",38,0,-1,0,7,7,"","",0,"rm_t3, palau_cantares, isaacs_colombia","","",7,0,0,[],"",""],["leonesas_diez-p0007-05",22,"De San José traigo el ramo,\nde San Francisco el cordón,\nde la Virgen, la corona,\nde mi amante, el corazón.",226,0,36,258,"",0,4,"o",31,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0008-01",22,"El corazón de los hombres\nes como un día nublado,\nque tiene más pensamientos\nque leyes un abogado.",226,0,36,258,"",0,4,"ao",14,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0008-02",22,"Ay de mí, que la perdí,\nay, que la traigo perdida,\njugué con un jugador,\ntengo perdida la vida.",226,0,36,259,"",0,4,"ia",37,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0008-03",22,"La baraja de los naipes,\nseñores, voy a explicar\npara que de Dios se acuerden\ncuando vayan a jugar.",226,0,36,259,"",0,4,"a",21,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0008-04",22,"Los pajaritos del cielo\ncantando mecen la cuna\ny el Niño recién nacido\njugando está con sus plumas.",226,0,36,259,"",0,4,"ua",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0008-05",22,"Por el río Torío\nbajaba una gabarra\ncon cuatro jugadores\nde las Ventas de Nava.",226,0,36,259,"",0,4,"aa",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0009-01",22,"Ya puedes tirar la barra\npor encima del sombrero,\nque, aunque pierdas la tirada,\ntuya es la flor, caballero.",226,0,36,259,"",0,4,"eo",38,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0009-02",22,"A tu puerta estamos cuatro,\ncuatro mozos a cantar,\nsi quieres que te cantemos,\nlicencia nos has de dar.",226,0,36,260,"",0,4,"a",21,0,-1,0,9,9,"","",0,"","","",8,0,0,[],"",""],["leonesas_diez-p0009-03",22,"Allá va la despedida,\ny con ésta ya van cuatro,\nya no canto más cantares\nsi no me dan vino blanco.",226,0,36,260,"",0,4,"ao",-1,0,-1,0,9,9,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0009-04",22,"Cuatro camisas tengo,\ntres no me vienen,\nporque están en el arca\nde quien las tiene.",226,0,36,260,"",6,4,"ee",-1,0,-1,0,9,9,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0009-05",22,"Cuatro flores principales\nse plantan en mi jardín:\nla rosa y la clavelina,\nla azucena y el jazmín.",226,0,36,260,"",0,4,"i",211,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0009-06",22,"Cuatro frailes franciscos,\ncuatro del Carmen,\ncuatro de la Victoria,\nson doce frailes.",226,0,36,260,"",6,4,"ae",-1,0,-1,0,9,10,"","",0,"rm_t4, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["leonesas_diez-p0010-01",22,"Cuatro frailes franciscos,\nde los más gordos,\nfueron a beber agua,\nse ahogaron todos.",226,0,36,260,"",6,4,"oo",-1,0,-1,0,10,10,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0010-02",22,"Cuatro lunares tienes,\nniña, en tu rostro,\ntienes abril y mayo,\njulio y agosto.",226,0,36,260,"",6,4,"oo",-1,0,-1,0,10,10,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0010-03",22,"Cuatro mozos como róbligos\nvenían de Carisédiga,\nxuraban e devoraban\nque había festa en Fornéliga.",226,0,36,260,"",0,4,"ea",-1,0,-1,0,10,10,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0010-04",22,"Cuatro pies tiene el lobo,\ncuatro la loba,\ncuatro la lagartija,\ndos la paloma.",226,0,36,260,"",6,4,"oa",-1,0,-1,0,10,10,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0010-05",22,"Cuatro tsobus que baxiarun\npor el vatse de Tsaciana\nfueron buscare a Buxionte\ntseite, tsume, tsinu, tsana.",226,0,36,260,"",0,4,"aa",4,0,-1,0,10,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0011-01",22,"De todos cuatro colores\ntengo de pintar un ramo,\ncolorado, azul y verde,\ny encima, sobredorado.",226,0,36,260,"",0,4,"ao",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0011-02",22,"Dime, panaderina,\ncómo te arreglas\npara vender los bollos\na cuatro perras.",226,0,36,260,"",6,4,"ea",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0011-03",22,"En el baile bailan cuatro,\ncinco con la del pandero,\ny ahora vamos a ver\nquién da la vuelta primero.",226,0,36,260,"",0,4,"eo",38,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0011-04",22,"En el medio de mi pueblo\ntengo de hacer una fuente,\ncon cuatro caños de agua\npara que beba la gente.",226,0,36,260,"",0,4,"ee",15,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0011-05",22,"Entre cuatro amigas mías\nme cortaron un vestido,\nlo cortaron sin tijeras\ny lo cosieron sin hilo.",226,0,36,260,"",0,4,"io",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0012-01",22,"Esta noche ha llovido,\nmañana hay barro,\ncuatro pares de mulas\nlleva mi carro.",226,0,36,260,"",6,4,"ao",392,0,-1,0,12,12,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0012-02",22,"Esta noche hemos de ver\ncómo relumbra el acero,\nporque han dicho cuatro mozos\nque han de romper el pandero.",226,0,36,260,"",0,4,"eo",38,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0012-03",22,"Hay quien por lograr la fama\nha perdido una fortuna,\nen cambio, por cuatro cuartos\nse hizo famosa la luna.",226,0,36,260,"",0,4,"ua",56,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0012-04",22,"La Virgen de Fuentes tiene\nencima de su corona\ncuatro lirios encarnados\ny el Padre Santo de Roma.",226,0,36,260,"",0,4,"oa",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0012-05",22,"La Virgen de la Encina,\n¿quién la sacará?\nLos cuatro pimenteros\nde Ponferrada.",226,0,36,260,"",6,4,"aa",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0012-06",22,"María, Magdalena,\nMarta y Mariana\nson los cuatro luceros\nde la mañana.",226,0,36,260,"",6,4,"aa",4,0,-1,0,12,13,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0013-01",22,"No me llames gallega,\nque soy berciana,\ncuatro leguas pa arriba\nde Ponferrada.",226,0,36,260,"",6,4,"aa",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0013-02",22,"No me tires chinitas,\ntírame nueces,\ntíramelas a pares,\ncuatro en dos veces.",226,0,36,260,"",6,4,"ee",196,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0013-03",22,"Por cantar cuatro cantares\na la puerta del molino,\nme dieron media peseta\ny me molieron el trigo.",226,0,36,260,"",0,4,"io",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0013-05",22,"Una despedida sola\ndicen que no vale nada,\nvayan una, vayan dos,\nvayan tres y cuatro vayan.",226,0,36,260,"",0,4,"aa",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0014-01",22,"A la luz del cigarro\nvoy al molino,\nsi el cigarro se apaga,\nme voy al río.",226,0,36,261,"",6,4,"io",-1,0,-1,0,14,14,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0014-02",22,"A la puerta de un molino\nme puse a considerar\nlas vueltas que da una piedra\npara moler un costal.",226,0,36,261,"",0,4,"a",-1,0,-1,0,14,14,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0014-03",22,"A la puerta del molino\nme puse a considerar\nque el que no tiene dinero\npocos amigos tendrá.",226,0,36,261,"",0,4,"a",-1,0,-1,0,14,14,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0014-04",22,"A la puerta del molino\ndejé atado al animal,\ny cuando salí a deshora,\nno quedaba ni el ronzal.",226,0,36,261,"",0,4,"a",1,0,-1,0,14,14,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0014-05",22,"A la puerta del molino\nuna molinera canta,\ncon el polvo de la harina\ntiene rota la garganta.",226,0,36,261,"",0,4,"aa",148,0,-1,0,14,14,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0014-06",22,"Al entrar en Cacabelos\nlo primero que se ve:\nLa Virgen de las Angustias,\ncon los molinos al pie.",226,0,36,261,"",0,4,"e",77,0,-1,0,14,15,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0015-01",22,"El molinero lleva\nfaja de seda,\nde la harina que roba\nla molinera.",226,0,36,261,"",6,4,"ea",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0015-02",22,"El peral del molino\nno tiene peras,\nque se las ha comido\nla molinera.",226,0,36,261,"",6,4,"ea",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0015-03",22,"Gasta la molinera\nricos zapatos,\ny al pobre molinero\nlo trae descalzo.",226,0,36,261,"",6,4,"ao",-1,0,-1,0,15,15,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0015-04",22,"Gasta la molinera\nricos zarcillos\nde la harina que roba\nde los cuartillos.",226,0,36,261,"",6,4,"io",161,0,-1,0,15,15,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0015-05",22,"La molinera está mala,\nno por falta de alimento,\nque en la cabecera tiene\nuna ristra de pimientos.",226,0,36,261,"",0,4,"eo",-1,0,-1,0,15,16,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0016-01",22,"La molinera\nllorando estaba\ny el molinero\nla consolaba.",226,0,36,261,"",6,4,"aa",28,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0016-02",22,"Para hacer ver que tienes\ntrigo y hacienda,\nllevas a los molinos\nsacos con tierra.",226,0,36,261,"",6,4,"ea",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0016-04",22,"Por debajo el molino\nretumba el agua,\nera la molinera,\nque paños lava.",226,0,36,261,"",6,4,"aa",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0016-05",22,"Tiene la molinera\nricas pulseras\nde la harina que roba\nde las fanegas.",226,0,36,261,"",6,4,"ea",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0017-02",22,"A la orilla del río\nsembré patatas\ny salieron cangrejos\ncon alpargatas.",226,0,36,262,"",6,4,"aa",328,0,-1,0,17,17,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0017-03",22,"A la orilla del río\ntengo sembrado\nazafrán y canela,\npimienta y clavo.",226,0,36,262,"",6,4,"ao",-1,0,-1,0,17,17,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0017-04",22,"Adiós, valle de Ancares,\nadiós te digo,\nadiós, árboles verdes\nde junto al río.",226,0,36,262,"",6,4,"io",-1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0017-05",22,"Al otro lado del río\nestaba llorando un piojo,\nque venía de las siegas\ncon una espiga en un ojo.",226,0,36,262,"",0,4,"oo",400,0,-1,0,17,17,"","",0,"","","",15,0,0,[],"",""],["leonesas_diez-p0017-06",22,"Al otro lado del río\ntengo de hacer mi labor\ncon una yunta de cabras\ny un perro de sembrador.",226,0,36,262,"",0,4,"o",72,0,-1,0,17,18,"","",0,"","","",15,0,0,[],"",""],["leonesas_diez-p0018-01",22,"Al otro lado del río\ntiene mi padre una viña,\nno la poda ni la cava,\nvendimiar, sí la vendimia.",226,0,36,262,"",0,4,"ia",-1,0,-1,0,18,18,"","",0,"","","",15,0,0,[],"",""],["leonesas_diez-p0018-02",22,"Allá va la despedida,\nésta sí que va con brío,\nmás vale una despedida\nque un chapuzón en el río.",226,0,36,262,"",1,4,"io",3,0,-1,0,18,18,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0018-03",22,"En el río del Jordán\nmil maravillas se han visto:\nCristo bautizó a San Juan\ny San Juan bautizó a Cristo.",226,0,36,262,"",1,4,"io",273,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0018-04",22,"Pajarillo jilguero,\ndime qué comes.\nArenillas del río,\ndel campo flores.",226,0,36,262,"",6,4,"oe",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0018-05",22,"Río arriba, río arriba,\nnunca el agua subirá,\nque en el mundo río abajo,\nrío abajo todo va.",226,0,36,262,"",0,4,"a",9,0,-1,0,18,19,"","",0,"rm_t4","","",3,0,0,[],"",""],["leonesas_diez-p0019-01",22,"Si la luna fuera queso\ny las estrellas, panetes,\ny el río fuera de vino,\nqué tragos y qué zoquetes.",226,0,36,262,"",0,4,"ee",505,0,-1,0,19,19,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0019-02",22,"Si pasas el río,\nno bebas el agua,\nque la envenenaron\nlos de la montaña.",226,0,36,262,"",0,4,"aa",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0019-03",22,"Si quieres que el carro cante,\nmétele el eje en el río,\nque de que esté bien mojado\ncantará como un judío.",226,0,36,262,"",0,4,"io",3,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0019-04",22,"Allá va la despedida,\nla que echó el galgo a la liebre,\nque si la pilla debajo\nno se moja cuando llueve.",226,0,36,263,"",0,4,"ee",-1,0,-1,0,19,19,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0019-05",22,"Braña de Zaramedo,\nquién te rondara\nde noche con la luna\ny aunque nevara.",226,0,36,263,"",6,4,"aa",57,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0020-01",22,"Cómo llueve en el campo,\ncómo ha llovido,\nque hasta los naranjales\nhan florecido.",226,0,36,263,"",6,4,"io",101,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0020-02",22,"Cómo nieva por la sierra,\ncómo nieva en la montaña,\ny qué sólo está mi amor\nallá arriba en esa braña.",226,0,36,263,"",0,4,"aa",213,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0020-03",22,"El patio de mi casa\nes particular\ncuando llueve se moja\ncomo los demás.",226,0,36,263,"",0,4,"a",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0020-04",22,"En el portal de Belén\ncaen copos de nieve airosa,\nestá la Virgen María\nmás hermosa que una rosa.",226,0,36,263,"",0,4,"oa",63,0,-1,0,20,20,"","",0,"","","",32,0,0,[],"",""],["leonesas_diez-p0020-05",22,"En este pueblo no hay mozos,\nque se los comió la helada,\ny los pocos que quedaron\nson pa la primer nevada.",226,0,36,263,"",0,4,"aa",49,0,-1,0,20,20,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0020-06",22,"Esta noche ha llovido,\nmañana hay barro,\npobre del carretero\nque va en el carro.",226,0,36,263,"",6,4,"ao",392,0,-1,0,20,21,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0021-01",22,"Esta noche va a llover,\nque tiene cerco la luna,\nlas estrellas me lo dicen\ny el cielo me lo asegura.",226,0,36,263,"",0,4,"ua",-1,0,-1,0,21,21,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0021-02",22,"Esta noche va a llover,\nque tiene cerco la luna,\nque si no llueve esta noche\nno llueve noche ninguna.",226,0,36,263,"",0,4,"ua",56,0,-1,0,21,21,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0021-03",22,"Cuando la perdiz canta\nagua requiere,\nno hay mejor seña de agua\nque cuando llueve.",226,0,36,263,"",6,4,"ee",-1,0,-1,0,21,21,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0021-04",22,"Las campanas de Barniedo,\ncuando la tormenta llega,\nlas echan todas al vuelo\nporque no quieren que llueva.",226,0,36,263,"",0,4,"ea",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0021-05",22,"Las culebras, cuando llueve,\nse arrastran por el camino,\nasí se arrastran los mozos\ncuando beben mucho vino.",226,0,36,263,"",0,4,"io",199,0,-1,0,21,22,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0022-01",22,"Marcha, truena reñubera,\npa los montes Pirineos,\nonde nu hai pan ni paya,\nnu andes pur estos careos.",226,0,36,263,"",0,4,"eo",662,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0022-02",22,"Mira, mira, cómo nieva\narriba en aquellos montes,\nmira, mira cómo nieva,\nnieva de día y de noche.",226,0,36,263,"",0,4,"oe",-1,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0022-03",22,"Oh, Cristo de los Remedios,\ntú que tienes el poder,\ndirige hacia aquí tus nubes\npara que empiece a llover.",226,0,36,263,"",0,4,"e",20,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0022-04",22,"Qué serenita\ncae la nieve,\ny el aire cierzo\nque la detiene.",226,0,36,263,"",6,4,"ee",-1,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0022-05",22,"Si me pierdo, que me busquen\nal lado del mediodía,\ndonde cae la nieve a copos\ny el agua es serena y fría.",226,0,36,263,"",3,4,"ia",0,0,-1,0,22,22,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0023-01",22,"Si se secan los pimientos,\npide a la Virgen que llueva,\nque se está secando toda,\ntoda, toda la Ribera.",226,0,36,263,"",0,4,"ea",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0023-02",22,"Tengo de subir al monte,\ntengo de pasar la Aquiana,\ntengo de pisar la nieve\nque Santa Elena pisaba.",226,0,36,263,"",0,4,"aa",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0023-03",22,"Tengo envidia de las nubes\nque llueven agua serena,\nellas lloran desde el cielo,\nyo lloro desde la tierra.",226,0,36,263,"",0,4,"ea",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0023-04",22,"Válgame Dios del cielo,\ncómo ha llovido,\nque hasta las calabazas\nhan florecido.",226,0,36,263,"",6,4,"io",101,0,-1,0,23,23,"","",0,"","","",8,0,0,[],"",""],["leonesas_diez-p0023-05",22,"A cantar me ganaréis,\npero no a saber cantares,\ntengo en casa un arca llena\ny encima siete costales.",226,0,36,264,"",0,4,"ae",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0023-06",22,"A cantares y a coplas\nnadie me gana,\nporque anduve a la escuela\nde una gitana.",226,0,36,264,"",6,4,"aa",4,0,-1,0,23,24,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0024-01",22,"Ahora voy a cantar yo\nuna tonadilla nueva,\nque cuando nació mi madre\nya la cantaba su abuela.",226,0,36,264,"",0,4,"ea",-1,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0024-02",22,"Aquí estamos a estas puertas,\ndispuestas para cantar,\nSeñora, danos licencia,\nque queremos empezar.",226,0,36,264,"",0,4,"a",21,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0024-03",22,"Aquí me pongo a cantar\ncon alegría y sin miedo,\nque al que no tiene delito\nno le llevan prisionero.",226,0,36,264,"",0,4,"eo",-1,0,-1,0,24,24,"","",0,"","","",18,0,0,[],"",""],["leonesas_diez-p0024-04",22,"Aquí me pongo a cantar,\nno sé si seré durable,\nporque tengo mala voz\ny no daré gusto a nadie.",226,0,36,264,"",0,4,"ae",-1,0,-1,0,24,24,"","",0,"","","",18,0,0,[],"",""],["leonesas_diez-p0024-05",22,"Aunque estuviera cantando\nun año con trece meses,\nsi no me diera la gana\nno canto un cantar dos veces.",226,0,36,264,"",0,4,"ee",196,0,-1,0,24,25,"","",0,"navalmoral_mata","","",2,0,0,[],"",""],["leonesas_diez-p0025-02",22,"Cantares por cantares\nsé más de ciento,\npero no se me vienen\nal pensamiento.",226,0,36,264,"",6,4,"eo",94,0,-1,0,25,25,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0025-03",22,"Cantares que no sepas,\nno los empieces,\nque te quedas nadando\ncomo los peces.",226,0,36,264,"",6,4,"ee",196,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0025-05",22,"Como no tengo gracia,\ncanto sin ella,\nque, aunque quiera comprarla\nno hay quien la venda.",226,0,36,264,"",6,4,"ea",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-01",22,"Cuando estoy en el baile\nno sé cantares,\ncuando estoy en la iglesia\nvienen a pares.",226,0,36,264,"",6,4,"ae",164,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-02",22,"Debajo del agua clara\nse ven correr las arenas,\ndebajo de mis cantares\nse ven deslizar las penas.",226,0,36,264,"",0,4,"ea",62,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-03",22,"Ese cantar que has cantado\nme lo has aprendido a mí,\nsi tuvieras más vergüenza\nno lo cantabas aquí.",226,0,36,264,"",0,4,"i",23,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-04",22,"Éste es el primer cantar,\nésta es la segunda letra,\nque sale de las entrañas\ny en el corazón penetra.",226,0,36,264,"",0,4,"ea",631,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-05",22,"La despedida canto\nde mis cantares,\ncomo no soy maestra,\nno van iguales.",226,0,36,264,"",6,4,"ae",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0026-06",22,"La gracia para cantar\nni se compra ni se arrienda,\nse la da Dios a quien quiere\ny a mí me dejó sin ella.",226,0,36,264,"",0,4,"ea",-1,0,-1,0,26,27,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0027-01",22,"La perdiz canta en el soto,\nla culebra en el espino,\ny yo canto en tu ventana,\nespejo de cristal fino.",226,0,36,264,"",0,4,"io",199,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0027-02",22,"Mozos que estáis escuchando,\nno digáis mal de quien canta,\ncon el polvo del camino,\nse me tomó la garganta.",226,0,36,264,"",0,4,"aa",148,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0027-03",22,"Ninguno por cantar bien\ndiga mal del que mal canta,\nunos cantan lo que saben\ny otros saben lo que cantan.",226,0,36,264,"",0,4,"aa",-1,0,-1,0,27,27,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0027-04",22,"No canto porque bien canto\nni por las gracias que tengo\ncanto por disimular\nuna penita que tengo.",226,0,36,264,"",0,4,"eo",-1,0,-1,0,27,27,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0027-05",22,"No creas que porque canto\ntengo el corazón alegre,\nque soy como el pajarillo,\nque si no canta se muere.",226,0,36,264,"",0,4,"ee",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0028-01",22,"No hay penitas ni alegrías\nque se queden sin cantar,\ny por eso hay más cantares\nque gotas de agua en la mar.",226,0,36,264,"",0,4,"a",21,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0028-02",22,"No sé qué cantares cante,\ntodos se me han olvidado,\nsólo tengo en la cabeza\nque eres un cielo estrellado.",226,0,36,264,"",0,4,"ao",14,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0028-03",22,"No sé si cante, si llore,\nque a mí todo me da pena,\ncantaré toda la vida,\npa llorar tiempo me queda.",226,0,36,264,"",0,4,"ea",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0028-04",22,"Para cantar cantares\nme crio el cielo,\npara hilar a la rueca\ntambién si quiero.",226,0,36,264,"",6,4,"eo",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0028-05",22,"Para empezar a cantar\nlicencia no pido a nadie,\nque la traigo yo conmigo\npara cantar en la calle.",226,0,36,264,"",0,4,"ae",-1,0,-1,0,28,28,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0028-06",22,"Para empezar a cantar,\nseñores, pido licencia,\nno digan a la mañana\natrevido y sinvergüenza.",226,0,36,264,"",0,4,"ea",-1,0,-1,0,28,29,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0029-02",22,"Por cantar, yo cantara,\npero la gracia\nse me quedó en el libro\nde la ignorancia.",226,0,36,264,"",6,4,"aa",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0029-03",22,"Quisiera que en mi garganta\nse criasen ruiseñores\npara cantar a la Virgen,\nque es la reina de las flores.",226,0,36,264,"",0,4,"oe",5,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0029-04",22,"Sé cantar y sé bailar,\nsé tocar la pandereta,\nel que se case conmigo\nlleva música completa.",226,0,36,264,"",0,4,"ea",200,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0029-05",22,"Si canto me llaman loco,\ny si no canto, cobarde;\nsi bebo vino, borracho,\nsi no bebo, miserable.",226,0,36,264,"",0,4,"ae",-1,0,-1,0,29,30,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0030-01",22,"Si estuviera cantando\nuna semana,\ndos veces una copla\nno la cantara.",226,0,36,264,"",6,4,"aa",-1,0,-1,0,30,30,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0030-02",22,"Si por cantar me pagaran,\ntoda mi voz empleara,\nasí, como no me pagan,\ncanto si me da la gana.",226,0,36,264,"",0,4,"aa",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0030-03",22,"Si quieres que te cante\ncantares nuevos,\ncorta pan de la hogaza\ny un par de huevos.",226,0,36,264,"",6,4,"eo",735,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0030-04",22,"Tengo de morir cantando,\nporque llorando nací,\ntodas las penas del mundo\nno van a ser para mí.",226,0,36,264,"",0,4,"i",23,0,-1,0,30,30,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0030-05",22,"Todos los que cantan bien\nbeben vino y aguardiente,\ny yo como canto mal,\nagua fría de la fuente.",226,0,36,264,"",0,4,"ee",15,0,-1,0,30,30,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0031-01",22,"Todos los que cantan bien\ncantan una vez al año,\ny yo, como canto mal,\npaso la vida cantando.",226,0,36,264,"",0,4,"ao",-1,0,-1,0,31,31,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0031-02",22,"Unas cantan de alegría,\notras cantan por cantar,\nyo canto todos los días\ny canto por no llorar.",226,0,36,264,"",0,4,"a",21,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0031-04",22,"A la orilla del río\ntengo mis bienes:\nuna gata y un gato\ncon cascabeles.",226,0,36,265,"",6,4,"ee",-1,0,-1,0,31,31,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0031-06",22,"Con un perrito que tengo\ny otro que me van a dar\ny otro que me están criando,\ntres perros voy a juntar.",226,0,36,265,"",0,4,"a",21,0,-1,0,31,32,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0032-01",22,"Duerme, niño chiquitín,\nque tu padre fue a León\na comprarte unos zapatos\nde pellejo de ratón.",226,0,36,265,"",0,4,"o",31,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0032-02",22,"El perro de San Roque\nno tiene rabo\nporque Ramón Rodríguez\nse lo ha cortado.",226,0,36,265,"",6,4,"ao",-1,0,-1,0,32,32,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0032-03",22,"En la calle de Santa Ana\nhay un ratón con viruelas,\ny a la cabecera un gato\nponiéndole sanguijuelas.",226,0,36,265,"",0,4,"ea",605,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0032-04",22,"En mi vida he visto yo\nlo que he visto esta mañana:\nuna gallina trillando\ny un ratón haciendo parva.",226,0,36,265,"",0,4,"aa",-1,0,-1,0,32,32,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0032-05",22,"Ese chico que está ahí\nle relumbran los botones,\ntambién le relumbra el pelo,\nroído de los ratones.",226,0,36,265,"",0,4,"oe",34,0,-1,0,32,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0033-01",22,"Esta noche los ratones\nhan tenido gran función,\nle han roído la levita\nal jefe de la estación.",226,0,36,265,"",0,4,"o",31,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0033-02",22,"La camisa del majo\nno tiene puños,\ndel pellejo del gato\nle haremos unos.",226,0,36,265,"",6,4,"uo",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0033-03",22,"Por decir: ¡Viva San Roque!\nme metieron prisionero,\ny ahora que estoy en prisiones:\n¡Viva San Roque y el perro!",226,0,36,265,"",3,4,"eo",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0033-04",22,"Ratón, que te pilla el gato,\nratón, que te va a pillar,\nsi no te pilla esta noche\nmañana te pillará.",226,0,36,265,"",0,4,"a",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0033-05",22,"San Antón a San Roque\nle pegó un palo,\nporque el perro al cochino\nle mordió el rabo.",226,0,36,265,"",6,4,"ao",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0034-01",22,"Tres años dura un milano,\ntres milanos dura un perro,\ntres perros dura un caballo,\ntres caballos dura el dueño.",226,0,36,265,"",0,4,"eo",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0034-02",22,"Al sol le llaman Lorenzo\ny a la luna, Catalina,\ncuando Lorenzo se acuesta\nse levanta Catalina.",226,0,36,266,"",0,4,"ia",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0034-03",22,"Colorada la manzana\ndel lado que le da el sol,\ndel lado que no le da\nblanca tiene la color.",226,0,36,266,"",0,4,"o",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0034-04",22,"El día que tú naciste\nnacieron tres cosas buenas:\nnació el sol, nació la luna\ny nacieron las estrellas.",226,0,36,266,"",0,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",16,0,0,[],"",""],["leonesas_diez-p0034-05",22,"En medio la plaza estoy,\nnadie me puede echar fuera,\ny aquí cantamos nosotros,\nsalga el sol por donde quiera.",226,0,36,266,"",3,4,"ea",44,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0034-06",22,"En lo alto de la sierra,\nlo moreno es lo que vale;\nlo blanco lo quema el sol,\ny lo colorao el aire.",226,0,36,266,"",0,4,"ae",-1,0,-1,0,34,35,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0035-01",22,"La luna para lucir\nal sol le pide licencia\ny yo se la pido a ustedes\ncon muchísima prudencia.",226,0,36,266,"",0,4,"ea",46,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0035-02",22,"La luna y el sol partieron\nel día por dos mitades;\nel sol cogió la mañana,\nla luna cogió la tarde.",226,0,36,266,"",0,4,"ae",-1,0,-1,0,35,35,"","",0,"navalmoral_mata","","",2,0,0,[],"",""],["leonesas_diez-p0035-03",22,"La luna y el sol riñeron,\nperdieron las amistades,\nsale el sol por la mañana\ny la luna por la tarde.",226,0,36,266,"",0,4,"ae",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0035-04",22,"La Virgen de la Guiana\nestá en el teso mayor,\nle da el aire, le da el cierzo,\nle dan los rayos del sol.",226,0,36,266,"",0,4,"o",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0035-05",22,"Majo, si vas a León,\ncompra un pañuelo de seda,\nque tenga pintado el sol,\nel lucero y las estrellas.\nMírala bien, que es un sol",226,0,36,266,"",7,5,"o",-1,0,-1,0,35,36,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0036-01",22,"Tres jueves hay en el año\nque relumbran como el sol,\nJueves Santo, Corpus Christi\ny el día de la Ascensión.",226,0,36,266,"",0,4,"o",-1,0,-1,0,36,36,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0036-02",22,"Vienen muchos pastorcitos\na adorar al Niño Dios,\nque en los brazos de María\nbrilla como el mismo sol.",226,0,36,266,"",0,4,"o",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0036-03",22,"Viva el sol, viva la luna,\nviva la Virgen del Carmen,\nviva todo aquel que tiene\nel corazón adorable.",226,0,36,266,"",0,4,"ae",-1,0,-1,0,36,36,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0036-04",22,"A la fuente voy por agua,\ny el agua no la aminoro,\nque se aumentan las corrientes\ncon las lágrimas que lloro.",226,0,36,267,"",0,4,"oo",85,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0036-05",22,"Algún día, fuente fría,\nyo bebía en tus corrientes,\ny ahora como no manas,\nvoy a beber a otras fuentes.",226,0,36,267,"",0,4,"ee",252,0,-1,0,36,37,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0037-01",22,"Allá arriba en aquel alto\nhay una fuente que mana\nagua para los mineros,\npara lavarse la cara.",226,0,36,267,"",0,4,"aa",-1,0,-1,0,37,37,"","",0,"","","",10,0,0,[],"",""],["leonesas_diez-p0037-02",22,"Allá arriba en la montaña\nhay una fuente muy fría,\ndonde beben los pastores\nagua clara y cristalina.",226,0,36,267,"",0,4,"ia",-1,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0037-03",22,"De cantares y coplas\ntengo una fuente,\ncuando quiero cantares\nle doy corriente.",226,0,36,267,"",6,4,"ee",15,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0037-05",22,"En el portal de Belén\nhay una fuente que mana\ndonde se lava la Virgen\nlas manos por la mañana.",226,0,36,267,"",0,4,"aa",4,0,-1,0,37,37,"","",0,"","","",32,0,0,[],"",""],["leonesas_diez-p0038-01",22,"Estoy ronca, ronquita,\nde la garganta\npor beber de una fuente\nmuy fría y clara.",226,0,36,267,"",6,4,"aa",-1,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0038-02",22,"La Virgen se fue a lavar\nlos pañuelos a una fuente\ny le dijo a San José:\nCuida al Niño, no despierte.",226,0,36,267,"",0,4,"ee",-1,0,-1,0,38,38,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0038-04",22,"Tres cosas tiene Casares\nque no las tiene León,\nel Cueto y la Caleal\ny las fuentes del Turrón.",226,0,36,267,"",0,4,"o",31,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0038-05",22,"Unos beben vino,\notros aguardiente,\ny los más borrachos,\nagua de la fuente.",226,0,36,267,"",0,4,"ee",15,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0038-06",22,"Vegamián tiene dos cosas\nque no las tiene León:\nla fuente de los Corrales\ny la Peña Susarón.",226,0,36,267,"",0,4,"o",31,0,-1,0,38,39,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0039-01",22,"Viva el pueblo de Luyego,\ncon sus fuentes y regatos\nla Virgen de los Remedios,\npatrona de Maragatos.",226,0,36,267,"",0,4,"ao",386,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0039-03",22,"Allá va la despedida,\nla que dio Cristo a su abuela,\nlos que bailan se divierten\ny los que tocan se amuelan.",226,0,36,268,"",0,4,"ea",-1,0,-1,0,39,39,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0039-04",22,"El día que yo nací\ndijo una verdad mi abuela:\nesta niña ha de vivir\nhasta el día que se muera.",226,0,36,268,"",0,4,"ea",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0039-05",22,"El que ahorra siempre tiene,\nel ahorrar siempre fue bueno,\nel sombrero de aquel mozo\nes del padre de su abuelo.",226,0,36,268,"",0,4,"eo",-1,0,-1,0,39,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0040-01",22,"Hoy es víspera de Reyes,\ndía muy aseñalado,\ny por eso mi abuelita\nme dará buen aguinaldo.",226,0,36,268,"",0,4,"ao",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0040-02",22,"Mi abuelo tenía un buey\nque se llamaba Gabino,\ncada vez que lo llamaba:\nVen, Gabino, venga vino.",226,0,36,268,"",0,4,"io",199,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0040-03",22,"Mi abuelo tenía un huerto\nque criaba ricos nabos,\ntambién tenía un borrico\nque le llevaba al mercado.",226,0,36,268,"",0,4,"ao",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0040-04",22,"Montañeses son mis padres,\nmontañeses mis abuelos,\ny viven en la montaña\nmucho más cerca del cielo.",226,0,36,268,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0040-05",22,"Vaya una abuela\nque tengo yo,\ncomiendo sopas\nme escalabró.",226,0,36,268,"",6,4,"o",2,0,-1,0,40,40,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0041-01",22,"Venimos de vendimiar\nde la viña de mi abuelo,\ny no nos quiere pagar\nporque hemos roto un puchero.",226,0,36,268,"",0,4,"eo",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0041-02",22,"Yo te ofrezco, Mi Niño\neste chorizo\nque lo ha hecho mi abuela\ny está muy rico.",226,0,36,268,"",6,4,"io",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0041-03",22,"Ahora me pongo a cantar\ncon alegría y con gozo,\nporque han salido a bailar\nla cigüeña y el raposo.",226,0,36,269,"",1,4,"oo",160,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0041-04",22,"Alegría, alegría,\nque dure, dure,\nque más vale alegría\nque pesadumbre.",226,0,36,269,"",6,4,"ue",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0041-06",22,"Aquí me pongo a cantar\ncon alegría y sin miedo,\nSeñor Mío Jesucristo,\nDios y Hombre Verdadero.",226,0,36,269,"",0,4,"eo",-1,0,-1,0,41,42,"","",0,"","","",18,0,0,[],"",""],["leonesas_diez-p0042-01",22,"Aunque estoy en tierra ajena\nsiempre estoy con alegría;\nporque tengo la esperanza\nque he de volver a la mía.",226,0,36,269,"",0,4,"ia",0,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0042-02",22,"Camino de Santander,\ncaminando muy alegre\niba un fraile capuchino\nmontadito en una liebre.",226,0,36,269,"",0,4,"ee",-1,0,-1,0,42,42,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0042-03",22,"Con la licencia de Dios\ny de la Virgen María,\nnos ponemos a cantar\ncon muchísima alegría.",226,0,36,269,"",0,4,"ia",0,0,-1,0,42,42,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0042-04",22,"En el portal de Belén\nhay alegría y contento,\nque ha nacido el Niño Dios,\nentre unas pajas envuelto.",226,0,36,269,"",0,4,"eo",-1,0,-1,0,42,42,"","",0,"","","",32,0,0,[],"",""],["leonesas_diez-p0042-05",22,"Gracias a Dios que llegó\neste deseado día\nen que se nos llena el pueblo\nde júbilo y alegría.",226,0,36,269,"",0,4,"ia",0,0,-1,0,42,43,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0043-01",22,"La alegría en un triste\nse da tan tarde\ncomo las valentías\nen un cobarde.",226,0,36,269,"",6,4,"ae",344,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0043-02",22,"La despedida les doy\nmetida en un ramo verde,\nen la vida he dado yo\ndespedida tan alegre.",226,0,36,269,"",0,4,"ee",-1,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0043-03",22,"La noche ya se despierta\ny se disfraza de día,\na su encuentro sale el alba,\nluego el sol y su alegría.",226,0,36,269,"",0,4,"ia",0,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0043-04",22,"La vendimia es en hogaño\nmejor de lo que creía,\nhay más uva que en antaño\ny mucha más alegría.",226,0,36,269,"",1,4,"ia",0,0,-1,0,43,43,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0043-05",22,"No canto porque bien canto\nni porque soy cantadora,\ncanto por dar alegría\na tu corazón, que llora.",226,0,36,269,"",0,4,"oa",107,0,-1,0,43,43,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0044-03",22,"Quien tiene penas, se muere,\nquien no las tiene, también;\nyo quiero vivir alegre,\nmañana me moriré.",226,0,36,269,"",0,4,"e",-1,0,-1,0,44,44,"","",0,"rm_t4, andina_t1, lafuente_madrid","","",4,0,0,[],"",""],["leonesas_diez-p0044-04",22,"Si quieren saber, señores,\ndónde reina la alegría,\nen el pueblo que nací\nreina de noche y de día.",226,0,36,269,"",0,4,"ia",0,0,-1,0,44,44,"","",0,"","","",11,0,0,[],"",""],["leonesas_diez-p0044-05",22,"Si quieres que te quiera\ndame doblones,\nque es moneda que alegra\nlos corazones.",226,0,36,269,"",6,4,"oe",34,0,-1,0,44,44,"","",0,"rm_t4","","",17,0,0,[],"",""],["leonesas_diez-p0044-06",22,"Si usté me da una limosna,\nle canto con alegría\nlas penas de San José\ny de la Virgen María.",226,0,36,269,"",0,4,"ia",0,0,-1,0,44,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0045-01",22,"Tengo cantar y bailar,\ny pasar la vida alegre,\nque este mundo es una trampa\ny el que llora tanto pierde.",226,0,36,269,"",0,4,"ee",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0045-02",22,"Tengo penas y alegrías,\ntengo dos males a un tiempo,\ncuando la pena me mata\nla alegría me da aliento.",226,0,36,269,"",0,4,"eo",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0045-03",22,"Vale más la alegría\nque yo derrocho,\nque los miles de reales\nque tienen otros.",226,0,36,269,"",6,4,"oo",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0045-04",22,"Viva la alegría, viva,\nel corazón nunca llore,\nvivan los hombres leales,\nmueran los que son traidores.",226,0,36,269,"",0,4,"oe",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0045-05",22,"Viva Tabuyo del Monte,\nque es un pueblo muy alegre,\ncon su pinar tan bonito,\nque siempre viste de verde.",226,0,36,269,"",0,4,"ee",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0046-01",22,"Ya se está poniendo el sol,\nya hacen sombra los terrones,\nya se entristecen los amos\ny se alegran los peones.",226,0,36,269,"",0,4,"oe",34,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0046-02",22,"Abre la puerta, María,\nque te traigo el aguinaldo,\nunas patatas cocidas,\nsopla, que vienen quemando.",226,0,36,270,"",0,4,"ao",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0046-03",22,"Adiós, que ya me despido\ny a la lumbre voy derecha,\nque está haciendo mucho frío\ny cede la pandereta.",226,0,36,270,"",0,4,"ea",-1,0,-1,0,46,46,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0046-04",22,"Al calor de la lumbre\nquiero ponerme\nporque la pandereta\nno se destemple.",226,0,36,270,"",6,4,"ee",-1,0,-1,0,46,46,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0046-05",22,"Dale, dale, maquinista,\ndale, dale fuego al tren,\néchale carbón de piedra,\nque no pare de correr.",226,0,36,270,"",0,4,"e",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0046-06",22,"En el portal de Belén\nhacen lumbre los pastores,\npara calentar al Niño,\nque ha nacido entre las flores.",226,0,36,270,"",0,4,"oe",5,0,-1,0,46,47,"","",0,"","","",32,0,0,[],"",""],["leonesas_diez-p0047-02",22,"Ponferrada se quema,\nMolina llora,\nporque no se ha quemado\nla villa toda.",226,0,36,270,"",6,4,"oa",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0047-03",22,"Quítate del sol que quema\ny de la luna que abrasa,\ny de las lenguas del mundo\nque cuentan lo que no pasa.",226,0,36,270,"",0,4,"aa",123,0,-1,0,47,47,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0047-04",22,"Santa Marina se quema,\nVillamor la lleva el agua,\nBenavides, como es villa,\nnunca le sucede nada.",226,0,36,270,"",0,4,"aa",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0047-05",22,"Sobre tu cunita,\nNiño, he visto arder\nuna farolita\ncomo la del tren.",226,0,36,270,"",0,4,"e",-1,0,-1,0,47,48,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0048-01",22,"Tras mayo entra junio,\nen San Juan hogueras,\nSantiago y Santa Ana\ncon julio ya llegan.",226,0,36,270,"",0,4,"ea",-1,0,-1,0,48,48,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0048-02",22,"Un ciego estaba mirando\ncómo se quema una casa,\ny un mudo dando voces\ny un cojo acarreando el agua.",226,0,36,270,"",3,4,"aa",-1,0,-1,0,48,48,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0048-04",22,"Ahí está el señor padrino\ntirando duros al aire,\ny también quien los recibe\nen sin perjuicio de nadie.",226,0,36,271,"",0,4,"ae",-1,0,-1,0,48,48,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0048-05",22,"Al chaleco de ese majo,\nle falta el botón cimero,\néchale de oro, galán,\nque sé yo que tiés dinero.",226,0,36,271,"",0,4,"eo",38,0,-1,0,48,48,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0049-01",22,"Cinco duros dan los pobres,\ndiez duros dan los medianos,\nde este noble caballero,\ncien pesetas esperamos.",226,0,36,271,"",0,4,"ao",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0049-02",22,"Cuando yo tenía dinero\nme llamaban don Tomás\ny ahora que no lo tengo,\nTomasillo y nada más.",226,0,36,271,"",0,4,"a",51,0,-1,0,49,49,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0049-03",22,"El padrino de esta boda\nes un señor caballero,\n¿quién le mandó ser padrino\nsi no tenía dinero?",226,0,36,271,"",0,4,"eo",38,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0049-04",22,"Entre un duro y un real\nse trabó combate duro,\nllevaba el real la razón\ny se la dieron al duro.",226,0,36,271,"",0,4,"uo",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0049-05",22,"Ese buen señor padrino\ntiene el bolso de pellejo,\npa sacarle una peseta\nhay que tocar a concejo.",226,0,36,271,"",0,4,"eo",264,0,-1,0,49,49,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0049-06",22,"Me compré unas alpargatas\nen casa la Filomena,\nme costaron siete reales\ny no valen cuatro perras.",226,0,36,271,"",0,4,"ea",-1,0,-1,0,49,50,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0050-01",22,"No dude el señor padrino\nen darnos mucho dinero,\nque el padrino que lo da\ntiénesele por muy bueno.",226,0,36,271,"",0,4,"eo",-1,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0050-02",22,"No quiero tus avellanas,\nno las quiero, no las quiero,\nque otros me las dan de balde,\ntú me llevas el dinero.",226,0,36,271,"",0,4,"eo",38,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0050-03",22,"Pastorcicos semos,\nde Oriente venimos,\nbolsillos trayemos,\ndinero pidimos.",226,0,36,271,"",1,4,"io",329,0,-1,0,50,50,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0050-05",22,"Por mi afición sin segundo\nmetime a tamburitero,\ny alegre voy por el mundo,\ntocando gano el dinero.",226,0,36,271,"",1,4,"eo",38,0,-1,0,50,51,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0051-01",22,"Por Madrid pasé cantando,\nsin saber lo que decía,\ny a fuerza de mi dinero\naprendí la cortesía.",226,0,36,271,"",0,4,"ia",0,0,-1,0,51,51,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0051-02",22,"Que dame tres perrinas,\nque dame medio real,\nque dame tres perrinas\ny vámonos allá.",226,0,36,271,"",0,4,"a",-1,0,-1,0,51,51,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0051-03",22,"Si no tienes un duro\nno te arrimes a nadie,\nen cambio si lo tienes,\namigos a millares.",226,0,36,271,"",0,4,"ae",-1,0,-1,0,51,51,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0051-04",22,"Si quieres que el dinero\nnunca te falte,\nlo primero que tengas\nno te lo gastes.",226,0,36,271,"",6,4,"ae",-1,0,-1,0,51,51,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0052-01",22,"Si yo tuviera en dinero\nlo que tengo en voluntad,\nte compraba en chocolate\nel Peñón de Gibraltar.",226,0,36,271,"",0,4,"a",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0052-03",22,"A mí me gusta la gaita\nviva la gaita, viva el gaitero\na mí me gusta la gaita\nque tenga el fuelle de terciopelo.",226,0,36,272,"",3,4,"eo",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0052-04",22,"Al ciego Benamarías\ntodos le mandan tocar,\npero no le dice nadie:\npasa, ciego, a merendar.",226,0,36,272,"",0,4,"a",21,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0052-05",22,"Al señor tamboritero\nlas gracias le voy a dar\npor la atención que ha tenido\nde acompañarme a tocar.",226,0,36,272,"",0,4,"a",21,0,-1,0,52,52,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0052-06",22,"Allá va la despedida,\nallá va, que nos marchamos,\nsi no nos sacan más vino,\nni tocamos ni cantamos.",226,0,36,272,"",0,4,"ao",116,0,-1,0,52,53,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0053-01",22,"Allá va la despedida,\nque el rabel se vuelve loco,\nmañana por la mañana\ntocaremos otro poco.",226,0,36,272,"",0,4,"oo",152,0,-1,0,53,53,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0053-02",22,"Con el permiso de ustedes\nme pongo a tocar un baile,\ny de mi gusto sería\nno perjudicar a nadie.",226,0,36,272,"",0,4,"ae",-1,0,-1,0,53,53,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0053-03",22,"El señor gobernador\nse gasta mucha finura\nque le ha puesto campanillas\nal carro de la basura.",226,0,36,272,"",0,4,"ua",17,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0053-04",22,"El rabel está enojado\ny el que lo toca también\nporque no le dan de aquello\nque rechina en la sartén.",226,0,36,272,"",0,4,"e",242,0,-1,0,53,53,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0053-05",22,"El rabel para ser fino\nha de ser de verde pino,\nla vihuela de culebra\ny el sedal de mula negra.",226,0,36,272,"",5,4,"ea",-1,0,-1,0,53,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0054-01",22,"El rabel se ha cansado,\nyo me despido,\nque cantando y tocando\nbien he cumplido.",226,0,36,272,"",6,4,"io",101,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0054-02",22,"En l'andar te conozco\nque tienes ganas\nde tocar la zambomba,\n¡tócala y calla!",226,0,36,272,"",6,4,"aa",-1,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0054-03",22,"Este pandero que toco\nen medio tiene una O\ncon un letrero que dice:\nviva quien toca el tambor.",226,0,36,272,"",0,4,"o",-1,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0054-04",22,"Este par de dulzaineros,\ncon dulzaina y tamboril,\nque nos toquen unas piezas\ny nos vamos a dormir.",226,0,36,272,"",0,4,"i",-1,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0054-05",22,"La gaita de la ribera\nes difícil de tocar,\nsólo la toca el gaitero\ny miradlo dónde está.",226,0,36,272,"",0,4,"a",-1,0,-1,0,54,54,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0055-01",22,"La guitarra que yo toco,\nsiente como una persona:\nunas veces canta y ríe,\notras veces gime y llora.",226,0,36,272,"",0,4,"oa",-1,0,-1,0,55,55,"","",0,"palau_cantares","","",4,0,0,[],"",""],["leonesas_diez-p0055-02",22,"La zambomba está ronca,\ntiene ronquera,\nporque ha bebido agua\nde la ribera.",226,0,36,272,"",6,4,"ea",44,0,-1,0,55,55,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0055-03",22,"La zambomba está mala,\n¿qué le daremos?\nuna taza de caldo,\nque la escaldemos.",226,0,36,272,"",6,4,"eo",127,0,-1,0,55,55,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0055-04",22,"Las castañuelas de tejo\nson de mi hermano Matías,\ncuando mi hermano se muera,\nlas castañuelas son mías.",226,0,36,272,"",0,4,"ia",214,0,-1,0,55,55,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0055-05",22,"Las cuerdas de mi guitarra\nyo te diré cuáles son:\nprima, segunda, tercera,\ncuarta, quinta y el bordón.",226,0,36,272,"",0,4,"o",31,0,-1,0,55,55,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0055-06",22,"Me dicen que no se puede\nhacer tres cosas a un tiempo;\nmira como bailo y canto\ny toco los instrumentos.",226,0,36,272,"",0,4,"eo",-1,0,-1,0,55,56,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0056-01",22,"Por el camino del Val\nun maragato cantaba\nal son de las campanillas\nque su reata llevaba.",226,0,36,272,"",0,4,"aa",28,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0056-02",22,"Por la calle abajo bajan,\nla vihuela van tocando,\nuna cuadrilla de mozos,\nque la ronda van echando.",226,0,36,272,"",0,4,"ao",33,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0056-04",22,"Rompióseme la flauta,\nrompióseme el tambor,\ny ahora que no lo tengo,\nal monte de pastor.",226,0,36,272,"",0,4,"o",72,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0056-05",22,"Si se cayera el templete\ny cogiera a un musiquín,\ny pillara a Arturo Cabo,\nque es el que toca el flautín.",226,0,36,272,"",0,4,"i",211,0,-1,0,56,56,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0057-01",22,"Siempre cuando vas de ronda\nte gusta llevar tambor,\neso me está demostrando\nque eres mozo fanfarrón.",226,0,36,272,"",0,4,"o",-1,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0057-02",22,"Todos los que cantan bien\nse acercan a la guitarra,\ny yo como canto mal\nni me acerco, ni me llaman.",226,0,36,272,"",0,4,"aa",-1,0,-1,0,57,57,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0057-03",22,"Toquen, toquen\nlos hierros y flautas,\nvamos todos al campo florido,\na ver al niño hermoso\nque en el portal ha nacido.",226,0,36,272,"",7,5,"io",101,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0057-04",22,"Volaban los pajarcitos\npor encima del romero,\ncon su lenguaje decían:\nQue viva el tamboritero.",226,0,36,272,"",0,4,"eo",38,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0057-05",22,"Zumba, zúmbale al pandero,\nal pandero y al rabel,\ntoca, toca la zambomba,\ndale, dale al almirez.",226,0,36,272,"",0,4,"e",-1,0,-1,0,57,57,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0058-01",22,"A la luna, a la luna,\ny a las estrellas,\ny al lucero del alba,\nque va con ellas.",226,0,36,273,"",6,4,"ea",89,0,-1,0,58,58,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0058-02",22,"A la luna de enero\nte he comparado,\nque es la luna más clara\nde todo el año.",226,0,36,273,"",6,4,"ao",-1,0,-1,0,58,58,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0058-03",22,"A la luna tengo envidia\ny al lucero cuando sales,\nal alba cuando despiertas\ny a la noche si andas tarde.",226,0,36,273,"",0,4,"ae",-1,0,-1,0,58,58,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0058-04",22,"A tu puerta estuve ayer\nhasta que salió la luna,\ny no me has querido abrir,\ncorazón de piedra dura.",226,0,36,273,"",0,4,"ua",-1,0,-1,0,58,58,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0058-06",22,"Amor mío, no rondes\ncalles oscuras,\nronda la de la iglesia,\nque da la luna.",226,0,36,273,"",6,4,"ua",-1,0,-1,0,58,59,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0059-01",22,"Eres pariente del sol\ny primita de la luna,\nhermana de las estrellas,\ndel cielo, prima segunda.",226,0,36,273,"",0,4,"ua",-1,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0059-02",22,"Esta noche la luna\ntarde ha salido,\nlos rizos de tu frente\nla han detenido.",226,0,36,273,"",6,4,"io",101,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0059-04",22,"Estrellitas del cielo,\nrayos de Luna,\nalumbrad a mi niño\nque está en la cuna.",226,0,36,273,"",6,4,"ua",56,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0060-03",22,"Por la ventanita,\npor el cuarterón\nentraba la luna\ny también el sol.",226,0,36,273,"",0,4,"o",-1,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0060-04",22,"Quítate del sol que quema\ny de la una que abrasa,\ny de las lenguas del mundo\nque cuentan lo que no pasa.",226,0,36,273,"",0,4,"aa",123,0,-1,0,60,60,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0060-05",22,"Si la luna se eclipsara\ny el claro sol no saliera,\nfueran bastante tus ojos\npara dar luz a la tierra.",226,0,36,273,"",0,4,"ea",-1,0,-1,0,60,60,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0061-01",22,"Yo creí que era la luna\nla que estaba en el balcón,\nyo creí que era la luna\ny era la luna y el sol.",226,0,36,273,"",3,4,"o",-1,0,-1,0,61,61,"","",0,"rm_t2","","",4,0,0,[],"",""],["leonesas_diez-p0061-02",22,"Lucero de la mañana,\ntú bien lo debes saber,\ndónde están las tres Marías\ncuando empieza a amanecer.",226,0,36,273,"",0,4,"e",20,0,-1,0,61,61,"","",0,"","","",22,0,0,[],"",""],["leonesas_diez-p0061-03",22,"Majo, si vas a León,\ncompra un pañuelo de seda,\nque tenga pintado el sol,\nel lucero y las estrellas.",226,0,36,273,"",0,4,"ea",-1,0,-1,0,61,61,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0061-04",22,"Por lo más alto del cielo\ncamina el carro triunfante,\nlas tres Marías detrás\ny siete estrellas delante.",226,0,36,273,"",0,4,"ae",47,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0061-05",22,"Una estrellita se ha muerto\ny la luna llora, llora,\ny las demás estrellitas\nde luto se visten todas.",226,0,36,273,"",0,4,"oa",-1,0,-1,0,61,61,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0061-06",22,"Vámonos de aquí, señores,\nque las estrellas van altas,\nya viene la luz del día\ndescubriendo nuestras faltas.",226,0,36,273,"",0,4,"aa",183,0,-1,0,61,62,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0062-01",22,"Ventana, ¿cómo no te abres?\nbalcón, ¿cómo no te cierras?\nlucero, ¿cómo no sales\na recoger las estrellas?",226,0,36,273,"",0,4,"ea",-1,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0062-02",22,"Virgen, madre sois de Dios,\nestrella siempre brillante,\nmás que la luna sois bella,\ny más que el sol relumbrante.",226,0,36,273,"",0,4,"ae",47,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0062-03",22,"Viva la estrella del Norte,\nviva el lucero del día,\nviva la estrella del Norte,\nque a los marineros guía.",226,0,36,273,"",1,4,"ia",0,0,-1,0,62,62,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0062-04",22,"Santa Bárbara bendita,\npatrona de los mineros.\nMira, mira, Maruxina, mira,\nmira cómo vengo yo.",226,0,36,274,"",3,4,"o",-1,0,-1,0,62,62,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0062-05",22,"Traigo la cabeza rota,\nque me la rompió un costero.\nTraigo la camisa roja\nde sangre de un compañero.",226,0,36,274,"",0,4,"eo",38,0,-1,0,62,63,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0063-01",22,"En el pozo María Luisa\nmurieron cuatro mineros.\nMañana son los entierros\nde esos pobres compañeros.",226,0,36,274,"",0,4,"eo",-1,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0063-04",22,"En la estación de Montejos\nun maquinista lloraba,\nque se le acabó el carbón\ny la máquina no andaba.",226,0,36,274,"",0,4,"aa",28,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0063-05",22,"Los mineros en la mina\ngastan camisa planchada\ncon un letrero que dice:\nLa mina todo lo paga.",226,0,36,274,"",0,4,"aa",-1,0,-1,0,63,63,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0064-01",22,"Madre mía, los mineros\nson negros como el carbón,\npero en ganando el dinero,\nlas pesetas blancas son.",226,0,36,274,"",0,4,"o",31,0,-1,0,64,64,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0064-02",22,"Mi carbonero, madre,\nmuy de mañana,\ntrae el carbón al pueblo\nde buena gana.",226,0,36,274,"",6,4,"aa",4,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0064-03",22,"Viva el Bierzo, viva el Bierzo,\ntierra de vino y carbón,\nviva el Cristo de los Barrios\ny el vino de la región.",226,0,36,274,"",0,4,"o",31,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0064-04",22,"Al empezar me temo,\nporque hay algunas\nque a las aves que vuelan\nles cortan plumas.",226,0,36,275,"",6,4,"ua",-1,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0064-05",22,"Al subir a una arboleda\ncantaban los pajarcitos,\ncantaban: Cristo nació,\ncantaban: Cristo ha nacido.",226,0,36,275,"",0,4,"io",-1,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0064-06",22,"Asómate a la ventana,\na esa que mira hacia el río,\ny verás que en la arboleda\nun pájaro ha puesto el nido.",226,0,36,275,"",0,4,"io",-1,0,-1,0,64,65,"","",0,"","","",14,0,0,[],"",""],["leonesas_diez-p0065-01",22,"Cantaban los pajarcitos\npor encima de la fuente,\ny en el cántico decían:\nvivan todos los presentes.",226,0,36,275,"",0,4,"ee",-1,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0065-03",22,"El pajarito\ny el pajarero\nqué bien cantaba\nn'el mes de enero.",226,0,36,275,"",6,4,"eo",38,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0065-04",22,"El pájaro era verde,\nlas alas de color,\npiquito de canario,\nmás bonito que el sol.",226,0,36,275,"",0,4,"o",-1,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0066-02",22,"Pajarillo que cantas\nen la laguna,\nno despiertes al niño\nque está en la cuna.",226,0,36,275,"",6,4,"ua",56,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0066-03",22,"Pajarito jilguero,\nno cantes tanto,\nno sea que la risa\nse vuelva llanto.",226,0,36,275,"",6,4,"ao",30,0,-1,0,66,66,"","",0,"fernan_caballero","","",2,0,0,[],"",""],["leonesas_diez-p0066-04",22,"Para empezar a cantar\nno voy a pedir permiso,\nque ya soy pájaro viejo\ny sin cantares no vivo.",226,0,36,275,"",0,4,"io",-1,0,-1,0,66,66,"","",0,"","","",6,0,0,[],"",""],["leonesas_diez-p0067-01",22,"Tengo un pájaro que canta\ncuando te suelo nombrar,\nmira si te nombraré\nque está ronco de cantar.",226,0,36,275,"",0,4,"a",21,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0067-02",22,"Todas las avechuchas\nhoy se han juntado\na comer un borrico\ndesorejado.",226,0,36,275,"",6,4,"ao",14,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0067-03",22,"Un pájaro con cien plumas\nno se puede mantener,\ny un escribano con una\nmantiene hijos y mujer.",226,0,36,275,"",0,4,"e",20,0,-1,0,67,67,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0067-05",22,"A la mar fui por naranjas,\ncosa que la mar no tiene,\nmetí la mano en el agua,\nla esperanza me mantiene.",226,0,36,276,"",0,4,"ee",70,0,-1,0,67,67,"","",0,"rm_t2","","",7,0,0,[],"",""],["leonesas_diez-p0067-06",22,"Adiós, adiós, le decimos\na quien fue de nuestro bando,\nla despedida le damos\ncon el pandero en la mano.",226,0,36,276,"",0,4,"ao",-1,0,-1,0,67,68,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0068-01",22,"Ahí vienen los taberneros\ncon la libreta en la mano,\napuntando a quien le debe,\ntachando al que le ha pagado.",226,0,36,276,"",0,4,"ao",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0068-02",22,"Allá va la despedida\ncon la mano en el sombrero,\nque quien les canta pretende\nquedar como un caballero.",226,0,36,276,"",0,4,"eo",38,0,-1,0,68,68,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0068-03",22,"Con respeto y con amor,\nhoy, San Roque, te cantamos,\nal compás de los panderos\nque zumban en nuestras manos.",226,0,36,276,"",0,4,"ao",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0068-04",22,"Cosa sagrada es el monte\ny el árbol que está en la huerta,\nmaldita de Dios la mano\nque lo tala o que lo incendia.",226,0,36,276,"",0,4,"ea",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0068-05",22,"Dame la mano, la mano,\ndame la mano derecha,\nesta es la que me has de dar\na la puerta de la iglesia.",226,0,36,276,"",0,4,"ea",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0069-01",22,"Dame la mano, niña,\ndame la mano,\nsubiremos la cuesta\ndel avellano.",226,0,36,276,"",6,4,"ao",81,0,-1,0,69,69,"","",0,"rm_t2","","",3,0,0,[],"",""],["leonesas_diez-p0069-02",22,"El ramín de San José\nera verde y se secó,\npor ser de manos de un santo,\nel cielo se lo llevó.",226,0,36,276,"",0,4,"o",2,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0069-03",22,"El tocar el pandero\nno tiene ciencia,\nes darle con la mano\ny dejarla muerta.",226,0,36,276,"",6,4,"ea",-1,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0069-04",22,"En el bolso del padrino\ntiene el lagarto la cueva,\nno se atreve a meter mano,\ntiene miedo que le muerda.",226,0,36,276,"",0,4,"ea",-1,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0069-05",22,"El campo tiene sus flores\ny sus estrellas el cielo\ny sus arenas los mares\ny sus cantares el pueblo.",226,0,36,277,"",0,4,"eo",-1,0,-1,0,69,70,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0070-01",22,"Viva Sahelices del Río\ny su iglesia tan famosa\ny la torre de barreales\nque en su provincia no hay otra.",226,0,36,277,"",0,4,"oa",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0070-02",22,"Al mal tiempo buena cara,\n¡Virgen de la Soledad!\nal mal tiempo buena cara\nque Dios lo remediará.",226,0,36,277,"",0,4,"a",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0070-03",22,"De la montaña he venido\na la montaña me vuelvo,\nporque solo en la montaña\nse cría todo lo bueno.",226,0,36,277,"",0,4,"eo",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0070-04",22,"Tengo mi cuerpo de coplas\nque parece un avispero,\nse empujan unas a otras\npor ver cual sale primero.",226,0,36,277,"",0,4,"eo",38,0,-1,0,70,70,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0070-05",22,"Tengo mi cuerpo de coplas\nque parece un avispero,\npicándose unas a otras\npor ver cual sale primero.",226,0,36,277,"",0,4,"eo",38,0,-1,0,70,71,"","",0,"","","",3,0,0,[],"",""],["leonesas_diez-p0071-01",22,"Cantares por cantares\nsé más de ciento,\npero no me vienen\nal pensamiento.",226,0,36,277,"",6,4,"eo",94,0,-1,0,71,71,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0071-03",22,"Allá va la despedida\ny esta sí que tiene brío,\nmás vale una despedida\nque un chapuzón en el río.",226,0,36,277,"",1,4,"io",3,0,-1,0,71,71,"","",0,"","","",25,0,0,[],"",""],["leonesas_diez-p0071-05",22,"Procuremos buena fama\nque nunca jamás se pierde,\nárbol que está siempre verde\ny con el fruto en la rama.",226,0,36,277,"",11,4,"aa",90,0,-1,0,71,71,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0072-02",22,"Que dame tres perrinas,\nque a ti qué más te da,\nque tres perrinas menos,\nque tres perrinas más.",226,0,36,277,"",0,4,"a",-1,0,-1,0,72,72,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0072-03",22,"A la puerta del cielo\nvenden zapatos,\npara los angelitos\nque están descalzos.",226,0,36,277,"",6,4,"ao",-1,0,-1,0,72,72,"","",0,"fernan_caballero","","",2,0,0,[],"",""],["leonesas_diez-p0072-04",22,"A tu puerta he llamado\ncon el galocho,\nno había nadie en casa\ncontestó el gocho.",226,0,36,277,"",6,4,"oo",424,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0072-04b",22,"La despedida vos doy\nmetida en una cereza,\ny no quiero cantar más\nque me duele la cabeza.",226,0,36,277,"",0,4,"ea",108,0,-1,0,72,72,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-01",22,"Eres una arrierillo,\nno me lo niegues,\nque la vara en el cinto\npuesta la tienes.",226,0,36,277,"",6,4,"ee",-1,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-02",22,"Eres arrierillo\nde cinco mulas,\ntres y dos son del amo\nlas demás tuyas.",226,0,36,277,"",6,4,"ua",-1,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-03",22,"Una a una, dos a dos,\ntodas me las van llevando,\nlas peras de mi peral,\nsin ellas me voy quedando.",226,0,36,277,"",0,4,"ao",33,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-04",22,"Eres pájaro diestro\npero no sabes,\nla destreza que tienen\nlas otras aves.",226,0,36,277,"",6,4,"ae",129,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-05",22,"Cuatro chobos que pasaron\npor el valle de cahceana.\nfueron buscare a busmonte\nchite, chume, chirio, chana.",226,0,36,277,"",0,4,"aa",4,0,-1,0,73,73,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0073-06",22,"Anduviste alabando\ny echándote alabaciones,\nque hallabas mi puerta abierta\nen todas las ocasiones.",226,0,36,277,"",0,4,"oe",34,0,-1,0,73,74,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0074-01",22,"A cantar sí me ganas,\npero a cantares,\ntengo yo un arca llena\ny siete costales.",226,0,36,277,"",6,4,"ae",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0074-02",22,"Las elevadas montañas\nte circundan por corona,\ny la virgen del pontón\nes tu reina y tu señora.",226,0,36,277,"",0,4,"oa",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0074-03",22,"Siempre viví en la montaña\ny morir en ellas quiero,\nque corre el aire más puro\ny está más cerca del cielo.",226,0,36,277,"",0,4,"eo",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0074-04b",22,"Majo, para hablar contigo\nnecesito memoriales,\nno sé dónde has aprendido\ntanto latín como sabes.",226,0,36,277,"",0,4,"ae",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-01",22,"Aunque dé vuelta el cerrojo\ny media vuelta la llave,\nno te despidas del todo\nde la casa de tus padres.",226,0,36,277,"",0,4,"ae",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-02",22,"El árbol de la humildad\ndicen que se está secando\npero el de la envidia no,\nque son muchos a regarlo.",226,0,36,277,"",0,4,"ao",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-03",22,"Este mundo es un teatro\ncon espaciosos salones,\nsiempre la misma comedia\nsólo cambian los actores.",226,0,36,277,"",0,4,"oe",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-04",22,"Me diste tacha de pobre\notra que darme no tienes,\nmi sangre no está manchada\nque vale más que tus bienes.",226,0,36,277,"",0,4,"ee",120,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-05",22,"En el monte canta el cuco,\nen la torre la cigüeña,\nel pajarillo en el campo,\nel borracho en la taberna.",226,0,36,277,"",0,4,"ea",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0075-06",22,"El hijo del alcalde\n¡qué tieso pisa!\nporque lleva su padre\nla vara en Misa.",226,0,36,277,"",6,4,"ia",68,0,-1,0,75,76,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0076-01",22,"Por ser vos quien sois\ndije arrepentido,\npésame señor\nde haberos ofendido.",226,0,36,277,"",0,4,"io",101,0,-1,0,76,76,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0076-02",22,"Que me des tres perrinas\nque a ti qué más te da.\nque tres perrinas menos\nque tres perrinas más.",226,0,36,277,"",0,4,"a",-1,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0076-03",22,"Cantar que va por la vida\nparece una mariposa,\nque en lugar de flor en flor\nrevuela de boca en boca.",226,0,36,277,"",0,4,"oa",-1,0,-1,0,76,76,"","",0,"palau_cantares","","",2,0,0,[],"",""],["leonesas_diez-p0076-04",22,"Si al Pontón quieres llegar\nsin ir por la carretera,\nten cuidado no te caigas\nn'el camín de la escalera.",226,0,36,277,"",0,4,"ea",44,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0076-04b",22,"Río Luna, río Luna\npor embajo de los barrios,\ncon chobos por el yvierno\ny truchas por el verano.",226,0,36,277,"",0,4,"ao",-1,0,-1,0,76,76,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0077-01",22,"Una mañana salía\nun labrador a la arada,\nen el medio del camino\nse le acordó la aguijada.",226,0,36,277,"",0,4,"aa",49,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0077-02",22,"Quién supiera la industria\nde la culebra,\ncuando se ve arrodeada\npor la cigüeña.",226,0,36,277,"",6,4,"ea",-1,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0077-03",22,"La culebra en el zarzal\ncanta, giba y no parece,\npor eso las malas lenguas\ncastigo de Dios merecen.",226,0,36,277,"",0,4,"ee",-1,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0077-04",22,"Al pie de un árbol sin fruto\nme puse a considerar,\nqué pocos amigos tiene\nel que no tiene que dar.",226,0,36,277,"",0,4,"a",21,0,-1,0,77,77,"","",0,"carrizo_salta","","",5,0,0,[],"",""],["leonesas_diez-p0077-05",22,"¡Ay, qué noche tan serena\nque no tiene movimiento!\n¡Ay quien pudiera tener\ntan sereno el pensamiento!",226,0,36,277,"",0,4,"eo",94,0,-1,0,77,77,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0078-01",22,"Viva Sahagún porque tiene\nla peregrina en su trono,\ny el niño en su camarín\ncon su cadenita de oro.",226,0,36,277,"",0,4,"oo",-1,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0078-02",22,"Los mocitos de este pueblo\ncuando van a las funciones,\nlleva la chaqueta al hombro\npresumiendo de botones.",226,0,36,277,"",0,4,"oe",34,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0078-03",22,"Pañuelo a la cabeza,\npañuelo al cuello,\nno sé de dónde sale\ntanto pañuelo.",226,0,36,277,"",6,4,"eo",-1,0,-1,0,78,78,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0078-04",22,"El señor juez me pregunta\nque de qué me mantenía,\nyo me mantengo del robo\n¿de qué se mantiene usía?",226,0,36,277,"",0,4,"ia",0,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0078-05",22,"Tengo que irme pa Asturias,\npor un mes o dos semanas,\npara ver cómo se guisa\ncon el caldo de castañas.",226,0,36,277,"",0,4,"aa",-1,0,-1,0,78,78,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0079-01",22,"El día que tu naciste\nnacieron todas las flores,\nnacieron las achicorias\ny los cardos corredores.",226,0,36,277,"",0,4,"oe",5,0,-1,0,79,79,"","",0,"","","",16,0,0,[],"",""],["leonesas_diez-p0079-02",22,"Ya se van los pastores\na Extremadura\nya se queda la montaña\ntriste y oscura.",226,0,36,277,"",6,4,"ua",17,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0079-03",22,"Un pastor disparó un tiro\njunto a los barrios de luna,\nla perdiz era de Torre\nfue a caer en La Majúa.",226,0,36,277,"",0,4,"ua",-1,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0079-04",22,"No hay pueblo, como mi pueblo,\nni valle, como este valle,\nni casa, como mi casa,\nni calle, como mi calle.",226,0,36,277,"",0,4,"ae",371,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0079-05",22,"Cuando voy pa la braña\nno llevo pena,\nporque llevo patatas\npara la cena.",226,0,36,277,"",6,4,"ea",59,0,-1,0,79,79,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0079-06",22,"En medio de mi pueblo\ntengo que hacer una fuente,\ncon cuatro caños de agua\npara que beba la gente.",226,0,36,277,"",0,4,"ee",15,0,-1,0,79,80,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0080-02",22,"Mi padre me dio una zurra,\nel lunes por la mañana,\ny yo dije, padre mío,\nbuen principio de semana.",226,0,36,277,"",0,4,"aa",4,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0080-03",22,"María, si vas al hórreo,\ndel tocino corta poco,\nque el año tién doce meses,\nsemanas, cuarenta y ocho.",226,0,36,277,"",0,4,"oo",-1,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0080-04",22,"En este mundo, señores,\nUnos sufren y otros gozan,\nmas los placeres se acaban\ny las penas no se agotan.",226,0,36,277,"",0,4,"oa",-1,0,-1,0,80,80,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0080-04b",22,"El tiempo y el desengaño\nson dos amigos leales,\nque despiertan al que duerme\ny enseñan al que no sabe.",226,0,36,277,"",0,4,"ae",-1,0,-1,0,80,80,"","",0,"rm_t4, palau_cantares, lafuente_madrid, huambachano","","",10,0,0,[],"",""],["leonesas_diez-p0081-01",22,"Nadie murmure de nadie,\nque somos de carne humana,\nque no hay pellejo de aceite\nque no tenga una botana.",226,0,36,277,"",0,4,"aa",4,0,-1,0,81,81,"","",0,"","","",5,0,0,[],"",""],["leonesas_diez-p0081-02",22,"La escalera de la vida\nhay que subirla despacio,\nel que la sube deprisa\nno llega al segundo tramo.",226,0,36,277,"",0,4,"ao",-1,0,-1,0,81,81,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0081-03",22,"Yo vivo de lo que como\ny bebo lo que me dan,\npero masco algunas cosas\nque no las puedo tragar.",226,0,36,277,"",0,4,"a",-1,0,-1,0,81,81,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["leonesas_diez-p0081-04",22,"Pobre, si vas a concejo,\ntus palabras son en balde,\nel rico que contradice\ny chitón dice el alcalde.",226,0,36,277,"",0,4,"ae",734,0,-1,0,81,81,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0081-05",22,"A la puerta de un molino\nme puse a considerar,\nlas vueltas que da una piedra\ny las que tiene que dar.",226,0,36,277,"",0,4,"a",21,0,-1,0,81,81,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0081-06",22,"Agua al pie de una fuente fría\nme puse a llorar mis penas,\ny la corriente me dijo:\nno las hagas no las temas.",226,0,36,277,"",0,4,"ea",-1,0,-1,0,81,82,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0082-01",22,"Al pie de una fuente fría,\nme puse a considerar.\nqué poco amigos tiene\nel que no tiene qué dar.",226,0,36,277,"",0,4,"a",21,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0082-02",22,"He visto un monte volar\ny una casa andar a gatas,\ny en el fondo de la mar\nun burro asando patatas.",226,0,36,277,"",1,4,"aa",328,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0082-03",22,"Un águila con cien plumas\nno se puede mantener,\ny un escribano con una\nmantiene hijos y mujer.",226,0,36,277,"",0,4,"e",20,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0082-04",22,"Dicen que las golondrinas\ntienen dulce el corazón,\nporque quitaron las espinas\nde la cruz del redentor.",226,0,36,277,"",0,4,"o",-1,0,-1,0,82,82,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-01",22,"Virgencita del brezo,\nqué linda eres,\ncon tu cara de gracia\n¡quién no te quiere!",226,0,36,277,"",6,4,"ee",-1,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-02",22,"Adiós, blanca Paloma,\nflor de abril\n¡qué linda estás, María!\nen tu camarín.",226,0,36,277,"",6,4,"i",-1,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-03",22,"Buenos días, Virgen Santa,\nde España la salvación,\nestas chicas de matanza\nsuplican tu bendición.",226,0,36,277,"",0,4,"o",31,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-04",22,"¡Virgen María la Blanca,\nescucha nuestra canción,\nque estas mozas de matanza\nte cantan con devoción.",226,0,36,277,"",0,4,"o",31,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-05",22,"Y es para darte las gracias\npor tu grande protección,\npues libraste a nuestra España\nde extraña persecución.",226,0,36,277,"",0,4,"o",31,0,-1,0,83,83,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0083-06",22,"Y el pueblo de Zalamillas,\nal ver la guerra en acción,\na la virgen de raneros\nacudió sin dilación.",226,0,36,277,"",0,4,"o",31,0,-1,0,83,84,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0084-01",22,"Como ves, está adornado,\ncon rosquillas y con pastas,\ncompuestas de rica harina\nque produce la comarca.",226,0,36,277,"",0,4,"aa",-1,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0084-02",22,"Yo, en nombre de estas doncellas,\nvengo este ramo a entregar.\nrecíbelo, Virgen Blanca,\npues lo dejo ante tu altar.",226,0,36,277,"",0,4,"a",21,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0084-03",22,"Las rosquillas que lo adornan\nson para el santo hospital,\nla cera que viene en él\npara tu altar alumbrar.",226,0,36,277,"",0,4,"a",-1,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0084-04",22,"¡Quién san Jerónimo fuera\npara poder explicar,\nlo que padecen las almas\nque en el purgatorio están!",226,0,36,278,"",0,4,"a",-1,0,-1,0,84,84,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-01",22,"Allí gritan y suspiran\nmetidas en aquel fuego,\nsuspirando a los mortales\nlas saquen de aquel tormento.",226,0,36,278,"",0,4,"eo",-1,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-01b",22,"Que en calabozos oscuros\nhay muchas almas metidas,\nenclavadas en el suelo\ndiciendo cómo me olvidas.",226,0,36,278,"",0,4,"ia",279,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-02",22,"Herederos y albaceas\ncomo de mí no se acuerdan,\npara hacer una limosna\ny sacarme de estas penas.",226,0,36,278,"",0,4,"ea",-1,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-03",22,"Mujer, hijos y familia,\natender nuestros lamentos,\ncumplir lo que vos mandamos,\nno alarguéis nuestros tormentos.",226,0,36,278,"",0,4,"eo",234,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-04",22,"Tener, presentes hijos míos,\nlas fatigas y tormentos,\nque yo en el mundo pasaba\npara ganaros el sustento.",226,0,36,278,"",0,4,"eo",-1,0,-1,0,85,85,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0085-05",22,"Si una enfermedad teníais,\nsiempre estaba a vuestro lado,\ndándovos medicinas\nnoche y día con cuidado.",226,0,36,278,"",0,4,"ao",14,0,-1,0,85,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0086-01",22,"¡Ay, si me vierais ahora,\nentre tanto arder,\nqué diligencias pondríais\npor no verme padecer!",226,0,36,278,"",0,4,"e",20,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0086-02",22,"Si los posibles son pocos,\ny no pudierais mandar\nque nos digan una Misa\naliviarnos con rezar.",226,0,36,278,"",0,4,"a",21,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0086-03",22,"Jesús amoroso,\ndulce Jesús mío.\npésame Señor,\nde haberos ofendido.",226,0,36,279,"",0,4,"io",-1,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0086-04",22,"En el huerto orando,\npor mi amor rendido,\nsudando entre angustia\nsangre, hilo a hilo.",226,0,36,279,"",6,4,"io",-1,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0086-05",22,"De un traidor aleve,\ntodo un Dios vendido,\nentre lobos fieros,\ncordero benigno.",226,0,36,279,"",0,4,"io",-1,0,-1,0,86,86,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-01",22,"Preso y maniatado\npor nuestros delitos,\nde atrevida mano\nen el rostro herido.",226,0,36,279,"",0,4,"io",-1,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-02",22,"De Pilato a Herodes,\ncruelmente traído,\njuzgado por loco\npor nuestros delitos.",226,0,36,279,"",0,4,"io",-1,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-03",22,"Sentenciado a muerte,\npor un juez inicuo,\ndesnudo y llagado,\natado, afligido.",226,0,36,279,"",0,4,"io",-1,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-04",22,"De dolor retrato\nen columna ha sido,\nclavel azotado,\nhollado, escupido.",226,0,36,279,"",0,4,"io",101,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-04b",22,"De espinas punzantes\ncoronado lirio,\nde su pueblo ha sido\npor nuestros delitos.",226,0,36,279,"",0,4,"io",-1,0,-1,0,87,87,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0087-05",22,"Véante, Dios hombre,\ndespreciado, herido,\ncon la cruz a cuestas\nfuisteis oprimido.",226,0,36,279,"",0,4,"io",101,0,-1,0,87,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0088-01",22,"Por mis graves culpas,\ntres veces caído,\nhijo de María\npor nos ofendido.",226,0,36,279,"",0,4,"io",101,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0088-02",22,"Entre duros clavos\npendiente te miro,\nlevantado en alto\nen la Cruz tendido.",226,0,36,279,"",0,4,"io",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0088-03",22,"Sed tiene el señor,\nser tienes dios mío,\nvinagre ahielada\nle dan por martirio.",226,0,36,279,"",0,4,"io",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0088-04",22,"El mi triste llanto\nvos sirva de alivio,\nagotado el cáliz\ncesó el sacrificio.",226,0,36,279,"",0,4,"io",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0088-04b",22,"Ya murió el señor,\nPadre y amor mío,\npor darme la vida\nmorir has querido.",226,0,36,279,"",0,4,"io",-1,0,-1,0,88,88,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0089-01",22,"Tu sangre preciosa\nme lave, Dios mío,\nveo mis pecados\nen tu cuerpo escritos.",226,0,36,279,"",0,4,"io",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0089-02",22,"Todas esas llagas\nme acusan, dan gritos,\nmueran mis pecados,\nmueran mis delitos.",226,0,36,279,"",0,4,"io",254,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0089-03",22,"Por estos misterios\nel perdón vos pido,\nque tengas piedad\nque estamos contritos.",226,0,36,279,"",0,4,"io",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0089-04",22,"Ved aquí, cristianos,\nel amor más fino,\nved que cristo os llama\ntierno y compasivo.",226,0,36,279,"",0,4,"io",-1,0,-1,0,89,89,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0089-04b",22,"Por ser vos quien sois\ndigo arrepentido,\npésame señor,\nde haberos ofendido.",226,0,36,279,"",0,4,"io",101,0,-1,0,89,89,"","",0,"","","",2,0,0,[],"",""],["leonesas_diez-p0089-05",22,"Este sí que lleva la gala,\neste sí que lleva la flor,\neste sí que lleva los votos,\nque es el partido mejor (en elecciones).",226,0,36,279,"",3,4,"oe",72,0,-1,0,89,90,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0090-01",22,"Salga ya la buena madre\nque su adorado hijo llega,\nya ha llegado el gran consuelo\nque la consuele en sus penas.",226,0,36,280,"",0,4,"ea",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0090-02",22,"Al que va a cantar Misa\nbien le ha inspirado el Señor,\npara elegir los padrinos\npara tan alta misión.",226,0,36,280,"",0,4,"o",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0090-03",22,"Las campanas de la iglesia\ntocan con alegría,\ndeseando proclamar\nque llegó tan feliz día.",226,0,36,280,"",0,4,"ia",0,0,-1,0,90,90,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0090-04",22,"En tan alto ministerio\ngoce la santa pasa,\nde la paz y la alegría\nque el mundo no puede dar.",226,0,36,280,"",0,4,"a",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0090-04b",22,"Los ángeles desde el cielo\nbajaron a preguntar,\nqué se celebra en la tierra\ncon tanta solemnidad.",226,0,36,280,"",0,4,"a",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-01",22,"Las maderas de esta casa\nson de pino y de nogal,\ny el señor misacantano\nlas merece de cristal.",226,0,36,280,"",0,4,"a",1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-02",22,"Le damos la despedida\ninvocando al Ser Supremo,\nle conceda larga vida\ny que nos junte en el cielo.",226,0,36,281,"",0,4,"eo",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-03",22,"Don Alejo se retira\ndejando el pueblo sentido,\npero no nos abandona,\nle representa un sobrino.",226,0,36,281,"",0,4,"io",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-04",22,"Nos despedimos de usted\ntodos juntos los vecinos,\nsi alguna cosa se ofrece\nya sabe dónde vivimos.",226,0,36,281,"",0,4,"io",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-05",22,"Con alegría sin par\nle damos la bienvenida,\nal ministro del altar\nque hoy la suerte nos destina.",226,0,36,281,"",0,4,"ia",-1,0,-1,0,91,91,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0091-06",22,"Este pueblo, en la ocasión,\nse considera dichoso,\npor obtener un pastor\ninstruido y virtuoso.",226,0,36,281,"",0,4,"oo",160,0,-1,0,91,92,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0092-01",22,"Obediencia encontrará en este lugar.\ny esto solo bastará,\npara que pueda llevar\nsu cargo sacerdotal.",226,0,36,281,"",3,4,"a",-1,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0092-02",22,"Muy de veras os pedimos\na la Virgen soberana\nque nos libréis de la miseria,\nque bastante hay en España.",226,0,36,282,"",0,4,"aa",-1,0,-1,0,92,92,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0092-03",22,"La Virgen se está peinando\nal pie de Sierra Morena:\nlos cabellos eran de oro.\nla cinta de primavera.",226,0,36,282,"",0,4,"ea",-1,0,-1,0,92,92,"","",0,"","","",9,0,0,[],"",""],["leonesas_diez-p0092-04",22,"La Virgen de las Angustias\nle dijo a la del Pilar:\nsi tu eres aragonesa\nyo soy berciana y con sal.",226,0,36,282,"",0,4,"a",-1,0,-1,0,92,92,"","",0,"","","",4,0,0,[],"",""],["leonesas_diez-p0093-01",22,"Angelitos del cielo,\nvenid y llevadme\nal portal de la Virgen\ny allí dejadme.",226,0,36,282,"",0,4,"ae",736,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0093-02",22,"Virgen de Fombasallá.\nbella cara, bello rostro.\nQue tengo que visitar\nel día quince agosto.",226,0,36,282,"",0,4,"oo",-1,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0093-03",22,"En mi tierra berciana\nhay un tesoro\nque tiene más valor\nque todo el oro:\nla Virgen de la Encina\na quien yo adoro.",226,0,36,282,"",9,6,"oo",85,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0093-04",22,"Morenica mía,\nsólo yo te imploro\nque nunca me olvides\nque yo te adoro.",226,0,36,282,"",6,4,"oo",85,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["leonesas_diez-p0093-05",22,"Virgen Santa de la Encina,\na vos os pido un favor:\nque acojas a los bercianos\ndentro de tu corazón.",226,0,36,282,"",0,4,"o",-1,0,-1,0,93,93,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0004-01",23,"Triste, ¿qué será de mí?\nDesamparado, ¿dó iría?\nPues la fortuna me corre\ncon su mala compañía.",227,0,37,283,"",0,4,"ia",0,0,-1,0,4,4,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0005-02",23,"Dame un diente de tu boca\nde ésos que tienes delante,\nque me lo ponga en el pecho\ny me sirva de diamante.",227,0,37,284,"",0,4,"ae",47,0,-1,0,5,5,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0006-01",23,"Subiste los escalones\nestando moza y soltera\nahora los bajas casada,\nque por muchos años sea.",227,0,37,284,"",0,4,"ea",-1,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0006-02",23,"Esta mañana temprano\nestrenaste un vestido;\nte lo has venido a quitar\na los pies de tu marido.",227,0,37,284,"",0,4,"io",101,0,-1,0,6,6,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0006-03",23,"Una rosa entró en la iglesia\ntoda llena de rocío\ny al momento se regresa\ncasada con su marío",227,0,37,284,"",0,4,"io",3,0,-1,0,6,6,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0006-04",23,"Viva la novia y el novio\ny el cura que los casó,\nla madrina y el padrino,\nlos convidados y yo.",227,0,37,284,"",0,4,"o",2,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0006-05",23,"Porque soy quinto de este año\nya no me vas a querer,\nya no saldrás a la puerta\ncomo solías hacer.",227,0,37,285,"",0,4,"e",20,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0006-07",23,"Salir morenitas,\nsalir a bailar\ncon gracia y salero\npara enamorar; salir morenitas,\nsalir al balcón\na ver tos los mozos,\ntodos en reunión.",227,0,37,285,"",4,7,"o",31,0,-1,0,6,6,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0006-08",23,"Si te toca, te jodes,\nque te tienes que ir\na luchar con los moros\na coger el fusil.\nSi te toca, te jodes\nque te tienes que ir.",227,0,37,285,"",9,6,"i",-1,0,-1,0,6,7,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0007-01",23,"Las madres son las que lloran,\nque las novias no lo sienten,\nse van con los amigotes\ny con ellos se divierten.",227,0,37,285,"",0,4,"ee",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0007-02",23,"Ya se van los quintos, madre,\nya se va mi corazón,\nya se va el que me tiraba\nchinitas en el balcón.",227,0,37,285,"",0,4,"o",31,0,-1,0,7,7,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0007-03",23,"Ya vienen los carnavales,\nla fiesta de las mujeres,\nla que no le salga novio,\nque espere al año que viene.",227,0,37,286,"",0,4,"ee",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0007-04",23,"Carnavalitos se vienen,\ncarnavalitos se van\ny nosotros nos iremos\ny no volveremos más.",227,0,37,286,"",0,4,"a",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0007-05",23,"Ya se murió la culebra\nque estaba en el castillo,\nla que por la boca echaba\nrosas, claveles y lirios.",227,0,37,287,"",0,4,"io",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0008-01",23,"La luna y el sol partieron\nel día por dos mitades;\nel sol cogió la mañana,\nla luna cogió la tarde.",227,0,37,288,"",0,4,"ae",-1,0,-1,0,8,8,"","",0,"leonesas_diez","","",2,0,0,[],"",""],["navalmoral_mata-p0008-02",23,"Un lucerito se ha muerto\ny la luna llora, llora\ny las estrellas del cielo\nde luto se visten todas.",227,0,37,288,"",0,4,"oa",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0008-03",23,"Todos los enamorados\ntienen pleito con la luna,\nla luna por alumbrarlos\ny ellos por estar a oscuras.",227,0,37,288,"",0,4,"ua",-1,0,-1,0,8,8,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0008-04",23,"Ya es de día y amanece,\nya canta la gallarna\ny el que quiera ir al molino,\nque coja la madrugada.",227,0,37,289,"",0,4,"aa",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0008-05",23,"¿Qué delito ha cometido\nel pobrecillo candil\nque siempre le dan la muerte\nal tiempo de irse a dormir?",227,0,37,290,"",0,4,"i",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0008-06",23,"Si quieres que viva, viva,\nquiera Dios que nunca muera,\nque la muerte deseada\nparece que nunca llega.",227,0,37,291,"",0,4,"ea",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0008-07",23,"Dicen que he sido malo\npero me voy a enmendar\ny el que es malo y se arrepiente,\nse le debe perdonar.",227,0,37,291,"",3,4,"a",21,0,-1,0,8,8,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-01",23,"Un lobo en la serranía\nme quiso clavar el diente;\nyo le gané la partida,\n¡vivan los hombres valientes!",227,0,37,292,"",0,4,"ee",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-02",23,"En la esquina del castillo\nme quisieron dar la muerte,\nsaqué mi puñal dorado\ny huyeron los valientes.",227,0,37,292,"",0,4,"ee",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-03",23,"Para pasear tu calle\nno necesito cuchillo:\nese novio que tú tienes,\nme lo meto en un bolsillo.",227,0,37,292,"",0,4,"io",228,0,-1,0,9,9,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0009-04",23,"Que me voy haciendo viejo\nla desgracia es para mí,\nque se me arruga el pellejo\ny me meo sin sentir.",227,0,37,293,"",0,4,"i",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-05",23,"Donde hay mozos hay fachenda,\ndonde hay mozas, alegría;\ndonde hay viejas reguñonas,\nsermones todos los días.",227,0,37,293,"",0,4,"ia",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-06",23,"Ahora tiene mi abuela\nsólo un colmillo,\ndonde cuelga mi abuelo\nlos calzoncillos.",227,0,37,293,"",6,4,"io",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-07",23,"Mi abuelo meaba un día,\nmeaba tras de un tomillo,\nse la miraba y decía:\n\"¡qué buen mango pal martillo!\".",227,0,37,293,"",1,4,"io",228,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-08",23,"Una vieja fue a lavar\nun par de medias azules\ny se le metió una rana\nentre el domingo y el lunes.",227,0,37,293,"",0,4,"ue",-1,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-09",23,"Una vieja de cien años\ny otra de noventa y siete\nse dicen una a la otra:\n\"¡estamos de rechupete!\".",227,0,37,293,"",3,4,"ee",285,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-10",23,"Una vieja se meó\nen un vaso reluciente\ny otra vieja lo bebió\ncreyendo que era aguardiente.",227,0,37,293,"",1,4,"ee",15,0,-1,0,9,9,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0009-11",23,"Una vieja se cagó\nal pie de un confesionario\ny otra vieja lo cogió\ncreyendo que era un rosario.",227,0,37,293,"",1,4,"ao",25,0,-1,0,9,9,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0009-12",23,"Una vieja muy revieja\na la sombra de un solano\nse lo miraba y decía:\n\"¡Qué triste estás, Cayetano!\".",227,0,37,293,"",0,4,"ao",81,0,-1,0,9,9,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0009-13",23,"Una vieja se peyó\nen un montón de salvao;\nde las arrobas que había,\nno quedó más que un puñado.",227,0,37,293,"",0,4,"ao",-1,0,-1,0,9,10,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0010-01",23,"Una vieja muy revieja\nse lo miraba y decía:\n\"¡cuántas veces habrá entrado\nel cañón de artillería!\".",227,0,37,293,"",0,4,"ia",0,0,-1,0,10,10,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0010-02",23,"Una vieja y un candil,\nla perdición de una casa:\nla vieja por lo que gruñe\ny el candil por lo que gasta.",227,0,37,293,"",0,4,"aa",-1,0,-1,0,10,10,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0010-03",23,"Esta noche es Nochebuena\ny mañana Navidad,\nlos abuelos a los nietos\nbuenos chorizos les dan.",227,0,37,294,"",0,4,"a",-1,0,-1,0,10,10,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0010-04",23,"Esta noche es Nochebuena\ny mañana Navidad,\nsaca la bota, María,\nque me voy a emborrachar.",227,0,37,294,"",0,4,"a",-1,0,-1,0,10,10,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0010-05",23,"Esta noche nace el niño\ny mañana lo bautizan\ny el día de las Candelas\nsale con su madre a misa.",227,0,37,294,"",0,4,"ia",-1,0,-1,0,10,10,"","",0,"","","",6,0,0,[],"",""],["navalmoral_mata-p0010-06",23,"Nochebuena, Nochebuena,\nbuena me la dio mi padre,\nque empezó con el más chico\ny acabó con el más grande.",227,0,37,294,"",0,4,"ae",-1,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0010-07",23,"Nochebuena, Nochebuena,\n¡cuándo acabas de venir\npara ver a los borrachos\nde la taberna salir!",227,0,37,294,"",0,4,"i",157,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0010-08",23,"A esta casa hemos llegado\ncon alegría y contento\npara dar las buenas noches\na la gente que hay adentro.",227,0,37,295,"",0,4,"eo",-1,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0010-09",23,"A esta casa hemos llegado\ncuatrocientos en cuadrilla;\nsi quieres que nos sentemos,\nsaca cuatrocientas sillas.",227,0,37,295,"",0,4,"ia",-1,0,-1,0,10,10,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0011-01",23,"A esta casa hemos llegado\ncuatrocientos en cuadrilla;\nsi quieres que te cantemos,\nsácanos pan y morcilla.",227,0,37,295,"",0,4,"ia",162,0,-1,0,11,11,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0011-02",23,"Esta casa sí que es casa,\npero no tiene balcones;\npero tiene una morena\nque roba los corazones.",227,0,37,295,"",0,4,"oe",34,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0011-03",23,"Viva quien canta y quien baila\ny quien toca el instrumento\ny los amos de esta casa\ny todos los que estamos dentro.",227,0,37,295,"",0,4,"eo",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0011-04",23,"Esta noche rondo yo,\nmañana ronde quien quiera;\nesta noche rondo yo\nla calle de mi morena.",227,0,37,295,"",0,4,"ea",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0011-05",23,"Ya sé que estás acostada,\npero dormidita no;\nya sé que estarás diciendo:\n\"ése que canta es mi amor\".",227,0,37,295,"",0,4,"o",-1,0,-1,0,11,11,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0011-06",23,"Ya sé que estás acostada\ncon los pies a lo caliente\ny yo estoy a la tu ventana\npegando diente con diente.",227,0,37,295,"",0,4,"ee",15,0,-1,0,11,11,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0011-07",23,"A tu puerta rondo yo\ny me mojan los canales;\nábreme la puerta, cielo,\nque soy aquel que tú sabes.",227,0,37,295,"",0,4,"ae",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0011-08",23,"Anoche a la tu ventana\nrondando me dio la una;\nno me quisistes abrir,\ncorazón de peña dura.",227,0,37,295,"",0,4,"ua",-1,0,-1,0,11,11,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0011-09",23,"Ahora sí que estoy contento,\nahora sí que estoy a gusto,\nporque me estoy divirtiendo\ncon amigos de mi gusto.",227,0,37,295,"",0,4,"uo",-1,0,-1,0,11,11,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0011-10",23,"Zaragata, zaragata,\nzaragata es lo que quiero,\nque a mí siempre me han gustado\nlos cuerpos zaragateros.",227,0,37,295,"",0,4,"eo",-1,0,-1,0,11,11,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0011-11",23,"Venga juerga, venga juerga,\nvenga juerga y alegría,\nque a mí me gusta la juerga\nmás de noche que de día.",227,0,37,295,"",1,4,"ia",0,0,-1,0,11,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-01",23,"Llega la noche serena\ny el cantor en su trovar\nva dejando en sus coplas\nlo que quiere y nada más.",227,0,37,295,"",0,4,"a",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-02",23,"No cantamos por dinero\nni cantamos por turrón,\ncantamos porque nos gusta\ny nos lleva la afición.",227,0,37,295,"",0,4,"o",31,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-03",23,"Cuando sientas de cantar,\nasómate a la ventana,\nque somos los percheleros\nque venimos de jarana.",227,0,37,295,"",0,4,"aa",4,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-04",23,"Esta noche va a salir\nla ronda de la alpargata;\nsi sale la del zapato,\nse forma la zaragata.",227,0,37,295,"",0,4,"aa",74,0,-1,0,12,12,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0012-05",23,"Dicen que canto muy mal;\npa lo que me dan, bien canto;\nel canto, para los curas,\nque cantando ganan cuartos.",227,0,37,295,"",0,4,"ao",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-06",23,"Aunque estuviera cantando\nun año con trece meses,\nsi no me diera la gana,\nno canto un cantar dos veces.",227,0,37,295,"",0,4,"ee",196,0,-1,0,12,12,"","",0,"leonesas_diez","","",2,0,0,[],"",""],["navalmoral_mata-p0012-07",23,"A cantar nos ganarán,\npero no a saber cantares:\nen mi casa tengo un arca\ny encima siete costales.",227,0,37,295,"",0,4,"ae",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-08",23,"Bendita sea la madre\nque parió a los zambomberos,\nque cuando van por el mundo\nvan repartiendo salero.",227,0,37,295,"",0,4,"eo",-1,0,-1,0,12,12,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0012-09",23,"Al que toca la zambomba,\nde buena gana le diera\ncinco duritos diarios\npara que se mantuviera.",227,0,37,295,"",0,4,"ea",44,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0012-10",23,"Dale, zambombero, dale\na la zambomba que suene,\nque está muy lejos la cama\ndonde mi morena duerme.",227,0,37,295,"",0,4,"ee",-1,0,-1,0,12,12,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-01",23,"Esta es la calle del aire,\nla calle del remolino,\ndonde se remolinean\ntus amores con los míos.",227,0,37,295,"",0,4,"io",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-02",23,"Esta calle huele a lirios,\nsalero quien vive aquí;\ntu padre quiso a tu madre,\nyo también te quiero a ti.",227,0,37,295,"",0,4,"i",23,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-03",23,"Si esta calle fuera mía,\nyo la mandaría empedrar\ncon onzas de chocolate\ny en cada esquina un rosal.",227,0,37,295,"",0,4,"a",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-04",23,"Por esta calle que vamos\nechan agua y salen rosas,\ny por eso la llamamos\nla calle de las hermosas.",227,0,37,295,"",1,4,"oa",61,0,-1,0,13,13,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0013-05",23,"Por esta calle me voy,\npor la otra doy la vuelta;\nla que quiera ser mi novia,\nque deje la puerta abierta.",227,0,37,295,"",0,4,"ea",-1,0,-1,0,13,13,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0013-06",23,"Por esta calle vivía,\nya no sé si vivirá,\nla que me lavó el pañuelo\ncon el agua de fregar.",227,0,37,295,"",0,4,"a",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-07",23,"Esta calle está empedrada\ncon agujas de coser;\na mi novia, que es costurera,\nse las voy a recoger.",227,0,37,295,"",0,4,"e",20,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-08",23,"En esta calle vivía\nmi novia calabacera,\nla que me dio calabazas\nantes que la pretendiera.",227,0,37,295,"",0,4,"ea",44,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-09",23,"Por esta calle que voy\nme han dicho que no hay salida.\nYo la tengo que encontrar\naunque me cueste la vida.",227,0,37,295,"",0,4,"ia",37,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-10",23,"La noche más oscurita\ntengo que andar por la calle,\npor ver si alguna rosita\nse deshoja con el aire.",227,0,37,295,"",0,4,"ae",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-11",23,"Cuando vino Dios al mundo\nvino por Navalmoral,\nel Cristo por Peraleda\ny el Ángel por Valdehuncar.",227,0,37,296,"",3,4,"a",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0013-12",23,"Navalmoral de la Mata\nes un pueblo de primera\nque tiene por monumento\na la Piedra Caballera.",227,0,37,296,"",0,4,"ea",44,0,-1,0,13,13,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0014-01",23,"Ni Plasencia ni Trujillo\nni Cáceres capital\nno llegarán a la altura\nque tiene Navalmoral.",227,0,37,296,"",0,4,"a",1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0014-02",23,"La virgen de las Angustias\nle dijo a la del Pilar:\n\"tú eres patrona de España\ny yo de Navalmoral\".",227,0,37,296,"",0,4,"a",-1,0,-1,0,14,14,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0014-03",23,"La Virgen de las Angustias\nes la mejor moralita;\nyo le quitaré la pena\nde su cara tan bonita.",227,0,37,296,"",0,4,"ia",50,0,-1,0,14,14,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0014-04",23,"Agua, Virgen Soberana,\nque se seca el molinillo.\n¿Cómo vamos a lavar\nlos pañales de los niños?",227,0,37,296,"",0,4,"io",-1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0014-05",23,"Navalmoral de la Mata\nes un Madrid en pequeño,\nse lo debe agradecer\na don Agustín Carreño.",227,0,37,296,"",0,4,"eo",138,0,-1,0,14,14,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0014-06",23,"Moralita, gentil moralita,\norgullosa tú debes estar\nporque al fin hay agua en abundancia,\nla trajo el alcalde de Navalmoral.",227,0,37,296,"",3,4,"a",-1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0014-07",23,"En el cielo manda Dios\ny en la tierra los gitanos\ny en Navalmoral, señores,\ndon Julio y don Emiliano.",227,0,37,296,"",0,4,"ao",-1,0,-1,0,14,14,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0014-08",23,"En el cielo manda Dios\ny en la tierra los gitanos\ny en Navalmoral, señores,\ndon Felipe se ha hecho el amo.",227,0,37,296,"",0,4,"ao",-1,0,-1,0,14,14,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0014-09",23,"En Navalmoral, señores,\nse vive con ilusión,\nporque se bebe buen vino\nen casa de Calderón.",227,0,37,296,"",0,4,"o",31,0,-1,0,14,14,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0014-10",23,"Ya no podemos comer\nlos peces del Trujillano\nni tomar en la Paleta\nel famoso bacalado.",227,0,37,296,"",0,4,"ao",-1,0,-1,0,14,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-01",23,"—¿Con qué te lavas la cara,\nmoralita resalá?\n—Me lavo con agua clara\ny Dios pone lo demás.",227,0,37,296,"",0,4,"a",-1,0,-1,0,15,15,"","",0,"","","",9,0,0,[],"",""],["navalmoral_mata-p0015-02",23,"—¿Con qué te lavas la cara,\nque la tienes tan bonita?\n—Me lavo con agua clara\nde la fuente de la ermita.",227,0,37,296,"",1,4,"ia",50,0,-1,0,15,15,"","",0,"","","",9,0,0,[],"",""],["navalmoral_mata-p0015-03",23,"—¿Con qué te lavas la cara\nque te conservas tan guapa?\n—Me lavo con el agüita\nde la fuente de la Bamba.",227,0,37,296,"",0,4,"aa",-1,0,-1,0,15,15,"","",0,"","","",9,0,0,[],"",""],["navalmoral_mata-p0015-04",23,"Un zapatito bien hecho\nen el pie de una morala,\nsabiéndolo menear,\n¡cuántos corazones mata!",227,0,37,296,"",0,4,"aa",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-05",23,"Desde la fuente La Bamba\nhasta la cruz de la Ermita\nno me dejo de encontrar\nmás que moralas bonitas",227,0,37,296,"",0,4,"ia",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-06",23,"En el mar se crían conchas\ny en el río caracoles\ny en Navalmoral se crían\nmocitas como soles.",227,0,37,296,"",0,4,"oe",27,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-07",23,"Mirailas y reparailas,\nque de Navalmoral son,\nestrechitas de cintura\ny alegres de corazón.",227,0,37,296,"",0,4,"o",31,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-08",23,"No quiero zapatos bajos,\nque se me llenan de arena;\nsí quiero novio moralo,\nno lo quiero de La Vera.",227,0,37,296,"",0,4,"ea",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0015-09",23,"En el baile del Rosneo\nya no se puede bailar\nporque están las Perinolas\ncon las tetas levantás.",227,0,37,296,"",0,4,"a",-1,0,-1,0,15,15,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0016-01",23,"En el baile del Rosneo\ntambién se juega al balón:\nla Güevilla es la portera\ny el que tira es Calderón.",227,0,37,296,"",0,4,"o",31,0,-1,0,16,16,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0016-02",23,"Si vas a Navalmoral\ny alegría quieres ver,\nentras por la carretera\ny das la vuelta al Perchel.",227,0,37,296,"",0,4,"e",-1,0,-1,0,16,16,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0016-03",23,"Si vas a Navalmoral\ny quieres pasarlo bien,\nvete por la carretera y\npásate por el Perchel.",227,0,37,296,"",3,4,"e",-1,0,-1,0,16,16,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0016-04",23,"En el Perchel está la Gloria\ny en el Cerro la alegría\ny en la Plaza Vieja está\nla mujer que yo quería.",227,0,37,296,"",0,4,"ia",0,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-05",23,"Dicen que los percheleros\nson los que sacan cantares;\ntambién somos los cerrucos:\nlos sacamos a millares.",227,0,37,296,"",0,4,"ae",164,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-06",23,"—Dime dónde vas, Feocho.\n—Voy en busca la Gorilla,\nque me la quieren quitar\nentre el Fuelle y su cuadrilla.",227,0,37,296,"",0,4,"ia",162,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-07",23,"Dicen que las percheleras\nson las que sacan cantares,\npero todos son bonitos,\nporque no insultan a nadie",227,0,37,296,"",0,4,"ae",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-08",23,"A la Virgen de las Angustias\nla sacan los del Perchel\ny los mocitos del Cerro,\nque saquen a San Andrés.",227,0,37,296,"",0,4,"e",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-09",23,"La Virgen de las Angustias\nla sacan los percheleros\npa que vean los cerrucos\nque tienen mucho salero.",227,0,37,296,"",0,4,"eo",-1,0,-1,0,16,16,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0016-10",23,"Vamos al Cerro, muchachos,\nque en el Cerro está la Gloria,\npor eso los de allá abajo\nen el Cerro se echan novia.",227,0,37,296,"",0,4,"oa",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-11",23,"Si quieren saber, señores,\ndónde reina la alegría,\nel barrio la Peligrosa\na cualquier hora del día.",227,0,37,296,"",0,4,"ia",0,0,-1,0,16,16,"","",0,"","","",11,0,0,[],"",""],["navalmoral_mata-p0016-12",23,"El animal más famoso\nde todo Navalmoral:\nla cabra de Piparrota,\nque la saca en Carnaval.",227,0,37,296,"",0,4,"a",1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-13",23,"Cuando llegas a este pueblo\nlo primero que se ve\nson las que van al tabaco\npor las mañanas correr",227,0,37,296,"",0,4,"e",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-14",23,"¿Quién anda tirando cohetes\na esta hora? ¡Qué locura!\nCelebrando el hombre inicuo\nanda don David el cura.",227,0,37,296,"",0,4,"ua",17,0,-1,0,16,16,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0016-15",23,"A la subida del Cerro\nlo primero que se ve\nes el taller de Ventura\ny a Ventura fuera de él.",227,0,37,296,"",0,4,"e",-1,0,-1,0,16,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-01",23,"A la subida del Cerro\nlo primero que se ve\nson las ventanas abiertas\ny las camas por hacer.",227,0,37,296,"",0,4,"e",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-02",23,"A la subida del Cerro\nha puesto un bando el alcalde\ncon un letrero que dice:\n\"Maricón el que no baile\".",227,0,37,296,"",0,4,"ae",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-03",23,"A la subida del Cerro,\nse oyó una voz que decía:\n\"Estate quieto, Manolo,\nque tienes las manos frías\".",227,0,37,296,"",0,4,"ia",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-04",23,"En tos los pueblos de España\nhay un tonto por lo menos\ny en Navalmoral, señores,\nel ayuntamiento en pleno.",227,0,37,296,"",0,4,"eo",-1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0017-05",23,"En el barrio del Perchel\nya no nos falta de nada:\ntenemos dos puticlubs\ny un almacén de chatarra.",227,0,37,296,"",0,4,"aa",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-06",23,"En el barrio del Perchel\nhay un bicho venenoso\nque echa a las mozas palante\ny echa la culpa a los mozos.",227,0,37,296,"",0,4,"oo",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-07",23,"En el barrio del Perchel\nhan hecho una carretera\npara que vayan los mozos\na ver a las camareras.",227,0,37,296,"",0,4,"ea",-1,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-08",23,"En el barrio del Perchel\nhan puesto una lechería\npara dar el biberón\na los mozos de hoy en día.",227,0,37,296,"",0,4,"ia",0,0,-1,0,17,17,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0017-09",23,"San Juan y la Magdalena\nfueron a robar melones;\npor huir de la justicia,\nSan Juan perdió los calzones.",227,0,37,297,"",0,4,"oe",34,0,-1,0,17,17,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0017-10",23,"Válgame Dios de los cielos,\na lo hecho no hay remedio:\nSan Juan tenía una novia\ny se la quitó San Pedro.",227,0,37,297,"",0,4,"eo",-1,0,-1,0,17,17,"","",0,"","","",33,0,0,[],"",""],["navalmoral_mata-p0017-11",23,"Un cura estaba meando\nen el tronco de una encina,\nse le cayó una bellota\ny le tronchó la minina.",227,0,37,297,"",0,4,"ia",11,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0017-12",23,"El cura de Peraleda\nno tiene más que una cama;\nsi en ella se acuesta el cura,\n¿dónde coño duerme el ama?",227,0,37,297,"",0,4,"aa",90,0,-1,0,17,17,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0017-13",23,"El cura le dijo al ama:\n\"Échate a los pies, cordera\".\nElla lo entendió al revés\ny se echó a la cabecera.",227,0,37,297,"",0,4,"ea",44,0,-1,0,17,17,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-01",23,"El cura de Peraleda\nle dijo al de Saucedilla:\n\"Yo soy más padre que tú,\nque soy padre de familia\".",227,0,37,297,"",0,4,"ia",-1,0,-1,0,18,18,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0018-02",23,"El cura perdió la mula\ny el sacristán perdió el potro\ny ahora tiene que montar\nel uno encima del otro.",227,0,37,297,"",3,4,"oo",275,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-03",23,"El cura de Torviscoso\npor ir a la misa santa\nse le ha caído la burra\ny no puede levantarla.",227,0,37,297,"",0,4,"aa",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-04",23,"El cura de Salmoral\ntiene la sotana rota,\nse la rompió en una zarza\npor correr tras de una moza.",227,0,37,297,"",0,4,"oa",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-05",23,"Para qué queremos rey\nsi en la baraja ya hay cuatro:\nel de oros, el de copas,\nel de espadas y el de bastos.",227,0,37,298,"",0,4,"ao",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-06",23,"Todos tienen una suegra,\nyo quisiera tener dos\npara engancharlas a un carro\ny de carretero, yo.",227,0,37,299,"",0,4,"o",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-07",23,"¡Si a mi suegra le picara\nuna víbora de cría\ny se estuviera arrascando\nun mes con cuarenta días!",227,0,37,299,"",0,4,"ia",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-08",23,"Anda diciendo tu madre\nque las gallinas no ponen:\nella se come los huevos\ny tira los cascarones.",227,0,37,299,"",0,4,"oe",-1,0,-1,0,18,18,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0018-09",23,"Mi suegra pa que la quiera\nme ha regalado un rosario\ny tengo yo con su hija\ncadena, cruz y rosario.",227,0,37,299,"",0,4,"ao",-1,0,-1,0,18,18,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0018-10",23,"Mi suegra, la vanidosa,\nme ha regalado un rosario\ny tengo yo con su hijo\ncorona, cruz y calvario.",227,0,37,299,"",0,4,"ao",25,0,-1,0,18,18,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0018-11",23,"Mi suegra pa que la quiera\nme ha regalado un reloj\ny tengo yo con su hija\nreloj de repetición.",227,0,37,299,"",0,4,"o",-1,0,-1,0,18,18,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0018-12",23,"Si mi suegra no me quiere,\nque se vaya a hacer puñetas,\nque, teniendo yo el clavel\n¿pa qué quiero la maceta?",227,0,37,299,"",0,4,"ea",-1,0,-1,0,18,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-01",23,"Tu madre a mí no me quiere\nporque dice que soy pobre;\nmás pobres son las cigüeñas,\nque están viviendo en la torre.",227,0,37,299,"",0,4,"oe",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-02",23,"Anda diciendo tu madre\nque los quieres de carrera;\nen mi casa tengo un galgo,\nvaya por él cuando quiera.",227,0,37,299,"",0,4,"ea",44,0,-1,0,19,19,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0019-03",23,"Anda diciendo tu madre\nde mi honor no sé qué;\n¿para qué enturbiar el agua\nsi la tiene que beber?",227,0,37,299,"",0,4,"e",-1,0,-1,0,19,19,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0019-04",23,"Anda diciendo mi suegra\nque soy un gallo capón;\nque le pregunte a su hija\ncómo tengo el espolón.",227,0,37,299,"",0,4,"o",31,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-05",23,"Mi suegra, la tía pescueza,\nme ha llamado panza alegre\ny yo la dije: \"Tía galga,\ncorre usté más que las liebres\".",227,0,37,299,"",0,4,"ee",-1,0,-1,0,19,19,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0019-06",23,"Esta calle tiene esquinas\nque no las suben los gatos,\npero las sube mi suegra\nsin quitarse los zapatos.",227,0,37,299,"",0,4,"ao",386,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-07",23,"Cuando se muera mi suegra,\nque la entierren boca abajo,\npor si se quiere salir\nque se meta más abajo.",227,0,37,299,"",0,4,"ao",-1,0,-1,0,19,19,"","",0,"","","",7,0,0,[],"",""],["navalmoral_mata-p0019-08",23,"Desde que salió la moda\nde tirar la suegra al mar,\nla mía, la tía pescueza,\nestá aprendiendo a nadar.",227,0,37,299,"",0,4,"a",21,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-09",23,"Mi suegra, la tía pescueza,\nla quiero tirar al mar\ny ella, la muy puñetera,\nse está enseñando a nadar.",227,0,37,299,"",0,4,"a",21,0,-1,0,19,19,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0019-10",23,"Mi suegra, la tía pescueza,\ntuvo que ser confitera:\npor eso tiene la hija\ntan dulce la pepinera.",227,0,37,299,"",0,4,"ea",44,0,-1,0,19,19,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0019-11",23,"Mi suegra tenía una huerta\ny en medio una regatera,\npor eso tiene la hija\ntan fresca la pepinera.",227,0,37,299,"",0,4,"ea",44,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-12",23,"El pellejo de mi suegra\nlo llevé a la tenería\ny me dijo el curtidor\nque era viejo y no valía.",227,0,37,299,"",0,4,"ia",0,0,-1,0,19,19,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0019-13",23,"En la mar se hundió un barco\ny en él estaba mi suegra,\npor eso los calamares\ntienen la tinta tan negra.",227,0,37,299,"",0,4,"ea",382,0,-1,0,19,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-01",23,"Si quieres ser buena suegra\ny por la nuera alabada,\nten la bolsa bien abierta\ny la boca bien cerrada.",227,0,37,299,"",0,4,"aa",49,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-02",23,"Mírala por dónde viene\nla madre de mis amores,\nla que crió para mí\nese ramito de flores.",227,0,37,299,"",0,4,"oe",5,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-03",23,"A tu puerta llamo puerta;\na tu ventana, ventana;\na tu madre, jardinera\ny a ti, rosita temprana.",227,0,37,299,"",0,4,"aa",4,0,-1,0,20,20,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0020-04",23,"Anoche me salió novio\ny se lo dije a mi abuela,\nestaba comiendo sopas\ny me tiró la cazuela.",227,0,37,300,"",0,4,"ea",167,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-05",23,"En mi vida he visto yo\nlo que he visto esta mañana:\nun elefante en un pozo\ndando por culo una rana.",227,0,37,300,"",0,4,"aa",4,0,-1,0,20,20,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0020-06",23,"Ya no son sólo los gatos\nlos que andan por los tejados,\nque son las putas baratas,\nen busca del bacalao.",227,0,37,300,"",0,4,"ao",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-07",23,"En la torre de la iglesia\nhay un nido de jilgueros\ny el señor cura ya ha dicho\nque no le toquen los güevos",227,0,37,300,"",0,4,"eo",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-08",23,"Andan diciendo los ricos\nque nos muramos los pobres;\ntenemos un patatal\nque nos zumba los cojones.",227,0,37,300,"",0,4,"oe",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-09",23,"Si quieres saber quién soy\ny de qué familia vengo\nbájame los pantalones\n¡verás qué cojones tengo!",227,0,37,300,"",0,4,"eo",124,0,-1,0,20,20,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0020-10",23,"Las mocitas cuando mean\nse lo limpian con la mano\ny los guarros de los hombres\nse lo sacuden a mano.",227,0,37,300,"",0,4,"ao",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0020-11",23,"Cuando me parió mi madre,\nal punto dijo mi abuela:\n\"Este niño es cantaor,\nporque trae castañuelas\".",227,0,37,300,"",0,4,"ea",-1,0,-1,0,20,20,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0021-01",23,"A tu puerta me cagué\nporque me vino la gana,\nahí te dejo el clavel\npara que huelas mañana.",227,0,37,300,"",0,4,"aa",4,0,-1,0,21,21,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0021-02",23,"A tu puerta me cagué\ncreyendo que me querías;\nahora que ya no me quieres,\ndame la mierda, que es mía.",227,0,37,300,"",0,4,"ia",-1,0,-1,0,21,21,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0021-03",23,"Mi aguelo tenía un choto\nque se llamaba Gabino;\ncada vez que lo llamaba,\n\"¡Ven-Gabino Ven-Gabino!\".",227,0,37,301,"",0,4,"io",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0021-04",23,"El vino tinto es mi primo,\nel aguardiente, pariente,\nyo me voy a la taberna,\nque allí está toda mi gente.",227,0,37,301,"",0,4,"ee",15,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0021-05",23,"La guitarra pide vino\ny las cuerdas aguardiente\ny el tocador que las toca,\nmocitas de quince a veinte.",227,0,37,301,"",0,4,"ee",-1,0,-1,0,21,21,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0021-06",23,"Este rabel pide vino\ny las cuerdas aguardiente\ny el mocito que lo toca,\nmocitas de quince a veinte.",227,0,37,301,"",0,4,"ee",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0021-07",23,"La calle del sol me mata,\nla torre del lao me alegra,\nla calle de los mesones\nme quita todas las penas.",227,0,37,301,"",0,4,"ea",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0021-08",23,"Hasta ayer no supe yo\nque al que se muere lo entierran,\nyo creí que lo llevaban\nderechito a la taberna.",227,0,37,301,"",0,4,"ea",-1,0,-1,0,21,21,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0021-09",23,"Borracho me acosté anoche,\nborracho me levanté,\nyo no sé que coño me pasa,\nborracho estoy otra vez.",227,0,37,301,"",0,4,"e",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0021-10",23,"La zambomba está borracha\ny el que la toca también,\nlos que la están escuchando\nya no se pueden tener.",227,0,37,301,"",0,4,"e",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0022-01",23,"Las mocitas de La Vera\nson guapas pero sin dientes,\nde beber el agua fría\ny los calbotes calientes.",227,0,37,302,"",0,4,"ee",252,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0022-02",23,"Ya viene la primavera,\nya viene cantando el grillo,\nya vienen las peraleas,\n\"¡espárragos y cardillos!\"",227,0,37,302,"",0,4,"io",-1,0,-1,0,22,22,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0022-03",23,"No te cases, no te cases,\ny estate siempre mocita\nque la rosa en el rosal\nsiempre está coloradita.",227,0,37,303,"",0,4,"ia",50,0,-1,0,22,22,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0022-04",23,"Yo me quisiera casar\ncon una que no pariera:\nfuera rica o fuera pobre,\nsu madre la mantuviera.",227,0,37,303,"",0,4,"ea",44,0,-1,0,22,22,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0022-05",23,"Dicen que casar, casar;\nyo también me casaría\nsi la vida de casado\nfuera como el primer día.",227,0,37,303,"",0,4,"ia",0,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0022-06",23,"Yo le pregunté a una casada:\n\"Casada, ¿qué tal te va?\"\ny la casada me dijo:\n\"Cásate tú y lo verás\".",227,0,37,303,"",0,4,"a",-1,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0022-07",23,"Una oliva bien plantada\nsiempre parece olivera,\nuna niña bien casada\nsiempre parece soltera",227,0,37,303,"",1,4,"ea",44,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0022-08",23,"Ya salen las casaditas,\nya salen de los rincones,\nya salen las casaditas,\nrobando los corazones.",227,0,37,303,"",1,4,"oe",34,0,-1,0,22,22,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0023-01",23,"La aceituna en el olivo,\nsi no se coge se pasa,\nlo mismo que las mocitas,\nsi a su tiempo no se casan.",227,0,37,303,"",0,4,"aa",-1,0,-1,0,23,23,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0023-02",23,"Todo hombre que se casa\ncon una mujer bonita,\nhasta que no llega a viejo\nel miedo no se le quita.",227,0,37,303,"",0,4,"ia",50,0,-1,0,23,23,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0023-03",23,"Una vez que fui soldado\ny cabo no pude ser;\nahora que ya me he casado,\nhe llegado a coronel.",227,0,37,303,"",0,4,"e",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0023-04",23,"Anda diciendo tu madre\nque tienes un olivar:\nel olivar que tú tienes\nes que te quieres casar.",227,0,37,303,"",0,4,"a",21,0,-1,0,23,23,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0023-05",23,"Anda diciendo tu madre\nque tienes y que tenías\nolivares en la Mancha\ny tierra en Andalucía.",227,0,37,303,"",0,4,"ia",-1,0,-1,0,23,23,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0023-06",23,"Madre, cáseme usted,\nque yo sé muy bien guisar:\na lo soso le echo agua\ny a lo saladito sal.",227,0,37,303,"",0,4,"a",-1,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0023-07",23,"Despedirse, despedirse,\nque nos vamos, que nos vamos,\nque estamos haciendo falta\nen el sitio que no estamos.",227,0,37,304,"",0,4,"ao",116,0,-1,0,23,23,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0023-08",23,"Allá va la despedida,\nyo no la quisiera echar,\npero se van mis amigos\ny me tengo que marchar.",227,0,37,304,"",0,4,"a",21,0,-1,0,23,23,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0023-09",23,"Allá va la despedida,\nyo no la quisiera echar,\npero se me ha roto una cuerda\ny la tengo que arreglar.",227,0,37,304,"",0,4,"a",21,0,-1,0,23,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-01",23,"Allá va la despedida,\nla que dan los herraores,\ncon la herradura en la mano\ny adiós, ramito de flores.",227,0,37,304,"",0,4,"oe",5,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-02",23,"Allá va la despedida,\nla que dan los zambomberos,\nalrededor de la lumbre,\ncalentando los calderos.",227,0,37,304,"",0,4,"eo",22,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-03",23,"Allá va la despedida,\nque me lo manda un amigo:\nsi me manda, yo le mando;\nsi me sirve, yo le sirvo.",227,0,37,304,"",0,4,"io",-1,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-04",23,"Allá va la despedida\ncon veinticinco claveles\ny una rosa de geranio\npara que de mí te acuerdes.",227,0,37,304,"",0,4,"ee",-1,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-05",23,"Allá va la despedida\ncon un ramito de nueces,\nque a ninguna se la he dado,\npero tú te la mereces.",227,0,37,304,"",0,4,"ee",196,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-06",23,"Allá va la despedida,\nque la mía es la mejor,\nporque ninguno te ha dicho:\n\"buenas noches, blanca flor\".",227,0,37,304,"",0,4,"o",72,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-07",23,"Allá va la despedida\ncon un ramo de alhelí,\ncon él te mando un beso, morena\npara que te acuerdes de mí.",227,0,37,304,"",3,4,"i",23,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-08",23,"Nos vamos a despedir\ncomo el sol de las paredes,\nque por las noches se va\ny por las mañanas vuelve.",227,0,37,304,"",0,4,"ee",-1,0,-1,0,24,24,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0024-09",23,"Allá va la despedida\nal estilo de mi tierra,\nal que nace lo bautizan\ny al que se muere lo entierran.",227,0,37,304,"",0,4,"ea",-1,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0024-10",23,"Allá va la despedida,\nque se me seca el ombligo\nporque no veo venir\nla botella de vino.",227,0,37,304,"",0,4,"io",-1,0,-1,0,24,24,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0025-01",23,"Las ventanas a la calle\ndicen que son peligrosas\npa los padres que tienen\nen casa hijas hermosas.",227,0,37,305,"",0,4,"oa",61,0,-1,0,25,25,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0025-02",23,"Dicen que andando, andando,\nse encuentran cosas,\nyo me encontré contigo,\ncara de rosa.",227,0,37,305,"",6,4,"oa",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0025-03",23,"Entre dos cortinas negras\ndos minas me han vuelto loco:\nlas cortinas, tus pestañas;\nlas niñas, las de tus ojos.",227,0,37,305,"",0,4,"oo",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0025-04",23,"El cristal de tu ventana\ncon el aliento lo empaño:\nen él escribo tu nombre\ny a besos lo voy borrando.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0025-05",23,"Las cortinas de tu alcoba\nson de terciopelo azul;\nentre cortina y cortina,\nun ángel pareces tú.",227,0,37,305,"",0,4,"u",-1,0,-1,0,25,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-01",23,"En la reja a tu ventana\nhay un gavilán prendido\nque se ha querido llevar\nla paloma de este nido.",227,0,37,305,"",0,4,"io",101,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-02",23,"Arrímate bailaor,\narrímate que no pecas,\nque el que baila y no se arrima\nes comer el pan a secas.",227,0,37,305,"",0,4,"ea",647,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-03",23,"Ahora sí que canto yo\ncon alegría y salero\nporque ha salido a bailar\nla chica que yo más quiero.",227,0,37,305,"",0,4,"eo",38,0,-1,0,26,26,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0026-04",23,"Cuando tocas la guitarra,\nla tocas muy despacito\nparece que vas diciendo\nque te quiera otro poquito.",227,0,37,305,"",0,4,"io",119,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-05",23,"Paso el río, paso el puente,\npaso la verde arboleda;\nsiempre te encuentro lavando,\nrosita de primavera.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-06",23,"Todos los enamorados\nse enamoran en el baile;\nyo me enamoré de ti\nyendo a por agua una tarde.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,26,26,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0026-07",23,"Yo a mi novia acompañé\na llenar la botijica\n¡qué buenos ratos pasamos\ncerca de la fuentecica!",227,0,37,305,"",0,4,"ia",174,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-08",23,"En el camino de arena\nhay un molino que muele\nperejil y hierbabuena\npara las damas que tienen\namores en tierra ajena.",227,0,37,305,"",7,5,"ea",59,0,-1,0,26,26,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0026-09",23,"Mocita de junto al río,\nya te tengo el ojo echado:\nsi no me caso contigo,\njamás me hubiera casado.",227,0,37,305,"",0,4,"ao",14,0,-1,0,26,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-01",23,"Una rubia me dio a mí\nagua en un cántaro nuevo;\ncada vez que bebo agua,\nde aquella rubia me acuerdo.",227,0,37,305,"",0,4,"eo",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-02",23,"Dicen que el agua divierte,\nquita penas y fatigas;\nyo me arrimaré a una fuente\npor ver si el agua me anima.",227,0,37,305,"",0,4,"ia",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-03",23,"Bajo un laurel florido\ntiene mi dama la cama\ny cuando se va a acostar\ncuelga el candil de una rama.",227,0,37,305,"",0,4,"aa",90,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-04",23,"Tengo yo una cuñadita\nque todo se lo merece:\nhasta la hierba que pisa\nsi está seca, reverdece.",227,0,37,305,"",0,4,"ee",64,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-05",23,"Dicen que las pastoras\nhuelen a sebo;\npastorcita es mi novia\ny huele a romero.",227,0,37,305,"",6,4,"eo",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-06",23,"A la sierra me he de ir\naunque me arrizca de frío\npor ver si puedo traerme\nuna serrana conmigo.",227,0,37,305,"",0,4,"io",-1,0,-1,0,27,27,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0027-07",23,"Eres como hierbabuena\nque en campo verde nace,\neres como caramelo\nque en la boca se deshace.",227,0,37,305,"",0,4,"ae",84,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0027-08",23,"¿Cómo quieres, capullito,\ncompararte con las rosas\nteniendo el olor más fino\ny las hojas más hermosas?",227,0,37,305,"",0,4,"oa",61,0,-1,0,27,27,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-01",23,"Cuando ibas entrando\nen el jardín,\nniña, las pantorrillas\nyo te las vi.",227,0,37,305,"",6,4,"i",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-02",23,"Un vez que fui a aceitunas\ncon unas aceituneras\nme hicieron pasar el río,\nsin puente y sin pasaderas.",227,0,37,305,"",0,4,"ea",103,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-03",23,"Unos ojos negros vi\nen una cara morena;\nsi no han de ser para mí\nque se los trague la tierra.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,28,28,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0028-04",23,"Por la calle abajo va\nla que tiene que ser mía,\nla que tiene que juntar\nsu carita con la mía.",227,0,37,305,"",0,4,"ia",-1,0,-1,0,28,28,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0028-05",23,"Manojitos de alfileres\nme parecen tus pestañas:\ncuando te miro de frente\nse me clavan en el alma.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,28,28,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0028-06",23,"Tengo penas si te veo\ny si no te veo, doble;\nno tengo más alegría\nque cuando escucho tu nombre.",227,0,37,305,"",0,4,"oe",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-07",23,"Los amantes de Teruel\nmurieron de sentimiento;\nyo también me moriré\nsi no logro lo que intento.",227,0,37,305,"",0,4,"eo",94,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-08",23,"Las tejas de tu tejado\nson de plata y pesan poco;\nla vida me ha de costar\nsi tú te casas con otro.",227,0,37,305,"",0,4,"oo",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0028-09",23,"Si me quieres, dímelo\ny si no, dame veneno,\nque sea la primera dama\nque se muere por su dueño.",227,0,37,305,"",0,4,"eo",-1,0,-1,0,28,28,"","",0,"","","",17,0,0,[],"",""],["navalmoral_mata-p0029-01",23,"Morenita, morenita,\nmal hay en tu morenura,\npues me tienes en la cama\nmalito y sin calentura.",227,0,37,305,"",0,4,"ua",17,0,-1,0,29,29,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0029-02",23,"Viva Cádiz, viva El Puerto,\nviva el saber querer,\nviva el que pasa en el mundo\npenas por una mujer.",227,0,37,305,"",0,4,"e",20,0,-1,0,29,29,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0029-03",23,"Quisiera ser por un rato\narillo de tus pendientes\npara decirte al oído\nlo que mi corazón siente.",227,0,37,305,"",0,4,"ee",-1,0,-1,0,29,29,"","",0,"","","",9,0,0,[],"",""],["navalmoral_mata-p0029-04",23,"Un beso tengo en los labios\na salir y no se atreve:\nsácamelo con los tuyos\nsi es que es verdad que me quieres.",227,0,37,305,"",0,4,"ee",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0029-05",23,"Si canto dicen que canto,\nsi lloro dicen que lloro\ny si me estoy calladita\ndicen que pienso en el novio.",227,0,37,305,"",0,4,"oo",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0029-06",23,"Qué bonita está una parra\ncon los racimos colgando;\nmás bonita está una niña\nde catorce a quince años.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-01",23,"Aquella clavellina\nque está puesta en la ventana\nsi la riegan esta noche,\nclaveles para mañana.",227,0,37,305,"",0,4,"aa",4,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-02",23,"Eres más chica que un huevo\ny ya te quieres casar,\nanda, ve y dile a tu madre\nque te enseñe a cocinar.",227,0,37,305,"",0,4,"a",21,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-03",23,"Tan pequeñita y con novio,\nya se lo diré a tu madre,\nque no te deje salir\nni a la puerta de la calle.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-04",23,"No hay carretera sin curvas\nni puente sin arroyuelo,\nno hay mocita que se olvide\nde sus amores primeros.",227,0,37,305,"",0,4,"eo",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-05",23,"El primer novio que tuve\nle metí en una maleta,\nle llevé a la casa empeño\ny me dieron tres pesetas.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-06",23,"La otra tarde vi vender\nen la plazuela real\nlas palabrillas de un hombre,\nnadie las quiso comprar.",227,0,37,305,"",0,4,"a",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-07",23,"Mozo de las veinte novias\ny conmigo veintiuna:\nsi todas son como yo,\ntú no has tenido ninguna.",227,0,37,305,"",0,4,"ua",56,0,-1,0,30,30,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0030-08",23,"Al hombre yo lo comparo\nlo mismo que a los melones,\nque hasta que no se les cala\nno se ven las intenciones.",227,0,37,305,"",0,4,"oe",34,0,-1,0,30,31,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0031-01",23,"Es el amor de los hombres\ncomo el sombrero de paja,\nque por mucho que los cuides\nno aguanta la temporada.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,31,31,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0031-02",23,"Amor mío, come y bebe,\nde mí no tengas sospechas,\nque me tienes tan segura\ncomo el agua en una cesta",227,0,37,305,"",0,4,"ea",-1,0,-1,0,31,31,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0031-03",23,"En una fila de mozos\nme pusieron a escoger:\nen un Juan puse los ojos,\nen un Francisco el querer.",227,0,37,305,"",0,4,"e",20,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0031-04",23,"El cielo está nublaíto,\nestá si llueve o no llueve;\nasí está mi corazón,\nsi te quiere o no te quiere.",227,0,37,305,"",0,4,"ee",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0031-05",23,"Cuando quise no quisiste,\nahora que quieres no quiero:\npásate la vida triste,\nque yo la pasé primero.",227,0,37,305,"",1,4,"eo",38,0,-1,0,31,31,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0031-06",23,"Me quisiste, me olvidaste\nme volvistes a querer;\nzapatos que yo desecho,\nno me los vuelvo a poner.",227,0,37,305,"",0,4,"e",20,0,-1,0,31,31,"","",0,"","","",8,0,0,[],"",""],["navalmoral_mata-p0031-07",23,"Yo conocí a quien tenía\nun pajarillo en la mano\ny por ir a coger otro\nse le han escapado ambos.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0031-08",23,"Si me quieres, dímelo\ny si no di que me vaya,\nno me tengas al sereno,\nque no soy cántaro de agua.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,31,31,"","",0,"rm_t2, palau_cantares","","",17,0,0,[],"",""],["navalmoral_mata-p0031-09",23,"Cómo quieres que adivine\nsi estás despierta o dormida\ncomo no baje un ángel\ndel cielo y me lo diga.",227,0,37,305,"",0,4,"ia",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0032-01",23,"Agua menudita llueve\ny corre por los canales;\nábreme la puerta, cielo,\nque soy el que tú ya sabes.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,32,32,"","",0,"","","",6,0,0,[],"",""],["navalmoral_mata-p0032-02",23,"Esta noche voy a ver\nla voluntad que me tienes:\nsi no te acuestas conmigo,\nes verdad que no me quieres.",227,0,37,305,"",0,4,"ee",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0032-03",23,"¿Cómo quieres que una luz\nalumbre a dos aposentos;\ncómo quieres que yo adore\ndos corazones a un tiempo?",227,0,37,305,"",0,4,"eo",-1,0,-1,0,32,32,"","",0,"","","",7,0,0,[],"",""],["navalmoral_mata-p0032-04",23,"Yo soy más clara que el agua\nque corre por esos caños,\nal que quiero doy palabra\ny al que no, lo desengaño.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0032-05",23,"Yo creí que era yo solo\nel que tu jardín regaba;\nahora veo que son muchos\nlos cubos que sacan agua.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,32,32,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0032-06",23,"No eres una ni eres dos,\nno eres tres ni eres cuarenta,\neres la iglesia mayor\ndonde todo el mundo entra.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0032-07",23,"Anoche a la tu ventana\notro ventanero vi.\nNo quise darle la muerte\npor no hacerte de sufrir.",227,0,37,305,"",0,4,"i",-1,0,-1,0,32,32,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0032-08",23,"Aunque me veas con otra\nno tengas celos de mí,\ntodas me parecen feas\ncuando me acuerdo de ti.",227,0,37,305,"",0,4,"i",23,0,-1,0,32,32,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-01",23,"Un limón eché a rodar\ny a tu puerta se paró,\nya hasta los limones saben\nque nos queremos tú y yo.",227,0,37,305,"",0,4,"o",2,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-02",23,"Anda diciendo tu madre\nque yo para ti soy poco;\niremos a la alameda\ny cortaremos un chopo.",227,0,37,305,"",0,4,"oo",-1,0,-1,0,33,33,"","",0,"","","",23,0,0,[],"",""],["navalmoral_mata-p0033-03",23,"Cuando paso por tu puerta\ncojo pan y voy comiendo\npa que no diga tu madre\nque con verte me mantengo.",227,0,37,305,"",0,4,"eo",-1,0,-1,0,33,33,"","",0,"","","",17,0,0,[],"",""],["navalmoral_mata-p0033-04",23,"Cuando mi madre me manda\nque vaya a cerrar la puerta:\ndoy cien vueltas a la llave\ny siempre la dejo abierta.",227,0,37,305,"",0,4,"ea",267,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-05",23,"Por un beso que te di\nlloraba tu madre un día;\nanda dame tú a mí otro\na ver si llora la mía.",227,0,37,305,"",0,4,"ia",0,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-06",23,"Tu madre y la mía tienen\npleito porque nos queremos\ndéjalas que ellas pleiteen,\nnosotras sentenciaremos.",227,0,37,305,"",0,4,"eo",127,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-07",23,"Tu madre es la que no quiere\nque yo tu carita vea;\npor encima de tu madre\nvoy a hacer yo una vereda.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-08",23,"Si yo fuera gato montés\ny entrara por tu ventana\na ti te diera un besito\ny a tu madre la arañara.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-09",23,"Una vez que yo quisí,\ntu madre no quisió;\nla puñetera la vieja\ntodo lo descompusió.",227,0,37,305,"",0,4,"o",2,0,-1,0,33,33,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0033-10",23,"Las mocitas de hoy en día\nno saben fregar un plato\npero sí saben llevar\nen la barriga un muchacho.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,33,33,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0034-01",23,"Tu madre tuvo la culpa\npor dejar la puerta abierta,\nyo por meterme pa dentro\ny tú por estarte quieta.",227,0,37,305,"",0,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0034-02",23,"Eres mi prima y me pesa\nel haberte conocido;\nojalá no fueras nada\npara casarme contigo.",227,0,37,305,"",0,4,"io",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0034-03",23,"Me quitan de que te quiera\ny también de que te ame,\npero no me han de quitar\nlos ojos para mirarte.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0034-04",23,"En Navalmoral no hay mozos\ny si los hay no se atreven,\nque vienen los forasteros\ny se llevan las que quieren.",227,0,37,305,"",0,4,"ee",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0034-05",23,"En este pueblo no hay mozos\ny si los hay no los veo:\nestarán en la cocina\nal cuidao de los pucheros.",227,0,37,305,"",0,4,"eo",-1,0,-1,0,34,34,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0034-06",23,"En mi vida he visto yo\nlo que he visto en este baile:\ntodas las mozas sentadas\nporque hay mozos cobardes",227,0,37,305,"",0,4,"ae",-1,0,-1,0,34,34,"","",0,"","","",5,0,0,[],"",""],["navalmoral_mata-p0034-07",23,"Los mozos de este pueblo\nson todos unos maricas\nque se van a las carteleras\na criticar a las chicas.",227,0,37,305,"",0,4,"ia",737,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0034-08",23,"Madre, que me quedo moza\nsin probar el chocolate,\nhágame usted cuatro onzas\nsiquiera pa que lo cate.",227,0,37,305,"",0,4,"ae",384,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-01",23,"Si yo me volviera mozo\ny lo pasado, pasado\nle ajustaría las cuentas\na ésa de lo colorado.",227,0,37,305,"",0,4,"ao",14,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-02",23,"Morenas las hay morenas\npero como tú, ninguna:\nquitas los rayos al sol\ny el resplandor a la luna.",227,0,37,305,"",0,4,"ua",56,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-03",23,"Me llamaste morenita\nme alegré cuando lo supe,\nporque morenita es\nla Virgen de Guadalupe.",227,0,37,305,"",0,4,"ue",271,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-04",23,"Perchelera de ojos negros,\nla de las largas pestañas,\ntú llevas luto en los ojos\ny yo lo llevo en el alma.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-05",23,"Todos los ojitos negros\nlos aprisionan mañana;\nmorena, tú que los tienes\néchate un velo a la cara.",227,0,37,305,"",0,4,"aa",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0035-06",23,"En lo alto de la sierra,\nlo moreno es lo que vale:\nlo blanco lo quema el sol,\nlo coloradito el aire.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,35,35,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0035-07",23,"Los dientes de tu boquita\nme tienen cautivo y preso;\nen mi vida he visto yo\nhacer cadenas de hueso.",227,0,37,305,"",0,4,"eo",48,0,-1,0,35,35,"","",0,"","","",6,0,0,[],"",""],["navalmoral_mata-p0036-01",23,"Bendito tu rico pico,\ny tu lindo y rico talle,\nbendita tú, rica toda,\nno hay riqueza que te iguale.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-02",23,"Eres alta y buena moza,\nno te lo presumas tanto,\nque también las buenas mozas\nse quedan pa vestir santos.",227,0,37,305,"",0,4,"ao",-1,0,-1,0,36,36,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0036-03",23,"Eres chiquita y bonita,\nasí como eres te quiero,\neres como una perlita\nde las manos de un platero.",227,0,37,305,"",1,4,"eo",38,0,-1,0,36,36,"","",0,"","","",12,0,0,[],"",""],["navalmoral_mata-p0036-04",23,"Dos hermanitas duermen\nen una cama de alambre;\nsi mucho quiero a la chica,\nmucho más quiero a la grande.",227,0,37,305,"",0,4,"ae",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-05",23,"Vale más una extremeña\ncon una cintita al pelo\nque todas las castellanas\nvestidas de terciopelo.",227,0,37,305,"",0,4,"eo",10,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-06",23,"Eres como el arcoíris\nque se aparta de la tormenta;\nyo no me aparto de ti\nporque no me tiene cuenta.",227,0,37,305,"",0,4,"ea",229,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-07",23,"Con una pluma en la mano\nyo me puse a dibujar\nlos colores de tu cara\nen un vaso de cristal.",227,0,37,305,"",0,4,"a",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-08",23,"Mira qué alta va la luna,\nmás alta no puede ir;\nmás altos van mis suspiros\ncuando me acuerdo de ti.",227,0,37,305,"",0,4,"i",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0036-09",23,"Yo me arrimé a un pino verde\narrimado a la pared:\ncuando el pino florezca,\nte dejaré de querer.",227,0,37,305,"",0,4,"e",-1,0,-1,0,36,36,"","",0,"","","",3,0,0,[],"",""],["navalmoral_mata-p0037-01",23,"En tu puerta planté un guindo\ny en tu ventana un cerezo:\npor cada guinda un abrazo,\npor cada cereza un beso.",227,0,37,305,"",0,4,"eo",48,0,-1,0,37,37,"","",0,"","","",2,0,0,[],"",""],["navalmoral_mata-p0037-02",23,"María, por ti me iría\na vivir a un espinero\na la orillita del mar,\ncomo junco marinero.",227,0,37,305,"",0,4,"eo",38,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0037-03",23,"Si quieres que al cielo suba\ny las estrellas cuente,\nque coja la más bonita\ny te la ponga en la frente.",227,0,37,305,"",0,4,"ee",15,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0037-04",23,"Las estrellitas del cielo\nlas cuento y no están cabales,\nfaltan la tuya y la mía,\nque son las dos principales.",227,0,37,305,"",0,4,"ae",26,0,-1,0,37,37,"","",0,"","","",25,0,0,[],"",""],["navalmoral_mata-p0037-05",23,"Si estás en el campo arando\ny te viene un aire frío,\nrecíbelo con amor\nque son suspiritos míos.",227,0,37,305,"",0,4,"io",-1,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0037-06",23,"Vente conmigo, conmigo,\nvente conmigo y tendremos\nuna casita en el campo\ny allí juntos viviremos.",227,0,37,305,"",0,4,"eo",127,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0037-07",23,"Los hombres y las mujeres\na veces nos peleamos,\npero al llegar la noche\na la misma cama vamos.",227,0,37,305,"",0,4,"ao",116,0,-1,0,37,37,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0038-01",23,"¿Cómo quieres que te quiera\nsi me estás amenazando?\nEl día que yo sea tuya,\nla muerte me está esperando.",227,0,37,305,"",0,4,"ao",33,0,-1,0,38,38,"","",0,"","","",16,0,0,[],"",""],["navalmoral_mata-p0038-02",23,"¿Cómo quieres que te quiera\nsi siempre me estás pegando,\ncomo si mi cuerpo fuera\nhecho de piedra o de mármol?",227,0,37,305,"",0,4,"ao",-1,0,-1,0,38,38,"","",0,"","","",16,0,0,[],"",""],["navalmoral_mata-p0038-03",23,"Mi mujer me dijo a mí\nque cantara y no llorara,\nque echara las penas a un lado\npero que no la olvidara.",227,0,37,305,"",0,4,"aa",57,0,-1,0,38,38,"","",0,"","","",1,0,0,[],"",""],["navalmoral_mata-p0038-04",23,"Amor mío, si te vas,\nescríbeme en el camino,\ny si no encuentras papel,\nen la hoja de un olivo.",227,0,37,305,"",0,4,"io",-1,0,-1,0,38,38,"","",0,"","","",4,0,0,[],"",""],["navalmoral_mata-p0038-05",23,"Que no\nme dejes sola, que yo\nme voy contigo\npara que no bebas agua\nen la fuente del olvido.",227,0,37,305,"",7,5,"io",-1,0,-1,0,38,38,"","",0,"","","",0,0,0,[],"",""],["pacifico_colombia-p0034-01",24,"Mi señora no me quiere,\nMi amo no me puede ve;\nMi señora, la chiquita,\nDice que me ha de vendé\nPor un plátano maduro\nY una totumita de mié",228,3,38,-1,"",9,6,"e",77,0,-1,0,34,34,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0034-02",24,"—Mi señora, la chiquita,\n¡No me venda sumecé!\n¡Fracica!\n—¡Señó!\n—¡Tu amo te quiere vendé!\n—¿Po qué?¿Po qué?\n—Poque no sabé molé",228,3,38,-1,"",4,7,"e",77,0,-1,0,34,34,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0034-03",24,"—Manque nunca sepa\nYo aprenderé,\nY si no aprendiere\nVéndame uté.",228,3,38,-1,"",6,4,"e",77,0,-1,0,34,34,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0035-01",24,"¡Molé, molé!\n¡Molé, trapiche, molé!\nMolé la caña pasada.\nMoléla a la medianoche\nMoléa a la madrugada.",228,3,38,-1,"",7,5,"aa",49,0,-1,0,35,35,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0051-02",24,"La virgen se está peinando\ndebajo de una palmera\nlos peines eran de plata,\nsu cinta es de primavera\nPor aquí pasó Jesús\ndiciéndole de esta manera",228,3,38,-1,"",9,6,"ea",44,0,-1,0,51,51,"","",78,"","","",9,0,0,[],"",""],["pacifico_colombia-p0053-01",24,"La virgen se está peinando\nentre cortina y cortina,\nlos cabellos son de oro\ny el peine de plata fina.",228,3,38,-1,"",0,4,"ia",11,0,-1,0,53,53,"","",78,"","","",9,0,0,[],"",""],["pacifico_colombia-p0054-01",24,"La virgen se está peinando\ndebajo de una palmera,\nlos peines eran de plata,\nla cinta de primavera.",228,3,38,-1,"",0,4,"ea",44,0,-1,0,54,54,"","",78,"","","",9,0,0,[],"",""],["pacifico_colombia-p0083-01",24,"Muy bonita es mi chatica,\nSólo un defecto le hallé;\nNo tiene los ojos negros,\nPero yo se los pondré.",228,3,38,-1,"",0,4,"e",77,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-02",24,"El primer amor que tuve\nParecía una borrachera:\nSe me nublaban los ojos\ny me temblaban las piernas.",228,3,38,-1,"",0,4,"ea",-1,0,-1,0,83,83,"","",78,"","","",6,0,0,[],"",""],["pacifico_colombia-p0083-03",24,"Para granizo, Guanacas,\nPara viejas, Timaná;\nPara muchachas bonitas,\nCali, Buga y Popayán.",228,3,38,-1,"",0,4,"a",-1,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-04",24,"Ah Guamo de mil demonios!\nQue allí fue onde amé una china,\nY me resultó que estaba\nSi no empeñada, vendida.",228,3,38,-1,"",0,4,"ia",-1,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-05",24,"Se embarcó mi china hermosa,\nSe embarcó en la Magalena[sic],\nY le iba creciendo el río\nCon el llanto de mi pena.",228,3,38,-1,"",3,4,"ea",-1,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-06",24,"«Como de aquí a Santa Rosa,\nYo le dije, te he de amar»;\nY me dio unas esperanzas\nComo de aquí a Bogotá.",228,3,38,-1,"",0,4,"a",-1,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-07",24,"Se estaba muriendo un indio\nY a su hijo le aconsejaba:\n\"Has de saber, hijo mio,\nQue un bien con un mal se paga.",228,3,38,-1,"",0,4,"aa",-1,0,-1,0,83,83,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0083-08",24,"\"Si fueres por un camino\nDonde te dieren posada,\nRóbate aunque sea el cuchillo\nY véte a la madrugada.",228,3,38,-1,"",0,4,"aa",49,0,-1,0,83,84,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0084-01",24,"\"Si algún blanco te mandare\nQue le ensilles el caballo.\nDéjale la cincha floja.\nY aunque se lo lleve el diablo.",228,3,38,-1,"",0,4,"ao",-1,0,-1,0,84,84,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0084-02",24,"\"Si cerrar la puerta mandan,\nSabe que nada te cuesta\nHacer como que la trancas,\nPero dejándola abierta\".",228,3,38,-1,"",0,4,"ea",-1,0,-1,0,84,84,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0084-03",24,"¿Dicen que no es muy triste\nLa despedida?\nDile al que te lo dijo\nQue se despida",228,3,38,-1,"",6,4,"ia",37,0,-1,0,84,84,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0085-01",24,"Si el más triste de los tristes\nmis lamentos escuchara,\npor compadecer mis penas\nde las suyas se olvidara.",228,3,38,-1,"",0,4,"aa",57,0,-1,0,85,85,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0085-02",24,"Cinco sentidos tenemos;\ntodos los necesitamos;\ntodos cinco los perdemos\ncuando nos enamoramos.",228,3,38,-1,"",1,4,"ao",116,0,-1,0,85,85,"","",78,"rm_t4, isaacs_colombia","","",8,0,0,[],"",""],["pacifico_colombia-p0085-03",24,"Muchos constancia prometen\nmientras logran sus intentos,\ny logrando lo que quieren,\nsi te vide no me acuerdo.",228,3,38,-1,"",0,4,"eo",-1,0,-1,0,85,85,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-01",24,"La vida paso muriendo;\nsi muriera, viviría,\nporque muriendo, saldría\ndel mal que sufro viviendo.",228,3,38,-1,"",11,4,"eo",52,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-02",24,"Malos pensamientos tienes\ny yo mil presentimientos:\npara dejar de pensar,\nmudemos de pensamiento",228,3,38,-1,"",0,4,"eo",-1,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-03",24,"Cuando te contemplo ausente\ncon más fineza te adoro,\nmi cogollo de romero,\nmi bello granito de oro.",228,3,38,-1,"",0,4,"oo",85,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-04",24,"Quisiera con un suspiro\ndescerrejar esta puerta,\npor ver si la vida mía\nestá dormida o despierta.",228,3,38,-1,"",0,4,"ea",267,0,-1,0,86,86,"","",78,"isaacs_colombia","","",3,0,0,[],"",""],["pacifico_colombia-p0086-05",24,"El clavel que me diste\nlo tengo en agua,\nporque no se marchite,\n¡prenda del alma!",228,3,38,-1,"",6,4,"aa",-1,0,-1,0,86,86,"","",78,"isaacs_colombia","","",3,0,0,[],"",""],["pacifico_colombia-p0086-06",24,"Qué lejos estás de mí;\nno te alcanzo a divisar;\nlos cerros tienen la culpa,\n¡Quién los pudiera tumbar!",228,3,38,-1,"",0,4,"a",21,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-07",24,"Ausente del bien que adoro\ncualquiera me considere:\n¿Qué gustos podré tener\nsin saber si vive o muere?",228,3,38,-1,"",0,4,"ee",115,0,-1,0,86,86,"","",78,"isaacs_colombia","","",10,0,0,[],"",""],["pacifico_colombia-p0086-08",24,"Suerte, suerte desgraciada,\n¿Para qué dichas mediste?\n¿Por qué con tiempo no viste\nque dichas no duran nada?",228,3,38,-1,"",11,4,"aa",49,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-09",24,"Di, Cali, en qué te ofendí:\n¿Por qué tanto me maceras?\n¡Ay! ¿por qué como las fieras\nme despedazas así?",228,3,38,-1,"",11,4,"i",23,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0086-10",24,"Adiós, Cali tan famoso,\ntierra donde yo nací,\nque para otros eres madre\ny madrastra para mí.",228,3,38,-1,"",0,4,"i",23,0,-1,0,86,86,"","",78,"isaacs_colombia","","",2,0,0,[],"",""],["pacifico_colombia-p0088-01",24,"Buen amigo, le pregunto,\nquiero que me dé razón:\n¿Cómo podré yo vivir\nSin que hablen de mi opinión?",228,3,38,-1,"",0,4,"o",31,0,-1,0,88,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-01",24,"Mucho me acuerdo de tí,\nMucho lloro por tu ausencia.\nTú no te acuerdas de mí\nQué ingrata correspondencia",228,3,38,-1,"",1,4,"ea",46,0,-1,0,89,89,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0089-02",24,"Matica de allajatica,\nMatizada con romero,\nSólo de tan bella boca\nLa contestación espero.",228,3,38,-1,"",0,4,"eo",38,0,-1,0,89,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-03",24,"Ya salió la luna al aire e\nAlumbrando naranjale.\nOnde nació Jesucristo\nNacieron lo libérale.",228,3,38,-1,"",5,4,"ee",-1,0,-1,0,89,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-04",24,"Cuando te vas a bañar\nLlevaré cuchillo y lanza,\nPorque están lo conservero\nComo perro en matanza.",228,3,38,-1,"",0,4,"aa",163,0,-1,0,89,89,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0089-05",24,"Ya salió la luna al aire\nAlumbrando lo potrero.\nOnde nacieron lo burro,\nNacieron lo conservero.",228,3,38,-1,"",0,4,"eo",38,0,-1,0,89,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-06",24,"No me canso de admirar\nEsa persona exquisita.\nAquí tenéis señorita,\nUn esclavo a quien mandar.",228,3,38,-1,"",11,4,"a",21,0,-1,0,89,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-07",24,"¡Abajo las cintas verdes,\nArriba las coloradas,\nAbajo lo mochoroco\nCon las espadas paradas!",228,3,38,-1,"",0,4,"aa",282,0,-1,0,89,89,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0089-08",24,"Por tu ceja vivo ancioso;\nPor tu color, singular;\nTus ojos son de cristal,\nTus pestañas laboriadas;\nY tu carita engastada\nNo me canso de mirar.\n¡Qué largas las horas son\nEn el reló de mi afán!\nY qué poco a poco dan\nAlivio a mi corazón.",228,3,38,-1,"",18,10,"o",31,0,-1,0,89,90,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0093-01",24,"Ay pajarillo zambo\nanoche 'onde dormirías (bis),\ndebajo del limón verde\ndonde el agua no corría (bis).\nTrala la lala (coro),\ndonde el agua no corría (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,93,94,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0094-01",24,"Qué alegre que está la novia\nmás alegre que una pascua (bis),\nmás alegre se pondrá\ncuando esté llevando la guasca (bis).\nTrala la lala (coro),\ncuando esté llevando la guasca (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0094-02",24,"Qué alegre que está la novia\nla noche en su casorio (bis),\ncon un ojo llorando\ncon el otro mira al novio (bis).\nTrala la lala (coro),\ncon el otro mira al novio (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0094-03",24,"Si el que se casa supiera\nla libertad cuánto vale (bis),\nperdonaría esos tres días\nde música, plaza y baile (bis).\nTrala la lala (coro),\nde música, plaza y baile (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0094-04",24,"El que cocina con tusa\ncocina es a fuego lento (bis),\nel que se casa se jode\ny vive lleno de tormento (bis).\nTrala la lala (coro),\ny vive lleno de tormento (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0094-05",24,"Yo creí que el casamiento\nera flor que florecía (bis),\nes verdad que sí florece\npero los primeros días (bis).\nTrala la lala (coro),\npero los primeros días (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0094-06",24,"Cuando a ti te estén poniendo\nflores en el pañuelón (bis),\na mí me estarán llevando\nlos amigos al pantión (bis).\nTrala la lala (coro),\nlos amigos al pantión (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",12,0,0,[],"",""],["pacifico_colombia-p0094-07",24,"Eso dicen las casadas\ncuando quieren chalaniar (bis),\nsi yo soltera me viera\nno me volvería a casar (bis).\nTrala la lala (coro),\nno me volvería a casar (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,94,94,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0095-01",24,"Ahora ya te casaste\nya sabes lo que es casarse (bis),\ndespués no vas a decir\nque para qué te casaste (bis).\nTrala la lala (coro),\nque para qué te casaste (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,95,95,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0095-02",24,"Cásate casamentera\nmujer de cuarenta novios (bis),\ndespués no vas a quedar\ncomo gallina sin pollos (bis).\nTrala la lala (coro),\ncomo gallina sin pollos (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,95,95,"","",78,"","","",3,0,0,[],"",""],["pacifico_colombia-p0095-03",24,"Cásate casamentera\ncásate que bien te irá (bis),\nsábado, domingo y lunes\ntu culo lo pagará (bis).\nTrala la lala (coro),\ntu culo lo pagará (bis).",228,3,38,-1,"El pajarillo zambo",9,6,"i",-1,0,-1,0,95,95,"","",78,"","","",3,0,0,[],"",""],["pacifico_colombia-p0096-02",24,"Tu madrina y tu padrino\nque te echen la bendición,\nque te la echen bien echada,\nque te llegue al corazón (bis).",228,3,38,-1,"El pajarillo zambo",5,4,"i",31,0,-1,0,96,96,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0096-03",24,"A los ángeles del cielo\nesto les vengo a pedir,\nuna pluma de sus alas\npara poderte escribir.",228,3,38,-1,"El pajarillo zambo",0,4,"i",157,0,-1,0,96,96,"","",78,"","","",9,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0096-04",24,"Niño lindo, niño bello (bis),\nniño paronde te vas (bis),\nniño si te vas al cielo (bis),\nno te vas a demorar (bis).",228,3,38,-1,"El pajarillo zambo",3,4,"i",-1,0,-1,0,96,96,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0096-05",24,"Los ángeles en el cielo\ntodos te están esperando,\npara que formen tu coro\ny alaben todos a Dios.",228,3,38,-1,"El pajarillo zambo",5,4,"o",-1,0,-1,0,96,97,"","",78,"","","",10,0,0,[],"",""],["pacifico_colombia-p0097-01",24,"A los ángeles del cielo\nles quiero recordar,\nuna pluma de sus alas\npara allá poder volar.",228,3,38,-1,"El pajarillo zambo",0,4,"a",21,0,-1,0,97,97,"","",78,"","","",9,0,0,[],"",""],["pacifico_colombia-p0097-02",24,"Licencia le pido a Dios\ny a la Virgen Soberana,\npara saber de qué modo\nse aparta el cuerpo del alma.",228,3,38,-1,"El pajarillo zambo",0,4,"aa",-1,0,-1,0,97,97,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0097-03",24,"El cuerpo le habló primero\ntodo bañado de lágrimas,\nel cuerpo le dijo al alma\nque ya es tiempo y Dios me llama.",228,3,38,-1,"El pajarillo zambo",0,4,"aa",-1,0,-1,0,97,97,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0097-04",24,"Quédate cuerpo traidor (bis),\nquédate para la tierra,\nque yo me voy a pagar\nlo que vos has hecho en ella.",228,3,38,-1,"El pajarillo zambo",0,4,"ea",-1,0,-1,0,97,97,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0097-05",24,"Ya me bajan de la cama (bis),\nya me empiezan a bañar,\ncon lágrimas y sollozos\nme empiezan a amortajar.",228,3,38,-1,"El pajarillo zambo",3,4,"a",21,0,-1,0,97,97,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0097-06",24,"La noche de mi velorio\ntodos juntos estarán (bis),\nunos estarán llorando\ny otros estarán riendo (bis).",228,3,38,-1,"El pajarillo zambo",3,4,"i",-1,0,-1,0,97,98,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0098-01",24,"Y los que estarán riendo\nesos serán los extraños (bis),\nporque esos que están llorando\nserán mis hijos y hermanos (bis).",228,3,38,-1,"El pajarillo zambo",3,4,"i",-1,0,-1,0,98,98,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0098-02",24,"Tengan cuidado señores\ny no se crean tan ufanos (bis),\nque estoy representando\nlo que somos los humanos (bis).",228,3,38,-1,"El pajarillo zambo",3,4,"i",-1,0,-1,0,98,98,"","",78,"","","",2,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0098-03",24,"Por aquí pasó María\ntres horas antes del día\ncon el rosario en la mano\nrezando el Ave María.",228,3,38,-1,"Salve",0,4,"ia",0,0,-1,0,98,98,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0098-04",24,"Mi rosario se ha perdido\nayúdenmelo a buscar\nque son cuentas de María\nque a mí me lo dio a guardar.",228,3,38,-1,"Salve",0,4,"a",21,0,-1,0,98,98,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0098-05",24,"Virgen de la Candelaria\nque le mandas a Jesús\nuna túnica morada\npara clavarlo en la cruz.",228,3,38,-1,"Salve",0,4,"u",109,0,-1,0,98,98,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0098-06",24,"Cincuenta escalones hay\npara subir al cielo,\ncincuenta Aves Marías\npara no ir al infierno.",228,3,38,-1,"Salve",0,4,"eo",-1,0,-1,0,98,98,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0099-01",24,"Un animal me picó\ndebajo de una batea,\nseñor que animal es ese\nque pica y no se menea (bis).",228,3,38,-1,"Un animal me picó",3,4,"i",54,0,-1,0,99,99,"","",78,"","","",2,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0099-02",24,"Un animal me picó\ndebajo de una batea,\nque animal tan venenoso\nque hasta la mano me hinchó (bis).",228,3,38,-1,"Un animal me picó",5,4,"i",2,0,-1,0,99,99,"","",78,"","","",2,0,0,[],"","Marcas del texto al final de los versos: (bis), (bis)"],["pacifico_colombia-p0099-03",24,"El pato le dijo al bimbo, aay\nque no buscara mujer,\nporque en el tiempo que estamos\nno la puede mantener.",228,3,38,-1,"El bimbo",3,4,"e",20,0,-1,0,99,99,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0099-04",24,"Le contesta el bimbo al pato\ncon su talega de arroz,\nninguno mantiene moza\ncomo la mantengo yo.",228,3,38,-1,"El bimbo",0,4,"o",-1,0,-1,0,99,99,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0099-05",24,"Del cielo cayó un pañuelo\nbordado con cinta negra,\naunque tu mama no quiera\ntu mama será mi suegra.",228,3,38,-1,"El bimbo",0,4,"ea",-1,0,-1,0,99,99,"","",78,"","","",17,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0099-06",24,"Cuando dos se quieren bien\ny todos son bien bonitos,\nel uno carga la jaula\ny el otro los pajaritos.",228,3,38,-1,"El bimbo",0,4,"io",254,0,-1,0,99,99,"","",78,"","","",9,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0100-01",24,"Yo tenía una pava echada\ncon huevos de morrocoy,\nsi los huevos no revientan, aay,\nmato la pava y me voy, aay.",228,3,38,-1,"El bimbo",3,4,"a",-1,0,-1,0,100,100,"","",78,"","","",1,0,0,[],"","Marcas del texto al final de los versos: (bis)"],["pacifico_colombia-p0100-02",24,"Si mi negrita fuera\nterrón de azúcar (bis),\nyo me la pasaría\nchupa que chupa (bis).",228,3,38,-1,"Terrón de azúcar",0,4,"i",-1,0,-1,0,100,100,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0100-03",24,"Si mi negrita fuera\npedazo de queso (bis),\nyo me la pasaría\ndándole beso (bis).",228,3,38,-1,"Terrón de azúcar",0,4,"i",48,0,-1,0,100,100,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0101-01",24,"Amorcito de mi vida\nde mi corazón encanto;\nqué yerba me habís echado\npara yo quererte tanto",228,3,38,-1,"Terrón de azúcar",0,4,"ao",-1,0,-1,0,101,101,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0101-02",24,"Asómate a la ventana\nboquita de mejorana;\nprima hermana de la luna,\nlucero de la mañana.",228,3,38,-1,"Terrón de azúcar",0,4,"aa",4,0,-1,0,101,101,"","",78,"","","",14,0,0,[],"",""],["pacifico_colombia-p0101-03",24,"Adiós quebradita honda\nadiós palo de ciprés\ncomo estamos tan distantes\ncuándo nos volveremos a ver.",228,3,38,-1,"Terrón de azúcar",3,4,"e",-1,0,-1,0,101,101,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0101-04",24,"Matica de albajaquita\nmatizada con anís,\nyo te doy mi corazón\ncon tal de que digas sí.",228,3,38,-1,"Terrón de azúcar",0,4,"i",-1,0,-1,0,101,101,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-01",24,"La naranja más madura\nle dijo a la más pintona\nno se vaya a madurar\nporque no hay quien se la coma",228,3,38,-1,"Terrón de azúcar",0,4,"oa",-1,0,-1,0,102,102,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-02",24,"El trigo y el arroz\nse pusieron en porfía\npara ver entre de los dos\ncuál fruto mejor tenía.",228,3,38,-1,"Terrón de azúcar",1,4,"ia",0,0,-1,0,102,102,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-03",24,"Que se acabe y se termine\nel amor que hemos tenido\nque volvamos a quedar\ncomo la pava en su nido",228,3,38,-1,"Terrón de azúcar",0,4,"io",101,0,-1,0,102,102,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-04",24,"yo sembré mi naranjito\ndonde el agua no corría\nyo le entregué mi corazón\na quien no lo merecía",228,3,38,-1,"Terrón de azúcar",0,4,"ia",0,0,-1,0,102,102,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-05",24,"Azucena y clavelino\nse siembran en el redor\npara que no se marchite\nel bejuco del amor.",228,3,38,-1,"Terrón de azúcar",0,4,"o",72,0,-1,0,102,102,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0102-06",24,"Ayer pasé por tu casa\nme tiraste un limón;\nel limón cayó en el pecho\nel zumo en el corazón.",228,3,38,-1,"Terrón de azúcar",0,4,"o",31,0,-1,0,102,102,"","",78,"","","",10,0,0,[],"",""],["pacifico_colombia-p0103-01",24,"Yo tenía mi guacharaca\ncon ella me divertía,\nalzó el vuelo y se me fue\nadiós, guacharaca mía.",228,3,38,-1,"Terrón de azúcar",0,4,"ia",0,0,-1,0,103,103,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0103-02",24,"Yo tenía mi Candelaria\ncon ella me divertía,\nse fue y me dejó llorando\nay adiós Candelaria mía.",228,3,38,-1,"Terrón de azúcar",0,4,"ia",0,0,-1,0,103,103,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0115-01",24,"Nariño que es Presidente\nY tiene el mando y el palo,\nSobre si es bueno o si es malo\nDividida está la gente.\nMás cualquier hombre prudente\nQue su conducta haya visto,\nY quiera hacerse bien quisto\nSin discrepar del nivel\nLo mismo ha de decir de él\nQue de Herodes Jesucristo.",228,3,38,-1,"Terrón de azúcar",18,10,"io",273,0,-1,0,115,115,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0115-02",24,"Unos dicen que es villano,\nOtros que es usurpador,\nAquéllos que es un traidor,\nEstos que es un mal cristiano;\nYa dicen que es un tirano\nY ya que es un francmasón;\nPero entre tanta opinión\nNos ha dicho don Juan Niño\nQue don Antonio Nariño\nEs un puro Napoleón.",228,3,38,-1,"Terrón de azúcar",18,10,"o",31,0,-1,0,115,115,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0116-01",24,"Si pública es la mujer\nque por puta es conocida,\naquella más prostituida\nRepública viene a ser.\nY siguiendo el parecer\nde esta lógica absoluta,\ntodo aquel que se reputa\nde República ser hijo,\ndebe ser, a punto fijo,\nun grandísimo hijueputa.",228,3,38,-1,"Terrón de azúcar",18,10,"ua",197,0,-1,0,116,116,"","",78,"","","",2,0,0,[],"",""],["pacifico_colombia-p0116-02",24,"El marido y la mujer\npelean en cualquier momento\ny es verdad que en ese cuento\nnadie se debe meter.\nSe dicen y se hacen ver\nlas cosas punto por punto,\nresucitan los difuntos\nentre gritos y reproches\ndespués que llega la noche\nse encueran y duermen juntos.",228,3,38,-1,"Terrón de azúcar",18,10,"uo",296,0,-1,0,116,117,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0122-01",24,"Hemos vivido violencia\nHemos vivido secuestro\nPero este país tan nuestro\nSalvémoslo con decencia\nHoy se acude a la indulgencia\nEn una forma muy sana\nEste pueblo se engalana\nY de ustedes soy amigo\nVengan y pidan conmigo\nPara la paz colombiana.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"aa",4,0,-1,0,122,122,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0122-02",24,"Hoy que estamos aquí reunidos\nYa sé cuál es la razón\nQue viva esta población\nY su folclor distinguido.\nUn instrumento ha venido\nSonando un pito distinto\nY yo no traje requinto\nMe despedí de mi taita\nYo me refiero a la gaita\nQue es folclor de san Jacinto",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"io",527,0,-1,0,122,122,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0123-01",24,"A lao mío está una mujer\nQue es muy linda y de admirar\nPero para improvisar\nTiene mucho que aprender\nYo no la voy a ofender\nPorque yo al ser femenino\nQue se imponga en mi camino\nMil flores le brindo yo\nY si me dice que no\nCon mi poesía la domino.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"io",199,0,-1,0,123,123,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0123-02",24,"Aquí están tres contrincantes\nExiste uno más novato\nQue a poco yo lo desbarato\nen una forma elegante\npero hay dos más importantes\nque han traído mucho brillo\ny aunque hable no me humillo\nsé que tienen mucha euforia\npero hoy su trayectoria\nme la llevo en el bolsillo",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"io",228,0,-1,0,123,123,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0123-03",24,"Mery tiene un complejo\nmi oído la escuchó\ny ese verso que cantó\nes un verso muy viejo.\nya tú vas como el cangrejo\nen este bonito plano\na los tres me los aplano\ny lo hago de inmediato\nahora observen un novato\nganando a tres veteranos",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ao",-1,0,-1,0,123,123,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0124-01",24,"Primero cantó Julito\ny después Mery Suescún\ndespués vino el de Sahagún\ny nada escuché bonito\nhoy Martelo pega un grito\nhaciendo versos divinos\ny yo les tracé el camino\npa' quitarles el capricho\nde lo que los tres han dicho\na mí me importa un comino",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"io",-1,0,-1,0,124,124,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0126-01",24,"Yo venía de cacería\nque me mataba el calor,\nme acerqué con gran primor\na un arroyo que corría;\ncuando gustoso bebía,\noí un ruido de repente,\nme oculté rápidamente\na ver lo que sucedía;\nvi una niña que venía\na la orilla de una fuente.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ee",15,0,-1,0,126,126,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0126-02",24,"En las piedras de la orilla\nla belleza se paró,\ny gustosa contempló\ncómo los peces nadaban;\nsus lindos ojos miraban\nrecelosos e impacientes,\npensando que no había gente\ny que sola se encontraba,\nlos vestidos se quitaba\na la orilla de la fuente.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ee",15,0,-1,0,126,126,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0127-01",24,"A medida que subía\nsu traje, poquito a poco,\nme fui sintiendo tan loco\nque no sé lo que veía.\nLos muslos me parecían\nmuy tensos y prominentes,\nlos vellos menudamente\nque en las piernas jugueteaban\ny los peces se ocultaban\na la orilla de una fuente.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ee",15,0,-1,0,127,127,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0127-02",24,"Si yo pudiera algún día\nremontarme a las estrellas,\npara darte cosas bellas\nconmigo te llevaría.\nTestigo el cielo sería\nde esta pasión que nos une,\nquiero aspirar tu perfume,\ntenerte cerca de mí;\nsediento de amor por ti\nmi corazón se consume.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ue",738,0,-1,0,127,127,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0127-03",24,"Si en la playa te bañaras\nbella dulce y apacible,\ntendría celo incontenible\nde que el mar te contemplara.\nSi el agua te acariciara\nmás grande sería mi pena,\nyo con el alma serena\nme iría donde estaba ella\npara besarle las huellas\nque sus pies marcó en la arena.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ea",-1,0,-1,0,127,127,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0128-01",24,"Pueda ser que mis ensueños\nse me vuelvan realidad,\nsería gran felicidad\nde ser yo tu único dueño.\nHe puesto todo mi empeño\nclaramente te lo digo,\nque el cielo está de testigo\nde este amor tan verdadero,\nque si tú mueres primero\na la tumba voy contigo.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"io",106,0,-1,0,128,128,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0128-02",24,"Qué triste es vivir así\nrecordando fantasías,\nal ver que nunca podría\ndarte el amor que te di.\nY digo pobre de mí\nya que vivo de ilusión,\nresponde mi corazón\ntú la quieres más y más\ny tú no podrás jamás\narrancar esta pasión.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"o",31,0,-1,0,128,128,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0129-01",24,"La receta voy a dar\nDel tejido de la hamaca,\nCuestión que más se destaca\nEn mi tierra popular.\nPara ese fabricar\nHay que buscar dos largueros,\nMás luego otros dos maderos\nQue les llaman travesaños,\nPara coger el tamaño,\nAsí se empieza primero.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"eo",-1,0,-1,0,129,129,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0129-02",24,"Cada larguero a lo fiel\nDos moscas se le trabajan,\nLos travesaños encajan\nEvitando el desnivel.\nCon manila fuerte y cruel\nSe les hace una cruceta,\nY si un desnivel inquieta\nCon cuatro cuñas combina,\nUna para cada esquina\nY así todo se sujeta.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ea",200,0,-1,0,129,129,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0130-01",24,"Ahora se busca el hilo\nPara esa elaboración,\nSe pasa por almidón\nEs un trabajo tranquilo.\nY se piensa en el estilo\nQue la hamaca se va a hacer,\nEso es como componer\nLos versos con buena rima,\nClaro que por esa cima\nDe mi pueblo es la mujer",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"e",20,0,-1,0,130,130,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0130-02",24,"Ahora llega un par de lata\nLlaman por naturaleza\nLa traba y la cabeza\nSon de una espinosa mata.\nAllí la artesana trata\nDe un devanador buscar,\nPara el hilo devanar\nPorque es mejor acomodo,\nDesde ahora me observan todos\nLa hamaca se empieza a echar.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"a",21,0,-1,0,130,130,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0130-03",24,"Nos llega un par de varillas\nPara el peine tejer,\nHilo por hilo coger\nDesde una a la otra orilla.\nNos falta cosa sencilla\nPorque hay que buscar paleta,\nY una vara se repleta\nDe lo que es la tejedura,\nPara empezar la figura\nDe lo que narra el poeta.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ea",200,0,-1,0,130,130,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0130-04",24,"Un templador se receta\nY una cuña a toda anchura,\nY al final las dos costuras\nSe les pasa cadeneta.\nMás luego una pita aprieta\nCada cabezal a lo igual,\nAsí se le da el final\nY para dormir se saca,\nAllí les dejo la hamaca\nDe mi tierra artesanal.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"a",1,0,-1,0,130,130,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0132-01",24,"Observando un decimal\nCon muchísima atención\nVi que su estructuración\nHace una estrofa genial.\nDel principio hasta el final\nNoté la ley que se rige,\nEntonces fue cuando dije\nQue el que la hace se previene\nPorque cualquiera no tiene\nLo que la décima exige.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ie",374,0,-1,0,132,132,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0132-02",24,"En su exigencia nos dice\nQue se cante y que se escriba\nPara que se tenga viva\nY también que se improvise.\nQue al pensarla se analice\nPara ver si da color,\nY que lleve con sabor\nLa consonante correcta,\nPorque la rima imperfecta\nNo tiene el mismo valor.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"o",72,0,-1,0,132,133,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0133-01",24,"Pide con grandes esfuerzos,\nRecta metrificación\nOchenta sílabas son\nDistribuidas en diez versos.\nTodos bien obvios y tersos\nCon cántico alrededor,\nEl verso de arte mayor\nY el verso libre no caben,\nY por eso los que saben\nRespetan este folclor.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"o",72,0,-1,0,133,133,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0133-02",24,"Que se cante en pie forzado\nEn piquería y dos con dos\nEn tema libre veloz\nY también en pie pisado.\nModalidades que han dado\nUna pesada conquista,\nDebe uno ser detallista\nCuando a eso ya va a lanzarse\nPara que pueda llamarse\nDecimero repentista.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ia",352,0,-1,0,133,133,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0133-03",24,"El primer verso es rimado\ncon cuatro y cinco a la vez\nel dos rima con el tres\npero bien organizado.\nY cuando el seis ha llegado\nCon siete y diez se sujeta,\nY el octavo se repleta\nRimando con el noveno\nY así cuadra el poeta bueno\nUna décima completa.",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ea",200,0,-1,0,133,133,"","",78,"","","",1,0,0,[],"",""],["pacifico_colombia-p0135-01",24,"Soy campesino vital\nde esos que tiran machete\ny me consigo el billete\ncon un mísero jornal.\nComo yo no hay otro igual\nsoy un hombre de prudencia,\npero he tomado conciencia\nque a pesar de lo que como\nalgún día me coge un plomo\nde esta maldita violencia",228,3,38,-1,"Pie Forzado: para la paz colombiana",18,10,"ea",46,0,-1,0,135,135,"","",78,"","","",1,0,0,[],"",""],["baguala_performance-p0040-01",25,"Aquí en El Carril, soy coplera\nsoy la Caja y su sonido.\nSoy la Puna en las alturas\nde los cerros, su colorido.",229,1,39,-1,"",3,4,"io",101,0,-1,0,40,40,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0041-01",25,"Yo soy de la Quebrada del Toro, señores\nSer coplera es mi destino.\nCon mi Caja y mi copla\nDéjenme mostrar lo argentino.",229,1,39,-1,"",3,4,"io",199,0,-1,0,41,41,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0043-01",25,"Desde muy lejos yo vengo\ntrayendo coplitas, señor.\nPara encontrar a mi dueño\nTengo yuyito pa'l amor.",229,1,39,-1,"",0,4,"o",72,0,-1,0,43,43,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0043-02",25,"De Nazareno es la copla\npurita como su sueño.\nBien perfumada en albahaca\nbuscando su propio dueño.",229,1,39,-1,"",0,4,"eo",138,0,-1,0,43,43,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0048-01",25,"Señor del Milagro,\nCristo Redentor\nen Salta tienes trono\nde promesa y oración.\nComo Padre del Universo\nnos protege con su amor.",229,1,39,-1,"",9,6,"o",-1,0,-1,0,48,48,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0049-01",25,"Oigan, escuchen, señores:\nvoy a probar mi garganta\ncon esta copla sentida\nque en Iruya la cantan.",229,1,39,-1,"",0,4,"aa",-1,0,-1,0,49,49,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0049-02",25,"Vengo de medio del monte\ncomo todo buen chaqueño\nEn verano con las vacas.\nSólo, para el invierno.",229,1,39,-1,"",0,4,"eo",-1,0,-1,0,49,49,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0050-01",25,"Cuando muera mi caballo\nha'i de llorar su montura\npor más que llueva en el mundo\nno borrará su herradura.",229,1,39,-1,"",0,4,"ua",17,0,-1,0,50,50,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0050-02",25,"Tengo una chancha sin chancho\ny una gallina sin gallo.\nTengo montura nuevita\nY me roban el caballo.",229,1,39,-1,"",0,4,"ao",102,0,-1,0,50,50,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0050-03",25,"Mi caballo se emborracha\ncuando llega el Carnaval\nes cuando yo me ladeo\npa' poderme equilibrar",229,1,39,-1,"",0,4,"a",-1,0,-1,0,50,50,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0057-01",25,"El bonito sombrero\nque gallardo yo lucía,\nme lo llevó el viento\npor plata que le debía.",229,1,39,-1,"",0,4,"ia",0,0,-1,0,57,57,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0058-01",25,"De ande ha salido esa flor.\nesa flor de ande ha salido\nYo nunca he visto esa flor\nni en el jardín más florido",229,1,39,-1,"",1,4,"io",101,0,-1,0,58,58,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0059-01",25,"De lejos me ven chiquita\nComo si fuera un borbojoooo.\nCuando me pongo a cantar\nSoy una gauchita que no aflojooo.",229,1,39,-1,"",3,4,"oo",739,0,-1,0,59,59,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0059-02",25,"Pacha Mama, Santa Tierra\nno me comas todavía.\nMira que estoy jovencita.\nquiero dejar una semilla.",229,1,39,-1,"",0,4,"ia",-1,0,-1,0,59,59,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0060-02",25,"Yo no corro atrás de las chinas.\nlas chinas corren del lado de mí.\nPor eso les tengo cariño\ny siempre las tengo para mí.",229,1,39,-1,"",3,4,"i",-1,0,-1,0,60,60,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0062-01",25,"El vino me está matando\ny no lo puedo tomar.\nSeguro que me morí\npasando días sin tomar.",229,1,39,-1,"",0,4,"a",-1,0,-1,0,62,62,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0062-04",25,"Primero, amar a Dios,\nSegundo, a la mujer.\nTercero, buscar mujer\nCuarto, dormir con ella.",229,1,39,-1,"",5,4,"ea",-1,0,-1,0,62,62,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0063-01",25,"Por el amor que te tengo\nno te puedo dejar.\nYo soy Severo Báez\n¿Quién puede ser mi par?",229,1,39,-1,"",0,4,"a",21,0,-1,0,63,63,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0063-02",25,"Tengo cabras. Tengo chivos.\nUn corral para encerrar.\nTengo la chiva mañera\nque se salió del corral.",229,1,39,-1,"",0,4,"a",-1,0,-1,0,63,63,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0063-03",25,"En la copla, soy Aguirre.\nen la caja, Severo Báez.\nQue la Virgen de Belén.\nnunca nos desampare.",229,1,39,-1,"",0,4,"ae",-1,0,-1,0,63,63,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0064-01",25,"Las estrellas en el cielo\ntienen escrito su nombre.\nY a mí, las desgraciadas,\nlas llamo y no me responden.",229,1,39,-1,"",0,4,"oe",-1,0,-1,0,64,64,"","",79,"","","",18,0,0,[],"",""],["baguala_performance-p0065-01",25,"Señores soy de la Puna,\nmiren mi color, mi trazo.\nDonde corre el viento blanco\nDonde las nubes me abrazan.",229,1,39,-1,"",5,4,"aa",-1,0,-1,0,65,65,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0065-02",25,"Para hacer chicha buena\nÉchale agua y romero.\nSe me sube a la cabeza\ncomo si fuera sombrero.",229,1,39,-1,"",0,4,"eo",38,0,-1,0,65,65,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0065-03",25,"El que sabe una copla\nnunca se equivoca.\nCantar lo que sabemos\nNo cierro nunca mi boca.",229,1,39,-1,"",0,4,"oa",178,0,-1,0,65,65,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0066-01",25,"En desfile de cristianos\ntodos vamos de la mano\nUn día llega la muerte.\nMorimos como hermanos.",229,1,39,-1,"",0,4,"ao",-1,0,-1,0,66,66,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0070-01",25,"“Yo soy Tomás David Vázquez\ncriollo de buena intención,\ny en cada copla que canto\nles dejo mi corazón”",229,1,39,-1,"",0,4,"o",-1,0,-1,0,70,70,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0071-01",25,"Me ha salido una copla\ny les quiero preguntar:\nCuando maten a la Tierra\n¿dónde la van a encontrar?...",229,1,39,-1,"",0,4,"a",21,0,-1,0,71,71,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0071-02",25,"Cuando yo esté en el cajón\nque mi poncho sea mortaja\npor flores pónganme[n]\nlo que más quiero: mi Caja.",229,1,39,-1,"",0,4,"aa",393,0,-1,0,71,71,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0071-03",25,"Llevo prendido en el aro\nde mi Caja bagualera\nun pedacito de trapo\nque saqué de tu pollera",229,1,39,-1,"",0,4,"ea",44,0,-1,0,71,71,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0071-04",25,"La mujer que a mí me quiera\ncuatro cosas hai de tener:\nlindo cuerpo, casa, plata\ny qué darme de comer.",229,1,39,-1,"",0,4,"e",20,0,-1,0,71,71,"","",79,"","","",3,0,0,[],"",""],["baguala_performance-p0071-05",25,"La mujer cuando llora\nson lágrimas del momento.\nEl hombre derrama una\nque es un mar de sentimientos",229,1,39,-1,"",0,4,"eo",-1,0,-1,0,71,71,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0072-01",25,"Yo soy nacida en Chicoana\npero vivo en El Carril,\ny así les voy a cantar,\ncon un inmenso sentir.",229,1,39,-1,"",0,4,"i",-1,0,-1,0,72,72,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0074-01",25,"Esta cajita que toco\nsonidito como ensayo…\nchirlera de siringuilla\nretodito cuero' i gallo.\nCarrileña, bien criollita\nbien salteña…",229,1,39,-1,"",9,6,"ea",-1,0,-1,0,74,74,"","",79,"","","",6,0,0,[],"",""],["baguala_performance-p0074-02",25,"A mis hijos y a mis nietos\nenseñé de corazón…\na valorar lo que es nuestro\ny defender la tradición.",229,1,39,-1,"",0,4,"o",31,0,-1,0,74,74,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0074-03",25,"A Diocito le doy gracias\nporque ilumina mi mente…\nAsí les puedo cantar\nlo que mi corazón siente.",229,1,39,-1,"",0,4,"ee",15,0,-1,0,74,74,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0075-02",25,"En Salta tú tienes trono\nde promesa y oraciones\ncomo padre de los gauchos\nnos protege con su amor.",229,1,39,306,"",5,4,"o",-1,0,-1,0,75,75,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0075-03",25,"Para cantarle a la Patria\nno hace falta tener linda voz\nhay que ponerle el alma,\nla vida y el corazón.",229,1,39,306,"",3,4,"o",-1,0,-1,0,75,75,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0077-01",25,"Cuando salí de mis pagos\nde nadie me despedí.\nTan solo de los pobres montes\nque me vieron partir.",229,1,39,306,"",0,4,"i",-1,0,-1,0,77,77,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0077-02",25,"En la vida amargura pasé\nhasta la hiel he bebido.\nPucha que fiero había sido\nquerer y no ser querido.",229,1,39,306,"",3,4,"io",101,0,-1,0,77,77,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0077-03",25,"Si me muero de amores\nno me entierren en Campo Santo.\nTírenme en el monte\npa' que me coman los carachos.",229,1,39,306,"",0,4,"ao",-1,0,-1,0,77,77,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0078-02",25,"De Iruya he'i venido\ncruzando ríos y quebradas\npa' cantarles a mis amigos\ny dejarles mi tonada.",229,1,39,307,"",0,4,"aa",-1,0,-1,0,78,78,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0078-03",25,"El día que yo me muera\nno me lloren los parientes\nLlórenme las damajuanas\nlos litros de aguardiente",229,1,39,307,"",0,4,"ee",-1,0,-1,0,78,78,"","",79,"","","",6,0,0,[],"",""],["baguala_performance-p0079-01",25,"Pregúntenle a mi sombrero\nél les dirá la verdad.\nLa mala noche que paso\ny el sereno que me da.",229,1,39,307,"",0,4,"a",-1,0,-1,0,79,79,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0079-02",25,"Vengo de medio del monte\ncomo todo chaqueño.\nEn el verano con las vacas.\nSólo, para el invierno.",229,1,39,307,"",0,4,"eo",-1,0,-1,0,79,79,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0101-01",25,"¡Achachila, mi mestiza\nque en Maimara abunda!\n¡Sus negros ojos que brillan\nparecen dos akatanqas!",229,1,39,308,"",5,4,"aa",-1,0,-1,0,101,101,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0101-02",25,"Ya viene la Pacha Mama\npa' ella, chicha y aloja.\nY pa' nosotros tenemos,\naguardiente de sobra.",229,1,39,308,"",0,4,"oa",-1,0,-1,0,101,101,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-01",25,"Buenos días, buenas tardes,\n¿Cómo están, cómo les va?\nMe presento en esta rueda\nsin ninguna novedad.",229,1,39,309,"",0,4,"a",-1,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-02",25,"Primera vez que me dirijo\nAquí busco mi entono\n¡Gloria al Padre y al Hijo!\n¡Gloria al Santo Patrono!",229,1,39,309,"",1,4,"oo",530,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-03",25,"Señor del Milagro,\nCristo Redentor\nen Salta tienes trono\nde promesa y oración.",229,1,39,309,"",0,4,"o",-1,0,-1,0,104,104,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0104-04",25,"Cuando llega la baguala\nestoy que no puedo estar.\nLa boca se me hace agua\npor empezarla a cantar",229,1,39,309,"",0,4,"a",21,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-05",25,"Si esta caja fuera queso\npalabra, la comería\npero si yo me la como…\n¿pa'nde se irá la alegría?",229,1,39,309,"",0,4,"ia",0,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-06",25,"Hay penas poco a poco\nVan pasando sin sentir;\nlastiman pero no matan\nduelen pero tienen fin.",229,1,39,309,"",0,4,"i",-1,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-07",25,"Un besito no es pecado,\nme lo dijo mi confesor.\nSi se da lengüita y todo\nal comienzo del amor.",229,1,39,309,"",0,4,"o",72,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-08",25,"Me' a dicho que era sanita\nsanita de corazón.\nPero había tenido más agujeros\nque una tabla de cardón.",229,1,39,309,"",3,4,"o",31,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-09",25,"Mujer de baile es rara\nsonríe, ríe y declara\ndarte amor toda la noche\nsólo si… tenés coche",229,1,39,309,"",5,4,"oe",337,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-10",25,"Me ven de poncho y ushutas,\nmuchos se ríen de mí,\npor juera, nada parezco,\npor dentro, tal vez que sí.",229,1,39,309,"",0,4,"i",23,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-11",25,"¡Aijuna pucha la vida!,\n¡qué cosa más despareja!\n¡unos deshacen terrones,\notros van como en bandeja!",229,1,39,309,"",0,4,"ea",165,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-12",25,"Una sola sepultura\nEs para todo mortal.\nPacha Mama es tan noble\nque a todos cubre por igual",229,1,39,309,"",0,4,"a",1,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-13",25,"Cada vez que lo recuerdo\nno lo quiero recordar\nQue el placer es del cuerpo\n¡y el cuerpo ha'i de cobrar!",229,1,39,309,"",0,4,"a",21,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-14",25,"Por el camino del Inca\ncamina mi raza vieja.\nSoy piedra, polvo y grito\nde los diaguitas, su fuerza.",229,1,39,309,"",0,4,"ea",-1,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-15",25,"Soy de arriba, tarijeño\nque los Incas no dominaron.\nAndo entre montes ralos,\nmontañas y descampados.",229,1,39,309,"",0,4,"ao",-1,0,-1,0,104,104,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0104-16",25,"Lindo, lindo es mi paguito\nlindo, lindo es mi lugar\ncriá muchas ovejas,\nlinda lana pa' hilar",229,1,39,309,"",0,4,"a",21,0,-1,0,104,104,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0105-01",25,"En la punta de aquel cerro\nestá meando una zorra.\nEstá igualita que vos\nsólo que no es tan pedorra.",229,1,39,310,"",0,4,"oa",461,0,-1,0,105,105,"","",79,"","","",21,0,0,[],"",""],["baguala_performance-p0105-02",25,"Yo soporto a las pulgas\ny a los piojos los aguanto.\nPero d' esta garrapata\nyo sí que d' eya me espanto.",229,1,39,310,"",0,4,"ao",30,0,-1,0,105,105,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0105-03",25,"Tu bizcocho me has mostrado\ny me lo has hecho oler.\nAhora mejor entrégalo\nantes de que se eche a perder",229,1,39,310,"",0,4,"e",20,0,-1,0,105,105,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0105-04",25,"Yo soy una leona brava\nsi su norte es pa' los cerros.\nAy!, mocito, no te mato\nporque no soy mata perros.",229,1,39,310,"",0,4,"eo",333,0,-1,0,105,105,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0105-05",25,"Mocito, ya no me sirves\nNipa' quitarme las ganas.\nHe probado otra cosa\nque me hace cantar tonadas.",229,1,39,310,"",0,4,"aa",-1,0,-1,0,105,105,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0123-02",25,"Te'i de querer\nte'i de adorar\nte'i de llevar adónde\nnadie más pueda encontrar\ntan solo muriendo yo te'i de olvidar.",229,1,39,311,"Estribillo",7,5,"a",21,0,-1,0,123,123,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0123-03",25,"El día que no te veo, ¡vidalitay!\nparamí no sale el sol, mi bien, ¡ay, mi dolor!\nNi brillo tiene la luna ¡vidalitay!\nNi sangre mi corazón.",229,1,39,311,"Estribillo",3,4,"o",-1,0,-1,0,123,123,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0124-01",25,"Maimanta traje fiesta\nMaimanta plata\nPa' colmo mi mulita\nCamina gata.",229,1,39,311,"Estribillo",6,4,"aa",74,0,-1,0,124,124,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0128-01",25,"Con su permiso, señores\naquí me voy a presentar\nYo soy el más bonito\nde este lugar.",229,1,39,312,"",3,4,"a",21,0,-1,0,128,128,"","",79,"","","",7,0,0,[],"",""],["baguala_performance-p0128-02",25,"¿Por qué estás triste, vidita?\n¿Por qué estás agachadita?\nYo desde aquí ya estoy viendo\nel hilo de tu tanguita.",229,1,39,312,"",0,4,"ia",50,0,-1,0,128,128,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0128-03",25,"A las viejas no las quiero\nporque ya saben de todo.\nYo quiero una de quince años,\npa' enseñarle a mi modo.",229,1,39,312,"",0,4,"oo",261,0,-1,0,128,128,"","",79,"","","",3,0,0,[],"",""],["baguala_performance-p0138-01",25,"De Nazareno he'i venido\ndiciendo volveré mañana:\ncomo soy moza soltera\nvolveré en una semana",229,1,39,312,"",0,4,"aa",4,0,-1,0,138,138,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0138-02",25,"De Nazareno hei venido,\nvolando como un papel\nDando vueltas por el aire\ncomo hilo carretel.",229,1,39,312,"",0,4,"e",32,0,-1,0,138,138,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0139-01",25,"Lindo, lindo es mi paguito,\nlindo, lindo es mi lugar\nSé criá muchas ovejas,\nlinda lana pa' hilar",229,1,39,312,"",0,4,"a",21,0,-1,0,139,139,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0141-01",25,"Aquí están porque han venido\n¿Qué más quieren que lo diga?\nSolo le pido a Diocito\ny que la Virgen los bendiga.",229,1,39,313,"",0,4,"ia",232,0,-1,0,141,141,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0141-02",25,"Soy esa vaquita negra\nque anda por la lomada.\nEn mi pelo traigo coplas\ny en el resello, tonadas.",229,1,39,313,"",0,4,"aa",-1,0,-1,0,141,141,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0141-03",25,"Yo soy hija de la nube\npariente del aguacero.\nVivo en los cerros más altos,\ndonde me alumbra el Lucero.",229,1,39,313,"",0,4,"eo",38,0,-1,0,141,141,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0143-01",25,"Carnaval anda diciendo:\n¡velay, velay, carnaval!\nAhora no hay que hacer nada,\nsino cantar y bailar.",229,1,39,313,"",0,4,"a",-1,0,-1,0,143,143,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0164-02",25,"La vaca es un animal\ntodo forrado de cuero\nque tiene las patas largas\nque le llegan hasta el suelo.",229,1,39,314,"",0,4,"eo",-1,0,-1,0,164,164,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0165-01",25,"Blanco me parió mi madre\nblanco como el algodón\nde tanto servir a mi Patria\nme he vuelto como el carbón.",229,1,39,314,"",0,4,"o",31,0,-1,0,165,165,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0165-02",25,"Amarillo es el oro\ny blanca es la plata\ny azules son los ojos\nque a mí me matan",229,1,39,314,"",6,4,"aa",-1,0,-1,0,165,165,"","",79,"","","",5,0,0,[],"",""],["baguala_performance-p0165-03",25,"Amarillo es el oro\ny blanco es la plata\ny negros son los ojos\nque a mí me matan",229,1,39,314,"",6,4,"aa",-1,0,-1,0,165,165,"","",79,"","","",5,0,0,[],"",""],["baguala_performance-p0175-03",25,"Ya me voy, ya me voy yendo\nde su presencia me alejo.\nMe voy a favor del viento\ny que me lleve más lejos.",229,1,39,314,"",0,4,"eo",-1,0,-1,0,175,175,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0176-01",25,"Andáte, andáte\nyo me quedaré\nhaciendo errar mi caballo\nmañana te alcanzaré",229,1,39,314,"",3,4,"e",77,0,-1,0,176,176,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0176-02",25,"Ahicito, ahicito\nen la planta de maicito\nyo le hei dicho a la viditay\nque me espere por ahicito",229,1,39,314,"",0,4,"io",119,0,-1,0,176,176,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0176-03",25,"Que esta flor solo se planta\na principio de Año nuevo\nA buscar amor se ha dich\ny amor que no tenga dueño",229,1,39,314,"",0,4,"eo",-1,0,-1,0,176,176,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0176-04",25,"Vidita cuando tei visto\nle dije a mi corazón:\nque piedrita tan churitay\nyo me gano un tropezón.",229,1,39,314,"",0,4,"o",31,0,-1,0,176,176,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0176-05",25,"Piedra soy en el camino\npiedra soy, piedra hei de ser:\nel que tropieza conmigo\nluego cae a mi poder:",229,1,39,314,"",0,4,"e",20,0,-1,0,176,176,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-01",25,"Ando buscando una copla\nal viento se la voy a pedir.\nSi el viento no me la da\nlas piedras me la darán.",229,1,39,314,"",3,4,"a",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-02",25,"Mi vida por una copla\nes el ejemplo del puñal.\nCualquier cosa que deseo\nella me ha de apuñalar.",229,1,39,314,"",0,4,"a",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-03",25,"El brasileño-argentino\nbuscando coplas llegó\nentrevistó a la Rosita,\nJuan Jaime y Fanor.",229,1,39,314,"",0,4,"o",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-04",25,"Después siguió con la charla\ncon la coplita del “Gringo”\nque “cobró” para dar la nota\ncinco botellas de vino.",229,1,39,314,"",0,4,"io",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-05",25,"Víctor Hugo, reportero\nque a Salta vino a buscar\nlas coplas y las bagualas\nque a Foz do Iguaçu llevará.",229,1,39,314,"",0,4,"a",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-06",25,"Es salteño, Víctor Hugo\nahora de Foz, ciudadano,\nreportando las coplas\npa' cantarlas todo el año.",229,1,39,314,"",0,4,"ao",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-07",25,"Que viva la copla, ¡que viva!\nel vino y el buen vivir\n¡Que viva el pueblo argentino\ny también el del Brasil!",229,1,39,314,"",0,4,"i",-1,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0177-08",25,"La copla, con la baguala\nen Brasil van a quedar\nasí la cantan con fuerza\ndesde la sierra hasta el mar.",229,1,39,314,"",0,4,"a",21,0,-1,0,177,177,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0178-02",25,"De Iruya hei venido\ncruzando ríos y quebradas\npa' cantarles a mis amigos\ndejarles mi tonada.",229,1,39,314,"",0,4,"aa",-1,0,-1,0,178,178,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0179-01",25,"Si la piedra de tu calle\ntuviera sentimientos\nCada vez que yo pasara\nllorará de sentimiento",229,1,39,314,"",0,4,"eo",-1,0,-1,0,179,179,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0179-02",25,"Todos quieren hacer leña\nde un árbol que está caído\nApuesto a que no lo harían\nde un árbol florido",229,1,39,314,"",0,4,"io",101,0,-1,0,179,179,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0182-01",25,"Habían visto al diablo\ncon el cigarro en la boca\nrecolectando las almas\nen un cielo verde coca",229,1,39,314,"",0,4,"oa",178,0,-1,0,182,182,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0183-01",25,"Yo soy de la Quebrada del Toro, señores…\nSer coplera es mi destino.\nCon mi caja y mi copla,\n¡déjenme a mí, Argentina!.",229,1,39,314,"",3,4,"ia",-1,0,-1,0,183,183,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0183-03",25,"Quince días voy cantando\nrecién me voy componiendo\nComo pimpollo de rosa\nQue recién está floreciendo",229,1,39,314,"",0,4,"eo",52,0,-1,0,183,183,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0184-01",25,"Ayer también estaba lejos\ny ahora estoy ahí\nmañana dónde estaré\nsolo Dios sabrá de mí.",229,1,39,314,"",0,4,"i",23,0,-1,0,184,184,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0185-01",25,"Golpiá, golpía tu cajita\nque hay que adorar\nQue si se hai de romper\npasar no debe por ese salar.",229,1,39,314,"",3,4,"a",21,0,-1,0,185,185,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0186-01",25,"Quisiera ser un patito\nchiquitito y nadador\npara meterme en tu pecho\ny nadar en tu corazón.",229,1,39,314,"",0,4,"o",-1,0,-1,0,186,186,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0186-02",25,"De arriba viene tronando\nde abajo, viene lloviendo\nApuren la olla del locro\npara que vamos comiendo",229,1,39,314,"",0,4,"eo",52,0,-1,0,186,186,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0187-01",25,"De Nazareno hei venido\ndiciendo volveré mañana:\ncomo soy moza soltera\nvolveré en una semana",229,1,39,314,"",0,4,"aa",4,0,-1,0,187,187,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0187-03",25,"Verde lima, verde lima,\nparece verde limón\nParece el mozo boni\nque me roba el corazón.",229,1,39,314,"",0,4,"o",31,0,-1,0,187,187,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0187-04",25,"Cuando me dicen que cante,\nluego sabía comenzar\nAunque no sé buenas coplas\npero soy de buen notar.",229,1,39,314,"",0,4,"a",21,0,-1,0,187,187,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0188-03",25,"Siento irme y retirarme,\nsiento irme y no volver.\nPero más estoy sintiendo\ncuándo les volveré a ver.",229,1,39,314,"",0,4,"e",20,0,-1,0,188,188,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0188-04",25,"Mira en esta tonada,\nmira en este lugar\nSi no cantamos nosotros\n¿quién va'i cantar regular?",229,1,39,314,"",0,4,"a",21,0,-1,0,188,188,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0188-05",25,"Con su permiso:\nNazareno, soy, señores\ny aquí me voy a presentar.\nYo soy el más bonito\nde todo este lugar",229,1,39,314,"",7,5,"a",21,0,-1,0,188,188,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0188-06",25,"¿Por qué estás triste, vidita?\n¿Por qué tan agachadita?\nYo de aquí ya estoy viendo\nel hilo de tu tanguita.",229,1,39,314,"",0,4,"ia",50,0,-1,0,188,188,"","",79,"","","",2,0,0,[],"",""],["baguala_performance-p0189-01",25,"A las viejas no las quiero\nporque ellas saben de todo\nYo quería una de quince años\npara enseñarle a mi modo.",229,1,39,314,"",0,4,"oo",261,0,-1,0,189,189,"","",79,"","","",3,0,0,[],"",""],["baguala_performance-p0189-02",25,"Debajo de su vestido\nhay una linda perdiz.\nTiene plumas y tiene boca\nsolo le falta el maíz",229,1,39,314,"",0,4,"i",335,0,-1,0,189,189,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0189-03",25,"Quisiera ser como el zorro\npara andar en las madrugadas\ncon mi ponchito amarillo\nte esperaré en la quebrada.",229,1,39,314,"",0,4,"aa",-1,0,-1,0,189,189,"","",79,"","","",3,0,0,[],"",""],["baguala_performance-p0189-04",25,"La mujer cuando es querendona\nquiere a uno y quiere a dos\ny le dijo al más tontito\nque este hijo es para vos",229,1,39,314,"",0,4,"o",87,0,-1,0,189,189,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0189-05",25,"Todas mujeres bellas\na su casa llevan un carnero\nY le dijo a su marido\naquí te traigo tu compañero.",229,1,39,314,"",3,4,"eo",38,0,-1,0,189,189,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0189-06",25,"El amor de la mujer\nes igual al alacrán:\ncuando no está su marido\nalza la cola y se va.",229,1,39,314,"",0,4,"a",-1,0,-1,0,189,189,"","",79,"","","",4,0,0,[],"",""],["baguala_performance-p0190-01",25,"A mi mujer yo la quiero\nporque es tan bonita y bella\nMe voy a dormir con otras\npara no lastimarla a ella",229,1,39,314,"",0,4,"ea",6,0,-1,0,190,190,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0190-02",25,"Anoche estaba durmiendo\nsoñé una cosa muy rara.\nSoñé que tú eras bicicleta\ny yo que yo te inflaba, te inflaba.",229,1,39,314,"",3,4,"aa",-1,0,-1,0,190,190,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0190-03",25,"Mi mujer estuvo en la cama\nyo sentado en la cabecera.\nCon el rosario en la mano\nrogando a Dios que se muera.",229,1,39,314,"",0,4,"ea",44,0,-1,0,190,190,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0190-04",25,"El amor de la mujer\nes como la lechuguita\nEchando un poquito de agua\nse mantiene verdecita.",229,1,39,314,"",0,4,"ia",50,0,-1,0,190,190,"","",79,"","","",4,0,0,[],"",""],["baguala_performance-p0190-06",25,"De lejos se la conoce\nla mujer cuando es bandida\nTiene las caderas anchas\ny las piernitas torcidas",229,1,39,314,"",0,4,"ia",-1,0,-1,0,190,190,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0190-07",25,"Soy soltero, quiéranme\naprovechen de esta pichincha\nPara el amor sí soy bueno\ncomo el burro pa' la cinta.",229,1,39,314,"",0,4,"ia",-1,0,-1,0,190,190,"","",79,"","","",1,0,0,[],"",""],["baguala_performance-p0190-08",25,"Con su permiso, señores.\nles vua a contar una hazaña.\nAnoche me ha picado una pulga.\nLa pillado de las pestañas.",229,1,39,314,"",3,4,"aa",-1,0,-1,0,190,190,"","",79,"","","",7,0,0,[],"",""],["genitalidad_colombia-p0001-01",26,"Toditos los campesinos\nsomos los olbidados\ni oritica en las iliciones\nai ci somos los conbidados.",230,3,40,-1,"",0,4,"ao",18,0,-1,0,1,1,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0001-02",26,"La jente ya no va a misa\nresan pero sin gracia\nserá por eso que aora\nsuseden tantas desgracias.",230,3,40,-1,"",0,4,"aa",-1,0,-1,0,1,1,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0001-03",26,"En los estados unidos\nla gente siempre nos gana\nporque allá le disen dotor\nal que juma maroguana.",230,3,40,-1,"",0,4,"aa",4,0,-1,0,1,1,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0002-01",26,"Los sentranos se la pasan\ndurmiendo desde asentados\ny se vuelben barrigones\ncomo burros enjalmados.",230,3,40,-1,"",0,4,"ao",18,0,-1,0,2,2,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0002-02",26,"Allá rriba en aquel alto\nbiene dos almas perdidas\nsino sabían el camino\npa'que se venían por'aí.",230,3,40,-1,"",3,4,"i",-1,0,-1,0,2,2,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0002-03",26,"Las mositas cuando disen\nmamita me boy pa'misa\nes señas que ya no caben\nlas tetas en la camisa.",230,3,40,-1,"",0,4,"ia",68,0,-1,0,2,2,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0002-04",26,"La mujer que a los cuarenta\nno se aya podido casar\nque se acueste boca abajo\nporque no lo ba a probar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,2,2,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0002-05",26,"Cuando estaremos mi vida\ncomo los pies del señor\nuno encima del otro\ny un clavito entre los dos.",230,3,40,-1,"",0,4,"o",-1,0,-1,0,2,2,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0002-06",26,"Los hombres son los ratones\ny las mujeres el queso\ny el matrimonio la trampa\nque los pilla del pescueso.",230,3,40,-1,"",0,4,"eo",48,0,-1,0,2,2,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0003-01",26,"Más vale querer a un burro\ny no querer a una mujer\nporque el burro carga leña\ny se ayuda a mantener.",230,3,40,-1,"",0,4,"e",20,0,-1,0,3,3,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0003-02",26,"Lo que se cocina con tusas\nse cocina a fuego lento\nal que se casa con viuda\nestá vivo y uele a muerto.",230,3,40,-1,"",0,4,"eo",-1,0,-1,0,3,3,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0003-03",26,"Ayer pasé por tu casa\ny te vide moliendo arepas\nque risa que me daba\nde verte jondiar las tetas.",230,3,40,-1,"",0,4,"ea",-1,0,-1,0,3,3,"","",80,"","","",10,0,0,[],"",""],["genitalidad_colombia-p0004-01",26,"Dame un besito mi vida\nque me voy a trabajar\nun besito no es pecado\npero ayuda a condenar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,4,4,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0004-02",26,"Esa chica de los serros\nque animal tan raro tenía\nun sapo cubierto e pelos\nsin patas ni sangre fría.",230,3,40,-1,"",0,4,"ia",0,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-03",26,"Mi mamá se fue a lavar\nmi papá para el trapiche\nmi hermano que se va a casar\na sacarle punta al chiche.",230,3,40,-1,"",1,4,"ie",721,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-04",26,"Una vieja no muy vieja\napenas apuntando canas\nse quería comer mis turmas\npensando que eran manzanas.",230,3,40,-1,"",0,4,"aa",263,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-05",26,"La guerrillera de la embajada\nno se pone fabricato\nse pone la minifalda\npara mostrar el aparato.",230,3,40,-1,"",3,4,"ao",19,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-06",26,"El conejo de las mujeres\nsi sirbe pa'cer surrones\nporque ni lo comen los perros\nni lo ruyen los ratones.",230,3,40,-1,"",0,4,"oe",34,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-07",26,"Esta noche está de tuna\nla copa de mí sombrero\nsi la copa está de tuna\nque será el sombrero antero.",230,3,40,-1,"",1,4,"eo",38,0,-1,0,4,4,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0004-08",26,"La ruana tiene a sus pelos\ny no se puede pelar\ntambién tiene su rotico\npa' su cabeza empujar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-09",26,"La novia le dijo al novio\npero le dijo al secreto\nmañana por la noche\nesta noche \"tese queto\".",230,3,40,-1,"",0,4,"eo",543,0,-1,0,4,4,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0004-10",26,"De las fiestas de Ubaté\nesto fue lo que sáqué\nlas naguas a media pierna\ny el chino puro a vusté.",230,3,40,-1,"",0,4,"e",77,0,-1,0,4,4,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0005-02",26,"Esto dijo el armadillo\nyendo pal molino\nsi no me dan guarapo\nsaco el CHICHE y los orino.",230,3,40,-1,"",0,4,"io",199,0,-1,0,5,5,"","",80,"","","",6,0,0,[],"",""],["genitalidad_colombia-p0005-03",26,"El CHIMBO se murió\nla CHIMBA está de luto\nabrá las piernas mijita\npa enterrar este difunto.",230,3,40,-1,"",0,4,"uo",-1,0,-1,0,5,5,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0006-01",26,"No me gustan las mujeres\ntan solo por un rato\nporque huelen a ratón\ny se me alborota el GATO.",230,3,40,-1,"",0,4,"ao",19,0,-1,0,6,6,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0006-02",26,"Mi comprade mono\ncocinando brevas\nle saltó un chisguete\ny le quemó las guevas",230,3,40,-1,"",0,4,"ea",632,0,-1,0,6,6,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0006-03",26,"Me rasco las GUEVAS\nme rasco el beril\nserá que Usted\nse quiere morir.",230,3,40,-1,"",6,4,"i",-1,0,-1,0,6,6,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0006-04",26,"Hasete el GUEVA pasando\nhasete el que no miras\ncon la puntica del pañuelo\nuna señita y no más.",230,3,40,-1,"",5,4,"a",-1,0,-1,0,6,6,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0006-05",26,"Santa Bárbara bendita\nSan Isidro labrador\nJoboresca a las mositas\ndel GUSANO MEDIDOR.",230,3,40,-1,"",0,4,"o",72,0,-1,0,6,6,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0007-01",26,"Una vez en unas fiestas\nen el barrio de Palmarito\ndos viejas se querían peliar\npor mi mincha de PAJARITO.",230,3,40,-1,"",3,4,"io",119,0,-1,0,7,7,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0007-02",26,"Présteme su conejo\npara ajuntarlo con el TOCHE\npara ponerlos a cantar\nen el silencio de la noche.",230,3,40,-1,"",0,4,"oe",337,0,-1,0,7,7,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0007-03",26,"Si la chocha tuviera dientes\ncomería PLATANO asado\npero como no los tiene\ncome TORTOLO parado.",230,3,40,-1,"",0,4,"ao",14,0,-1,0,7,7,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0007-05",26,"De tierra caliente vengo\npero no soy calentano\ntengo las TURMAS atrás\npero no son de marrano.",230,3,40,-1,"",0,4,"ao",81,0,-1,0,7,7,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0007-06",26,"Compañero, compañero.\nno nos vamos en ayunas\nmientras yo labo la olla\nusted lávese las TURMAS.",230,3,40,-1,"",0,4,"ua",-1,0,-1,0,7,7,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0008-01",26,"De la peña sale el agua\ndel agua el pescado\nde la chocha de las mujeres\nsale el VICHIRO mojado.",230,3,40,-1,"",0,4,"ao",14,0,-1,0,8,8,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0008-02",26,"La gerrillera de la embajada\nno se pone fabricato\nse pone la minifalda\npara mostrar el APARATO.",230,3,40,-1,"",3,4,"ao",19,0,-1,0,8,8,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0008-03",26,"Pobrecita mi vecina\nque tuvo una gran desmocha\npor irse a meter el dedo en el ombligo\nse lo metió en la CHOCHA.",230,3,40,-1,"",3,4,"oa",441,0,-1,0,8,8,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0008-04",26,"El pato para volar\nlas alas las encartucha\nla mujer para pichar\nse acuesta y abre la CHUCHA",230,3,40,-1,"",1,4,"ua",485,0,-1,0,8,8,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0009-02",26,"Adiós porque ya me voy\nque ya me voy y te dejo\npero me queda el volver\nal amor de tu CONEJO.",230,3,40,-1,"",0,4,"eo",264,0,-1,0,9,9,"","",80,"","","",4,0,0,[],"",""],["genitalidad_colombia-p0009-03",26,"La mujer que no se peina\nel piojo le hace camino\nla royen las cucharachas\ny no le canta el GALLO fino.",230,3,40,-1,"",0,4,"io",199,0,-1,0,9,9,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0009-04",26,"Una niña me rogó\nque le apuntara la saya\ny como yo no sabía\nle apunté a la MUSARANA.",230,3,40,-1,"",0,4,"aa",-1,0,-1,0,9,9,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0009-05",26,"Al pobre del armadillo\nlo llevan preso para Vélez\npor no saber respetar\nel NEGOCIO de las mujeres.",230,3,40,-1,"",0,4,"ee",-1,0,-1,0,9,9,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0010-01",26,"Las muchachas de hoy en día\nson como la papa criolla\nno saben lavar un plato\ncuando ya les pica la POLLA.",230,3,40,-1,"",0,4,"oa",453,0,-1,0,10,10,"","",80,"","","",14,0,0,[],"",""],["genitalidad_colombia-p0010-02",26,"Los gatos y los casados\nson de una mesma opinión\nteniendo carne en la casa\nsalen a buscar RATON.",230,3,40,-1,"",0,4,"o",31,0,-1,0,10,10,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0011-01",26,"Hablemos un poquito\nde los hombres que hay solteros\nque cuando van a enamorar\nofrecen hasta el SOMBRERO.",230,3,40,-1,"",0,4,"eo",-1,0,-1,0,11,11,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0011-02",26,"Esta noche está de tuna\nla copa de mi SOMBRERO\nsi la copa está de tuna\nque será el SOMBRERO entero.",230,3,40,-1,"",1,4,"eo",38,0,-1,0,11,11,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0012-01",26,"Eso dice busté\npa'ber que digo yo\ncuénteme otro cuentico\nque'se ya me lo contó.",230,3,40,-1,"",0,4,"o",2,0,-1,0,12,12,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-01",26,"Cuando estaremos mi vida\ncomo los pies del señor\nuno encima de otro\ny un clavito entre los dos.",230,3,40,-1,"",0,4,"o",-1,0,-1,0,13,13,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0013-02",26,"Una niña me rrogó\nque le apuntara el zapato\ny como yo no sabía\nle apuntaba cada rrato.",230,3,40,-1,"",0,4,"ao",19,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-03",26,"Acuéstese boca arriba\nacuéstese boca abajo\ncuéstese como quiera\npero no se la rebajo.",230,3,40,-1,"",0,4,"ao",168,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-04",26,"Desde allá se be la casa\ni también la mata de pino\nsabiendo que estaba sola\npendejo por que no vino.",230,3,40,-1,"",0,4,"io",199,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-05",26,"Arriba señora nobia\ny a bailar con su marido\ny a pagar los chicharrones\nque de soltera se a comido.",230,3,40,-1,"",0,4,"io",101,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-06",26,"No se baya mi señora\ndeje y mañana se ba\nme levanto y le ago un caldo\nle echo un huevo ya y se ba.",230,3,40,-1,"",0,4,"a",-1,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-07",26,"Una niña se encontró\nun brisol en un disiembre\ny yo como agricultor\nme rruega que se lo siembre.",230,3,40,-1,"",0,4,"ee",740,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-08",26,"Me rruega que se lo siembre\nen los primeros de marso\ny en los días de disiembre\nva Pa juera el brijolazo.",230,3,40,-1,"",0,4,"ao",-1,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0013-09",26,"Si mi prima fuera cuerda\ny a mi tipla la pusiera\nso le templara yo a mi prima\nmientrás más prima fuera.",230,3,40,-1,"",0,4,"ea",44,0,-1,0,13,13,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-01",26,"Señora mi señorita\nprésteme su poco o mucho\npara guardar mi pajarito\nMientras pasa el gabilucho.",230,3,40,-1,"",0,4,"uo",415,0,-1,0,14,14,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0014-02",26,"A la vecina del frente\nyo se lo estaba metiendo\nel estantillo en la casa\nque se le estaba cayendo.",230,3,40,-1,"",0,4,"eo",52,0,-1,0,14,14,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0014-03",26,"La ruana tiene sus pelos\ny no se puede pelar\ntambién tiene su rotico\npa' su cabeza empujar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-04",26,"Yo pedí un cuartillo de Chicha\nen la totuma timaná\nyo no lo ago por la chicha\nsino usted ya lo sabrá.",230,3,40,-1,"",1,4,"a",9,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-05",26,"Por esta cañada arriba\nbuscando la flor de poleo\npara llevarla a mi novia\nque estoy que me saraceo.",230,3,40,-1,"",0,4,"eo",66,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-06",26,"Noviecita mía dame lo que yo te pido\nde la cintura pa'bajo\nde las rodillas pa'rriba\nque es lo que Dios te ha socorrido.",230,3,40,-1,"",3,4,"io",101,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-07",26,"Señora, mi señorita\nyo se lo quiero desir\nteniendo usted el remedio\npor que me deja morir.",230,3,40,-1,"",0,4,"i",157,0,-1,0,14,14,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0014-08",26,"Ola mi chata querida\nvenga la acuesto al rincón\nque si mi mama la siente\nyo digo que es un ratón.",230,3,40,-1,"",0,4,"o",31,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0014-09",26,"De todos los animales\nyo quisiera ser el toche\npara ir a tu alcoba\nel sábado por la noche.",230,3,40,-1,"",0,4,"oe",337,0,-1,0,14,14,"","",80,"","","",11,0,0,[],"",""],["genitalidad_colombia-p0014-10",26,"Usted se va por el camino\ny yo por el rastrojo\ny hacemos una cosita\nmientras me limpio un ojo.",230,3,40,-1,"",0,4,"oo",400,0,-1,0,14,14,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0015-01",26,"Esto dijo el armadillo\ncavando su llano duro\ncortico de piernas soy\npero eso sí se lo aseguro.",230,3,40,-1,"",0,4,"uo",248,0,-1,0,15,15,"","",80,"","","",6,0,0,[],"",""],["genitalidad_colombia-p0015-02",26,"El hombre que se casa\ncon una mujer bonita\nse está muriendo de viejo\ny las ganas no se le quitan.",230,3,40,-1,"",0,4,"ia",-1,0,-1,0,15,15,"","",80,"","","",5,0,0,[],"",""],["genitalidad_colombia-p0015-03",26,"Chinita por un trabajo\nme cobraste cuatro riales\nchinita no sea carera\nque yo puse los materiales.",230,3,40,-1,"",0,4,"ae",26,0,-1,0,15,15,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0015-04",26,"la nobia que yo tenía\ncon otro se ba a casar\npero el consuelo que tengo\nes que no se fue sin probar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,15,15,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0015-05",26,"Eche chicha por tutumas\ny por vasos de aguardiente\nque un hombre con buenos polvos\nningunos trabajos siente.",230,3,40,-1,"",0,4,"ee",15,0,-1,0,15,15,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0015-07",26,"Esto me dijo mi chata\ncuando la tenía debajo\nparece gota de anibal\nlo que me echa este vergajo.",230,3,40,-1,"",0,4,"ao",168,0,-1,0,15,15,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0016-01",26,"A la novia le puse cita\ndonde no se prestaba el prado\ncomo no pudimos de otro modo\nnos toco desde parados.",230,3,40,-1,"",3,4,"ao",-1,0,-1,0,16,16,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0016-02",26,"En el sitio el colorado\nno se puede aser un trato\nporque allí muchas solteritas\nduermen la noche con cuatro.",230,3,40,-1,"",0,4,"ao",-1,0,-1,0,16,16,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0016-03",26,"El cura de mi pueblo\nme trato de sinverguenza\nporque me encontro en el parque\nboca abajo asiendo fuerza.",230,3,40,-1,"",0,4,"ea",-1,0,-1,0,16,16,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0016-04",26,"Mi mamita me pego\ncon un rabito de oveja\nmás que yo quiera ser buena\nmi rabito no me deja.",230,3,40,-1,"",0,4,"ea",-1,0,-1,0,16,16,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0016-05",26,"De las fiestas de Ubaté\nyo si traje que contar\nque me dieron mantecadas\ny tocino sin pelar.",230,3,40,-1,"",0,4,"a",21,0,-1,0,16,16,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0016-06",26,"Esto me dijo mi chata\ndebajo del palo de gaque\nde que cuña es ese palo\nle pago y no me lo saque.",230,3,40,-1,"",0,4,"ae",741,0,-1,0,16,16,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0016-07",26,"Cuando me vaya de aquí\nme voy a la madrugada\npara que nadie me vea\nla falda tan arrugada.",230,3,40,-1,"",0,4,"aa",49,0,-1,0,16,16,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0016-08",26,"El chímbalo está preso\nen la cárcel de los grillos\npor una declaración\nque dieron los armadillos.",230,3,40,-1,"",0,4,"io",161,0,-1,0,16,16,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0016-09",26,"A noche a la media noche\nla media noche sería\nse cayó la cama al suelo\npor tar en la jullería.",230,3,40,-1,"",0,4,"ia",0,0,-1,0,16,16,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0016-10",26,"Una vieja y un viejito\nse fueron a comer guamas\nla vieja quedó llena\ny el viejo quedó con ganas.",230,3,40,-1,"",0,4,"aa",-1,0,-1,0,16,16,"","",80,"","","",9,0,0,[],"",""],["genitalidad_colombia-p0017-01",26,"Esto dijo la gallina\nablando con la ardilla\nque me meterá el gallo\nque me ase ver candelillas.",230,3,40,-1,"",0,4,"ia",-1,0,-1,0,17,17,"","",80,"","","",3,0,0,[],"",""],["genitalidad_colombia-p0017-02",26,"Esto dijo la armadilla\ncuando estaba embarazada\nsi Dios me saca con bien\nhechamos otra cuasquiada.",230,3,40,-1,"",0,4,"aa",49,0,-1,0,17,17,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0017-03",26,"La sapa estaba pariendo\ndebajo de un barranquito\ny el sapo estaba mirando\npor donde salía el sapito.",230,3,40,-1,"",0,4,"io",119,0,-1,0,17,17,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0017-04",26,"Ora que estamos solos\nhagamos una agua miel\nhagamos un muchachito\ny le echamos la culpa aquel.",230,3,40,-1,"",0,4,"e",32,0,-1,0,17,17,"","",80,"","","",1,0,0,[],"",""],["genitalidad_colombia-p0017-06",26,"Esto dijo la armadilla\ncuando estaba embarazada\ncon la voluntad de Dios\nquizá no me pase nada",230,3,40,-1,"",0,4,"aa",49,0,-1,0,17,17,"","",80,"","","",2,0,0,[],"",""],["genitalidad_colombia-p0017-07",26,"El caballo resabiado\nle dijo a la yegua mansa\neso no haga fuerza mija\nque se vuelve sola pansa.",230,3,40,-1,"",0,4,"aa",177,0,-1,0,17,17,"","",80,"","","",1,0,0,[],"",""],["antioquia_animales-p0008-01",27,"yo soy como el camaleón\nque entre l'agua tengo el nido\ny vivo muerto de sed\ncon ser qu'entre l'agua vivo",231,3,41,315,"",0,4,"io",-1,0,-1,0,8,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-01",27,"Entre Melín y Melambas\nmataron una ternera:\nMelín se llevó la cola\ny Melambas la trasera",231,3,41,315,"",0,4,"ea",44,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-02",27,"Un pájaro mochilero\nle pregunta al diostedé:\ncon ese pico tan largo\ncómo come su mercé?",231,3,41,315,"",0,4,"e",77,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-03",27,"Sobre la tierra la palma\nsobre la palma los cielos;\nsobre mi caballo yo\ny sobre yo… ¡mi sombrero!",231,3,41,315,"",0,4,"eo",-1,0,-1,0,9,9,"","",81,"","","",2,0,0,[],"",""],["antioquia_animales-p0009-04",27,"La sirena se ha perdido\nen un monte muy oscuro,\nsu madre l' anda buscando\ncon un candil… en la boca",231,3,41,315,"",5,4,"oa",-1,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-05",27,"Cuando voy a un fandango\na bailar con mi paloma,\na lo que le piso el pie\nno hay capitín que me coma",231,3,41,315,"",0,4,"oa",86,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-06",27,"En las corrientes del Cauca\nuna gallina se 'hogó:\nen agonías de muerte\nabrió el pico y izo: cló!",231,3,41,315,"",0,4,"o",2,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0009-07",27,"El amor de las mujeres\nes como el de las gallinas,\nque en faltándoles el gallo\na cualquier pollo se arriman.",231,3,41,315,"",0,4,"ia",-1,0,-1,0,9,9,"","",81,"machado_venezuela","","",18,0,0,[],"",""],["antioquia_animales-p0009-08",27,"Pajarillo mensajero\nde aquél ángel que yo adoro\ndile a mi dueña que lloro,\nque la quise y que la quiero.",231,3,41,315,"",11,4,"eo",38,0,-1,0,9,9,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0010-01",27,"Una paloma maté\ny cruda me la comí:\nSi no me lo pueden creer\nmiren las plumas aquí.",231,3,41,315,"",0,4,"i",23,0,-1,0,10,10,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0010-02",27,"Pajarillo que ayer tarde\ncantabas tu libertá\ny agora por tu desgracia\nte ves prisionera ya",231,3,41,315,"",0,4,"a",9,0,-1,0,10,10,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0010-03",27,"Se te fue el pájaro ya\nqu'en la mano lo tuviste;\nno sabes lo que perdiste,\nel tiempo te lo dirá",231,3,41,315,"",11,4,"a",9,0,-1,0,10,10,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0010-04",27,"Malpago se llama el perro,\nno me le quiten el nombre,\nqu'ese es el pago que dan\nlas mujeres a los hombres.",231,3,41,315,"",0,4,"oe",-1,0,-1,0,10,10,"","",81,"","","",3,0,0,[],"",""],["antioquia_animales-p0010-05",27,"Yo soy gavilán pollero\nque a las pollas no me atrevo,\npero a las gallinas grandes\nen las uñas me las llevo.",231,3,41,315,"",0,4,"eo",240,0,-1,0,10,10,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0011-01",27,"Un pájaro me ofreció\nlas plumas de su copete:\nno hay pájaro en esta vida\nque cumpla lo que promete.",231,3,41,315,"",0,4,"ee",285,0,-1,0,11,11,"","",81,"isaacs_colombia","","",2,0,0,[],"",""],["antioquia_animales-p0011-02",27,"No te dé cuidado, pava,\nque a tu nido volverás;\ny si acaso no volvieses,\nhartos gavilanes hay!",231,3,41,315,"",0,4,"a",-1,0,-1,0,11,11,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0011-03",27,"Esto dijo el armadillo\ncuando se iba para su cueva:\ncomo yo meta mi rabo,\nqué importa lo que llueva.",231,3,41,315,"",0,4,"ea",481,0,-1,0,11,11,"","",81,"","","",6,0,0,[],"",""],["antioquia_animales-p0011-04",27,"Esto dijo la gallina\ncuando l'iban a matar:\neste mal no tiene cura\npongan l'agua a calentar.",231,3,41,315,"",0,4,"a",21,0,-1,0,11,11,"","",81,"","","",3,0,0,[],"",""],["antioquia_animales-p0011-05",27,"Ninguno me supirite (*)\nporque yo también soy gallo;\nen el corral de mis yeguas\nno me relincha caballo.",231,3,41,315,"",0,4,"ao",102,0,-1,0,11,11,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0011-06",27,"Te fuiste y me dejaste\ncomo garza en la laguna:\ncon el pescuezo tan largo,\nsin esperanza ninguna.",231,3,41,315,"",0,4,"ua",56,0,-1,0,11,11,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0011-07",27,"El sapo estaba de viaje\na llevar mulas al puerto,\ny la sapa le decía:\n¿cuándo vuelves, patiabierto?",231,3,41,315,"",0,4,"eo",88,0,-1,0,11,11,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0012-01",27,"Un águila va volando\ny en el pico lleva un rejo;\ncon las alas va diciendo:\n¡qué pendejo, qué pendejo!",231,3,41,315,"",0,4,"eo",-1,0,-1,0,12,12,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0012-02",27,"Que bonito canta y silba\nun cuervo en el lavadero:\ncuide, mamita, la casa\nque yo me voy a cogerlo.",231,3,41,315,"",0,4,"eo",-1,0,-1,0,12,12,"","",81,"","","",2,0,0,[],"",""],["antioquia_animales-p0012-03",27,"Al lá va la guacharaca\npor la orilla del estero:\nvoy a quitarle una pluma\npa ponerle a mi sombrero.",231,3,41,315,"",0,4,"eo",38,0,-1,0,12,12,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0012-04",27,"Más vale querer a un perro\nque querer a una mujer,\nquel perro es agradecido\ncuando le dan de comer.",231,3,41,315,"",0,4,"e",20,0,-1,0,12,12,"","",81,"","","",5,0,0,[],"",""],["antioquia_animales-p0012-05",27,"De la pava la pechuga,\nde la gallina el alón,\nde las muchachas bonitas\nlas alas del corazón.",231,3,41,315,"",0,4,"o",31,0,-1,0,12,12,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0012-06",27,"Malpago se llama el perro,\ny Fortuna la perrita,\nque si Malpago se muere\nqueda Fortuna solita.",231,3,41,315,"",0,4,"ia",50,0,-1,0,12,12,"","",81,"","","",3,0,0,[],"",""],["antioquia_animales-p0012-08",27,"El pajarito voló\nde la sala al aposento,\n¿qué hará ahora la señora\ncon el pajarito adentro?",231,3,41,315,"",0,4,"eo",-1,0,-1,0,12,12,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0013-01",27,"Los sapos en la laguna\ncuando sienten tempestá\nunos cantan tunga-tunga\ny otros cantan tungará",231,3,41,315,"",0,4,"a",9,0,-1,0,13,13,"","",81,"","","",6,0,0,[],"",""],["antioquia_animales-p0013-02",27,"Si el sapo tuviera dientes\ncomo tiene fortaleza,\nno se encontrara en el mundo\nuna rana con cabeza.",231,3,41,315,"",0,4,"ea",108,0,-1,0,13,13,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0013-03",27,"Los sapos en la laguna\ncuando sienten aguacero,\nunos piden la cuchara\ny otros piden el sombrero.",231,3,41,315,"",0,4,"eo",38,0,-1,0,13,13,"","",81,"","","",6,0,0,[],"",""],["antioquia_animales-p0014-01",27,"Esto dijo el armadillo\ncuando se iba para su cueva:\ncomo yo meta mi rabo\nqué me importa lo que llueva.",231,3,41,315,"",0,4,"ea",481,0,-1,0,14,14,"","",81,"","","",6,0,0,[],"",""],["antioquia_animales-p0014-02",27,"Anoche a la media noche\nlloraba el garrapatero,\nporque no podía sacar\ngarrapatas con el dedo.",231,3,41,315,"",0,4,"eo",-1,0,-1,0,14,14,"","",81,"","","",4,0,0,[],"",""],["antioquia_animales-p0014-04",27,"La palomita en su nido\nse lamenta, gime y llora,\ndel que duerme en casa ajena\na los pies de su señora.",231,3,41,315,"",0,4,"oa",107,0,-1,0,14,14,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0014-06",27,"Si yo fuera pajarillo\nno me ocupara en volar;\nme asentara en el camino\nsólo por verte pasar.",231,3,41,315,"",0,4,"a",21,0,-1,0,14,14,"","",81,"","","",2,0,0,[],"",""],["antioquia_animales-p0014-07",27,"Mi padre y un gallinazo\nse fueron pa' Santa fe;\nel gallinazo volando\ny el pobre viejo de a pie.",231,3,41,315,"",0,4,"e",77,0,-1,0,14,14,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0014-09",27,"Dame tu mano, paloma,\npara subir a tu nido;\nque es sabido qu'estás\ny quiero dormir contigo.",231,3,41,315,"",0,4,"io",-1,0,-1,0,14,14,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0014-10",27,"Qué bonito canta y silba\nun cuervo en el lavadero:\ncuide, mamita, la casa\nque yo voy a cogerlo.",231,3,41,315,"",0,4,"eo",-1,0,-1,0,14,14,"","",81,"","","",2,0,0,[],"",""],["antioquia_animales-p0014-11",27,"Mi gallinita y mis pollos\ncon que me mantenía yo,\nque sólo por ir a misa\nmi gallina se perdió.",231,3,41,315,"",0,4,"o",2,0,-1,0,14,14,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0016-04",27,"El pájaro voló\nde la sala al aposento,\n¿qué hará ahora la señora\ncon el pajarito adentro?",231,3,41,315,"",0,4,"eo",-1,0,-1,0,16,16,"","",81,"","","",1,0,0,[],"",""],["antioquia_animales-p0016-06",27,"Yo soy el tigre mojano\nnacido en la serranía:\ntengo las uñas gastadas\nde castigar picardías.",231,3,41,315,"",0,4,"ia",-1,0,-1,0,16,16,"","",81,"","","",1,0,0,[],"",""]]);
